# ============================================================================
# Architecture / 架构 / アーキテクチャ
# Layer 1: Process bootstrap, shared runtime defaults, and global policy.
# 第一层：进程启动、共享运行时默认值与全局策略。
# 第1層：プロセス起動、共有ランタイム既定値、全体ポリシー。
# ============================================================================

def _shared_http_ssl_context():
    global _HTTP_SSL_CONTEXT
    if _HTTP_SSL_CONTEXT is not None:
        return _HTTP_SSL_CONTEXT
    cafile = str(os.getenv("SSL_CERT_FILE", "") or "").strip()
    if not cafile and _certifi is not None:
        try:
            cafile = str(_certifi.where() or "").strip()
        except Exception:
            cafile = ""
    try:
        ctx = ssl.create_default_context(cafile=cafile or None)
    except Exception:
        ctx = ssl.create_default_context()
    _HTTP_SSL_CONTEXT = ctx
    return ctx

def urlopen(url, *args, **kwargs):
    if "context" not in kwargs:
        target = getattr(url, "full_url", url)
        if str(target or "").strip().lower().startswith("https://"):
            try:
                kwargs["context"] = _shared_http_ssl_context()
            except Exception:
                pass
    return _URL_OPEN_ORIGINAL(url, *args, **kwargs)

def _resolve_default_agent_workdir() -> Path:
    raw = str(os.getenv("AGENT_WORKDIR", "") or "").strip()
    if raw:
        return Path(raw).expanduser().resolve()
    return SCRIPT_DIR

def _migrate_legacy_runtime_roots(workspace: Path) -> dict:
    root = Path(workspace).resolve()
    legacy_root = (root / "skills").resolve()
    moved: list[str] = []
    errors: list[str] = []
    if legacy_root == root or (not legacy_root.exists()) or (not legacy_root.is_dir()):
        return {
            "root": str(root),
            "legacy_root": str(legacy_root),
            "moved": moved,
            "errors": errors,
        }
    # Earlier builds could incorrectly place runtime data under workspace/skills when started from that cwd.
    for name in ("RAG_Library", "Code_Library", "Codes", "js_lib", "LLM.config.json"):
        src = legacy_root / name
        dst = root / name
        try:
            if (not src.exists()) or dst.exists():
                continue
            shutil.move(str(src), str(dst))
            moved.append(name)
        except Exception as exc:
            errors.append(f"{name}:{trim(str(exc), 220)}")
    return {
        "root": str(root),
        "legacy_root": str(legacy_root),
        "moved": moved,
        "errors": errors,
    }

