OFFLINE_JS_LIB_INDEX_FILE = "index.json"
OFFLINE_JS_LIB_README_FILE = "README.md"


def _normalize_js_lib_asset_ref(value: str) -> str:
    raw = str(value or "").replace("\\", "/").strip()
    if not raw:
        return ""
    raw = raw.lstrip("/")
    pure = PurePosixPath(raw)
    parts: list[str] = []
    for part in pure.parts:
        if part in {"", "."}:
            continue
        if part == "..":
            return ""
        parts.append(part)
    return "/".join(parts)


def _resolve_js_lib_asset_path(js_root: Path, asset_ref: str) -> Path | None:
    rel = _normalize_js_lib_asset_ref(asset_ref)
    if not rel:
        return None
    exact = (js_root / rel).resolve()
    try:
        if exact.is_file() and exact.is_relative_to(js_root):
            return exact
    except Exception:
        pass
    basename = _safe_js_filename(Path(rel).name, "lib.js")
    candidates: list[Path] = []
    try:
        for fp in js_root.rglob(basename):
            try:
                resolved = fp.resolve()
            except Exception:
                continue
            if resolved.is_file():
                try:
                    if resolved.is_relative_to(js_root):
                        candidates.append(resolved)
                except Exception:
                    continue
    except Exception:
        return None
    if not candidates:
        return None
    candidates.sort(key=lambda p: (len(p.relative_to(js_root).parts), p.relative_to(js_root).as_posix()))
    return candidates[0]


def _discover_extra_js_lib_files(js_root: Path, known_relative_paths: set[str]) -> list[dict]:
    rows: list[dict] = []
    if not js_root.exists():
        return rows
    seen: set[str] = set()
    for fp in sorted(js_root.rglob("*")):
        if not fp.is_file() or fp.name in {".DS_Store", OFFLINE_JS_LIB_INDEX_FILE, OFFLINE_JS_LIB_README_FILE}:
            continue
        if fp.suffix.lower() not in {".js", ".mjs", ".cjs"}:
            continue
        rel = fp.relative_to(js_root).as_posix()
        if rel in known_relative_paths or rel in seen:
            continue
        seen.add(rel)
        stem = fp.stem.replace(".min", "").replace(".umd", "").replace(".bundle", "")
        rows.append(
            {
                "id": f"local:{stem or fp.name}",
                "filename": fp.name,
                "relative_path": rel,
                "available": True,
                "size": int(fp.stat().st_size),
                "sha256": _sha256_file(fp),
                "source": "existing-local",
                "error": "",
                "match_tokens": [fp.name.lower(), stem.lower(), rel.lower()],
                "urls": [],
                "catalog": False,
            }
        )
    return rows


def normalize_ui_language(raw: str | None) -> str:
    key = str(raw or "").strip()
    if key in UI_LANGUAGE_LABELS:
        return key
    low = key.lower()
    aliases = {
        "zh": "zh-CN",
        "zh-cn": "zh-CN",
        "zh_simplified": "zh-CN",
        "cn": "zh-CN",
        "zh-tw": "zh-TW",
        "zh-hk": "zh-TW",
        "zh_hant": "zh-TW",
        "tc": "zh-TW",
        "ja-jp": "ja",
        "jp": "ja",
        "en-us": "en",
        "en-gb": "en",
    }
    mapped = aliases.get(low)
    if mapped and mapped in UI_LANGUAGE_LABELS:
        return mapped
    return DEFAULT_UI_LANGUAGE


def normalize_ui_style(raw: str | None) -> str:
    key = str(raw or "").strip().lower().replace("-", "_")
    aliases = {
        "neo": "neo",
        "modern": "neo",
        "new": "neo",
        "cards": "neo",
        "card": "neo",
        "trad": "trad",
        "traditional": "trad",
        "classic": "trad",
        "legacy": "trad",
        "old": "trad",
    }
    mapped = aliases.get(key)
    if mapped in UI_STYLE_CHOICES:
        return mapped
    return DEFAULT_UI_STYLE


def supported_ui_languages_payload() -> list[dict]:
    return [dict(x) for x in SUPPORTED_UI_LANGUAGES]


def normalize_execution_mode(raw: str | None, default: str = EXECUTION_MODE_SYNC) -> str:
    key = str(raw or "").strip().lower().replace("-", "_")
    aliases = {
        "single": EXECUTION_MODE_SINGLE,
        "legacy": EXECUTION_MODE_SINGLE,
        "sequential": EXECUTION_MODE_SEQUENTIAL,
        "async_sequential": EXECUTION_MODE_SEQUENTIAL,
        "pipeline": EXECUTION_MODE_SEQUENTIAL,
        "sync": EXECUTION_MODE_SYNC,
        "synchronous": EXECUTION_MODE_SYNC,
        "collaborative": EXECUTION_MODE_SYNC,
        "sync_collab": EXECUTION_MODE_SYNC,
    }
    mapped = aliases.get(key, "")
    if mapped in EXECUTION_MODE_CHOICES:
        return mapped
    fallback = str(default or EXECUTION_MODE_SYNC).strip().lower()
    if fallback in EXECUTION_MODE_CHOICES:
        return fallback
    return EXECUTION_MODE_SYNC


def model_language_instruction(lang: str) -> str:
    code = normalize_ui_language(lang)
    if code == "zh-CN":
        return (
            "Language policy: use Simplified Chinese by default for all user-facing answers, plans, "
            "blackboard notes, manager delegates, and agent-bus collaboration messages. "
            "Only switch language when user explicitly requests it. "
            "Do not translate code, file paths, commands, API/tool names, or JSON keys."
        )
    if code == "zh-TW":
        return (
            "Language policy: use Traditional Chinese by default for all user-facing answers, plans, "
            "blackboard notes, manager delegates, and agent-bus collaboration messages. "
            "Only switch language when user explicitly requests it. "
            "Do not translate code, file paths, commands, API/tool names, or JSON keys."
        )
    if code == "ja":
        return (
            "Language policy: use Japanese by default for all user-facing answers, plans, "
            "blackboard notes, manager delegates, and agent-bus collaboration messages. "
            "Only switch language when user explicitly requests it. "
            "Do not translate code, file paths, commands, API/tool names, or JSON keys."
        )
    return (
        "Language policy: use English by default for all user-facing answers, plans, "
        "blackboard notes, manager delegates, and agent-bus collaboration messages. "
        "Only switch language when user explicitly requests it. "
        "Do not translate code, file paths, commands, API/tool names, or JSON keys."
    )


