def backend_i18n_text(language: str, key: str, **kwargs) -> str:
    code = normalize_ui_language(language)
    pack = BACKEND_I18N.get(code, BACKEND_I18N["en"])
    fallback = BACKEND_I18N["en"]
    template = str(pack.get(key, fallback.get(key, key)))
    if kwargs:
        try:
            return template.format(**{k: ("" if v is None else v) for k, v in kwargs.items()})
        except Exception:
            return template
    return template


def backend_role_label(role: str, language: str) -> str:
    role_key = str(role or "").strip().lower()
    if role_key in {"explorer", "developer", "reviewer", "manager", "planner"}:
        return backend_i18n_text(language, f"role_{role_key}")
    return backend_i18n_text(language, "role_agent")


def _detect_os_shell_instruction() -> str:
    """Return a shell environment note for the agent system prompt based on the host OS."""
    import platform as _platform
    _sys = _platform.system()
    if _sys == "Windows":
        return (
            "Shell environment: Windows (cmd.exe via shell=True). "
            "IMPORTANT — use Windows-native commands only: "
            "use 'dir' (not 'ls'), 'type' (not 'cat'), 'del' (not 'rm'), "
            "'move' (not 'mv'), 'copy' (not 'cp'), 'findstr' (not 'grep'), "
            "'where' (not 'which'), 'echo %VAR%' (not 'echo $VAR'). "
            "To list files recursively use 'dir /s /b'. "
            "Path separator is backslash (\\). "
            "Environment variables WORKSPACE_ROOT, SESSION_ROOT, and SKILLS_ROOT are available. "
            "Do NOT use POSIX paths like /workspace, /tmp, /usr, ~/... — they do not exist. "
            "Working directory is already set; use relative paths or the absolute session root shown above."
        )
    if _sys == "Darwin":
        return (
            "Shell environment: macOS (bash/zsh). "
            "Standard POSIX commands are available (ls, cat, grep, find, etc.). "
            "Package manager is 'brew'. "
            "Environment variables WORKSPACE_ROOT, SESSION_ROOT, and SKILLS_ROOT are available. "
            "Virtual aliases '/workspace/...' and '/skills/...' are supported in shell commands and rewritten to real paths before execution. "
            "Virtual alias '/js_lib/...' maps to the offline JS libraries root ($JS_LIB_ROOT) and is also supported in file tools. "
            "Do NOT assume Linux-specific paths like /proc or /etc/os-release exist. "
            "IMPORTANT: The workspace path contains spaces. Always use relative paths "
            "(e.g., 'ls uploaded/' not 'ls /full/absolute/path/uploaded/'). "
            "If you must use absolute paths, always quote them with double quotes."
        )
    # Linux / other POSIX
    return (
        "Shell environment: Linux (bash). "
        "Standard POSIX commands are available (ls, cat, grep, find, etc.). "
        "Environment variables WORKSPACE_ROOT, SESSION_ROOT, and SKILLS_ROOT are available. "
        "Virtual aliases '/workspace/...' and '/skills/...' are supported in shell commands and rewritten to real paths before execution. "
        "IMPORTANT: The workspace path may contain spaces. Always use relative paths "
        "(e.g., 'ls uploaded/' not 'ls /full/absolute/path/uploaded/'). "
        "If you must use absolute paths, always quote them with double quotes."
    )

def resolve_web_ui_dir_path(raw: str, base_dir: Path | None = None) -> Path:
    txt = str(raw or "").strip()
    if not txt:
        txt = DEFAULT_WEB_UI_DIR
    p = Path(txt).expanduser()
    if p.is_absolute():
        return p.resolve()
    return ((base_dir or WORKDIR).resolve() / p).resolve()


def resolve_optional_file_path(raw: str, base_dir: Path | None = None) -> Path:
    txt = str(raw or "").strip()
    if not txt:
        return ((base_dir or WORKDIR).resolve() / DEFAULT_WEB_UI_CONFIG).resolve()
    p = Path(txt).expanduser()
    if p.is_absolute():
        return p.resolve()
    return ((base_dir or WORKDIR).resolve() / p).resolve()


def resolve_skills_root_path(raw: str, base_dir: Path | None = None) -> Path:
    txt = str(raw or "").strip()
    if not txt:
        txt = "skills"
    p = Path(txt).expanduser()
    if p.is_absolute():
        return p.resolve()
    return ((base_dir or WORKDIR).resolve() / p).resolve()


def _count_skill_markdown_files(root: Path, limit: int = 2048) -> int:
    if not root.exists() or not root.is_dir():
        return 0
    total = 0
    try:
        for _ in root.rglob("SKILL.md"):
            total += 1
            if total >= limit:
                break
    except Exception:
        return 0
    return total


def select_preferred_skills_root(
    workdir: Path = WORKDIR,
    *,
    explicit: str = "",
    external_config: dict | None = None,
    web_ui_config: dict | None = None,
) -> tuple[Path, str]:
    external_config = external_config if isinstance(external_config, dict) else {}
    web_ui_config = web_ui_config if isinstance(web_ui_config, dict) else {}
    explicit_candidates = [
        ("cli", explicit),
        ("env", os.getenv("AGENT_SKILLS_ROOT", "")),
        ("config", external_config.get("skills_root", external_config.get("skills_dir", ""))),
        ("web_ui_config", web_ui_config.get("skills_root", web_ui_config.get("skills_dir", ""))),
    ]
    for source, raw in explicit_candidates:
        txt = str(raw or "").strip()
        if not txt:
            continue
        return resolve_skills_root_path(txt, workdir), source

    auto_rows: list[tuple[bool, int, int, Path]] = []
    for idx, name in enumerate(AUTO_SKILLS_ROOT_CANDIDATES):
        candidate = (workdir / name).resolve()
        if not candidate.exists() or not candidate.is_dir():
            continue
        skill_count = _count_skill_markdown_files(candidate)
        embedded = (candidate / ".embedded_bundle_state.json").exists()
        auto_rows.append((not embedded and skill_count > 0, skill_count, -idx, candidate))
    if auto_rows:
        auto_rows.sort(reverse=True)
        chosen = auto_rows[0][3]
        return chosen, "auto-detect"

    return ensure_embedded_skills(workdir), "embedded-default"


def load_web_ui_config_file(path: Path) -> dict:
    if not path.exists() or not path.is_file():
        return {}
    try:
        raw = path.read_text(encoding="utf-8")
    except Exception:
        try:
            raw = path.read_text(encoding="utf-8-sig")
        except Exception:
            return {}
    try:
        parsed = json.loads(raw)
    except Exception:
        return {}
    return parsed if isinstance(parsed, dict) else {}


def extract_show_upload_list_setting(raw: object) -> bool | None:
    if not isinstance(raw, dict):
        return None
    keys = ("show_upload_list", "upload_list_visible", "enable_upload_list")
    for key in keys:
        if key in raw:
            return _to_bool_like(raw.get(key), default=False)
    for section_key in ("web_ui", "ui", "frontend"):
        section = raw.get(section_key)
        if not isinstance(section, dict):
            continue
        for key in keys:
            if key in section:
                return _to_bool_like(section.get(key), default=False)
    return None


def extract_ui_style_setting(raw: object) -> str | None:
    if not isinstance(raw, dict):
        return None
    keys = ("UI_Style", "ui_style", "uiStyle", "style_mode", "chat_ui_style")
    for key in keys:
        if key in raw:
            return normalize_ui_style(str(raw.get(key) or ""))
    for section_key in ("web_ui", "ui", "frontend"):
        section = raw.get(section_key)
        if not isinstance(section, dict):
            continue
        for key in keys:
            if key in section:
                return normalize_ui_style(str(section.get(key) or ""))
    return None


def extract_js_lib_download_setting(raw: object) -> bool | None:
    """Read download_js_lib flag from config dict.
    Keys accepted: download_js_lib / js_lib_download / enable_js_lib_download
    Sections searched: top-level, then 'startup' / 'offline' / 'web_ui'.
    Returns True/False, or None if key absent (caller uses default=True).
    """
    if not isinstance(raw, dict):
        return None
    keys = ("download_js_lib", "js_lib_download", "enable_js_lib_download", "offline_js_download")
    for key in keys:
        if key in raw:
            return _to_bool_like(raw.get(key), default=True)
    for section_key in ("startup", "offline", "web_ui", "ui"):
        section = raw.get(section_key)
        if not isinstance(section, dict):
            continue
        for key in keys:
            if key in section:
                return _to_bool_like(section.get(key), default=True)
    return None


def extract_daily_session_limit_setting(raw: object) -> int | None:
    """Read per-IP daily session creation limit from config dict.

    Accepted keys:
      - daily_session_limit
      - daily_sessions_per_ip
      - max_daily_sessions_per_ip
      - session_daily_limit
    Sections searched: top-level, then 'startup' / 'limits' / 'web_ui' / 'ui'.
    Returns a non-negative integer, or None if no setting is present.
    """
    if not isinstance(raw, dict):
        return None

    def _parse_non_negative_int(value: object) -> int | None:
        if value is None:
            return None
        if isinstance(value, bool):
            return int(value)
        try:
            text = str(value).strip()
            if not text:
                return None
            return max(0, int(float(text)))
        except Exception:
            return None

    keys = (
        "daily_session_limit",
        "daily_sessions_per_ip",
        "max_daily_sessions_per_ip",
        "session_daily_limit",
    )
    for key in keys:
        if key in raw:
            return _parse_non_negative_int(raw.get(key))
    for section_key in ("startup", "limits", "web_ui", "ui"):
        section = raw.get(section_key)
        if not isinstance(section, dict):
            continue
        for key in keys:
            if key in section:
                return _parse_non_negative_int(section.get(key))
    return None


