# ============================================================================
# Architecture / 架构 / アーキテクチャ
# Layer 4: Session execution chain and agent-facing runtime state.
# 第四层：会话执行链与面向 agent 的运行时状态。
# 第4層：セッション実行チェーンと agent 向けランタイム状態。
# ============================================================================

# Per-session orchestrator: maintains conversation state, plan state, tool
# routing, todo synchronization, completion checks, and agent coordination.
class SessionState:
    def __init__(
        self,
        session_id: str,
        title: str,
        root: Path,
        ollama_base: str,
        model: str,
        skills_root: Path,
        crypto: CryptoBox,
        repo_root: Path,
        thinking: bool = False,
        default_llm_config: dict | None = None,
        context_token_limit: int = DEFAULT_CONTEXT_TOKEN_LIMIT,
        context_limit_locked: bool = False,
        max_rounds: int = MAX_AGENT_ROUNDS,
        max_run_seconds: int = MAX_RUN_SECONDS,
        shell_command_timeout_seconds: int = DEFAULT_SHELL_COMMAND_TIMEOUT_SECONDS,
        auto_task_level_ceiling: int = DEFAULT_AUTO_TASK_LEVEL_CEILING,
        auto_model_switch: bool = False,
        arbiter_enabled: bool = True,
        arbiter_model: str = "",
        arbiter_timeout_seconds: float = ARBITER_DEFAULT_TIMEOUT_SECONDS,
        arbiter_max_tokens: int = ARBITER_DEFAULT_MAX_TOKENS,
        arbiter_temperature: float = ARBITER_DEFAULT_TEMPERATURE,
        execution_mode: str = EXECUTION_MODE_SYNC,
        max_output_tokens: int = AGENT_MAX_OUTPUT_TOKENS,
        web_search_enabled: bool = DEFAULT_WEB_SEARCH_ENABLED,
        ui_language: str = DEFAULT_UI_LANGUAGE,
        js_lib_root: Path | None = None,
        owner_user_id: str = "",
        upload_callback=None,
        run_finished_callback=None,
        reference_prepare_callback=None,
        query_code_library_callback=None,
        query_knowledge_library_callback=None,
        rag_remember_callback=None,
        code_library_root: Path | str | None = None,
        code_library_status_callback=None,
        knowledge_library_root: Path | str | None = None,
        knowledge_library_status_callback=None,
        mcp_manager=None,
    ):
        self.id = session_id
        self.title = title
        self.root = root / session_id
        self.root.mkdir(parents=True, exist_ok=True)
        self.files_root = self.root / "files"
        self.files_root.mkdir(parents=True, exist_ok=True)
        self.uploads_dir = self.root / "uploads"
        self.uploads_dir.mkdir(parents=True, exist_ok=True)
        self.js_lib_root = (js_lib_root or offline_js_lib_root(WORKDIR)).resolve()
        self.js_lib_root.mkdir(parents=True, exist_ok=True)
        self.context_archive_dir = self.root / "context_archive"
        self.context_archive_dir.mkdir(parents=True, exist_ok=True)
        self.code_preview_dir = self.root / "code_preview"
        self.code_preview_dir.mkdir(parents=True, exist_ok=True)
        self.long_output_dir = self.files_root / ".clouds_coder" / "long_output"
        self.long_output_dir.mkdir(parents=True, exist_ok=True)
        self.meta_path = self.root / "meta.json"
        self.state_path = self.root / "state.json"
        self.crypto = crypto
        # Session methods may emit events while already holding this lock.
        # Use a re-entrant lock to avoid self-deadlock during nested callbacks.
        self.lock = threading.RLock()
        self.owner_user_id = str(owner_user_id or "")
        self.upload_callback = upload_callback
        self.run_finished_callback = run_finished_callback
        self.reference_prepare_callback = reference_prepare_callback
        self.query_code_library_callback = query_code_library_callback
        self.query_knowledge_library_callback = query_knowledge_library_callback
        self.rag_remember_callback = rag_remember_callback
        try:
            self.code_library_root = (
                str(Path(code_library_root).resolve()) if code_library_root else ""
            )
        except Exception:
            self.code_library_root = str(code_library_root or "").strip()
        self.code_library_status_callback = code_library_status_callback
        try:
            self.knowledge_library_root = (
                str(Path(knowledge_library_root).resolve()) if knowledge_library_root else ""
            )
        except Exception:
            self.knowledge_library_root = str(knowledge_library_root or "").strip()
        self.knowledge_library_status_callback = knowledge_library_status_callback
        self.events = EventHub()
        self.ollama = OllamaClient(ollama_base, model)
        self.auto_model_switch = bool(auto_model_switch)
        self.arbiter_enabled = bool(arbiter_enabled)
        self.arbiter_model = str(arbiter_model or "").strip()
        self.arbiter_timeout_seconds = max(0.2, min(15.0, float(arbiter_timeout_seconds or ARBITER_DEFAULT_TIMEOUT_SECONDS)))
        self.arbiter_max_tokens = max(24, min(256, int(arbiter_max_tokens or ARBITER_DEFAULT_MAX_TOKENS)))
        self.arbiter_temperature = max(0.0, min(1.0, float(arbiter_temperature if arbiter_temperature is not None else ARBITER_DEFAULT_TEMPERATURE)))
        self.execution_mode = normalize_execution_mode(execution_mode, default=EXECUTION_MODE_SYNC)
        self.web_search_enabled = bool(web_search_enabled)
        self.user_memory_mode = DEFAULT_USER_MEMORY_MODE
        self.user_profile_capsule = ""
        self.user_profile_capsule_meta: dict = {"mode": DEFAULT_USER_MEMORY_MODE, "memory_count": 0}
        # Hot-path capsule de-dup: the ts of the latest user message we already
        # injected the capsule for on an execution turn — keeps execution-stage
        # injection to once-per-user-request (turns 2..N pay nothing).
        self._capsule_exec_injected_user_ts: float = 0.0
        env_ok, env_tags, _ = probe_ollama_environment(ollama_base)
        self.ollama_env_available = bool(env_ok)
        self.ollama_env_tags: list[str] = list(env_tags)
        self.thinking = False
        self.ui_language = normalize_ui_language(ui_language)
        self.runtime_region_hint = extract_runtime_region_hint_setting(default_llm_config or {})
        self.runtime_timezone_hint = extract_runtime_timezone_hint_setting(default_llm_config or {})
        self.model_profiles: dict[str, dict] = {}
        self.active_profile_id = ""
        self.multimodal_capability_cache: dict[str, dict] = {}
        self.failed_selections: list[str] = []
        self.todo = TodoManager(self.ui_language)
        self.single_advance_prompt_enhance = False
        self.skills = SkillStore(skills_root)
        self.skill_load_cache: dict[str, dict] = {}
        self.skills_last_refresh_ts = 0.0
        self.skills_runtime_prepared = False
        self.tasks = TaskManager(self.root / "tasks", crypto)
        self.bg = BackgroundManager(self.files_root)
        self.bus = MessageBus(self.root / "team" / "inbox", crypto)
        self.worktrees = WorktreeManager(self.id, self.tasks, self.root, crypto, repo_root)
        # External MCP (Model Context Protocol) tool driver. Prefer the shared
        # app-level manager (one mounted service, consistent health + hot-swap for
        # all sessions); fall back to a private one only if none was injected (e.g.
        # standalone/test construction). Either way all the _mcp_* call sites and
        # the dispatch routing read whatever this points at, live each turn.
        self.mcp = mcp_manager if mcp_manager is not None else MCPManager(logger=self._mcp_log)
        self.messages: list[dict] = []
        self.agent_messages: list[dict] = []  # unified agent context (replaces contexts + manager_context)
        self.contexts: dict[str, list[dict]] = {role: [] for role in AGENT_ROLES}  # kept as view caches
        self.manager_context: list[dict] = []  # kept as view cache
        self._last_mgr_bb_state_sig = ""  # Fix E: skip re-injecting unchanged blackboard md
        self._role_seen_bb_sig: dict[str, str] = {}  # Fix 3: per-role last-seen bb signature
        self.blackboard: dict = {}
        self.agent_bus_messages: list[dict] = []
        self.manager_routes: list[dict] = []
        self.active_agent_role = ""
        self.activity: list[dict] = []
        self.operations: list[dict] = []
        self.code_preview_index: dict[str, list[dict]] = {}
        self.uploads: list[dict] = []
        self.upload_parse_queue: queue.Queue[dict] = queue.Queue(maxsize=CHAT_UPLOAD_PARSE_QUEUE_MAX)
        self.upload_parse_worker_started = False
        self.upload_parse_worker_lock = threading.Lock()
        self.upload_parse_last_heartbeat = 0.0
        self.upload_parse_active_id = ""
        self.upload_parse_active_started_at = 0.0
        self.upload_ingest_queue: queue.Queue[dict] = queue.Queue(maxsize=CHAT_UPLOAD_INGEST_QUEUE_MAX)
        self.upload_ingest_worker_started = False
        self.upload_ingest_worker_lock = threading.Lock()
        self.runtime_code_reference_text = ""
        self.runtime_code_reference_meta: dict = {}
        self.runtime_knowledge_reference_text = ""
        self.runtime_knowledge_reference_meta: dict = {}
        self.teammates: dict[str, dict] = {}
        self.running = False
        self.scheduler_starting = False
        self.cancel_requested = False
        self.pending_user_inputs: list[dict] = []
        # ask_user pause/resume: pending question surfaced to the user (None when not
        # awaiting). _ask_user_pause_pending is the transient flag the run loops read
        # to break-and-pause without finalizing the run.
        self.pending_user_question: dict | None = None
        self._ask_user_pause_pending = False
        # Mid-run steering (Fix 3): set when a live user message is classified as
        # a steer (stop / change direction / redo), so the next round re-plans at
        # the top before the model call — a genuine instruction, not a diluted
        # background suggestion.
        self._steer_pending = False
        # Per-step acceptance quality-bar cache (Fix 5): step_id -> target dict.
        self._acceptance_target_cache: dict = {}
        self.live_input_queue_lock = threading.Lock()
        self.deferred_start_inputs: list[dict] = []
        self.deferred_start_seq = 0
        self.deferred_start_worker_started = False
        self.deferred_start_worker_lock = threading.Lock()
        self.scheduler_visible_inputs: list[dict] = []
        # Display-only ledger of genuine user-input bubbles. Compaction archives
        # old messages out of self.messages (and the snapshot window caps the
        # rest), which made earlier user turns disappear from the UI. This ledger
        # is rendered back into the conversation feed at snapshot time so user
        # bubbles always stay visible. It NEVER feeds the LLM context or any
        # compaction/planning logic — pure frontend retention.
        self.user_bubble_log: list[dict] = []
        self.run_generation = 0
        self.run_started_at = 0.0
        self.run_last_heartbeat = 0.0
        self.run_recovered_at = 0.0
        self.run_recovered_reason = ""
        self.live_input_seq = 0
        self.agent_round_index = 0
        self.current_phase = "idle"
        self.current_tool_name = ""
        self.runtime_task_level = 0
        self.user_task_level_override = 0
        self.runtime_execution_mode = ""
        self.runtime_assigned_expert = ""
        self.runtime_participants: list[str] = []
        self.multi_agent_context_hud_enabled = False
        self.runtime_round_budget = 0
        self.runtime_requires_confirmation = False
        self.runtime_confirmation_needed = False
        self.runtime_task_judgement = ""
        self.runtime_task_type = ""
        self.runtime_task_complexity = ""
        self.runtime_complexity_floor = ""
        self.runtime_task_level_floor = 0
