    def _looks_like_substantial_informative_reply(self, text: str) -> bool:
        raw = str(text or "")
        clean = strip_thinking_content(raw).strip()
        if not clean:
            return False
        if len(clean) < 110:
            return False
        low = clean.lower()
        if "```" in clean:
            return True
        bullet_count = len(
            re.findall(
                r"(?m)^\s*(?:[-*]|\d+\.)\s+\S+",
                clean,
            )
        )
        if bullet_count >= 2:
            return True
        section_count = len(re.findall(r"(?m)^\s{0,3}#{1,6}\s+\S+", clean))
        if section_count >= 1:
            return True
        informative_markers = [
            "here's what",
            "here is what",
            "what i built",
            "what was built",
            "changes made",
            "implemented",
            "created",
            "updated",
            "fixed",
            "completed",
            "summary",
            "已完成",
            "完成了",
            "修复了",
            "修改了",
            "实现了",
            "总结",
            "说明如下",
            "结果如下",
            "已完成",
            "修復了",
            "修改了",
            "實作了",
            "總結",
            "說明如下",
            "結果如下",
            "実装しました",
            "修正しました",
            "更新しました",
            "作成しました",
            "まとめ",
            "結果は以下",
        ]
        if any(x in low for x in informative_markers):
            return True
        path_like = bool(
            re.search(
                r"(?:/users/|[a-z]:\\\\|\.py\b|\.js\b|\.ts\b|\.html\b|\.css\b|\.md\b)",
                low,
            )
        )
        sentence_count = len(re.findall(r"[.!?。！？]", clean))
        return path_like and sentence_count >= 2

    def _looks_like_direct_question_request(self, text: str) -> bool:
        raw = str(text or "").strip()
        t = raw.lower()
        if not t:
            return False
        if len(t) <= 220 and ("?" in t or "？" in raw):
            return True
        if len(t) > 220:
            return False
        markers = [
            "是什么",
            "是什麼",
            "为什么",
            "為什麼",
            "怎么",
            "如何",
            "explain",
            "what is",
            "why",
            "how to",
            "difference",
            "差異",
            "とは",
            "なぜ",
            "どうやって",
            "どうすれば",
            "違い",
            "何ですか",
        ]
        return any(x in t for x in markers)

    def _todo_should_block_auto_continue(self, assistant_text: str = "") -> bool:
        if not self.todo.has_open_items():
            return False
        if self._looks_like_conclusive_reply(assistant_text):
            return False
        if self._looks_like_substantial_informative_reply(assistant_text):
            return False
        goal = self._latest_user_goal_text()
        if self._looks_like_direct_question_request(goal) and (not self._looks_nontrivial_request(goal)):
            return False
        return self._looks_nontrivial_request(goal)

    def _is_long_running_engineering_context(self) -> bool:
        goal = self._latest_user_goal_text()
        if not self._looks_nontrivial_request(goal):
            return False
        rows = self.todo.snapshot()
        if not rows:
            return False
        open_count = sum(1 for row in rows if str(row.get("status", "pending")) != "completed")
        active_count = sum(1 for row in rows if str(row.get("status", "pending")) == "in_progress")
        return open_count >= 2 or active_count >= 1

    def _detect_endpoint_intent(self, text: str, tool_calls: list | None = None) -> dict:
        if tool_calls:
            return {"matched": False, "score": 0, "reasons": ["tool-calls-present"]}
        raw = str(text or "")
        clean = strip_thinking_content(raw).strip()
        if not clean:
            return {"matched": False, "score": 0, "reasons": ["empty-content"]}
        score = 0
        reasons: list[str] = []
        if self._looks_like_conclusive_reply(clean):
            score += 4
            reasons.append("conclusive-marker")
        if self._looks_like_substantial_informative_reply(clean):
            score += 2
            reasons.append("substantial-reply")
        if "```" in clean:
            score += 2
            reasons.append("contains-code-block")
        if len(clean) >= 220:
            score += 1
            reasons.append("long-form-output")
        tail = clean[-220:].lower()
        endpoint_markers = [
            "希望这能帮到你",
            "解释如上",
            "代码已修改完毕",
            "请查看上述代码",
            "已完成",
            "all set",
            "ready to use",
            "as requested",
            "that is all",
            "希望這能幫到你",
            "說明如上",
            "程式碼已修改完成",
            "請查看上述程式碼",
            "完了しました",
            "以上です",
            "ご確認ください",
        ]
        if any(x in tail for x in endpoint_markers):
            score += 2
            reasons.append("endpoint-tail-marker")
        if self._looks_like_incomplete_reply(clean):
            score -= 3
            reasons.append("incomplete-marker")
        if self._looks_like_user_decision_needed(clean):
            score -= 3
            reasons.append("decision-needed")
        threshold = 4 if self._is_long_running_engineering_context() else 3
        return {
            "matched": bool(score >= threshold),
            "score": int(score),
            "threshold": int(threshold),
            "reasons": reasons[:6],
        }

    def _detect_no_tool_deliverable_intent(
        self,
        text: str,
        tool_calls: list | None = None,
    ) -> dict:
        """Classify a no-tool assistant reply as a possible final user deliverable.

        This is deliberately task-agnostic. A direct text answer, analysis,
        outline, draft, checklist, explanation, or generated snippet can be the
        requested output. Auto-continue should only preempt such replies when the
        assistant clearly promised additional concrete execution.
        """
        if tool_calls:
            return {"matched": False, "score": 0, "threshold": 0, "reasons": ["tool-calls-present"]}
        clean = strip_thinking_content(str(text or "")).strip()
        if not clean:
            return {"matched": False, "score": 0, "threshold": 0, "reasons": ["empty-content"]}
        score = 0
        reasons: list[str] = []
        endpoint = self._detect_endpoint_intent(clean, None)
        if bool(endpoint.get("matched", False)):
            score += 4
            reasons.append("endpoint-intent")
        if self._looks_like_substantial_informative_reply(clean):
            score += 3
            reasons.append("substantial-informative")
        if self._looks_like_conclusive_reply(clean):
            score += 3
            reasons.append("conclusive")
        if len(clean) >= 360:
            score += 2
            reasons.append("long-form-output")
        elif len(clean) >= 160:
            score += 1
            reasons.append("medium-form-output")
        section_count = len(re.findall(r"(?m)^\s{0,3}#{1,6}\s+\S+", clean))
        list_count = len(re.findall(r"(?m)^\s*(?:[-*]|\d+\.|#{1,6})\s*\S+", clean))
        if section_count >= 1:
            score += 1
            reasons.append("structured-sections")
        if list_count >= 3:
            score += 1
            reasons.append("structured-list")
        if self._looks_like_user_decision_needed(clean):
            score += 2
            reasons.append("awaits-user-choice")
        if self._looks_like_action_promise_without_tool(clean):
            score -= 5
            reasons.append("action-promise")
        elif self._looks_like_incomplete_reply(clean):
            score -= 4
            reasons.append("incomplete-marker")
        if self._is_long_running_engineering_context():
            score -= 2
            reasons.append("engineering-context")
        open_rows = self._completion_scoped_open_todo_rows(self._ensure_blackboard())
        if open_rows:
            score -= 3
            reasons.append("open-completion-todos")
        if self._manager_has_error_log(self._ensure_blackboard()):
            score -= 3
            reasons.append("blocking-error-log")
        threshold = 4
        return {
            "matched": bool(score >= threshold),
            "score": int(score),
            "threshold": int(threshold),
            "reasons": reasons[:8],
            "endpoint": endpoint,
        }

    def _infer_arbiter_status_from_text(self, text: str) -> str:
        low = str(text or "").strip().lower()
        if not low:
            return ""
        if any(
            x in low
            for x in [
                "user_input_required",
                "user input required",
                "user_required",
                "needs_user_input",
                "needs user input",
                "need user input",
                "waiting_for_user",
                "waiting for user",
                "requires user",
                "ask user",
                "需要用户输入",
                "需要用戶輸入",
                "需要用户确认",
                "需要用戶確認",
                "等待用户",
                "等待用戶",
                "ユーザー入力が必要",
                "ユーザー確認が必要",
            ]
        ):
            return "USER_INPUT_REQUIRED"
        if any(
            x in low
            for x in [
                "task_completed",
                "task completed",
                "已完成",
                "完成",
                "已完成了",
                "done",
                "completed",
                "finished",
                "任務完成",
                "完了",
                "完了しました",
            ]
        ):
            return "TASK_COMPLETED"
        if any(
            x in low
            for x in [
                "action_required",
                "action required",
                "tool_required",
                "tool required",
                "execute_tool",
                "execute tool",
                "needs tool",
                "needs_action",
                "needs action",
                "需要工具",
                "需要执行",
                "需要執行",
                "需要動作",
                "工具が必要",
                "実行が必要",
            ]
        ):
            return "ACTION_REQUIRED"
        if any(
            x in low
            for x in [
                "valid_planning",
                "valid planning",
                "plan",
                "planning",
                "next step",
                "analysis",
                "计划",
                "計畫",
                "规划",
                "規劃",
                "下一步",
                "分析",
                "計画",
                "次のステップ",
            ]
        ):
            return "VALID_PLANNING"
        if any(
            x in low
            for x in [
                "empty_rambling",
                "empty rambling",
                "rambling",
                "idle",
                "stalled",
                "hallucination",
                "空想",
                "停滞",
                "停滯",
                "だらだら",
            ]
        ):
            return "EMPTY_RAMBLING"
        return ""

    def _normalize_arbiter_status(self, raw_status: str, fallback_text: str = "") -> str:
        key = str(raw_status or "").strip().upper().replace("-", "_").replace(" ", "_")
        aliases = {
            "TASK_COMPLETE": "TASK_COMPLETED",
            "COMPLETED": "TASK_COMPLETED",
            "DONE": "TASK_COMPLETED",
            "VALID_PLAN": "VALID_PLANNING",
            "PLANNING": "VALID_PLANNING",
            "PLAN": "VALID_PLANNING",
            "ACTION": "ACTION_REQUIRED",
            "REQUIRES_ACTION": "ACTION_REQUIRED",
            "NEEDS_ACTION": "ACTION_REQUIRED",
            "TOOL_REQUIRED": "ACTION_REQUIRED",
            "NEEDS_TOOL": "ACTION_REQUIRED",
            "EXECUTE_TOOL": "ACTION_REQUIRED",
            "USER_INPUT": "USER_INPUT_REQUIRED",
            "USER_REQUIRED": "USER_INPUT_REQUIRED",
            "USER_CONFIRMATION_REQUIRED": "USER_INPUT_REQUIRED",
            "NEEDS_USER_INPUT": "USER_INPUT_REQUIRED",
            "WAITING_FOR_USER": "USER_INPUT_REQUIRED",
            "ASK_USER": "USER_INPUT_REQUIRED",
            "EMPTY": "EMPTY_RAMBLING",
            "RAMBLING": "EMPTY_RAMBLING",
            "IDLE": "EMPTY_RAMBLING",
        }
        status = aliases.get(key, key)
        if status in {"TASK_COMPLETED", "ACTION_REQUIRED", "VALID_PLANNING", "USER_INPUT_REQUIRED", "EMPTY_RAMBLING"}:
            return status
        inferred = self._infer_arbiter_status_from_text(fallback_text)
        return inferred or ""

    def _arbiter_context_snapshot(self, assistant_text: str, thinking_text: str = "") -> dict:
        rows = self.todo.snapshot()
        open_count = sum(1 for x in rows if str(x.get("status", "pending")) != "completed")
        in_progress_count = sum(1 for x in rows if str(x.get("status", "pending")) == "in_progress")
        active_rows = []
        for row in rows:
            if str(row.get("status", "pending")) != "in_progress":
                continue
            content = normalize_work_text(row.get("content", ""), "in_progress") or str(row.get("content", "")).strip()
            if content:
                active_rows.append(trim(content, 140))
            if len(active_rows) >= 3:
                break
        snapshot = {
            "goal": self._latest_user_goal_text(),
            "todo_open_count": int(open_count),
            "todo_in_progress_count": int(in_progress_count),
            "todo_active": active_rows,
            "assistant_reply": trim(strip_thinking_content(str(assistant_text or "")).strip(), 2200),
            "assistant_thinking": trim(str(thinking_text or "").strip(), 700),
            "agent_round_index": int(self.agent_round_index),
        }
        # Inject plan step progress so arbiter knows overall completion state
        bb = self._ensure_blackboard()
        plan_todos = bb.get("project_todos", [])
        plan_steps = [t for t in plan_todos if t.get("category") == "plan_step"]
        if plan_steps:
            completed = len([t for t in plan_steps if t.get("status") == "completed"])
            total = len(plan_steps)
            snapshot["plan_progress"] = f"{completed}/{total} steps completed"
            snapshot["approved_plan_unfinished"] = bool(completed < total)
            active_step = self._get_active_plan_step(bb)
            if isinstance(active_step, dict) and active_step:
                snapshot["active_plan_step"] = {
                    "id": trim(str(active_step.get("id", "") or ""), 40),
                    "content": trim(str(active_step.get("content", "") or ""), 240),
                    "status": trim(str(active_step.get("status", "") or ""), 40),
                }
            if completed < total:
                snapshot["plan_warning"] = (
                    f"IMPORTANT: Only {completed}/{total} plan steps are completed. "
                    "Do NOT classify as TASK_COMPLETED unless ALL steps are done."
                )
        return snapshot

    def _build_arbiter_client(self) -> OllamaClient:
        client = OllamaClient(self.ollama.base_url, self.ollama.model)
        active_profile = dict(self.model_profiles.get(self.active_profile_id, {}))
        if active_profile:
            try:
                client.apply_profile(active_profile)
            except Exception:
                pass
        model_override = str(self.arbiter_model or "").strip()
        if model_override:
            client.model = model_override
        client.thinking_stream = False
        client.timeout = max(0.2, float(self.arbiter_timeout_seconds or ARBITER_DEFAULT_TIMEOUT_SECONDS))
        return client

    def _call_arbiter_llm(self, assistant_text: str, thinking_text: str = "", *, force: bool = False) -> dict:
        clean = strip_thinking_content(str(assistant_text or "")).strip()
        thinking_clean = str(thinking_text or "").strip()
        if not self.arbiter_enabled:
            return {"status": "DISABLED", "reasoning": "arbiter disabled", "raw": ""}
        probe_len = max(len(clean), len(thinking_clean))
        if (
            not force
            and
            probe_len < int(ARBITER_TRIGGER_MIN_CONTENT_CHARS)
            and not self._looks_like_action_promise_without_tool(f"{clean}\n{thinking_clean}")
        ):
            return {"status": "SKIP_SHORT", "reasoning": "content too short", "raw": ""}
        snapshot = self._arbiter_context_snapshot(clean, thinking_text)
        arbiter_system = (
            "You are a task-state arbiter. "
            "Classify worker output into exactly one status: "
            "TASK_COMPLETED, ACTION_REQUIRED, VALID_PLANNING, USER_INPUT_REQUIRED, or EMPTY_RAMBLING. "
            "Return strict JSON only."
        )
        arbiter_user = (
            "Read the snapshot and classify the worker state.\n"
            "Status definitions:\n"
            "- TASK_COMPLETED: worker already completed user's target and gave final deliverable/summary.\n"
            "- ACTION_REQUIRED: worker has decided or promised to create/write/modify/run/verify something, or thinking contains a concrete next tool action, but no tool call was emitted.\n"
            "- ACTION_REQUIRED also applies when an approved plan is unfinished and the worker only asks for routine confirmation, routine plan advancement, Todo updates, evidence collection, or verification instead of using a tool.\n"
            "- VALID_PLANNING: worker output is useful high-level analysis or design that still needs more reasoning before a concrete tool action.\n"
            "- USER_INPUT_REQUIRED: worker is genuinely blocked by missing external information, a subjective user choice, credentials, permissions, or a requirement decision that cannot be inferred from the current goal/plan.\n"
            "- Do not use USER_INPUT_REQUIRED for routine approved-plan advancement or ordinary self-management; those are ACTION_REQUIRED.\n"
            "- EMPTY_RAMBLING: worker is stalling, repeating, or hallucinating with no actionable progress.\n"
            "Prefer ACTION_REQUIRED over VALID_PLANNING when the next step is already a concrete artifact/action.\n"
            "Output JSON only:\n"
            "{\"status\":\"TASK_COMPLETED|ACTION_REQUIRED|VALID_PLANNING|USER_INPUT_REQUIRED|EMPTY_RAMBLING\",\"reasoning\":\"<=40 words\"}\n\n"
            f"Snapshot:\n{json_dumps(snapshot, indent=2)}"
        )
        box: dict[str, object] = {}

        def _runner():
            try:
                arbiter_client = self._build_arbiter_client()
                rsp = arbiter_client.chat(
                    [{"role": "user", "content": arbiter_user}],
                    system=arbiter_system,
                    max_tokens=int(self.arbiter_max_tokens),
                    temperature=float(self.arbiter_temperature),
                    think=False,
                    stream_thinking=False,
                )
                box["rsp"] = rsp
            except Exception as exc:
                box["error"] = exc

        thread = threading.Thread(target=_runner, daemon=True)
        thread.start()
        thread.join(timeout=max(0.2, float(self.arbiter_timeout_seconds or ARBITER_DEFAULT_TIMEOUT_SECONDS)))
        if thread.is_alive():
            return {"status": "ARBITER_TIMEOUT", "reasoning": "arbiter timeout", "raw": ""}
        err = box.get("error")
        if isinstance(err, Exception):
            return {"status": "ARBITER_ERROR", "reasoning": trim(str(err), 220), "raw": ""}
        rsp = box.get("rsp") if isinstance(box.get("rsp"), dict) else {}
        raw_content = trim(str((rsp or {}).get("content", "") or ""), 2000)
        raw_thinking = trim(str((rsp or {}).get("thinking", "") or ""), 1200)
        status_source = raw_content or raw_thinking
        payload = extract_json_object_from_text(raw_content, {})
        if not payload and raw_thinking:
            payload = extract_json_object_from_text(raw_thinking, {})
        status = self._normalize_arbiter_status(str(payload.get("status", "") or ""), status_source)
        if not status:
            status = self._infer_arbiter_status_from_text(status_source)
        if (
            (not status or status == "UNKNOWN")
            and self._looks_like_action_promise_without_tool(f"{clean}\n{thinking_clean}\n{status_source}")
        ):
            status = "ACTION_REQUIRED"
        reasoning = trim(
            str(payload.get("reasoning", payload.get("reason", "")) or ""),
            280,
        ) or trim(status_source, 280)
        return {
            "status": status or "UNKNOWN",
            "reasoning": reasoning,
            "raw": raw_content,
            "raw_thinking": raw_thinking,
            "model": str(self.arbiter_model or self.ollama.model or "").strip(),
        }

    def _inject_arbiter_continue_hint(self, decision: dict):
        reasoning = trim(str(decision.get("reasoning", "") or "").strip(), 180)
        self._prune_runtime_retry_hints()
        self.messages.append(
            {
                "role": "user",
                "content": (
                    "<arbiter-continue>"
                    "系统仲裁判定：当前回复属于有效计划。请立即推进执行：下一轮必须调用一个具体工具，"
                    "不要重复口头计划，不要新增无意义 Todo。"
                    f"{(' 判定依据: ' + reasoning + '。') if reasoning else ''}"
                    "</arbiter-continue>"
                ),
                "ts": now_ts(),
            }
        )

    def _inject_arbiter_action_required_hint(self, decision: dict, assistant_text: str = ""):
        reasoning = trim(str(decision.get("reasoning", "") or "").strip(), 180)
        latest = trim(strip_thinking_content(str(assistant_text or "")).strip(), 420)
        self._prune_runtime_retry_hints()
        self.messages.append(
            {
                "role": "user",
                "content": (
                    "<arbiter-continue>"
                    "系统仲裁判定：当前回复已经到了需要执行工具的阶段，但没有发出工具调用。"
                    "下一轮必须只调用一个具体工具来推进，例如 write_file/edit_file/bash/read_file/check_background；"
                    "如果确实已经完成，则调用 finish_task 并提供文件路径和验证证据。不要再输出计划性说明。"
                    f"{(' 判定依据: ' + reasoning + '。') if reasoning else ''}"
                    f"{(' 上一条文本: ' + latest) if latest else ''}"
                    "</arbiter-continue>"
                ),
                "ts": now_ts(),
            }
        )

    def _mark_all_done_silently(self, reason: str = "") -> dict:
        summary = trim(str(reason or "").strip(), 160) or "arbiter: task completed"
        # Protect plan_step todos — they must only be completed by _advance_plan_step
        bb = self._ensure_blackboard()
        plan_todos = bb.get("project_todos", [])
        saved_plan_steps: dict[str, dict] = {}
        for t in plan_todos:
            if t.get("category") == "plan_step" and t.get("status") != "completed":
                saved_plan_steps[str(t.get("id", ""))] = {
                    "status": t.get("status", "pending"),
                    "completed_at": t.get("completed_at"),
                    "completed_by": t.get("completed_by", ""),
                    "evidence": t.get("evidence", ""),
                }
        result = self.todo.complete_all_open(summary)
        # Restore plan_step todos to their original state
        if saved_plan_steps:
            bb = self._ensure_blackboard()
            for t in bb.get("project_todos", []):
                tid = str(t.get("id", ""))
                if tid in saved_plan_steps:
                    t["status"] = saved_plan_steps[tid]["status"]
                    t["completed_at"] = saved_plan_steps[tid]["completed_at"]
                    t["completed_by"] = saved_plan_steps[tid]["completed_by"]
                    t["evidence"] = saved_plan_steps[tid]["evidence"]
            self.blackboard = bb
            self._sync_todos_from_blackboard(reason="plan-step-restore")
        updated = int(result.get("updated", 0) or 0)
        total = int(result.get("total", 0) or 0)
        pending_steps = len(saved_plan_steps)
        self._prune_runtime_retry_hints()
        self._emit(
            "status",
            {
                "summary": (
                    f"arbiter marked task completed; todos completed={updated}/{total}"
                    + (f"; {pending_steps} plan steps protected (still pending)" if pending_steps else "")
                )
            },
        )
        return result

    def _generate_run_completion_summary(self):
        """Generate a brief summary bubble when a run completes, so user isn't left without feedback."""
        if not RUN_COMPLETION_SUMMARY_ENABLED:
            return
        if self.cancel_requested:
            return
        bb = self._ensure_blackboard()
        plan = bb.get("plan", {}) if isinstance(bb.get("plan"), dict) else {}
        plan_phase = str(plan.get("phase", "") or "").strip().lower()
        proposal_waiting = bool(self.runtime_plan_proposal) and not bool(self.runtime_plan_approved)
        board_has_proposal = isinstance(plan.get("proposal"), dict) and bool(plan.get("proposal"))
        # Guard: plan mode paused for user selection or still in intermediate planning phases
        if (
            (plan_phase in {"awaiting_choice", "research", "synthesis"} and not self.runtime_plan_approved)
            or proposal_waiting
            or (plan_phase == "awaiting_choice" and board_has_proposal)
        ):
            return
        # Guard: approved-plan execution uses its own plan/todo progress UI; avoid redundant completion bubble
        if self.runtime_plan_approved or plan_phase == "executing":
            return
        # Guard: in single-agent mode the developer already replied directly — no redundant summary
        _exec_mode = self._effective_execution_mode()
        if _exec_mode == EXECUTION_MODE_SINGLE:
            for _m in reversed(self.messages[-20:]):
                if not isinstance(_m, dict):
                    continue
                _r = str(_m.get("role", "") or "")
                _ar = str(_m.get("agent_role", "") or "")
                if _r == "assistant" and _ar not in ("manager", "planner", ""):
                    return
        _summary_role = "developer"
        try:
            board_md = self._blackboard_read_state_markdown(max_items=10)
            # Collect completed plan steps
            plan_steps = [t for t in bb.get("project_todos", []) if t.get("category") == "plan_step"]
            completed = [t for t in plan_steps if t.get("status") == "completed"]
            pending = [t for t in plan_steps if t.get("status") != "completed"]
            # Collect recent file operations from step_files
            step_files = bb.get("step_files", {})
            file_list = []
            for _sf_key, entries in (step_files.items() if isinstance(step_files, dict) else []):
                if isinstance(entries, list):
                    for e in entries[-5:]:
                        fp = str(e.get("path", "") if isinstance(e, dict) else e or "").strip()
                        if fp:
                            file_list.append(fp)
            file_list = list(dict.fromkeys(file_list))[-10:]  # Dedupe, last 10
            # Build context for LLM summary
            goal = trim(str(bb.get("original_goal", "") or self.runtime_reclassify_goal or ""), 600)
            lang_hint = model_language_instruction(self.ui_language)
            parts = [f"GOAL: {goal}"] if goal else []
            if completed:
                parts.append(f"COMPLETED STEPS ({len(completed)}/{len(plan_steps)}):")
                for t in completed:
                    idx = int(t.get("plan_step_index", 0) or 0) + 1
                    parts.append(f"  ✅ {idx}. {trim(str(t.get('content', '')), 100)}")
            if pending:
                parts.append(f"REMAINING ({len(pending)}):")
                for t in pending[:3]:
                    idx = int(t.get("plan_step_index", 0) or 0) + 1
                    parts.append(f"  ⬜ {idx}. {trim(str(t.get('content', '')), 100)}")
            if file_list:
                parts.append(f"FILES CREATED/MODIFIED: {', '.join(file_list[:8])}")
            if board_md:
                parts.append(f"BLACKBOARD STATE:\n{trim(board_md, 800)}")
            context = "\n".join(parts)
            # --- Supplement context from messages history when plan steps are unavailable ---
            # (pure sync mode: no plan steps, so file_list/ops may be empty above)
            files_from_msgs: list[str] = []
            ops_from_msgs: list[str] = []
            agent_conclusion = ""
            for _m in self.messages[-60:]:
                if not isinstance(_m, dict):
                    continue
                _role = _m.get("role", "")
                # file_patch type → extract file location
                if _m.get("type") == "file_patch":
                    _loc = str(_m.get("location", "") or _m.get("path", "") or "").strip()
                    if _loc and _loc not in files_from_msgs:
                        files_from_msgs.append(_loc)
                # command output → capture brief preview
                if _m.get("type") == "command" and _role == "system":
                    _cmd = trim(str(_m.get("content", "") or ""), 120)
                    if _cmd:
                        ops_from_msgs.append(_cmd)
                # last non-manager/non-planner assistant reply → agent self-description
                if _role == "assistant" and str(_m.get("agent_role", "") or "") not in ("manager", "planner"):
                    _txt = str(_m.get("content", "") or "").strip()
                    if _txt:
                        agent_conclusion = trim(_txt, 400)
            # Merge: use message-derived file list only when step_files gave nothing
            if not file_list and files_from_msgs:
                file_list = files_from_msgs[:8]
            # Append agent conclusion and bash ops to context if not already present
            if agent_conclusion and "AGENT LAST OUTPUT" not in context:
                context += f"\nAGENT LAST OUTPUT:\n{agent_conclusion}"
            if ops_from_msgs and "BASH OPS" not in context:
                context += f"\nBASH OPS (last {min(3, len(ops_from_msgs))}):\n" + "\n".join(ops_from_msgs[-3:])
            # ---
            prompt = (
                f"{lang_hint}\n"
                "Generate a BRIEF completion summary for the user (3-8 sentences).\n"
                "Include: what was accomplished, key files created, and any remaining work.\n"
                "Use markdown formatting. Be concise and informative.\n"
                f"Do NOT include code blocks unless essential.\n\n"
                f"CONTEXT:\n{context}"
            )
            rsp = self.ollama.chat(
                [{"role": "user", "content": prompt}],
                system=self._inject_runtime_environment_context("Generate a concise user-visible completion summary."),
                max_tokens=800,
                temperature=0.3,
            )
            summary_text = str(rsp.get("content", "") or "").strip()
            if not summary_text or len(summary_text) < 10:
                summary_text = self._generate_static_completion_summary(
                    completed, pending, file_list, goal, agent_text=agent_conclusion
                )
            self.messages.append({
                "role": "assistant",
                "content": summary_text,
                "ts": now_ts(),
                "agent_role": _summary_role,
            })
            self._emit("message", {
                "role": "assistant",
                "text": trim(summary_text, int(ASSISTANT_MESSAGE_EVENT_MAX_CHARS)),
                "summary": "run completion summary",
                "agent_role": _summary_role,
            })
        except Exception:
            try:
                bb = self._ensure_blackboard()
                plan_steps = [t for t in bb.get("project_todos", []) if t.get("category") == "plan_step"]
                completed = [t for t in plan_steps if t.get("status") == "completed"]
                pending = [t for t in plan_steps if t.get("status") != "completed"]
                goal = trim(str(bb.get("original_goal", "") or ""), 200)
                summary_text = self._generate_static_completion_summary(completed, pending, [], goal)
                self.messages.append({
                    "role": "assistant",
                    "content": summary_text,
                    "ts": now_ts(),
                    "agent_role": _summary_role,
                })
                self._emit("message", {
                    "role": "assistant",
                    "text": trim(summary_text, int(ASSISTANT_MESSAGE_EVENT_MAX_CHARS)),
                    "summary": "run completion summary (static)",
                    "agent_role": _summary_role,
                })
            except Exception:
                pass

    def _generate_static_completion_summary(
        self,
        completed: list[dict],
        pending: list[dict],
        file_list: list[str],
        goal: str,
        agent_text: str = "",
    ) -> str:
        """Static fallback summary when LLM call fails."""
        lines = ["## ✅ 任务执行完成\n"]
        if goal:
            lines.append(f"**目标：** {trim(goal, 200)}\n")
        total = len(completed) + len(pending)
        if completed:
            lines.append(f"**进度：** {len(completed)}/{total} 步骤已完成")
            for t in completed[-5:]:
                idx = int(t.get("plan_step_index", 0) or 0) + 1
                lines.append(f"- ✅ {idx}. {trim(str(t.get('content', '')), 80)}")
        if pending:
            lines.append(f"\n**待完成：** {len(pending)} 步骤")
            for t in pending[:3]:
                idx = int(t.get("plan_step_index", 0) or 0) + 1
                lines.append(f"- ⬜ {idx}. {trim(str(t.get('content', '')), 80)}")
        # When no plan steps exist (pure sync mode), show agent conclusion text instead
        if not completed and agent_text:
            lines.append(f"\n**执行摘要：** {trim(agent_text, 300)}")
        if file_list:
            lines.append(f"\n**涉及文件：** {', '.join(file_list[:6])}")
        return "\n".join(lines)

    def _should_soft_pause_no_action(self, assistant_text: str, tool_calls: list | None = None) -> bool:
        if tool_calls:
            return False
        clean = strip_thinking_content(str(assistant_text or "")).strip()
        if not clean:
            return False
        if bool(self.arbiter_enabled):
            return False
        if len(clean) >= 100 or self._looks_nontrivial_request(clean):
            return True
        if self._is_long_running_engineering_context():
            return False
        if self._looks_like_incomplete_reply(clean):
            return False
        return True

    def _todo_active_brief(self) -> str:
        rows = self.todo.snapshot()
        if not rows:
            return self._ui_text("todo_no_todos")
        active = []
        open_count = 0
        done_count = 0
        for row in rows:
            status = str(row.get("status", "pending"))
            content = normalize_work_text(row.get("content", ""), status) or str(row.get("content", "")).strip()
            if status == "completed":
                done_count += 1
            else:
                open_count += 1
            if status == "in_progress":
                active.append(trim(content or "(empty todo)", 140))
        if active:
            lines = [f"Active todos ({len(active)}):"]
            for item in active[:3]:
                lines.append(f"- {item}")
            lines.append(f"Open={open_count}, Completed={done_count}")
            return "\n".join(lines)
        return f"No active in_progress todo. Open={open_count}, Completed={done_count}"

    def clear_stale_todos(self) -> dict:
        result = self.todo.clear_all()
        self.rounds_without_todo = 0
        self.todo_reminder_count = 0
        self.todo_write_issue_count = 0
        self.todo_last_issue = ""
        removed_plan_fragments: list[str] = []
        bb = self._ensure_blackboard()
        if isinstance(bb.get("project_todos"), list):
            cleaned_todos, changed, removed_plan_fragments = self._sanitize_project_plan_todos(bb.get("project_todos", []))
            if changed:
                bb["project_todos"] = cleaned_todos
                bb["plan_step_total"] = len([
                    t for t in cleaned_todos
                    if isinstance(t, dict) and t.get("category") == "plan_step"
                ])
                plan = bb.get("plan", {}) if isinstance(bb.get("plan"), dict) else {}
                if isinstance(plan.get("steps"), list):
                    plan["steps"] = self._group_plan_steps(plan.get("steps", []))
                    bb["plan"] = plan
                self.blackboard = bb
        repair_result: dict = {}
        if self._has_resumable_plan_state():
            try:
                repair_result = self._maybe_prompt_plan_resume_repair(
                    reason="clear-stale-todos",
                )
            except Exception as exc:
                repair_result = {"issue": False, "reason": f"repair-prompt-error:{trim(str(exc), 120)}"}
        self.updated_at = now_ts()
        self._persist()
        self._emit(
            "status",
            {
                "summary": (
                    "stale todos cleared by user "
                    f"(removed={int(result.get('removed', 0) or 0)}, "
                    f"open_removed={int(result.get('open_removed', 0) or 0)})"
                )
            },
        )
        return {
            "ok": True,
            **result,
            "repair": repair_result,
            "removed_plan_fragments": removed_plan_fragments[:8],
        }

    def _is_empty_action_turn(self, text: str, thinking_text: str, tool_calls: list | None = None) -> bool:
        if tool_calls:
            return False
        raw = str(text or "")
        body = strip_thinking_content(raw).strip()
        if len(body) >= int(EMPTY_ACTION_MIN_CONTENT_CHARS):
            return False
        thinking = str(thinking_text or "").strip()
        raw_low = raw.lower()
        has_think_marker = ("<think" in raw_low) or ("<|start_of_thought|>" in raw_low)
        if thinking or has_think_marker:
            return True
        return not body

    def _is_thinking_budget_exhausted(
        self,
        text: str,
        thinking_text: str,
        tool_calls: list | None = None,
        output_tokens: int = 0,
    ) -> bool:
        if tool_calls:
            return False
        if not self._is_empty_action_turn(text, thinking_text, tool_calls):
            return False
        if not str(thinking_text or "").strip():
            return False
        threshold = int(max(1, self.max_output_tokens) * float(THINKING_BUDGET_FORCE_RATIO))
        return int(output_tokens or 0) >= max(1, threshold)

    def _is_thinking_only_dead_turn(self, text: str, thinking_text: str, tool_calls: list | None = None) -> bool:
        if self._is_empty_action_turn(text, thinking_text, tool_calls):
            return True
        if tool_calls:
            return False
        body = strip_thinking_content(str(text or "")).strip()
        thinking = str(thinking_text or "").strip()
        return len(body) < int(EMPTY_ACTION_MIN_CONTENT_CHARS) and len(thinking) >= 80

    def _clear_live_thinking(self):
        with self.lock:
            self.live_thinking_text = ""
            self.live_thinking_last_emit = 0.0

    def _clear_live_response(self):
        stream_id = ""
        with self.lock:
            stream_id = str(self.live_response_stream_id or "")
            self.live_response_text = ""
            self.live_response_role = ""
            self.live_response_label = ""
            self.live_response_visible = False
            self.live_response_last_emit = 0.0
            self.live_response_stream_id = ""
            self.updated_at = now_ts()
        if stream_id:
            self._emit(
                "response_delta",
                {
                    "summary": "response streaming cleared",
                    "active": False,
                    "stream_id": stream_id,
                },
            )

    def _begin_live_response(self, *, context_label: str = "", visible: bool = True) -> tuple[str, str]:
        role = self._sanitize_agent_bubble_role(self.active_agent_role) or self._sanitize_agent_bubble_role(
            str(context_label or "").split(" ", 1)[0]
        )
        if not role:
            role = "single" if self._effective_execution_mode() == EXECUTION_MODE_SINGLE else ""
        stream_id = make_id("resp")
        with self.lock:
            self.live_response_text = ""
            self.live_response_role = role
            self.live_response_label = trim(str(context_label or "model response"), 120)
            self.live_response_visible = bool(visible)
            self.live_response_last_emit = 0.0
            self.live_response_stream_id = stream_id
            self.updated_at = now_ts()
        return stream_id, role

    def _append_live_response_delta(self, chunk: str, *, context_label: str = "", visible: bool = True):
        piece = str(chunk or "")
        if not piece:
            return
        now_tick = now_ts()
        with self.lock:
            if self.cancel_requested or (not self.running):
                return
            if not self.live_response_stream_id:
                self._begin_live_response(context_label=context_label, visible=visible)
            self.live_response_visible = bool(visible)
            if context_label:
                self.live_response_label = trim(str(context_label), 120)
            self.live_response_text = (self.live_response_text + piece)[-48_000:]
            self.updated_at = now_tick
            should_emit = (now_tick - self.live_response_last_emit) >= 0.12
            if should_emit:
                self.live_response_last_emit = now_tick
                payload = {
                    "summary": "response streaming",
                    "active": True,
                    "visible": bool(self.live_response_visible),
                    "stream_id": self.live_response_stream_id,
                    "agent_role": self.live_response_role,
                    "label": self.live_response_label,
                    "size": len(self.live_response_text),
                    "text": self.live_response_text[-4000:] if self.live_response_visible else "",
                }
            else:
                payload = None
        if payload:
            self._emit("response_delta", payload)

    def _append_live_thinking(self, chunk: str):
        piece = str(chunk or "").strip()
        if not piece:
            return
        now_tick = now_ts()
        with self.lock:
            if self.cancel_requested or (not self.running):
                return
            self.live_thinking_text = (self.live_thinking_text + ("\n" if self.live_thinking_text else "") + piece)[-24_000:]
            self.updated_at = now_tick
            should_emit = (now_tick - self.live_thinking_last_emit) >= 0.35
            if should_emit:
                self.live_thinking_last_emit = now_tick
        if should_emit:
            self._emit(
                "thinking_delta",
                {
                    "summary": "thinking streaming",
                    "size": len(self.live_thinking_text),
                },
            )

    def _looks_nontrivial_request(self, text: str) -> bool:
        t = (text or "").strip().lower()
        if not t:
            return False
        if len(t) >= 120:
            return True
        markers = [
            # Engineering / development
            "实现", "修复", "重构", "设计", "构建", "架构", "内核", "框架",
            "死循环", "状态机", "调度", "后端", "前端", "自动化",
            "agentbus", "watchdog", "decomposition", "workflow",
            "architecture", "build", "implement", "refactor", "fix", "debug",
            "multi-step",
            # Documents / presentations / design deliverables
            "ppt", "pptx", "演示文稿", "幻灯片", "presentation",
            "生成报告", "制作", "做一个",
            "excel", "xlsx", "电子表格", "docx", "word",
            "pdf", "可视化", "visualization", "dashboard",
            "svg", "canvas", "动画", "animation",
            # Full-stack / deployment
            "api", "server", "数据库", "database", "部署", "deploy",
            "docker", "mcp", "agent", "bot", "爬虫", "crawler",
            "测试", "test", "playwright",
            # Brand / content
            "品牌", "brand", "theme", "gif",
            # Generic high-complexity task verbs
            "分析并", "总结并", "对比", "深度",
        ]
        return any(x in t for x in markers)

    def _llm_classify_task_complexity(self, goal_text: str) -> str:
        """LLM semantic pre-screening: classify task into 4 complexity bands via 4-dimension analysis. 5s timeout."""
        goal = trim(str(goal_text or ""), 400)
        if not goal or len(goal) < 6:
            return "simple"
        import threading
        result_box = ["simple"]
        def _classify():
            try:
                rsp = self.ollama.chat(
                    [{"role": "user", "content": (
                        f"/no_think\nRate this task on 4 dimensions (1=low 2=med 3=high), then classify.\n\n"
                        f"Task: {goal}\n\n"
                        f"SCOPE: how many files/components/systems are touched?\n"
                        f"STEPS: how many distinct execution steps are needed?\n"
                        f"SKILL: does it need specialized tools, skills, research, or APIs?\n"
                        f"OUTPUT: what is expected (1=text answer, 2=single file, 3=system/multi-file)?\n\n"
                        f"Output exactly one line:\n"
                        f"SCOPE:N STEPS:N SKILL:N OUTPUT:N VERDICT:SIMPLE|MODERATE|COMPLEX|EXPERT"
                    )}],
                    system=self._inject_runtime_environment_context("/no_think\nAnalyze task dimensions. One line output only."),
                    max_tokens=40,
                    think=False,
                )
                answer = str(rsp.get("content", "") or "").strip().upper()
                # Parse dimension scores
                dims: dict = {}
                for dim in ("SCOPE", "STEPS", "SKILL", "OUTPUT"):
                    m = re.search(rf"{dim}:(\d)", answer)
                    if m:
                        dims[dim.lower()] = int(m.group(1))
                if dims:
                    self._cached_complexity_dimensions = dims
                    vals = [int(v) for v in dims.values()]
                    max_dim = max(vals) if vals else 1
                    count_ge2 = sum(1 for v in vals if int(v) >= 2)
                    count_ge3 = sum(1 for v in vals if int(v) >= 3)
                    if max_dim <= 1:
                        result_box[0] = "simple"
                    elif max_dim == 2:
                        result_box[0] = "moderate"
                    elif count_ge3 >= 2 or count_ge2 >= 4:
                        result_box[0] = "expert"
                    else:
                        result_box[0] = "complex"
                if "VERDICT:EXPERT" in answer:
                    result_box[0] = "expert"
                elif "VERDICT:COMPLEX" in answer:
                    result_box[0] = "complex"
                elif "VERDICT:MODERATE" in answer:
                    result_box[0] = "moderate"
                elif "VERDICT:SIMPLE" in answer:
                    result_box[0] = "simple"
            except Exception:
                pass
        t = threading.Thread(target=_classify, daemon=True)
        t.start()
        t.join(timeout=5.0)
        return result_box[0]

    def _infer_task_profile(self, goal: str) -> dict:
        clean = strip_thinking_content(str(goal or "")).strip()
        low = clean.lower()
        explicit_complexity = infer_user_complexity_value(clean)
        # Use cached LLM complexity result (set by _agent_worker entry point)
        llm_complexity = normalize_task_complexity(str(getattr(self, '_cached_llm_complexity', '') or ''), default="simple")
        nontrivial = self._looks_nontrivial_request(clean) or task_complexity_at_least(llm_complexity, "moderate")
        direct_question = self._looks_like_direct_question_request(clean) and (not task_complexity_at_least(llm_complexity, "moderate"))
        code_markers = [
            # Coding / programming
            "代码", "寫代碼", "写代码", "脚本", "模块", "函数", "class", "bug",
            "修复", "实现", "重构", "app.py", "crawler.py",
            ".py", ".js", ".ts", ".html", ".css", ".vue", ".jsx", ".tsx",
            "python", "javascript", "bash", "terminal", "tool", "patch", "edit",
            "write_file", "read_file", "build", "implement", "fix", "refactor", "debug",
            # Document / presentation generation, usually skill-backed
            "ppt", "pptx", "演示文稿", "幻灯片", "presentation", "slide",
            "生成ppt", "制作ppt", "做ppt", "做一个ppt",
            "excel", "xlsx", "电子表格", "spreadsheet", "表格",
            "docx", "word", "文档", "document", "报告", "report",
            "pdf", "生成pdf", "制作pdf",
            # Design / frontend / visualization
            "html报告", "可视化", "visualization", "图表", "chart", "dashboard",
            "前端", "frontend", "ui", "界面", "landing page", "网页", "页面",
            "svg", "canvas", "动画", "animation", "设计",
            # Systems / architecture
            "api", "server", "服务", "数据库", "database", "部署", "deploy",
            "docker", "容器", "微服务", "microservice", "架构",
            "mcp", "agent", "bot", "爬虫", "crawler", "scraper",
            # Testing
            "测试", "test", "单元测试", "集成测试", "playwright", "selenium",
            # Brand / content
            "品牌", "brand", "logo", "主题", "theme",
            "gif", "图片", "image", "插画",
        ]
        research_markers = [
            "分析", "调研", "研究", "白皮书", "论文", "report",
            "analysis", "research", "investigate", "总结", "综述",
            "对比", "compare", "benchmark", "评测", "survey",
            "阅读", "解读", "review",
        ]
        has_code_intent = any(x in low for x in code_markers)
        has_research_intent = any(x in low for x in research_markers)
        length = len(clean)
        derived_complexity = max_task_complexity(explicit_complexity, llm_complexity, default="simple")
        if direct_question and (not nontrivial) and (not has_code_intent) and length <= 220:
            return {
                "task_type": "simple_qa",
                "complexity": explicit_complexity or "simple",
                "direct_objective": (
                    "Directly answer the user question in natural language. "
                    "Do not create or edit files unless explicitly requested."
                ),
                "recommended_agents": ["developer"],
                "round_budget": 2,
                "reason": "short direct question with no code intent",
                "goal_chars": int(length),
                "updated_at": float(now_ts()),
            }
        if has_code_intent and (not nontrivial) and length <= 260:
            return {
                "task_type": "simple_code",
                "complexity": explicit_complexity or "simple",
                "direct_objective": (
                    "Deliver one minimal concrete code change, run one quick verification, then conclude."
                ),
                "recommended_agents": ["developer", "reviewer"],
                "round_budget": 5,
                "reason": "small scoped code-oriented request",
                "goal_chars": int(length),
                "updated_at": float(now_ts()),
            }
        if has_research_intent and (not has_code_intent):
            return {
                "task_type": "research",
                "complexity": explicit_complexity or max_task_complexity(
                    derived_complexity,
                    ("complex" if length >= 480 else "moderate" if (nontrivial or length >= 280) else "simple"),
                    default="simple",
                ),
                "direct_objective": "Collect evidence first, then synthesize a concise actionable answer.",
                "recommended_agents": ["explorer", "developer", "reviewer"],
                "round_budget": 10 if (nontrivial or length >= 280) else 6,
                "reason": "research/evidence intent detected",
                "goal_chars": int(length),
                "updated_at": float(now_ts()),
            }
        if nontrivial or has_code_intent or length >= 280:
            return {
                "task_type": "engineering",
                "complexity": explicit_complexity or max_task_complexity(
                    derived_complexity,
                    (
                        "expert"
                        if ((has_code_intent and has_research_intent) or length >= 900)
                        else "complex"
                    ),
                    default="moderate",
                ),
                "direct_objective": (
                    "Use blackboard collaboration to implement, validate, and converge with concrete outputs."
                ),
                "recommended_agents": ["explorer", "developer", "reviewer"],
                "round_budget": 14,
                "reason": "multi-step engineering characteristics detected",
                "goal_chars": int(length),
                "updated_at": float(now_ts()),
            }
        return {
            "task_type": "general",
            "complexity": explicit_complexity or derived_complexity or "simple",
            "direct_objective": (
                "Provide the most direct useful response with minimal orchestration, "
                "anchored to the current project context and user goal."
            ),
            "recommended_agents": ["developer"],
            "round_budget": 3,
            "reason": "default lightweight profile",
            "goal_chars": int(length),
            "updated_at": float(now_ts()),
        }

    def _is_default_session_title(self, title: str) -> bool:
        t = str(title or "").strip()
        if not t:
            return True
        low = t.lower()
        default_titles = {
            "web session",
            "session",
            "web 会话",
            "会话",
            "web 會話",
            "會話",
            "web セッション",
            "セッション",
        }
        if low in default_titles or t in default_titles:
            return True
        if re.fullmatch(
            r"(web[\s_-]*)?(session|会话|會話|セッション)[\s_-]*\d*",
            low,
            flags=re.IGNORECASE,
        ):
            return True
        if t == self.id:
            return True
        if re.fullmatch(r"sess_[a-z0-9]{6,}", low):
            return True
        return False

    def _title_context_brief(self) -> str:
        goal = self._latest_user_goal_text()
        todo_rows = []
        for row in self.todo.snapshot():
            status = str(row.get("status", "pending"))
            if status not in {"pending", "in_progress", "completed"}:
                status = "pending"
            content = normalize_work_text(row.get("content", ""), status) or str(row.get("content", "")).strip()
            if content:
                todo_rows.append(f"[{status}] {trim(content, 80)}")
            if len(todo_rows) >= 4:
                break
        task_rows = []
        for row in self.tasks.list_objects():
            status = str(row.get("status", "pending"))
            if status not in {"pending", "in_progress", "blocked", "completed"}:
                status = "pending"
            subject = normalize_work_text(row.get("subject", ""), status) or str(row.get("subject", "")).strip()
            if subject:
                task_rows.append(f"#{row.get('id')}[{status}] {trim(subject, 80)}")
            if len(task_rows) >= 4:
                break
        todos_txt = " | ".join(todo_rows) if todo_rows else "none"
        tasks_txt = " | ".join(task_rows) if task_rows else "none"
        return (
            f"goal: {trim(goal, 180)}\n"
            f"todos: {todos_txt}\n"
            f"tasks: {tasks_txt}"
        )

    def _normalize_auto_title(self, raw: str) -> str:
        text = str(raw or "").strip()
        if not text:
            return ""
        text = text.replace("\r", " ").replace("\n", " ")
        text = re.sub(r"\s+", " ", text).strip()
        text = re.sub(r"^['\"`#\-\s]+|['\"`#\-\s]+$", "", text).strip()
        text = re.sub(r"^[Tt]itle\s*[:：]\s*", "", text).strip()
        if not text:
            return ""
        if len(text) > 40:
            text = text[:40].rstrip(" -_:;,.")
        if self._is_default_session_title(text):
            return ""
        return text

    def _fallback_auto_title(self) -> str:
        goal = self._latest_user_goal_text()
        if not goal:
            return ""
        candidate = normalize_work_text(goal) or goal
        candidate = re.sub(
            r"^(实现|實現|修复|修復|构建|構建|创建|創建|请|請|帮我|幫我|需要|"
            r"implement|fix|build|create|please|need|"
            r"実装|修正|作成|構築|お願い)\s*",
            "",
            candidate,
            flags=re.IGNORECASE,
        ).strip()
        return self._normalize_auto_title(candidate)

    def _maybe_auto_rename_session_title(self, trigger: str = "") -> bool:
        now_tick = now_ts()
        with self.lock:
            current = str(self.title or "").strip()
            if not self._is_default_session_title(current):
                return False
            if (now_tick - float(self.last_auto_title_ts or 0.0)) < 12:
                return False
            self.last_auto_title_ts = now_tick

        if self.cancel_requested:
            return False

        prompt = (
            "Generate one concise session title from current coding task progress.\n"
            "Rules:\n"
            "- max 20 characters (or 3-6 English words)\n"
            "- no quotes, no markdown, no punctuation-only title\n"
            "- output title only\n\n"
            f"{self._title_context_brief()}"
        )
        candidate = ""
        try:
            rsp = self.ollama.chat(
                [{"role": "user", "content": f"/no_think\n{prompt}"}],
                system=self._inject_runtime_environment_context(
                    "/no_think\n"
                    "You generate short practical session titles for developer workflow tracking. "
                    f"{model_language_instruction(self.ui_language)}"
                ),
                max_tokens=80,
                think=False,
            )
            candidate = self._normalize_auto_title(str(rsp.get("content", "") or ""))
        except Exception:
            candidate = ""
        if not candidate:
            candidate = self._fallback_auto_title()
        if not candidate:
            return False
        if self.cancel_requested:
            return False

        with self.lock:
            if self.cancel_requested:
                return False
            old_title = str(self.title or "").strip()
            if not self._is_default_session_title(old_title):
                return False
            if candidate == old_title:
                return False
            self.title = candidate
            self.updated_at = now_ts()
            self._persist()
        self._emit(
            "status",
            {
                "summary": (
                    f"session auto-renamed ({trigger or 'progress'}): "
                    f"'{trim(old_title, 36)}' -> '{candidate}'"
                )
            },
        )
        return True

    def _ensure_runtime_model_ready(self):
        active_profile = dict(self.model_profiles.get(self.active_profile_id, {}))
        if not self._profile_is_runnable(active_profile):
            if not bool(self.auto_model_switch):
                self._emit(
                    "status",
                    {
                        "summary": (
                            "runtime model is not runnable; auto model switch disabled, "
                            "please switch model manually"
                        )
                    },
                )
                return
            fallback = self._pick_runnable_selection(
                preferred_provider=str(self.ollama.provider or ""),
                exclude={f"{self.active_profile_id}::{self.ollama.model}"},
            )
            if fallback:
                self.set_runtime_selection(fallback, reset_failures=False)
                self._emit(
                    "status",
                    {
                        "summary": (
                            "runtime model auto-recovered from non-runnable profile "
                            f"to {fallback}"
                        )
                    },
                )
            return
        if str(self.ollama.provider or "").lower() != "ollama":
            return
        try:
            tags = list_ollama_models(self.ollama.base_url)
        except Exception:
            tags = []
        if not tags:
            return
        current_model = str(self.ollama.model or "").strip()
        if current_model:
            loaded = list_loaded_ollama_models(self.ollama.base_url, timeout=5)
            if current_model not in set(loaded):
                woke, wake_err = wake_ollama_model(
                    self.ollama.base_url,
                    current_model,
                    timeout=self._global_wait_timeout_seconds(),
                )
                if woke:
                    self._emit(
                        "status",
                        {"summary": f"woke pinned ollama model: {current_model}"},
                    )
                elif wake_err:
                    self._emit(
                        "status",
                        {
                            "summary": (
                                f"pinned model wake failed for '{current_model}': "
                                f"{trim(wake_err, 160)}"
                            )
                        },
                    )
        if self.ollama.model in tags:
            return
        preferred = resolve_ollama_model(self.ollama.base_url, current_model)
        if not preferred or preferred == current_model:
            return
        if not bool(self.auto_model_switch):
            self._emit(
                "status",
                {
                    "summary": (
                        f"detected unavailable ollama tag '{current_model}' in scan; "
                        "auto model switch disabled, please switch manually"
                    )
                },
            )
            return
        selection = f"{self.active_profile_id}::{preferred}"
        self.set_runtime_selection(selection, reset_failures=False)
        self._emit(
            "status",
            {
                "summary": (
                    f"model preflight switched unavailable tag '{current_model}' "
                    f"-> '{preferred}'"
                )
            },
        )

    def _active_runtime_selection(self) -> str:
        profile = dict(self.model_profiles.get(self.active_profile_id, {}))
        model = str(profile.get("model", self.ollama.model) or self.ollama.model).strip()
        return f"{self.active_profile_id}::{model}"

    def _queue_deferred_runtime_update(self, kind: str, payload: dict) -> int:
        row = {
            "kind": str(kind or "").strip().lower(),
            "payload": dict(payload or {}),
            "queued_at": float(now_ts()),
        }
        if not row["kind"]:
            raise ValueError("deferred runtime update kind required")
        with self.lock:
            self._pending_runtime_updates.append(row)
            self._pending_runtime_updates = self._pending_runtime_updates[-16:]
            queued = len(self._pending_runtime_updates)
            self.updated_at = now_ts()
            self._persist()
        return queued

    def _apply_deferred_runtime_updates(self) -> list[str]:
        with self.lock:
            if self.running or not self._pending_runtime_updates:
                return []
            queued = list(self._pending_runtime_updates)
            self._pending_runtime_updates = []
            self.updated_at = now_ts()
            self._persist()
        applied_notes: list[str] = []
        sync_needed = False
        for item in queued:
            kind = str(item.get("kind", "") or "").strip().lower()
            payload = item.get("payload", {}) if isinstance(item.get("payload"), dict) else {}
            try:
                if kind == "llm_config":
                    source = str(payload.get("source", "") or "deferred-config").strip()
                    config = payload.get("config", {})
                    if isinstance(config, dict) and config:
                        self.load_llm_config(config, source=source)
                        applied_notes.append(f"deferred llm config applied: {trim(source, 120)}")
                        sync_needed = True
                elif kind == "model_selection":
                    selection = str(payload.get("selection", "") or "").strip()
                    model_override = payload.get("model_override")
                    self.set_runtime_selection(
                        selection,
                        model_override if isinstance(model_override, str) else None,
                    )
                    applied_notes.append(f"deferred model switch applied: {trim(selection, 120)}")
                    sync_needed = True
            except Exception as exc:
                self._emit(
                    "status",
                    {
                        "summary": (
                            f"deferred runtime update failed ({kind or 'unknown'}): "
                            f"{trim(str(exc), 180)}"
                        )
                    },
                )
        if sync_needed:
            self._deferred_runtime_sync_requested = True
        return applied_notes

    def _global_wait_timeout_seconds(self) -> int:
        raw = (
            self.max_run_seconds
            or getattr(self.ollama, "timeout", 0)
            or DEFAULT_REQUEST_TIMEOUT
        )
        return normalize_timeout_seconds(
            raw,
            minimum=MIN_TIMEOUT_SECONDS,
            maximum=MAX_TIMEOUT_SECONDS,
            fallback=DEFAULT_REQUEST_TIMEOUT,
        )

    def _set_runtime_phase(self, phase: str, tool_name: str = ""):
        with self.lock:
            self.current_phase = str(phase or "idle")
            self.current_tool_name = str(tool_name or "")
            self.run_last_heartbeat = now_ts()

    def _startup_phase(self, step: str = "") -> str:
        label = trim(str(step or "").strip(), 80)
        return f"starting:{label}" if label else "starting"

    def _call_interruptible(
        self,
        fn,
        poll_interval: float = 0.08,
        *,
        progress_label: str = "model call",
        progress_interval: float | None = None,
        progress_delay: float | None = None,
    ):
        if self.cancel_requested:
            raise OllamaError("interrupted by user", status=499)
        done = threading.Event()
        box: dict[str, object] = {}
        start_ts = time.time()
        interval = MODEL_CALL_PROGRESS_INTERVAL if progress_interval is None else float(progress_interval)
        delay = MODEL_CALL_PROGRESS_DELAY if progress_delay is None else float(progress_delay)
        label = trim(str(progress_label or "model call"), 120) or "model call"
        last_progress_emit = start_ts
        with self.lock:
            self.live_run_notice_active = True
            self.live_run_notice_label = label
            self.live_run_notice_started_at = float(start_ts)
            self.live_run_notice_elapsed = 0.0
        self._emit_transient("runtime_progress", {"state": "start", "label": label, "elapsed": 0.0})

        def worker():
            try:
                box["result"] = fn()
            except Exception as exc:
                box["error"] = exc
            finally:
                done.set()

        threading.Thread(target=worker, daemon=True).start()
        try:
            while True:
                if done.wait(poll_interval):
                    break
                if self.cancel_requested:
                    raise OllamaError("interrupted by user", status=499)
                try:
                    self.run_last_heartbeat = now_ts()
                except Exception:
                    pass
                if interval > 0:
                    now = time.time()
                    if now - start_ts >= delay and now - last_progress_emit >= interval:
                        last_progress_emit = now
                        with self.lock:
                            self.live_run_notice_elapsed = max(0.0, now - start_ts)
                        self._emit_transient(
                            "runtime_progress",
                            {
                                "state": "tick",
                                "label": label,
                                "elapsed": round(max(0.0, now - start_ts), 1),
                            },
                        )
            if "error" in box:
                err = box.get("error")
                if isinstance(err, Exception):
                    raise err
                raise OllamaError(trim(str(err), 220))
            return box.get("result", {})
        finally:
            end_elapsed = max(0.0, time.time() - start_ts)
            with self.lock:
                self.live_run_notice_elapsed = end_elapsed
                if self.running:
                    self.run_model_active_seconds = max(
                        0.0,
                        float(self.run_model_active_seconds or 0.0) + end_elapsed,
                    )
                self.live_run_notice_active = False
                self.live_run_notice_label = ""
                self.live_run_notice_started_at = 0.0
            self._emit_transient(
                "runtime_progress",
                {"state": "stop", "label": label, "elapsed": round(end_elapsed, 1)},
            )

    def _profile_effort_bounds(self) -> tuple[str, str]:
        """Return (default_effort, ceiling) configured on the active profile.

        Falls back to ("", max) so task level fully drives effort unless the
        user explicitly pins/caps it in their LLM config profile via the
        optional `effort` / `max_effort` fields.
        """
        try:
            prof = dict(self.model_profiles.get(self.active_profile_id, {}))
        except Exception:
            prof = {}
        if not isinstance(prof, dict):
            prof = {}
        default = str(prof.get("effort", "") or "").strip().lower()
        ceiling = str(prof.get("max_effort", "") or "").strip().lower()
        if ceiling not in EFFORT_ORDER:
            ceiling = EFFORT_MAX
        if default not in EFFORT_ORDER:
            default = ""
        return default, ceiling

    def _resolve_effort_for_call(self, *, role_hint: str = "", explicit: str = "", coordination: bool = False) -> str:
        """Decide the reasoning effort for a model call.

        Precedence: explicit arg > profile pin > task-level default. The result
        is raised to any per-role floor (manager/reviewer reason >= HIGH) and
        then clamped down to the profile's max_effort ceiling. L3-L5 default to
        MAX via TASK_LEVEL_EFFORT.

        coordination=True marks a pure routing/dispatch call (manager picking the
        next agent). These bypass the role floor and default to COORDINATION_EFFORT
        so the manager stops burning HIGH/MAX reasoning on a mechanical tool-pick
        every round. A profile pin / explicit arg still wins, and the ceiling still
        clamps.
        """
        default_pin, ceiling = self._profile_effort_bounds()
        if str(explicit or "").strip().lower() in EFFORT_ORDER:
            effort = str(explicit).strip().lower()
        elif default_pin in EFFORT_ORDER:
            effort = default_pin
        elif coordination:
            effort = COORDINATION_EFFORT
        else:
            level = int(getattr(self, "runtime_task_level", 0) or 0)
            effort = TASK_LEVEL_EFFORT.get(level, EFFORT_DEFAULT)
        if not coordination:
            role = str(role_hint or "").strip().lower()
            floor = ROLE_EFFORT_FLOOR.get(role, EFFORT_OFF)
            if EFFORT_ORDER.get(floor, 0) > EFFORT_ORDER.get(effort, 0):
                effort = floor
        return clamp_effort(effort, ceiling=ceiling)

    def _chat_with_same_model_retry(
        self,
        messages: list[dict],
        *,
        tools: list | None = None,
        system: str = "",
        max_tokens: int | None = None,
        think: bool | None = None,
        stream_thinking: bool = False,
        on_thinking_chunk=None,
        pinned_selection: str = "",
        context_label: str = "agent",
        retries: int = MODEL_OUTPUT_RETRY_TIMES,
        media_inputs: list[dict] | None = None,
        effort: str = "",
        coordination: bool = False,
    ) -> dict:
        retry_budget = max(0, int(retries or 0))
        pin = str(pinned_selection or self._active_runtime_selection()).strip() or self._active_runtime_selection()
        last_exc: OllamaError | None = None
        wake_attempted = False
        system = self._inject_runtime_environment_context(system)
        estimated_prompt_tokens = self._estimate_model_call_prompt_tokens(
            messages,
            tools=tools,
            system=system,
            media_inputs=media_inputs,
        )
        label_low = str(context_label or "").strip().lower()
        context_role_hint = ""
        if "manager" in label_low:
            context_role_hint = "manager"
        else:
            for _role in AGENT_ROLES:
                if _role in label_low:
                    context_role_hint = _role
                    break
        resolved_effort = self._resolve_effort_for_call(role_hint=context_role_hint, explicit=effort, coordination=coordination)
        response_stream_enabled = bool(getattr(self.ollama, "response_stream", False))
        visible_response_stream = bool(
            response_stream_enabled
            and (
                label_low == "agent turn"
                or (
                    label_low.endswith(" turn")
                    and not any(x in label_low for x in ("manager", "planner"))
                )
            )
        )

        def _emit_http_retry(meta: dict):
            try:
                delay = float((meta or {}).get("delay", 0.0) or 0.0)
            except Exception:
                delay = 0.0
            status = int((meta or {}).get("status", 0) or 0)
            provider = str((meta or {}).get("provider", "") or pin).strip() or pin
            attempt_no = int((meta or {}).get("attempt", 0) or 0)
            retry_budget = int((meta or {}).get("retry_budget", 0) or 0)
            reason = trim(str((meta or {}).get("reason", "") or ""), 160)
            status_txt = f"HTTP {status}" if status else "network"
            if attempt_no > 0:
                label = f"retry {attempt_no}/{retry_budget}"
            else:
                label = "cooldown"
            self._emit(
                "status",
                {
                    "summary": (
                        f"{context_label} model call {status_txt} on {provider}; "
                        f"{label} after {delay:.0f}s"
                        + (f": {reason}" if reason else "")
                    ),
                    "llm_http_retry": True,
                    "provider": provider,
                    "status": status,
                    "delay": delay,
                    "attempt": attempt_no,
                    "retry_budget": retry_budget,
                },
            )

        for attempt in range(1, retry_budget + 2):
            try:
                if visible_response_stream:
                    self._clear_live_response()
                    self._begin_live_response(
                        context_label=context_label,
                        visible=visible_response_stream,
                    )
                response = self._call_interruptible(
                    lambda: self.ollama.chat(
                        messages,
                        tools=tools,
                        system=system,
                        max_tokens=max_tokens,
                        think=False,
                        stream_thinking=bool(stream_thinking),
                        on_thinking_chunk=on_thinking_chunk,
                        response_stream=response_stream_enabled,
                        on_content_delta=(
                            lambda chunk: self._append_live_response_delta(
                                chunk,
                                context_label=context_label,
                                visible=visible_response_stream,
                            )
                        )
                        if visible_response_stream
                        else None,
                        media_inputs=media_inputs,
                        cancel_check=lambda: bool(self.cancel_requested),
                        on_http_retry=_emit_http_retry,
                        effort=resolved_effort,
                    ),
                    progress_label=f"{context_label} model call",
                )
                if visible_response_stream:
                    self._clear_live_response()
                self._record_model_usage(
                    response,
                    estimated_prompt_tokens=estimated_prompt_tokens,
                    context_label=context_label,
                )
                return response
            except OllamaError as exc:
                if visible_response_stream:
                    self._clear_live_response()
                last_exc = exc
                if self.cancel_requested or "interrupted by user" in str(exc).lower():
                    raise
                if bool(getattr(exc, "stream_emitted", False)):
                    break
                if self._context_window_error_hint(exc):
                    if self._shrink_context_upper_bound_from_actual_pressure(
                        estimated_prompt_tokens=estimated_prompt_tokens,
                        reason=f"{context_label}:{trim(str(exc), 80)}",
                    ):
                        self._apply_auto_compact_if_needed(
                            f"provider-context-error:{context_label}",
                            metrics=self._context_budget_metrics(token_estimate=estimated_prompt_tokens),
                            role=context_role_hint,
                        )
                        if attempt <= retry_budget:
                            self._emit(
                                "status",
                                {
                                    "summary": (
                                        f"{context_label} context-window retry after compact "
                                        f"({attempt}/{retry_budget})"
                                    )
                                },
                            )
                            time.sleep(min(1.0, 0.25 * attempt))
                            continue
                # Detect media format incompatibility and auto-fallback
                exc_str = str(exc).lower()
                _media_fmt_err = media_inputs and any(
                    kw in exc_str for kw in (
                        "unknown format", "unsupported image", "invalid image",
                        "cannot process image", "image format",
                        "failed to process inputs: image",
                    )
                )
                if _media_fmt_err:
                    media_desc = ", ".join(
                        str(m.get("name", "unknown"))
                        for m in media_inputs
                        if isinstance(m, dict)
                    )
                    self._emit("status", {
                        "summary": f"media format not supported by model ({media_desc}), retrying without media"
                    })
                    fallback_note = {
                        "role": "user",
                        "content": (
                            f"[Note: The following files could not be processed as images "
                            f"by the model: {media_desc}. "
                            f"Please analyze them using text-based tools (bash/read_file) instead.]"
                        ),
                    }
                    try:
                        fallback_messages = list(messages) + [fallback_note]
                        fallback_estimated_prompt_tokens = self._estimate_model_call_prompt_tokens(
                            fallback_messages,
                            tools=tools,
                            system=system,
                            media_inputs=None,
                        )
                        response = self._call_interruptible(
                            lambda: self.ollama.chat(
                                fallback_messages,
                                tools=tools,
                                system=system,
                                max_tokens=max_tokens,
                                think=False,
                                stream_thinking=bool(stream_thinking),
                                on_thinking_chunk=on_thinking_chunk,
                                response_stream=response_stream_enabled,
                                on_content_delta=(
                                    lambda chunk: self._append_live_response_delta(
                                        chunk,
                                        context_label=f"{context_label}:no-media",
                                        visible=visible_response_stream,
                                    )
                                )
                                if visible_response_stream
                                else None,
                                media_inputs=None,
                                cancel_check=lambda: bool(self.cancel_requested),
                                on_http_retry=_emit_http_retry,
                            ),
                            progress_label=f"{context_label} model call (no-media fallback)",
                        )
                        if visible_response_stream:
                            self._clear_live_response()
                        self._record_model_usage(
                            response,
                            estimated_prompt_tokens=fallback_estimated_prompt_tokens,
                            context_label=f"{context_label}:no-media",
                        )
                        return response
                    except OllamaError:
                        if visible_response_stream:
                            self._clear_live_response()
                        pass  # fallback also failed, continue normal retry
                wake_note = ""
                status = int(getattr(exc, "status", 0) or 0)
                if (
                    not wake_attempted
                    and str(self.ollama.provider or "").lower() == "ollama"
                    and status in {0, 408, 429, 500, 502, 503, 504}
                ):
                    wake_attempted = True
                    model_now = str(self.ollama.model or "").strip()
                    if model_now:
                        woke, wake_err = wake_ollama_model(
                            self.ollama.base_url,
                            model_now,
                            timeout=self._global_wait_timeout_seconds(),
                        )
                        if woke:
                            wake_note = " | wake=ok"
                        elif wake_err:
                            wake_note = f" | wake={trim(wake_err, 96)}"
                if attempt > retry_budget:
                    break
                self._emit(
                    "status",
                    {
                        "summary": (
                            f"{context_label} model call failed on {pin}; "
                            f"retry {attempt}/{retry_budget}: {trim(str(exc), 180)}"
                            f"{wake_note}"
                        )
                    },
                )
                time.sleep(min(1.4, 0.35 * attempt))
        raise last_exc if last_exc is not None else OllamaError("chat failed")

    def _is_allowed_absolute_write_path(self, raw_path: str) -> bool:
        txt = str(raw_path or "").strip().strip("'\"")
        if not txt.startswith("/"):
            return True
        special = {"/dev/null", "/dev/stdout", "/dev/stderr", "/dev/tty"}
        if txt in special:
            return True
        try:
            target = Path(txt).expanduser().resolve()
        except Exception:
            return False
        roots: list[Path] = [self.root.resolve(), self.files_root.resolve()]
        try:
            roots.append(self.skills.skills_root.resolve())
        except Exception:
            pass
        for root in roots:
            try:
                if target == root or target.is_relative_to(root):
                    return True
            except Exception:
                continue
        return False

    def _shell_virtual_prefix_start_boundary(self, ch: str) -> bool:
        if not ch:
            return True
        return not (ch.isalnum() or ch in "._~-/%")

    def _shell_virtual_prefix_end_boundary(self, ch: str) -> bool:
        if not ch:
            return True
        if ch == "/":
            return True
        return not (ch.isalnum() or ch in "._~-")

    def _shell_quote_virtual_root(self, path_text: str, quote_mode: str) -> str:
        txt = str(path_text or "")
        if quote_mode == "double":
            return (
                txt.replace("\\", "\\\\")
                .replace('"', '\\"')
                .replace("$", "\\$")
                .replace("`", "\\`")
            )
        if quote_mode == "single":
            return txt.replace("'", "'\"'\"'")
        return shlex.quote(txt)

    def _rewrite_shell_virtual_paths(self, command: str, cwd: Path) -> str:
        raw = str(command or "")
        if not raw or os.name == "nt":
            return raw
        try:
            workspace_root = str(cwd.resolve())
        except Exception:
            workspace_root = str(cwd)
        try:
            skills_root = str(self.skills.skills_root.resolve())
        except Exception:
            skills_root = str(self.skills.skills_root)
        try:
            js_lib_root = str(self.js_lib_root.resolve())
        except Exception:
            js_lib_root = str(self.js_lib_root)
        mappings = self.skills.shell_virtual_mappings() + [
            ("/workspace", workspace_root),
            (SKILLS_VIRTUAL_PREFIX, skills_root),
            ("/js_lib", js_lib_root),
        ]
        # Auto-quote raw absolute paths that contain spaces (prevents word-splitting)
        if " " in workspace_root and workspace_root not in ("/workspace",):
            mappings.append((workspace_root, workspace_root))
        if " " in skills_root and skills_root != SKILLS_VIRTUAL_PREFIX:
            mappings.append((skills_root, skills_root))
        if " " in js_lib_root and js_lib_root != "/js_lib":
            mappings.append((js_lib_root, js_lib_root))
        out: list[str] = []
        mode = "plain"
        i = 0
        n = len(raw)
        while i < n:
            ch = raw[i]
            if mode in {"plain", "double"} and ch == "\\" and (i + 1) < n:
                out.append(raw[i : i + 2])
                i += 2
                continue
            replaced = False
            if ch == "/":
                prev = raw[i - 1] if i > 0 else ""
                if self._shell_virtual_prefix_start_boundary(prev):
                    for prefix, target in mappings:
                        if not raw.startswith(prefix, i):
                            continue
                        next_idx = i + len(prefix)
                        next_ch = raw[next_idx] if next_idx < n else ""
                        if not self._shell_virtual_prefix_end_boundary(next_ch):
                            continue
                        out.append(self._shell_quote_virtual_root(target, mode))
                        i += len(prefix)
                        replaced = True
                        break
            if replaced:
                continue
            out.append(ch)
            if mode == "plain":
                if ch == "'":
                    mode = "single"
                elif ch == '"':
                    mode = "double"
            elif mode == "double":
                if ch == '"':
                    mode = "plain"
            else:
                if ch == "'":
                    mode = "plain"
            i += 1
        return "".join(out)

    def _shell_write_targets_outside_scope(self, command: str) -> list[str]:
        cmd = str(command or "")
        if not cmd.strip():
            return []
        low = cmd.lower()
        has_write_intent = bool(
            re.search(r"(^|[^<])>>?\s*", cmd)
            or any(
                token in low
                for token in (
                    " mkdir ",
                    " touch ",
                    " rm ",
                    " rmdir ",
                    " mv ",
                    " cp ",
                    " install ",
                    " chmod ",
                    " chown ",
                    " truncate ",
                    " tee ",
                    " sed -i",
                    " perl -i",
                    " dd ",
                )
            )
        )
        if not has_write_intent:
            return []

        targets: list[str] = []
        # Redirection targets.
        for m in re.finditer(
            r"(^|[^<])>>?\s*(?:'(?P<sq>[^']+)'|\"(?P<dq>[^\"]+)\"|(?P<raw>[^\s;&|]+))",
            cmd,
        ):
            p = str(m.group("sq") or m.group("dq") or m.group("raw") or "").strip()
            if p.startswith("/"):
                targets.append(p)

        clauses = [x for x in re.split(r"(?:&&|\|\||;)", cmd) if str(x or "").strip()]
        for clause in clauses:
            try:
                toks = shlex.split(clause, posix=True)
            except Exception:
                toks = []
            if not toks:
                continue
            tool = str(toks[0] or "").strip().lower()
            args = [t for t in toks[1:] if str(t or "").strip() and (not str(t).startswith("-"))]
            if tool in {"mkdir", "touch", "rm", "rmdir", "chmod", "chown", "truncate"}:
                for tok in args:
                    if tok.startswith("/"):
                        targets.append(tok)
            elif tool == "mv":
                for tok in args:
                    if tok.startswith("/"):
                        targets.append(tok)
            elif tool in {"cp", "install", "ln"}:
                if args:
                    dst = args[-1]
                    if dst.startswith("/"):
                        targets.append(dst)
            elif tool == "tee":
                for tok in args:
                    if tok.startswith("/"):
                        targets.append(tok)
            elif tool == "dd":
                for tok in toks[1:]:
                    if str(tok).startswith("of=/"):
                        targets.append(str(tok)[3:])

        blocked: list[str] = []
        seen: set[str] = set()
        for path_text in targets:
            p = str(path_text or "").strip()
            if not p or p in seen:
                continue
            seen.add(p)
            if not self._is_allowed_absolute_write_path(p):
                blocked.append(p)
        return blocked

    def _guard_shell_write_scope(self, command: str, cwd: Path | None = None) -> str:
        effective = self._rewrite_shell_virtual_paths(command, cwd or self.files_root)
        blocked = self._shell_write_targets_outside_scope(effective)
        if not blocked:
            return ""
        preview = ", ".join(blocked[:3])
        suffix = " ..." if len(blocked) > 3 else ""
        return (
            "Error: write blocked for absolute path(s) outside session/skills scope: "
            f"{preview}{suffix}. "
            "Use relative paths in session workspace, or use write_skill for skills."
        )

    def _run_shell_meta(self, command: str, cwd: Path, timeout: int) -> dict:
        effective_command = self._rewrite_shell_virtual_paths(command, cwd)
        meta = {
            "command": command,
            "effective_command": effective_command,
            "cwd": str(cwd),
            "timeout": timeout,
            "exit_code": None,
            "duration_ms": 0,
            "changed_files": [],
            "output": "",
            "error": "",
        }
        if any(x in effective_command for x in DANGEROUS_PATTERNS):
            meta["error"] = "Error: dangerous command blocked"
            meta["output"] = meta["error"]
            return meta
        before = self._git_status_map(cwd)
        start = time.time()
        proc: subprocess.Popen | None = None
        capture_limit = max(200_000, int(MAX_TOOL_OUTPUT) * 4)
        out_buf = bytearray()
        err_buf = bytearray()
        next_progress_emit = start + 0.8
        # Idle-timeout tracking: reset whenever output is captured.
        # Timeout fires only when no output has arrived for `timeout` seconds;
        # a hard cap of MAX_SHELL_COMMAND_TIMEOUT_SECONDS prevents infinite runs.
        last_activity_ts = [start]

        def _stop_process(p: subprocess.Popen):
            # shell=True may spawn child processes; stop the whole process group on POSIX.
            try:
                if os.name == "posix":
                    try:
                        os.killpg(os.getpgid(p.pid), signal.SIGTERM)
                    except Exception:
                        p.terminate()
                else:
                    p.terminate()
                p.wait(timeout=1.5)
            except Exception:
                try:
                    if os.name == "posix":
                        try:
                            os.killpg(os.getpgid(p.pid), signal.SIGKILL)
                        except Exception:
                            p.kill()
                    else:
                        p.kill()
                except Exception:
                    pass

        def _append_capture(target: bytearray, piece: bytes):
            if not piece:
                return
            target.extend(piece)
            last_activity_ts[0] = time.time()  # Reset idle timer on any output
            overflow = len(target) - capture_limit
            if overflow > 0:
                del target[:overflow]

        def _merge_output_text() -> str:
            def _decode_pipe(data: bytes) -> str:
                raw = bytes(data or b"")
                if not raw:
                    return ""
                encodings: list[str] = ["utf-8", "utf-8-sig"]
                if os.name == "nt":
                    # cmd.exe often uses a system codepage (e.g. cp936/GBK), while
                    # modern tools/MCP shims commonly emit UTF-8. Try UTF-8 first
                    # when it is valid, then locale and Chinese Windows fallbacks.
                    try:
                        encodings.append(str(locale.getpreferredencoding(False) or ""))
                    except Exception:
                        pass
                    encodings.extend(["gb18030", "gbk", "cp936"])
                else:
                    try:
                        encodings.append(str(locale.getpreferredencoding(False) or ""))
                    except Exception:
                        pass
                seen: set[str] = set()
                for enc in encodings:
                    enc = str(enc or "").strip()
                    if not enc or enc.lower() in seen:
                        continue
                    seen.add(enc.lower())
                    try:
                        return raw.decode(enc, errors="strict")
                    except Exception:
                        continue
                return raw.decode("utf-8", errors="replace")

            # On Windows, cmd.exe can output in the system codepage while some
            # tools emit UTF-8. Decode bytes defensively instead of assuming one.
            if os.name == "nt":
                out_text = _decode_pipe(out_buf)
                err_text = _decode_pipe(err_buf)
            else:
                out_text = _decode_pipe(out_buf)
                err_text = _decode_pipe(err_buf)
            return (out_text + err_text).strip()

        def _store_shell_output(output_value: str, exit_code: int | None = None):
            text = str(output_value or "").strip()
            if not text:
                text = str(meta.get("error") or "(no output)")
            if exit_code is not None:
                meta["exit_code"] = int(exit_code)
            meta.update(self._prepare_shell_output_payload(command, text, cwd=cwd))

        def _collect_with_reader_threads(proc: subprocess.Popen):
            nonlocal next_progress_emit
            reader_threads: list[threading.Thread] = []
            io_queue: queue.Queue = queue.Queue()
            active_readers: set[str] = set()

            def _spawn_reader(label: str, stream):
                if stream is None:
                    return
                active_readers.add(label)
                # Selector fallback may leave PIPE FDs in non-blocking mode.
                # Reader threads expect blocking reads to avoid early EOF/pipe close.
                try:
                    os.set_blocking(stream.fileno(), True)
                except Exception:
                    pass

                def _reader():
                    try:
                        while True:
                            try:
                                chunk = stream.read(65536)
                            except Exception:
                                break
                            if chunk is None:
                                time.sleep(0.01)
                                continue
                            if not chunk:
                                break
                            io_queue.put((label, chunk))
                    finally:
                        try:
                            stream.close()
                        except Exception:
                            pass
                        io_queue.put((label, None))

                th = threading.Thread(target=_reader, daemon=True)
                th.start()
                reader_threads.append(th)

            _spawn_reader("stdout", proc.stdout)
            _spawn_reader("stderr", proc.stderr)

            _auto_confirmed: set[bytes] = set()
            while True:
                now = time.time()
                elapsed = now - start
                if (not meta.get("error")) and self.cancel_requested:
                    _stop_process(proc)
                    meta["error"] = "Error: interrupted by user"
                    meta["exit_code"] = -130
                    break
                elif (not meta.get("error")) and timeout > 0 and (
                    (now - last_activity_ts[0]) >= timeout
                    or elapsed >= MAX_SHELL_COMMAND_TIMEOUT_SECONDS
                ):
                    idle_secs = int(now - last_activity_ts[0])
                    meta["error"] = (
                        f"Error: timeout (idle {idle_secs}s / limit {timeout}s)"
                        if (now - last_activity_ts[0]) >= timeout
                        else f"Error: hard cap reached ({int(elapsed)}s)"
                    )
                    _stop_process(proc)
                    meta["exit_code"] = -1
                    break
                try:
                    label, chunk = io_queue.get(timeout=0.12)
                    if chunk is None:
                        active_readers.discard(str(label))
                    elif str(label) == "stderr":
                        _append_capture(err_buf, chunk)
                    else:
                        _append_capture(out_buf, chunk)
                except queue.Empty:
                    pass
                while True:
                    try:
                        label, chunk = io_queue.get_nowait()
                    except queue.Empty:
                        break
                    if chunk is None:
                        active_readers.discard(str(label))
                    elif str(label) == "stderr":
                        _append_capture(err_buf, chunk)
                    else:
                        _append_capture(out_buf, chunk)
                if now >= next_progress_emit:
                    _idle_secs = int(now - last_activity_ts[0])
                    _idle_str = f", idle={_idle_secs}s" if _idle_secs > 5 else ""
                    self._emit_transient(
                        "status",
                        {
                            "summary": (
                                f"bash running ({int(elapsed)}s, "
                                f"captured={len(out_buf) + len(err_buf)}B{_idle_str})"
                            )
                        },
                    )
                    next_progress_emit = now + 0.8
                # Auto-confirm interactive prompts (Windows reader thread path)
                if proc.stdin and not proc.stdin.closed:
                    _tail = (bytes(out_buf[-300:]) + bytes(err_buf[-300:])).lower()
                    for _pat in _SHELL_AUTO_CONFIRM_PATTERNS:
                        if _pat in _tail and _pat not in _auto_confirmed:
                            try:
                                proc.stdin.write(b"y\n")
                                proc.stdin.flush()
                            except Exception:
                                pass
                            _auto_confirmed.add(_pat)
                            break
                if (proc.poll() is not None) and (not active_readers) and io_queue.empty():
                    break

            for th in reader_threads:
                try:
                    th.join(timeout=0.8)
                except Exception:
                    pass
            while True:
                try:
                    label, chunk = io_queue.get_nowait()
                except queue.Empty:
                    break
                if chunk is None:
                    continue
                if str(label) == "stderr":
                    _append_capture(err_buf, chunk)
                else:
                    _append_capture(out_buf, chunk)
            merged_raw = _merge_output_text()
            merged, _ = filter_runtime_noise_lines(merged_raw)
            if meta.get("error"):
                _store_shell_output(merged or str(meta["error"]))
            else:
                _store_shell_output(
                    merged or "(no output)",
                    int(proc.returncode if proc.returncode is not None else 0),
                )

        try:
            proc_env = os.environ.copy()
            proc_env["WORKSPACE_ROOT"] = str(self.root)
            proc_env["SESSION_ROOT"] = str(self.files_root)
            proc_env["SESSION_FILES_ROOT"] = str(self.files_root)
            proc_env["SKILLS_ROOT"] = str(self.skills.skills_root)
            proc_env["CLOUDS_CODER_ROOT"] = str(self.root)
            proc_env["JS_LIB_ROOT"] = str(self.js_lib_root)
            popen_kwargs = {
                "shell": True,
                "cwd": cwd,
                "stdin": subprocess.PIPE,
                "stdout": subprocess.PIPE,
                "stderr": subprocess.PIPE,
                "text": False,
                "bufsize": 0,
                "start_new_session": (os.name == "posix"),
                "env": proc_env,
            }
            if os.name == "nt":
                create_group = int(getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0) or 0)
                if create_group > 0:
                    popen_kwargs["creationflags"] = create_group
            proc = subprocess.Popen(effective_command, **popen_kwargs)
            self._running_bash_proc = proc
            if os.name == "nt":
                # Windows: read PIPE output via blocking reader threads + queue.
                _collect_with_reader_threads(proc)
            else:
                try:
                    with selectors.DefaultSelector() as sel:
                        if proc.stdout is not None:
                            try:
                                os.set_blocking(proc.stdout.fileno(), False)
                            except Exception:
                                pass
                            sel.register(proc.stdout, selectors.EVENT_READ, data="stdout")
                        if proc.stderr is not None:
                            try:
                                os.set_blocking(proc.stderr.fileno(), False)
                            except Exception:
                                pass
                            sel.register(proc.stderr, selectors.EVENT_READ, data="stderr")
                        _auto_confirmed: set[bytes] = set()
                        while True:
                            now = time.time()
                            elapsed = now - start
                            if self.cancel_requested:
                                _stop_process(proc)
                                meta["error"] = "Error: interrupted by user"
                                meta["exit_code"] = -130
                                break
                            elif timeout > 0 and (
                                (now - last_activity_ts[0]) >= timeout
                                or elapsed >= MAX_SHELL_COMMAND_TIMEOUT_SECONDS
                            ):
                                idle_secs = int(now - last_activity_ts[0])
                                meta["error"] = (
                                    f"Error: timeout (idle {idle_secs}s / limit {timeout}s)"
                                    if (now - last_activity_ts[0]) >= timeout
                                    else f"Error: hard cap reached ({int(elapsed)}s)"
                                )
                                _stop_process(proc)
                                meta["exit_code"] = -1
                                break
                            events = sel.select(timeout=0.12)
                            for key, _ in events:
                                stream = key.fileobj
                                try:
                                    chunk = os.read(stream.fileno(), 65536)
                                except BlockingIOError:
                                    continue
                                except Exception:
                                    chunk = b""
                                if not chunk:
                                    try:
                                        sel.unregister(stream)
                                    except Exception:
                                        pass
                                    continue
                                if key.data == "stderr":
                                    _append_capture(err_buf, chunk)
                                else:
                                    _append_capture(out_buf, chunk)
                            if now >= next_progress_emit:
                                _idle_secs = int(now - last_activity_ts[0])
                                _idle_str = f", idle={_idle_secs}s" if _idle_secs > 5 else ""
                                self._emit_transient(
                                    "status",
                                    {
                                        "summary": (
                                            f"bash running ({int(elapsed)}s, "
                                            f"captured={len(out_buf) + len(err_buf)}B{_idle_str})"
                                        )
                                    },
                                )
                                next_progress_emit = now + 0.8
                            # Auto-confirm interactive prompts (e.g. "Ok to proceed? (y)")
                            if proc.stdin and not proc.stdin.closed:
                                _tail = (bytes(out_buf[-300:]) + bytes(err_buf[-300:])).lower()
                                for _pat in _SHELL_AUTO_CONFIRM_PATTERNS:
                                    if _pat in _tail and _pat not in _auto_confirmed:
                                        try:
                                            proc.stdin.write(b"y\n")
                                            proc.stdin.flush()
                                        except Exception:
                                            pass
                                        _auto_confirmed.add(_pat)
                                        break
                            if (proc.poll() is not None) and (not sel.get_map()):
                                break
                        merged_raw = _merge_output_text()
                        merged, _ = filter_runtime_noise_lines(merged_raw)
                        if meta.get("error"):
                            _store_shell_output(merged or str(meta["error"]))
                        else:
                            _store_shell_output(
                                merged or "(no output)",
                                int(proc.returncode if proc.returncode is not None else 0),
                            )
                except Exception as exc:
                    # Some platforms may reject selector registration for PIPEs.
                    # On Windows, also catch any OSError (e.g. WinError 10093 WSANOTINITIALISED).
                    if is_benign_socket_error(exc) or isinstance(exc, ValueError) or (os.name == "nt" and isinstance(exc, OSError)):
                        _collect_with_reader_threads(proc)
                    else:
                        raise
        except Exception as exc:
            # On Windows, WinError 10038 (WSAENOTSOCK) can surface here when
            # selector-based I/O is used with pipe FDs. Fall back to thread-based reading.
            if proc is not None and is_benign_socket_error(exc):
                _collect_with_reader_threads(proc)
            else:
                meta["error"] = f"Error: {exc}"
                meta["output"] = meta["error"]
                meta["exit_code"] = -1
        finally:
            self._running_bash_proc = None
        meta["duration_ms"] = int((time.time() - start) * 1000)
        after = self._git_status_map(cwd)
        meta["changed_files"] = self._status_delta(before, after) if before or after else []
        if not meta.get("ui_output_pages"):
            meta.update(
                self._prepare_shell_output_payload(
                    command,
                    str(meta.get("output") or meta.get("error") or "(no output)"),
                    cwd=cwd,
                )
        )
        return meta

    def _shell_command_timeout(self) -> int:
        return normalize_timeout_seconds(
            getattr(self, "shell_command_timeout_seconds", DEFAULT_SHELL_COMMAND_TIMEOUT_SECONDS),
            minimum=MIN_SHELL_COMMAND_TIMEOUT_SECONDS,
            maximum=MAX_SHELL_COMMAND_TIMEOUT_SECONDS,
            fallback=DEFAULT_SHELL_COMMAND_TIMEOUT_SECONDS,
        )

    def _run_bash(self, command: str) -> str:
        return self._run_shell_meta(command, self.files_root, self._shell_command_timeout())["output"]

    def _fuzzy_resolve_path(self, fp: Path) -> Path:
        """If fp doesn't exist, try stripping spaces from the filename to find a close match.
        Handles the common model error of hallucinating spaces in Chinese/mixed filenames.
        Returns the resolved Path if found, otherwise the original fp unchanged."""
        if fp.exists():
            return fp
        stripped = fp.name.replace(" ", "")
        if stripped != fp.name:
            candidate = fp.parent / stripped
            if candidate.exists():
                return candidate
        try:
            query = fp.name.replace(" ", "").lower()
            for sibling in fp.parent.iterdir():
                if sibling.name.replace(" ", "").lower() == query:
                    return sibling
        except Exception:
            pass
        return fp

    def _suggest_workspace_paths(self, rel: str, limit: int = 6, max_scan: int = 1800) -> list[str]:
        target = str(rel or "").strip().replace("\\", "/")
        if not target:
            return []
        wanted = PurePosixPath(target)
        desired_name = wanted.name.lower()
        desired_compact = desired_name.replace(" ", "")
        desired_stem = wanted.stem.lower()
        parent_hint = str(wanted.parent).strip(". /").lower()
        if not desired_name and not parent_hint:
            return []
        scored: list[tuple[int, str]] = []
        seen: set[str] = set()
        scanned = 0
        skip_dirs = {".git", ".hg", ".svn", "node_modules", "__pycache__", ".mypy_cache", ".pytest_cache", ".ruff_cache"}
        for root, dirs, files in os.walk(self.files_root):
            dirs[:] = [d for d in dirs if d not in skip_dirs and not d.startswith(".")]
            entries = list(files) + list(dirs)
            for name in entries:
                scanned += 1
                if scanned > max_scan:
                    break
                full = Path(root) / name
                try:
                    rel_path = full.relative_to(self.files_root).as_posix()
                except Exception:
                    continue
                if rel_path in seen:
                    continue
                low = rel_path.lower()
                base = name.lower()
                compact = base.replace(" ", "")
                stem = Path(base).stem
                score = 0
                if desired_name and base == desired_name:
                    score += 90
                if desired_compact and compact == desired_compact:
                    score += 80
                if desired_stem and stem == desired_stem:
                    score += 65
                if desired_name and desired_name in low:
                    score += 28
                if desired_stem and desired_stem in stem:
                    score += 22
                if parent_hint and parent_hint in low:
                    score += 12
                if score <= 0:
                    continue
                seen.add(rel_path)
                scored.append((score, rel_path))
            if scanned > max_scan:
                break
        scored.sort(key=lambda row: (-row[0], len(row[1]), row[1]))
        return [path for _, path in scored[: max(1, int(limit or 1))]]

    def _render_directory_read(
        self,
        fp: Path,
        rel: str,
        limit: int | None = None,
        offset: int | None = None,
        *,
        query: object = "",
        max_chars: object = None,
    ) -> str:
        entries = sorted(
            list(fp.iterdir()),
            key=lambda p: (0 if p.is_dir() else 1, p.name.lower()),
        )
        total = len(entries)
        if total == 0:
            return f"[read_file directory path={rel} entries=0]\n(empty directory)"
        query_text = str(query or "").strip().lower()
        if query_text:
            filtered = [p for p in entries if query_text in p.name.lower() or query_text in p.as_posix().lower()]
        else:
            filtered = entries
        filtered_total = len(filtered)
        offset_val = self._read_file_int_arg(offset, 0, 0, max(0, filtered_total))
        requested_limit = self._read_file_int_arg(limit, 200 if query_text else 120, 1, 500)
        if offset_val >= filtered_total:
            return (
                f"[read_file directory path={rel} entries=0 of {filtered_total} total={total} offset={offset_val}]\n"
                "[end_of_directory]"
            )
        page = filtered[offset_val: offset_val + requested_limit]
        lines = [
            (
                f"[read_file directory path={rel} entries={offset_val + 1}-{offset_val + len(page)} "
                f"of {filtered_total} total={total} mode=directory"
                f"{f' query={query_text!r}' if query_text else ''}]"
            )
        ]
        for child in page:
            kind = "dir" if child.is_dir() else "file"
            try:
                size_text = f" ({child.stat().st_size} bytes)" if child.is_file() else ""
            except Exception:
                size_text = ""
            lines.append(f"{kind} {child.name}{size_text}")
        remaining = max(0, filtered_total - (offset_val + len(page)))
        if remaining > 0:
            lines.append(
                f"[directory has {remaining} more matching entries. Use query to narrow results, "
                "or read a specific subdirectory/file.]"
            )
        if not query_text and total > requested_limit:
            lines.append(f"[tip read_file path=\"{rel}\" mode=\"directory\" query=\"<name-fragment>\" narrows large directories]")
        return self._clip_read_file_output("\n".join(lines), self._read_file_max_chars(max_chars))

    def _read_text_with_fallback(self, fp: Path) -> str:
        tried: list[str] = []
        for enc in ("utf-8", "utf-8-sig", locale.getpreferredencoding(False) or "utf-8", "gb18030"):
            enc_norm = str(enc or "").strip() or "utf-8"
            if enc_norm in tried:
                continue
            tried.append(enc_norm)
            try:
                return fp.read_text(encoding=enc_norm)
            except UnicodeDecodeError:
                continue
        return fp.read_text(encoding="utf-8", errors="replace")

    def _render_missing_read_hint(self, rel: str) -> str:
        fb_ref = self._file_buffer_ref_from_text(rel)
        if fb_ref:
            expected = f"file_buffer/{fb_ref}.txt"
            return (
                f"Error: FileNotFoundError: {rel}\n"
                f"File-buffer hint: use read_file path=\"{expected}\" or reference `[file_buffer:{fb_ref}]`. "
                "If the buffer was compacted away, use the recent tool result summary/search context instead of repeating the same failed read."
            )
        if self._is_plan_file_rel_path(rel):
            if self._ensure_plan_file_current(force=True):
                try:
                    return self._read_plan_file() or self._runtime_managed_plan_missing_read_hint()
                except Exception:
                    pass
            return self._runtime_managed_plan_missing_read_hint()
        suggestions = self._suggest_workspace_paths(rel, limit=6)
        parent = PurePosixPath(str(rel or "").replace("\\", "/")).parent.as_posix()
        lines = [f"Error: FileNotFoundError: {rel}"]
        if suggestions:
            lines.append("Closest workspace matches:")
            lines.extend(f"- {cand}" for cand in suggestions)
        if parent and parent not in {".", ""}:
            lines.append(
                f"Path hint: if `{parent}` is the intended folder, read that directory or create `{rel}` with write_file."
            )
        lines.append(
            "Next action: reconcile the path against uploads/recent file paths, open one close match, "
            "or create the missing target instead of repeating the same failed read."
        )
        return "\n".join(lines)

    def _render_full_text_read(self, rel: str, lines: list[str], *, max_chars: object = None) -> str:
        full_text = "\n".join(lines)
        cap = self._read_file_max_chars(max_chars)
        if len(full_text) <= cap:
            return full_text
        header = (
            f"[read_file full path={rel} chars=1-{cap} of {len(full_text)} max_chars={cap}]\n"
        )
        return header + self._clip_read_file_output(
            full_text,
            cap,
            "For exact focused context, use mode=\"search\", mode=\"symbol\", or mode=\"window\"; "
            "for a wider full read, set a larger max_chars value.",
        )

    def _render_window_text_read(
        self,
        rel: str,
        lines: list[str],
        *,
        limit: int | None = None,
        offset: int | None = None,
        line: object = None,
        context: object = None,
        max_chars: object = None,
    ) -> str:
        total = len(lines)
        if total <= 0:
            return f"[read_file window path={rel} lines=0]\n[end_of_file]"
        ctx = self._read_file_int_arg(context, 60, 0, 2000)
        default_limit = ctx * 2 + 1 if line not in (None, "") else LONG_OUTPUT_READ_PAGE_LINES
        requested_limit = self._read_file_int_arg(limit, default_limit, 1, 4000)
        line_val = self._read_file_int_arg(line, 0, 0, max(1, total)) if line not in (None, "") else 0
        if line_val > 0:
            start = max(0, line_val - ctx - 1)
        else:
            start = self._read_file_int_arg(offset, 0, 0, max(0, total))
        end = min(total, start + requested_limit)
        if start >= total:
            return f"[read_file window path={rel} lines=0 of {total} start={start + 1}]\n[end_of_file]"
        body = "\n".join(lines[start:end])
        header = f"[read_file window path={rel} lines={start + 1}-{end} of {total}]\n"
        return header + self._clip_read_file_output(body, self._read_file_max_chars(max_chars))

    def _render_search_text_read(
        self,
        rel: str,
        lines: list[str],
        *,
        query: object = "",
        regex: object = False,
        context: object = None,
        max_chars: object = None,
    ) -> str:
        needle = str(query or "").strip()
        if not needle:
            return (
                f"[read_file search path={rel}]\n"
                "Error: query is required for mode=\"search\". Use mode=\"overview\" to inspect available structure."
            )
        ctx = self._read_file_int_arg(context, 6, 0, 80)
        total = len(lines)
        matches: list[int] = []
        if bool(regex):
            try:
                pattern = re.compile(needle)
            except re.error as exc:
                return f"Error: invalid regex for read_file search: {exc}"
            for idx, row in enumerate(lines):
                if pattern.search(row):
                    matches.append(idx)
                if len(matches) >= READ_FILE_SEARCH_MAX_MATCHES:
                    break
        else:
            low = needle.lower()
            for idx, row in enumerate(lines):
                if low in row.lower():
                    matches.append(idx)
                if len(matches) >= READ_FILE_SEARCH_MAX_MATCHES:
                    break
        if not matches:
            return f"[read_file search path={rel} query={needle!r} matches=0]\n(no matches)"
        ranges: list[tuple[int, int]] = []
        for idx in matches:
            start = max(0, idx - ctx)
            end = min(total, idx + ctx + 1)
            if ranges and start <= ranges[-1][1]:
                ranges[-1] = (ranges[-1][0], max(ranges[-1][1], end))
            else:
                ranges.append((start, end))
        out = [
            (
                f"[read_file search path={rel} query={needle!r} matches_returned={len(matches)} "
                f"windows={len(ranges)} total_lines={total}]"
            )
        ]
        for start, end in ranges:
            out.append(f"\n@@ lines {start + 1}-{end} @@")
            for line_no in range(start, end):
                out.append(f"{line_no + 1:>6}: {lines[line_no]}")
        return self._clip_read_file_output("\n".join(out), self._read_file_max_chars(max_chars))

    def _render_symbol_text_read(
        self,
        fp: Path,
        rel: str,
        lines: list[str],
        *,
        target: object = "",
        context: object = None,
        max_chars: object = None,
    ) -> str:
        symbol_name = str(target or "").strip()
        if not symbol_name:
            return (
                f"[read_file symbol path={rel}]\n"
                "Error: target is required for mode=\"symbol\".\n"
                + self._render_text_overview(fp, rel, lines, max_chars=max_chars)
            )
        data = self._read_file_code_data(fp, lines)
        symbols = data.get("symbols", []) if isinstance(data.get("symbols"), list) else []
        wanted = symbol_name.lower()

        def score(row: dict) -> int:
            name = str(row.get("name", "") or "").strip().lower()
            sig = str(row.get("signature", "") or "").strip().lower()
            if name == wanted:
                return 100
            if name.endswith("." + wanted):
                return 90
            if wanted in name:
                return 70
            if wanted in sig:
                return 50
            return 0

        ranked = sorted(((score(row), row) for row in symbols), key=lambda x: (-x[0], int(x[1].get("line_start", 0) or 0)))
        match = next((row for sc, row in ranked if sc > 0), None)
        if not match:
            available = ", ".join(str(row.get("name", "")) for row in symbols[:40] if str(row.get("name", "")).strip())
            return (
                f"[read_file symbol path={rel} target={symbol_name!r} matches=0]\n"
                f"Available symbols: {available or '(none detected)'}\n"
                f"Try read_file path=\"{rel}\" mode=\"search\" query=\"{symbol_name}\""
            )
        total = len(lines)
        ctx = self._read_file_int_arg(context, 0, 0, 1000)
        start = max(1, int(match.get("line_start", 1) or 1) - ctx)
        end = min(total, int(match.get("line_end", start) or start) + ctx)
        body = "\n".join(lines[start - 1:end])
        header = (
            f"[read_file symbol path={rel} target={symbol_name!r} "
            f"matched={match.get('kind', 'symbol')} {match.get('name', '')} lines={start}-{end} of {total}]\n"
        )
        return header + self._clip_read_file_output(body, self._read_file_max_chars(max_chars))

    def _run_read(
        self,
        path: str,
        limit: int | None = None,
        offset: int | None = None,
        *,
        mode: object = None,
        target: object = "",
        query: object = "",
        line: object = None,
        context: object = None,
        regex: object = False,
        max_chars: object = None,
    ) -> str:
        try:
            rel = self._normalize_tool_path_text(path)
            fp = self._fuzzy_resolve_path(self._session_path(rel))
            rel = self._session_rel(fp)
            if self._is_plan_file_rel_path(rel) and not fp.exists():
                self._ensure_plan_file_current(force=True)
            if not fp.exists():
                return self._render_missing_read_hint(rel)
            if fp.is_dir():
                return self._render_directory_read(fp, rel, limit=limit, offset=offset, query=query, max_chars=max_chars)
            # Multimodal: detect image/audio/video files and handle natively
            ext = fp.suffix.lower() if fp.suffix else ""
            if ext in IMAGE_EXTS:
                return self._run_read_media(fp, rel, "image")
            if ext in AUDIO_EXTS:
                return self._run_read_media(fp, rel, "audio")
            if ext in VIDEO_EXTS:
                return self._run_read_media(fp, rel, "video")
            lines = self._read_text_with_fallback(fp).splitlines()
            total_lines = len(lines)
            if total_lines == 0:
                return ""
            try:
                file_size = int(fp.stat().st_size)
            except Exception:
                file_size = 0
            mode_text = str(mode or "auto").strip().lower() or "auto"
            if mode_text not in {"auto", "full", "overview", "window", "symbol", "search", "directory"}:
                mode_text = "auto"
            if mode_text == "auto":
                if str(target or "").strip():
                    mode_text = "symbol"
                elif str(query or "").strip():
                    mode_text = "search"
                elif line not in (None, ""):
                    mode_text = "window"
            if mode_text == "directory":
                return f"Error: path is a file, not a directory: {rel}"
            if mode_text == "overview":
                return self._render_text_overview(fp, rel, lines, max_chars=max_chars)
            if mode_text == "full":
                return self._render_full_text_read(rel, lines, max_chars=max_chars)
            if mode_text == "search":
                return self._render_search_text_read(
                    rel,
                    lines,
                    query=query or target,
                    regex=regex,
                    context=context,
                    max_chars=max_chars,
                )
            if mode_text == "symbol":
                return self._render_symbol_text_read(
                    fp,
                    rel,
                    lines,
                    target=target or query,
                    context=context,
                    max_chars=max_chars,
                )
            if (
                mode_text == "window"
                or limit is not None
                or self._read_file_int_arg(offset, 0, 0, 1_000_000) > 0
                or line not in (None, "")
            ):
                return self._render_window_text_read(
                    rel,
                    lines,
                    limit=limit,
                    offset=offset,
                    line=line,
                    context=context,
                    max_chars=max_chars,
                )
            if (
                limit is None
                and self._read_file_int_arg(offset, 0, 0, 1_000_000) <= 0
                and (file_size >= LARGE_FILE_AUTO_PAGE_BYTES or total_lines >= LARGE_FILE_AUTO_PAGE_LINES)
            ):
                return self._render_text_overview(fp, rel, lines, max_chars=max_chars)
            full_text = "\n".join(lines)
            if len(full_text) <= self._read_file_max_chars(max_chars):
                return full_text
            return self._render_text_overview(fp, rel, lines, max_chars=max_chars)
        except Exception as exc:
            return f"Error: {type(exc).__name__}: {exc}"

    def _run_read_media(self, fp: Path, rel: str, media_type: str) -> str:
        """Read a media file and return description or inject into multimodal context."""
        if not fp.exists():
            return f"Error: file not found: {rel}"
        caps = self._capabilities_from_profile()
        cap_key = f"input_{media_type}"
        file_size = fp.stat().st_size
        size_kb = file_size / 1024
        if bool(caps.get(cap_key, False)) and file_size < 20 * 1024 * 1024:
            # Model supports this media type — check format compatibility first
            ext = fp.suffix.lower()
            if media_type == "image" and ext == ".svg":
                # SVG: read as text source code instead of injecting as image
                try:
                    svg_text = fp.read_text(encoding="utf-8", errors="replace")
                    return (
                        f"[SVG file: {rel} ({size_kb:.1f} KB)]\n"
                        f"SVG source code (use for analysis, do not send as image):\n"
                        f"```svg\n{trim(svg_text, 12000)}\n```"
                    )
                except Exception as exc:
                    return f"Error reading SVG file: {exc}"
            if media_type == "image" and ext in IMAGE_FORMATS_NEED_CONVERSION:
                # Try converting to a safe format via Pillow
                converted, conv_mime, method = _convert_image_to_safe_format(fp)
                if converted:
                    b64 = base64.b64encode(converted).decode("ascii")
                    mime = conv_mime
                else:
                    return (
                        f"[{media_type} file: {rel} ({size_kb:.1f} KB, format={ext})] "
                        f"Note: format {ext} could not be converted for native vision. "
                        f"File exists at {fp}. Use bash tools to process it if needed."
                    )
            else:
                # Safe format — encode directly
                try:
                    b64 = base64.b64encode(fp.read_bytes()).decode("ascii")
                    mime = guess_mime_from_name(fp.name)
                except Exception as exc:
                    return f"Error reading {media_type} file: {exc}"
            media_item = {
                "type": media_type,
                "data_b64": b64,
                "mime": mime,
                "name": fp.name,
                "workspace_path": str(rel),
            }
            # Store for injection into next API call
            with self.lock:
                self._pending_media_inputs.append(media_item)
            return (
                f"[{media_type} file loaded: {rel} ({size_kb:.1f} KB, {mime})] "
                f"The {media_type} has been attached to the conversation for native {media_type} analysis. "
                f"Describe or analyze it directly."
            )
        else:
            # Model doesn't support this media type — return metadata only
            reason = "model does not support" if not caps.get(cap_key) else "file too large"
            return (
                f"[{media_type} file: {rel} ({size_kb:.1f} KB)] "
                f"Note: {reason} native {media_type} input. "
                f"File exists at {fp}. Use bash tools to process it if needed."
            )

    def _tool_result_context_content(
        self,
        name: str,
        args: dict | None,
        output: object,
        default_limit: int = MAX_TOOL_OUTPUT,
    ) -> str:
        text = str(output or "")
        tool_name = canonicalize_tool_name(name)
        if tool_name == "read_file":
            req = (args or {}).get("max_chars") if isinstance(args, dict) else None
            requested = self._read_file_max_chars(req, default=READ_FILE_DEFAULT_MAX_CHARS)
            cap = max(int(default_limit or 0), min(int(READ_FILE_HARD_MAX_CHARS), requested))
            return trim(text, cap)
        return trim(text, int(default_limit or MAX_TOOL_OUTPUT))

    def _is_html_file_rel(self, path: str) -> bool:
        low = str(path or "").strip().lower()
        return low.endswith(".html") or low.endswith(".htm")

    def _resolve_offline_js_asset_for_url(self, src_url: str) -> tuple[Path | None, str]:
        if not is_external_js_src(src_url):
            return None, "not-external"
        target_url = _normalize_external_js_url(src_url)
        catalog = match_offline_js_catalog_by_url(target_url)
        if catalog:
            filename = _safe_js_filename(
                str(catalog.get("filename", "") or f"{catalog.get('id', 'lib')}.js"),
                "lib.js",
            )
            fp = (self.js_lib_root / filename).resolve()
            if fp.exists() and fp.is_file() and fp.stat().st_size > 40:
                return fp, "catalog"
            try:
                ensure_offline_js_libs(self.js_lib_root.parent, force=False)
            except Exception:
                pass
            if fp.exists() and fp.is_file() and fp.stat().st_size > 40:
                return fp, "catalog-refreshed"
        cached_fp, reason = cache_external_js_url(self.js_lib_root, target_url)
        if cached_fp and cached_fp.exists() and cached_fp.is_file():
            return cached_fp, reason
        return None, reason

    def _localize_html_js_dependencies(self, rel_path: str) -> dict:
        if not self._is_html_file_rel(rel_path):
            return {"applied": False, "summary": ""}
        try:
            html_fp = self._session_path(rel_path)
        except Exception as exc:
            return {"applied": False, "summary": f"offline-js skipped ({exc})"}
        if not html_fp.exists() or (not html_fp.is_file()):
            return {"applied": False, "summary": ""}
        src = try_read_text(html_fp)
        if src is None:
            return {"applied": False, "summary": ""}
        js_dir = (html_fp.parent / "js").resolve()
        rewritten_count = 0
        copied: list[str] = []
        unresolved: list[str] = []
        copied_set: set[str] = set()
        unresolved_set: set[str] = set()

        def _resolve_and_rewrite(url: str) -> str | None:
            nonlocal rewritten_count
            asset, reason = self._resolve_offline_js_asset_for_url(url)
            if not asset:
                key = _normalize_external_js_url(url)
                if key and key not in unresolved_set:
                    unresolved_set.add(key)
                    unresolved.append(f"{key} ({reason})")
                return None
            js_dir.mkdir(parents=True, exist_ok=True)
            dst_name = _safe_js_filename(asset.name, "lib.js")
            dst = (js_dir / dst_name).resolve()
            try:
                if (not dst.exists()) or dst.stat().st_size != asset.stat().st_size:
                    shutil.copy2(asset, dst)
            except Exception as exc:
                key = _normalize_external_js_url(url)
                if key and key not in unresolved_set:
                    unresolved_set.add(key)
                    unresolved.append(f"{key} (copy-failed:{trim(str(exc), 120)})")
                return None
            if dst_name not in copied_set:
                copied_set.add(dst_name)
                copied.append(dst_name)
            rewritten_count += 1
            return f"./js/{dst_name}"

        quoted_re = re.compile(
            r"(?is)(?P<prefix><script\b[^>]*?\bsrc\s*=\s*)(?P<q>['\"])(?P<url>[^\"']+)(?P=q)"
        )
        unquoted_re = re.compile(
            r"(?is)(?P<prefix><script\b[^>]*?\bsrc\s*=\s*)(?P<url>[^\s\"'>]+)"
        )

        def _replace_quoted(m: re.Match) -> str:
            full = m.group(0)
            url = str(m.group("url") or "").strip()
            if not is_external_js_src(url):
                return full
            repl = _resolve_and_rewrite(url)
            if not repl:
                return full
            q = str(m.group("q") or "\"")
            return f"{m.group('prefix')}{q}{repl}{q}"

        def _replace_unquoted(m: re.Match) -> str:
            full = m.group(0)
            url = str(m.group("url") or "").strip()
            if (not url) or (not is_external_js_src(url)):
                return full
            repl = _resolve_and_rewrite(url)
            if not repl:
                return full
            return f"{m.group('prefix')}{repl}"

        after = quoted_re.sub(_replace_quoted, src)
        after = unquoted_re.sub(_replace_unquoted, after)
        if after != src:
            html_fp.write_text(after, encoding="utf-8")
        if rewritten_count <= 0 and not unresolved:
            return {"applied": False, "summary": ""}
        summary = (
            f"offline-js: localized={rewritten_count}, copied={len(copied)}, "
            f"unresolved={len(unresolved)} for {self._session_rel(html_fp)}"
        )
        return {
            "applied": rewritten_count > 0,
            "summary": summary,
            "localized": rewritten_count,
            "copied": copied,
            "unresolved": unresolved,
            "path": self._session_rel(html_fp),
        }

    def _run_write(self, path: str, content: str) -> str:
        try:
            rel = self._normalize_tool_path_text(path)
            fp = self._fuzzy_resolve_path(self._session_path(rel))
            rel = self._session_rel(fp)
            fp.parent.mkdir(parents=True, exist_ok=True)
            fp.write_text(content, encoding="utf-8")
            return f"Wrote {len(content)} bytes to {rel}"
        except Exception as exc:
            return f"Error: {type(exc).__name__}: {exc}"

    def _run_edit(self, path: str, old_text: str, new_text: str) -> str:
        try:
            rel = self._normalize_tool_path_text(path)
            fp = self._fuzzy_resolve_path(self._session_path(rel))
            rel = self._session_rel(fp)
            content = fp.read_text(encoding="utf-8")
            if old_text not in content:
                diag = self._edit_mismatch_diagnostic(content, old_text)
                return f"Error: text not found in {rel}. {diag}"
            fp.write_text(content.replace(old_text, new_text, 1), encoding="utf-8")
            return f"Edited {rel}"
        except Exception as exc:
            return f"Error: {type(exc).__name__}: {exc}"

    def _edit_mismatch_diagnostic(self, content: str, old_text: str) -> str:
        """为 edit_file 匹配失败提供诊断信息"""
        lines = content.splitlines()
        first_line = old_text.strip().splitlines()[0].strip() if old_text.strip() else ""
        if not first_line:
            return "The old_text is empty or whitespace-only."
        # Locate the first line of old_text inside the current file content.
        matches = []
        for i, line in enumerate(lines, 1):
            if first_line in line:
                matches.append(i)
        if matches:
            loc = ", ".join(str(m) for m in matches[:5])
            return (
                f"The first line of old_text was found at line(s) {loc}, "
                f"but the full multi-line match failed. "
                f"Likely cause: whitespace or indentation mismatch. "
                f"Tip: use read_file to get the exact content, then copy it precisely."
            )
        # Retry with whitespace-normalized matching before failing the edit.
        norm_first = " ".join(first_line.split())
        for i, line in enumerate(lines, 1):
            norm_line = " ".join(line.split())
            if norm_first and norm_first in norm_line:
                return (
                    f"A whitespace-normalized partial match was found near line {i}. "
                    f"The old_text likely has wrong indentation or extra/missing spaces. "
                    f"Use read_file to get exact content."
                )
        return (
            f"No match found. The file has {len(lines)} lines. "
            f"The old_text first line '{first_line[:60]}' does not appear in the file. "
            f"The content may have changed since last read. Use read_file to refresh."
        )

    def _write_global_skill(self, args: dict) -> str:
        rel_raw = str(args.get("path", "") or "").strip().replace("\\", "/")
        if not rel_raw:
            return "Error: path is required"
        rel_path = Path(rel_raw)
        if rel_path.name.lower() == "skill.md":
            final_rel = rel_path.parent / "SKILL.md"
        else:
            final_rel = rel_path / "SKILL.md"
        try:
            target = safe_path(final_rel.as_posix(), self.skills.skills_root)
        except Exception as exc:
            return f"Error: invalid skill path: {exc}"
        overwrite = bool(args.get("overwrite", False))
        if target.exists() and not overwrite:
            return (
                f"Error: skill already exists at {target}. "
                "Set overwrite=true to replace it."
            )
        body = str(args.get("content", "") or "").strip()
        if not body:
            return "Error: content is required"
        meta, _ = parse_front_matter(body)
        if not meta.get("name") or not meta.get("description"):
            inferred_name = re.sub(r"[^A-Za-z0-9._-]+", "-", target.parent.name).strip("-") or "custom-skill"
            inferred_desc = "User provided reusable skill."
            if body.startswith("---"):
                # Keep user content unchanged if it already carries front matter.
                pass
            else:
                body = (
                    "---\n"
                    f"name: {inferred_name}\n"
                    f"description: {inferred_desc}\n"
                    "---\n\n"
                    f"{body}\n"
                )
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(body, encoding="utf-8")
        try:
            self._ensure_skills_ready(force=True)
            self.skill_load_cache = {}
        except Exception:
            pass
        try:
            rel_saved = target.resolve().relative_to(self.skills.skills_root.resolve()).as_posix()
        except Exception:
            rel_saved = str(target)
        self._emit(
            "skill_write",
            {
                "path": rel_saved,
                "summary": f"skill written: {rel_saved}",
            },
        )
        return f"OK: wrote skill to {rel_saved}"

    def _scan_global_skills(self) -> str:
        try:
            self._ensure_skills_ready(force=True)
        except Exception:
            pass
        payload = {
            "skills_count": len(self.skills.skills),
            "skill_names": sorted(self.skills.list_names())[:240],
            "providers": self.skills.list_providers(),
            "protocols": self.skills.list_protocols(),
            "warnings": list(self.skills.warnings),
        }
        return json_dumps(payload, indent=2)

    def run_subagent(self, prompt: str, agent_type: str = "Explore") -> str:
        subtools = [
            tool_def("bash", "Run command.", {"command": {"type": "string"}}, ["command"]),
            tool_def(
                "read_file",
                (
                    "Read files or directories with structure-aware modes. "
                    "Examples: large.py + func_42 -> mode='symbol' target='func_42'; "
                    "app.py line 240 -> mode='window' line=240 context=5; "
                    "run.txt E123 -> mode='search' query='E123'. "
                    "Use mode='symbol', 'search', or 'window' for focused reads; use mode='full' only when needed. "
                    "Successful reads are remembered in the tool-memory registry."
                ),
                {
                    "path": {"type": "string"},
                    "mode": {
                        "type": "string",
                        "enum": ["auto", "full", "overview", "window", "symbol", "search", "directory"],
                        "description": "Reading strategy. Use symbol with target for a function/class; search with query for known text/errors; window with line/context for a line range. Avoid full for large logs when a query is known.",
                    },
                    "target": {"type": "string", "description": "Symbol name for mode='symbol', for example 'ClassName.method' or 'func_42'."},
                    "query": {"type": "string", "description": "Search text or regex for mode='search'; can also be used when target is unknown."},
                    "line": {"type": "integer", "description": "1-based center line for mode='window'."},
                    "context": {"type": "integer", "description": "Number of surrounding lines for mode='window' or mode='search'."},
                    "regex": {"type": "boolean", "description": "Treat query as a regular expression in mode='search'."},
                    "max_chars": {"type": "integer", "description": "Maximum characters to return for broad reads; use only when wider context is needed."},
                    "limit": {"type": "integer", "description": "Legacy line count for compatibility; prefer mode/context for new calls."},
                    "offset": {"type": "integer", "description": "Legacy 0-based line offset for compatibility; prefer mode='window' with line/context."},
                },
                ["path"],
            ),
        ]
        if agent_type != "Explore":
            subtools.extend(
                [
                    tool_def("write_file", "Write file.", {"path": {"type": "string"}, "content": {"type": "string"}}, ["path", "content"]),
                    tool_def("edit_file", "Edit file.", {"path": {"type": "string"}, "old_text": {"type": "string"}, "new_text": {"type": "string"}}, ["path", "old_text", "new_text"]),
                ]
            )
        msgs = [{"role": "user", "content": prompt}]
        last_text = ""
        pinned_selection = self._active_runtime_selection()
        for _ in range(20):
            try:
                sub_system = f"You are a focused subagent. {model_language_instruction(self.ui_language)}"
                response = self._chat_with_same_model_retry(
                    msgs,
                    tools=subtools,
                    system=sub_system,
                    think=False,
                    pinned_selection=pinned_selection,
                    context_label="subagent",
                    retries=MODEL_OUTPUT_RETRY_TIMES,
                )
            except OllamaError as exc:
                return f"Error: {exc}"
            text = str(response.get("content") or "")
            tcs = response.get("tool_calls", [])
            entry = {"role": "assistant", "content": text}
            if tcs:
                entry["tool_calls"] = [
                    {
                        "id": t["id"],
                        "type": "function",
                        "function": {"name": t["function"]["name"], "arguments": json_dumps(t["function"]["arguments"])},
                    }
                    for t in tcs
                ]
            msgs.append(entry)
            last_text = text or last_text
            if not tcs:
                break
            for tc in tcs:
                name = tc["function"]["name"]
                args = tc["function"]["arguments"]
                args_error = str(tc.get("args_error", "") or "").strip()
                raw_args = tc.get("raw_arguments")
                if args_error:
                    if name in {"TodoWrite", "TodoWriteRescue"}:
                        repaired, repaired_out = self._attempt_malformed_tool_repair(name, raw_args)
                        if repaired:
                            msgs.append({"role": "tool", "tool_call_id": tc["id"], "name": name, "content": trim(repaired_out)})
                            continue
                    out = (
                        f"Error: malformed arguments for tool '{name}'. {args_error}. "
                        "Please regenerate this tool call with complete JSON arguments."
                    )
                    msgs.append({"role": "tool", "tool_call_id": tc["id"], "name": name, "content": trim(out)})
                    continue
                missing = self._missing_required_args(name, args)
                if missing:
                    repaired, repaired_out = self._attempt_malformed_tool_repair(name, args)
                    if repaired:
                        msgs.append({"role": "tool", "tool_call_id": tc["id"], "name": name, "content": trim(repaired_out)})
                        continue
                    out = (
                        f"Error: tool '{name}' missing required arguments: {', '.join(missing)}. "
                        "Likely truncated tool call. Please regenerate complete JSON arguments."
                    )
                    msgs.append({"role": "tool", "tool_call_id": tc["id"], "name": name, "content": trim(out)})
                    continue
                if name == "bash":
                    out = self._run_bash(args.get("command", ""))
                    self._maybe_record_tool_memory_after_result(name, args if isinstance(args, dict) else {}, out, "single")
                elif name == "read_file":
                    out = self._run_read(
                        args.get("path", ""),
                        args.get("limit"),
                        args.get("offset"),
                        mode=args.get("mode"),
                        target=args.get("target"),
                        query=args.get("query"),
                        line=args.get("line"),
                        context=args.get("context"),
                        regex=args.get("regex"),
                        max_chars=args.get("max_chars"),
                    )
                    try:
                        rel = self._session_rel(self._session_path(self._normalize_tool_path_text(args.get("path", ""))))
                        self._record_read_context(rel, args if isinstance(args, dict) else {}, out, role="single")
                    except Exception:
                        pass
                elif name == "write_file":
                    out = self._run_write(args.get("path", ""), args.get("content", ""))
                    if not str(out).startswith("Error:"):
                        try:
                            rel = self._session_rel(self._session_path(self._normalize_tool_path_text(args.get("path", ""))))
                            self._mark_read_context_stale(rel, reason="subagent write_file changed file")
                        except Exception:
                            pass
                    self._maybe_record_tool_memory_after_result(name, args if isinstance(args, dict) else {}, out, "single")
                elif name == "edit_file":
                    out = self._run_edit(args.get("path", ""), args.get("old_text", ""), args.get("new_text", ""))
                    if not str(out).startswith("Error:"):
                        try:
                            rel = self._session_rel(self._session_path(self._normalize_tool_path_text(args.get("path", ""))))
                            self._mark_read_context_stale(rel, reason="subagent edit_file changed file")
                        except Exception:
                            pass
                    self._maybe_record_tool_memory_after_result(name, args if isinstance(args, dict) else {}, out, "single")
                else:
                    out = f"Unknown tool: {name}"
                msgs.append({
                    "role": "tool",
                    "tool_call_id": tc["id"],
                    "name": name,
                    "content": self._tool_result_context_content(name, args if isinstance(args, dict) else {}, out),
                })
        return last_text or "(subagent done)"

    def _spawn_teammate(self, name: str, role: str, prompt: str) -> str:
        member = self.teammates.get(name)
        if member and member.get("status") == "working":
            return f"Error: teammate '{name}' already working"
        self.teammates[name] = {"name": name, "role": role, "status": "working", "updated_at": now_ts()}

        def worker():
            try:
                result = self.run_subagent(f"Teammate={name}, role={role}\n{prompt}", agent_type="general-purpose")
                self.bus.send(name, "lead", f"[{name}] {result}", "message")
                status = "idle"
            except Exception as exc:
                self.bus.send(name, "lead", f"[{name}] failed: {exc}", "message")
                status = "error"
            with self.lock:
                if name in self.teammates:
                    self.teammates[name]["status"] = status
                    self.teammates[name]["updated_at"] = now_ts()
                self._emit("teammate", {"summary": f"{name} -> {status}"})
                self._persist()

        threading.Thread(target=worker, daemon=True).start()
        return f"Spawned teammate '{name}' ({role})"

    def _list_teammates(self) -> str:
        if not self.teammates:
            return "No teammates."
        lines = []
        for m in self.teammates.values():
            lines.append(f"{m['name']} ({m['role']}): {m['status']}")
        return "\n".join(lines)

    def _handle_shutdown_request(self, teammate: str) -> str:
        req_id = make_id("shutdown")
        self.shutdown_requests[req_id] = {"target": teammate, "status": "pending"}
        self.bus.send("lead", teammate, "Please shut down.", "shutdown_request", {"request_id": req_id})
        if teammate in self.teammates:
            self.teammates[teammate]["status"] = "shutdown"
        return f"Shutdown request {req_id} sent to '{teammate}'"

    def _handle_plan_approval(self, request_id: str, approve: bool, feedback: str = "") -> str:
        req = self.plan_requests.get(request_id)
        if not req:
            return f"Error: unknown plan request_id '{request_id}'"
        req["status"] = "approved" if approve else "rejected"
        self.bus.send("lead", req["from"], feedback, "plan_approval_response", {"request_id": request_id, "approve": approve, "feedback": feedback})
        return f"Plan {req['status']} for '{req['from']}'"

    def _is_html_frontend_goal(self, text: str) -> bool:
        probe = str(text or "").strip().lower()
        if not probe:
            return False
        for key in HTML_FRONTEND_REQUEST_KEYWORDS:
            k = str(key or "").strip().lower()
            if k and k in probe:
                return True
        return False

    def _html_frontend_boost_instruction(self) -> str:
        goal = self._latest_user_goal_text()
        if not self._is_html_frontend_goal(goal):
            return ""
        index = load_offline_js_lib_index(self.js_lib_root)
        available_rows = [
            str(item.get("id", "")).strip()
            for item in (index.get("libs", []) if isinstance(index, dict) else [])
            if isinstance(item, dict) and bool(item.get("available", False))
        ]
        libs_hint = ", ".join([x for x in available_rows if x][:10]) if available_rows else "none"
        return (
            "Current task is likely frontend/html/report oriented. "
            "Load specialized skills when needed: "
            "load_skill('html-report-engineering'), "
            "load_skill('frontend-composition-algorithm'), "
            "load_skill('visualization-report-pipeline'), "
            "load_skill('offline-html-js-bundling'). "
            "Use this build algorithm: "
            "1) define audience + acceptance criteria; "
            "2) draft information architecture; "
            "3) scaffold semantic HTML; "
            "4) apply CSS tokens + responsive layout; "
            "5) wire JS state/data interactions; "
            "6) localize external JS dependencies to a task-local relative folder such as ./js from ./js_lib, and rewrite final HTML to plain relative paths; "
            "7) run QA loop for desktop/mobile/a11y/performance and iterate. "
            f"Offline JS libs available now: {libs_hint}. "
            "Final exported HTML should avoid unresolved CDN-only script src and must not keep '/js_lib/...' or '/assets/js_lib/...' virtual URLs."
        )

    def _contains_any_keyword(self, text: str, keywords: tuple[str, ...]) -> bool:
        probe = str(text or "").strip().lower()
        if not probe:
            return False
        for row in keywords:
            key = str(row or "").strip().lower()
            if key and key in probe:
                return True
        return False

    def _is_deep_research_goal(self, text: str) -> bool:
        return self._contains_any_keyword(text, DEEP_RESEARCH_REQUEST_KEYWORDS)

    def _http_probe_ok(self, url: str, timeout: float = 4.0) -> bool:
        target = str(url or "").strip()
        if not target:
            return False
        try:
            req = Request(target, headers={"User-Agent": "Mozilla/5.0"})
            with urlopen(req, timeout=timeout) as resp:
                status = int(getattr(resp, "status", 0) or 0)
                if 200 <= status < 400:
                    return True
        except Exception:
            return False
        return False

    def _probe_live_search_runtime(self, force: bool = False) -> dict[str, object]:
        now_tick = float(now_ts())
        cached = self.research_probe_cache if isinstance(self.research_probe_cache, dict) else {}
        checked_at = float(cached.get("checked_at", 0.0) or 0.0)
        if (not force) and checked_at > 0 and (now_tick - checked_at) < 180:
            return {
                "checked_at": checked_at,
                "online_ok": bool(cached.get("online_ok", False)),
                "search_ok": bool(cached.get("search_ok", False)),
                "mode": str(cached.get("mode", "simulated") or "simulated"),
                "reason": str(cached.get("reason", "") or ""),
            }
        online_ok = False
        search_ok = False
        reason = "offline"
        try:
            online_ok = self._http_probe_ok("https://example.com", timeout=4.0) or self._http_probe_ok(
                "https://www.wikipedia.org", timeout=4.0
            )
            if online_ok:
                search_ok = self._http_probe_ok("https://duckduckgo.com/?q=research", timeout=5.0)
                if search_ok:
                    reason = "search-ready"
                else:
                    reason = "internet-ok-search-check-failed"
            else:
                search_ok = False
                reason = "network-unreachable"
        except Exception as exc:
            online_ok = False
            search_ok = False
            reason = f"probe-error:{trim(str(exc), 120)}"
        mode = "online" if search_ok else "simulated"
        payload = {
            "checked_at": now_tick,
            "online_ok": bool(online_ok),
            "search_ok": bool(search_ok),
            "mode": mode,
            "reason": reason,
        }
        self.research_probe_cache = dict(payload)
        return payload

    def _detect_deep_research_mode(self, text: str) -> str:
        goal = str(text or "").strip()
        if not self._is_deep_research_goal(goal):
            return ""
        force_text_only = self._contains_any_keyword(goal, DEEP_RESEARCH_TEXT_ONLY_HINT_KEYWORDS)
        retrieval_requested = self._contains_any_keyword(goal, DEEP_RESEARCH_RETRIEVAL_KEYWORDS)
        if force_text_only and (not retrieval_requested):
            return "text_deep_analysis"
        if retrieval_requested:
            probe = self._probe_live_search_runtime(force=False)
            return "retrieval_integrated_online" if bool(probe.get("search_ok", False)) else "retrieval_integrated_simulated"
        return "text_deep_analysis"

    def _deep_research_boost_instruction(self) -> str:
        goal = self._latest_user_goal_text()
        mode = self._detect_deep_research_mode(goal)
        if not mode:
            return ""
        probe = self._probe_live_search_runtime(force=False)
        if mode == "text_deep_analysis":
            mode_hint = "Mode=text_deep_analysis (independent text deep analysis)."
        elif mode == "retrieval_integrated_online":
            mode_hint = "Mode=retrieval_integrated_online (internet retrieval synthesis)."
        else:
            mode_hint = (
                "Mode=retrieval_integrated_simulated (internet/search unavailable; use model-knowledge simulated retrieval cards)."
            )
        return (
            "Current task is deep-research oriented. "
            "Load specialized skills when needed: "
            "load_skill('deep-research-orchestrator'), "
            "load_skill('retrieval-synthesis-fallback'), "
            "load_skill('pdf-vision-literature-integrator'). "
            f"{mode_hint} "
            f"Search runtime probe: online_ok={bool(probe.get('online_ok', False))}, "
            f"search_ok={bool(probe.get('search_ok', False))}, reason={probe.get('reason', '')}. "
            "If analyzing PDF literature and image capability is available, integrate extracted PDF figures with textual evidence. "
            "If model image-input capability is false, skip figure extraction and stay in text-only evidence mode. "
            "Final output must be a structured markdown deep-analysis report."
        )

    def _latest_user_goal_text(self) -> str:
        for msg in reversed(self.messages):
            if msg.get("role") != "user":
                continue
            text = str(msg.get("content", "")).strip()
            if not text:
                continue
            if text.startswith("<"):
                continue
            return trim(text.replace("\n", " "), 220)
        return "current task"

    def _compose_default_direct_objective(self, base_objective: str, goal: str, task_type: str) -> str:
        base = trim(str(base_objective or "").strip(), 520)
        goal_clean = trim(strip_thinking_content(str(goal or "")).replace("\n", " ").strip(), 220)
        path_hits = re.findall(
            r"(?:[A-Za-z0-9_.-]+/)*[A-Za-z0-9_.-]+\.(?:py|js|ts|tsx|jsx|java|go|rs|md|json|yaml|yml|toml|ini|sh|html|css|c|cpp|h)",
            goal_clean,
        )
        uniq_paths: list[str] = []
        for item in path_hits:
            one = trim(str(item or "").strip(), 80)
            if one and one not in uniq_paths:
                uniq_paths.append(one)
            if len(uniq_paths) >= 3:
                break
        if uniq_paths:
            anchor = f" Project anchors: {', '.join(uniq_paths)}."
        elif goal_clean:
            anchor = f" Project anchor: {goal_clean}."
        else:
            anchor = " Project anchor: current repository context."
        if task_type == "simple_qa":
            postfix = " Keep orchestration lightweight and answer directly with project-aware specifics."
        else:
            postfix = (
                " Keep orchestration lightweight and execution-first. "
                "Use bounded creativity for ambiguous details while preserving existing architecture and constraints."
            )
        return trim(f"{base}{anchor}{postfix}", 800)

    def _normalize_task_profile(self, goal: str, raw: object) -> dict:
        base = self._infer_task_profile(goal)
        src = raw if isinstance(raw, dict) else {}
        task_type = trim(
            str(src.get("task_type", base.get("task_type", "general")) or "").strip().lower(),
            40,
        ) or str(base.get("task_type", "general"))
        if task_type not in TASK_PROFILE_TYPES:
            task_type = str(base.get("task_type", "general"))
        complexity = normalize_task_complexity(
            src.get("complexity", base.get("complexity", "simple")),
            default=str(base.get("complexity", "simple") or "simple"),
        )
        src_direct_objective = trim(str(src.get("direct_objective", "") or "").strip(), 800)
        legacy_objectives = {
            "Provide the most direct useful response with minimal orchestration.",
            (
                "Provide the most direct useful response with minimal orchestration, "
                "anchored to the current project context and user goal."
            ),
        }
        if src_direct_objective and src_direct_objective not in legacy_objectives:
            direct_objective = src_direct_objective
        else:
            direct_objective = self._compose_default_direct_objective(
                str(base.get("direct_objective", "")),
                goal,
                task_type,
            )
        rec_raw = src.get("recommended_agents", base.get("recommended_agents", []))
        recommended: list[str] = []
        if isinstance(rec_raw, list):
            for item in rec_raw:
                role = self._sanitize_agent_role(item)
                if role and role not in recommended:
                    recommended.append(role)
        if not recommended:
            recommended = list(base.get("recommended_agents", []))
        max_budget = max(1, int(getattr(self, "max_agent_rounds", MAX_AGENT_ROUNDS) or MAX_AGENT_ROUNDS))
        if int(getattr(self, 'user_task_level_override', 0) or 0) > 0:
            raw_level = int(self.user_task_level_override)
        else:
            try:
                raw_level = int(src.get("task_level", 0) or 0)
            except Exception:
                raw_level = 0
            if raw_level not in TASK_LEVEL_CHOICES:
                if task_type == "simple_qa":
                    raw_level = 1 if len(str(goal or "")) <= 180 else 2
                elif task_type in {"simple_code", "research"} and task_complexity_rank(complexity) <= task_complexity_rank("moderate"):
                    raw_level = 3
                elif task_complexity_at_least(complexity, "complex"):
                    raw_level = 4
                else:
                    raw_level = 2
        task_level = int(raw_level)
        level_policy = TASK_LEVEL_POLICIES.get(task_level, TASK_LEVEL_POLICIES[3])
        execution_mode = normalize_execution_mode(
            src.get("execution_mode", level_policy.get("execution_mode", EXECUTION_MODE_SYNC)),
            default=str(level_policy.get("execution_mode", EXECUTION_MODE_SYNC)),
        )
        assigned_expert = self._sanitize_agent_role(
            src.get("assigned_expert", level_policy.get("assigned_expert", "developer"))
        ) or self._sanitize_agent_role(level_policy.get("assigned_expert", "developer")) or "developer"
        raw_participants = src.get("participants", src.get("recommended_agents", recommended))
        participants: list[str] = []
        if isinstance(raw_participants, list):
            for item in raw_participants:
                role = self._sanitize_agent_role(item)
                if role and role not in participants:
                    participants.append(role)
        if not participants:
            fallback_roles = level_policy.get("participants", recommended)
            if isinstance(fallback_roles, list):
                for item in fallback_roles:
                    role = self._sanitize_agent_role(item)
                    if role and role not in participants:
                        participants.append(role)
        if execution_mode == EXECUTION_MODE_SINGLE:
            participants = [assigned_expert]
        else:
            min_count = 2 if task_level == 3 else 3 if task_level in {4, 5} else 1
            for role in AGENT_ROLES:
                if len(participants) >= min_count:
                    break
                if role not in participants:
                    participants.append(role)
            if assigned_expert not in participants:
                assigned_expert = participants[0] if participants else assigned_expert
        participants = participants[:3] or [assigned_expert]
        if task_level == 5:
            round_budget = 0
        else:
            try:
                budget_raw = int(src.get("round_budget", level_policy.get("round_budget", base.get("round_budget", max_budget))) or 0)
            except Exception:
                budget_raw = int(level_policy.get("round_budget", base.get("round_budget", max_budget)) or max_budget)
            round_budget = max(1, min(max_budget, budget_raw))
        requires_user_confirmation = bool(
            src.get(
                "requires_user_confirmation",
                level_policy.get("requires_user_confirmation", False),
            )
        )
        if task_level != 5:
            requires_user_confirmation = False
        scale_preference = str(src.get("scale_preference", "balanced") or "").strip().lower()
        if scale_preference not in TASK_SCALE_PREFERENCES:
            scale_preference = "balanced"
        reason = trim(str(src.get("reason", base.get("reason", "")) or "").strip(), 400)
        try:
            goal_chars = max(0, int(src.get("goal_chars", base.get("goal_chars", len(str(goal or "")))) or 0))
        except Exception:
            goal_chars = max(0, int(base.get("goal_chars", len(str(goal or ""))) or 0))
        try:
            updated_at = float(src.get("updated_at", base.get("updated_at", now_ts())) or now_ts())
        except Exception:
            updated_at = float(now_ts())
        return {
            "task_type": task_type,
            "complexity": complexity,
            "direct_objective": direct_objective,
            "recommended_agents": list(participants),
            "task_level": int(task_level),
            "execution_mode": execution_mode,
            "participants": list(participants),
            "assigned_expert": assigned_expert,
            "requires_user_confirmation": bool(requires_user_confirmation),
            "scale_preference": scale_preference,
            "round_budget": int(round_budget),
            "reason": reason or trim(str(base.get("reason", "")), 400),
            "goal_chars": int(goal_chars),
            "updated_at": float(updated_at),
            "deliverable_target": self._infer_deliverable_target(goal, existing=src.get("deliverable_target")),
        }

    # Units that signal a multi-unit generative deliverable (novel chapters,
    # paper sections, batches of files, etc.). Chinese + English.
    _DELIVERABLE_UNIT_MAP = {
        "章": ("chapter", "content"), "章节": ("chapter", "content"), "节": ("section", "content"),
        "篇": ("article", "content"), "页": ("page", "content"), "首": ("poem", "content"),
        "集": ("episode", "content"), "回": ("chapter", "content"), "部": ("volume", "content"),
        "段": ("paragraph", "content"), "份": ("document", "content"), "问": ("question", "content"),
        "题": ("question", "content"), "个文件": ("file", "files"), "个脚本": ("file", "files"),
        "chapters": ("chapter", "content"), "chapter": ("chapter", "content"),
        "sections": ("section", "content"), "section": ("section", "content"),
        "articles": ("article", "content"), "essays": ("essay", "content"),
        "pages": ("page", "content"), "poems": ("poem", "content"),
        "episodes": ("episode", "content"), "parts": ("part", "content"),
        "files": ("file", "files"), "scripts": ("file", "files"), "modules": ("file", "files"),
        "questions": ("question", "content"), "problems": ("question", "content"),
        "papers": ("paper", "content"), "documents": ("document", "content"),
        "reports": ("report", "content"), "stories": ("story", "content"),
        "entries": ("entry", "content"), "records": ("record", "content"),
    }

    def _infer_deliverable_target(self, goal: str, existing: object = None) -> dict:
        """Detect a multi-unit generative quota in the goal (e.g. '写20章小说',
        'analyze 50 papers', 'generate 30 files'). Returns
        {kind, unit, target_count, produced_count, verify} or {} when no quota.

        A quota is a COUNT ('20 章', '50 chapters') — an INDEX ('第20章',
        'chapter 20') is deliberately NOT matched. This is what lets a long task
        block premature finish until the real target is met (Fix 2)."""
        # Preserve an already-established target (keeps produced_count across
        # re-normalizations) unless it is malformed.
        if isinstance(existing, dict) and int(existing.get("target_count", 0) or 0) >= 2:
            out = dict(existing)
            out.setdefault("produced_count", 0)
            out.setdefault("verify", "content")
            out.setdefault("unit", "unit")
            out.setdefault("kind", "generation")
            return out
        text = str(goal or "")
        if not text.strip():
            return {}
        best: dict = {}
        # Chinese: <count><unit>, NOT preceded by 第 (which marks an index).
        zh_units = "章节|章|节|篇|页|首|集|回|部|段|份|题|问"
        for m in re.finditer(r"(?<!第)(\d{1,4})\s*(" + zh_units + r")", text):
            n = int(m.group(1))
            unit_raw = m.group(2)
            if n < 2 or n > 2000:
                continue
            unit, verify = self._DELIVERABLE_UNIT_MAP.get(unit_raw, ("unit", "content"))
            if not best or n > best.get("target_count", 0):
                best = {"kind": "generation", "unit": unit, "target_count": n, "produced_count": 0, "verify": verify}
        # Chinese file/script count: "N个文件" / "N个脚本"
        for m in re.finditer(r"(\d{1,4})\s*个?\s*(文件|脚本|模块|函数)", text):
            n = int(m.group(1))
            if n < 2 or n > 2000:
                continue
            if not best or n > best.get("target_count", 0):
                best = {"kind": "generation", "unit": "file", "target_count": n, "produced_count": 0, "verify": "files"}
        # English: <count> <plural-unit>. Plural (or explicit count noun) only —
        # 'chapter 20' (singular after) is an index and is skipped.
        for m in re.finditer(
            r"(\d{1,4})\s+(chapters|sections|articles|essays|pages|poems|episodes|parts|files|scripts|modules|questions|problems|papers|documents|reports|stories|entries|records)\b",
            text, re.IGNORECASE,
        ):
            n = int(m.group(1))
            unit_raw = m.group(2).lower()
            if n < 2 or n > 2000:
                continue
            unit, verify = self._DELIVERABLE_UNIT_MAP.get(unit_raw, ("unit", "content"))
            if not best or n > best.get("target_count", 0):
                best = {"kind": "generation", "unit": unit, "target_count": n, "produced_count": 0, "verify": verify}
        return best

    def _deliverable_progress(self, board: dict | None = None) -> dict:
        """Count produced units of the deliverable target from REAL evidence
        (files written, content markers in artifacts), never model self-claims.
        Returns {active, target, produced, unit, verify, remaining}."""
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        profile = bb.get("task_profile", {}) if isinstance(bb.get("task_profile"), dict) else {}
        target = profile.get("deliverable_target", {}) if isinstance(profile.get("deliverable_target"), dict) else {}
        target_count = int(target.get("target_count", 0) or 0)
        if target_count < 2:
            return {"active": False, "target": 0, "produced": 0, "unit": "", "verify": "", "remaining": 0}
        verify = str(target.get("verify", "content") or "content")
        unit = str(target.get("unit", "unit") or "unit")
        produced = 0
        # File-based deliverables: count distinct written output paths.
        if verify == "files":
            paths: set[str] = set()
            arts = bb.get("code_artifacts", {}) if isinstance(bb.get("code_artifacts"), dict) else {}
            for p in arts.keys():
                if str(p).strip():
                    paths.add(str(p).strip())
            step_files = bb.get("step_files", {}) if isinstance(bb.get("step_files"), dict) else {}
            for entries in step_files.values():
                if isinstance(entries, list):
                    for item in entries:
                        if isinstance(item, dict) and str(item.get("path", "") or "").strip():
                            paths.add(str(item.get("path")).strip())
            produced = len(paths)
        else:
            # Content-unit deliverables: scan written artifact text + research
            # notes for the highest distinct unit index (第N章 / Chapter N / N.).
            blob_parts: list[str] = []
            arts = bb.get("code_artifacts", {}) if isinstance(bb.get("code_artifacts"), dict) else {}
            for v in arts.values():
                if isinstance(v, dict):
                    blob_parts.append(str(v.get("content", "") or v.get("summary", "") or ""))
                else:
                    blob_parts.append(str(v or ""))
            notes = bb.get("research_notes", []) if isinstance(bb.get("research_notes"), list) else []
            for n in notes:
                if isinstance(n, dict):
                    blob_parts.append(str(n.get("content", "") or n.get("text", "") or ""))
                else:
                    blob_parts.append(str(n or ""))
            blob = "\n".join(blob_parts)
            indices: set[int] = set()
            for m in re.finditer(r"第\s*(\d{1,4})\s*(?:章|节|篇|回|集|部|页|首)", blob):
                indices.add(int(m.group(1)))
            for m in re.finditer(r"\b(?:chapter|section|part|episode|page|article|essay)\s+(\d{1,4})\b", blob, re.IGNORECASE):
                indices.add(int(m.group(1)))
            produced = len(indices)
            # Fallback: distinct completed plan-step count can stand in when the
            # units aren't explicitly numbered in text but each maps to a step.
            step_done = sum(
                1 for t in (bb.get("project_todos", []) if isinstance(bb.get("project_todos"), list) else [])
                if isinstance(t, dict) and str(t.get("category", "") or "") == "plan_step"
                and str(t.get("status", "") or "").strip().lower() == "completed"
            )
            produced = max(produced, step_done)
        produced = min(produced, target_count)
        return {
            "active": True,
            "target": target_count,
            "produced": produced,
            "unit": unit,
            "verify": verify,
            "remaining": max(0, target_count - produced),
        }


    def _ensure_blackboard_task_profile(self, board: dict | None = None, *, force: bool = False) -> dict:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        goal = str(bb.get("original_goal", "") or "")
        current = bb.get("task_profile", {})
        profile = self._normalize_task_profile(goal, {} if force else current)
        if task_complexity_rank(profile.get("complexity", "simple")) < task_complexity_rank("complex"):
            logs = bb.get("execution_logs", []) if isinstance(bb.get("execution_logs"), list) else []
            tail = "\n".join(
                str((row or {}).get("content", "") or "")
                for row in logs[-3:]
                if isinstance(row, dict)
            ).lower()
            if any(tok in tail for tok in ("error", "failed", "traceback", "exception", "blocked", "not found")):
                bumped = max(int(profile.get("round_budget", 1) or 1) + 3, 8)
                profile["complexity"] = "complex"
                profile["round_budget"] = max(
                    1,
                    min(
                        int(getattr(self, "max_agent_rounds", MAX_AGENT_ROUNDS) or MAX_AGENT_ROUNDS),
                        int(bumped),
                    ),
                )
                profile["reason"] = "auto-escalated: runtime errors detected"
                profile["recommended_agents"] = ["explorer", "developer", "reviewer"]
        bb["task_profile"] = profile
        self.blackboard = bb
        return profile

    def _manager_feedback_passed_from_blackboard(self, board: dict | None = None) -> bool:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        gate_ok, _ = self._reviewer_approval_log_gate(bb)
        if not gate_ok:
            return False
        feedback = bb.get("review_feedback", []) if isinstance(bb.get("review_feedback"), list) else []
        if not feedback:
            return False
        txt = str((feedback[-1] or {}).get("content", "") if isinstance(feedback[-1], dict) else "").lower()
        return any(
            token in txt
            for token in (
                "approved",
                "review passed",
                "tests passed",
                "no issues found",
                "验证通过",
                "审核通过",
                "已通过",
            )
        )

    def _manager_has_error_log(self, board: dict | None = None) -> bool:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        logs = bb.get("execution_logs", []) if isinstance(bb.get("execution_logs"), list) else []
        if not logs:
            return False
        focus = self._blackboard_focus_identity(bb)
        current_step_id = str(focus.get("id", "") or "") if str(focus.get("kind", "") or "") == "plan_step" else ""
        try:
            current_epoch = float(focus.get("epoch", 0.0) or 0.0)
        except Exception:
            current_epoch = 0.0
        recent = [row for row in logs[-12:] if isinstance(row, dict)]
        last_blocking_idx = -1
        last_success_idx = -1
        last_blocking_ts = 0.0
        for idx, row in enumerate(recent):
            row_step_id = str(row.get("plan_step_id", "") or "")
            if current_step_id and row_step_id and row_step_id != current_step_id:
                continue
            try:
                row_ts = float(row.get("ts", 0.0) or 0.0)
            except Exception:
                row_ts = 0.0
            if current_step_id and current_epoch > 0 and row_ts > 0 and row_ts + 1e-6 < current_epoch:
                continue
            if self._execution_log_entry_is_blocking_error(row):
                last_blocking_idx = idx
                try:
                    last_blocking_ts = float(row.get("ts", 0.0) or 0.0)
                except Exception:
                    last_blocking_ts = 0.0
            if self._execution_log_entry_is_success_evidence(row):
                last_success_idx = idx
        if last_blocking_idx < 0:
            return False
        if last_success_idx > last_blocking_idx:
            return False
        if last_blocking_ts > 0:
            approval = bb.get("approval", {}) if isinstance(bb.get("approval"), dict) else {}
            try:
                approval_ts = float(approval.get("ts", 0.0) or 0.0)
            except Exception:
                approval_ts = 0.0
            if bool(approval.get("approved", False)) and approval_ts + 1e-6 >= last_blocking_ts:
                return False
            feedback = bb.get("review_feedback", []) if isinstance(bb.get("review_feedback"), list) else []
            for row in reversed(feedback[-8:]):
                if not isinstance(row, dict):
                    continue
                txt = str(row.get("content", "") or "").strip().lower()
                if not txt:
                    continue
                if not any(tok in txt for tok in ("approved", "review passed", "tests passed", "no issues found", "验证通过", "审核通过", "已通过")):
                    continue
                try:
                    ts = float(row.get("ts", 0.0) or 0.0)
                except Exception:
                    ts = 0.0
                if ts + 1e-6 >= last_blocking_ts:
                    return False
        return True

    def _execution_log_count_search_zero_ok(self, row: dict) -> bool:
        txt = str((row or {}).get("content", "") or "").strip()
        if not txt:
            return False
        lines = [line.strip() for line in txt.replace("\r\n", "\n").split("\n") if line.strip()]
        if not lines:
            return False
        first = lines[0]
        if not first.startswith(("bash ", "worktree_run ", "background_run ")):
            return False
        command = first.split(" ", 1)[1] if " " in first else ""
        output_lines = [
            line for line in lines[1:]
            if not re.match(r"(?i)^exit\s*[:=]\s*-?\d+\b", line)
        ]
        return self._count_search_output_is_zero(command, "\n".join(output_lines))

    def _execution_log_entry_is_success_evidence(self, row: dict) -> bool:
        txt = str((row or {}).get("content", "") or "").strip().lower()
        if not txt:
            return False
        if self._execution_log_count_search_zero_ok(row):
            return True
        if re.search(r"(?m)^\s*exit\s*[:=]\s*0\b", txt) and not self._command_output_has_error_shape(txt):
            return True
        success_markers = (
            "no errors", "0 errors", "0 error", "no error", "no issues found",
            "tests passed", "all tests passed", "test passed", "build succeeded",
            "build successful", "compiled successfully", "syntax ok", "validation:",
            "workspace clean", "passed", "success",
        )
        strong_error_markers = (
            "traceback", "exception", "syntax error", "fatal error", "build failed",
            "test failed", "assertionerror", "error:", "failed:", "exit code 1",
            "exit: 1", "exit=1",
        )
        return any(marker in txt for marker in success_markers) and not any(
            marker in txt for marker in strong_error_markers
        )

    def _execution_log_entry_is_blocking_error(self, row: dict) -> bool:
        txt = str((row or {}).get("content", "") or "").strip()
        if not txt:
            return False
        low = txt.lower()
        if ".clouds_coder/plan.md" in low or "$workspace_root/.clouds_coder/plan.md" in low or "$session_root/.clouds_coder/plan.md" in low:
            return False
        actor = self._sanitize_agent_role(str((row or {}).get("actor", "") or ""))
        benign_phrases = (
            "no errors", "0 errors", "0 error", "no error", "without errors",
            "no error logs", "no failing", "not an error", "error-free",
            "workspace clean", "validation: workspace clean",
        )
        if any(phrase in low for phrase in benign_phrases):
            return False
        if self._execution_log_count_search_zero_ok(row):
            return False
        if re.search(r"(?m)^\s*exit\s*[:=]\s*0\b", low) and not self._command_output_has_error_shape(txt):
            return False
        if low.startswith("tool_error agent_web_search:"):
            return False
        if "agent_web_search" in low and (
            "timed out after" in low
            or "url_error" in low
            or "http " in low
            or "network" in low
        ):
            return False
        if low.startswith("tool_error "):
            return True
        if "error: tool" in low:
            return True
        if "timed out after" in low and actor in {"developer", "reviewer"}:
            return True
        return self._command_output_has_error_shape(txt)

    def _plan_step_ready_for_finish_reconcile(self, plan_step: dict, board: dict | None = None) -> bool:
        if not isinstance(plan_step, dict):
            return False
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        if not self._step_subtasks_all_completed(plan_step):
            return False
        if not self._plan_step_acceptance_gate_passed(plan_step, None, bb):
            return False
        has_evidence = self._plan_step_has_blackboard_evidence(plan_step, bb) or self._step_has_accumulated_evidence(plan_step, bb)
        if not has_evidence:
            return False
        step_text = str(plan_step.get("full_content", "") or plan_step.get("content", "") or "").lower()
        phase = self._plan_step_phase_hint(step_text)
        if phase in {"implement", "test", "deploy"}:
            sig = self._plan_step_blackboard_signals(plan_step, bb)
            verified = self._check_step_verified_tag(plan_step, messages=self.agent_messages)
            if not (
                verified
                or bool(sig.get("has_exec", False))
                or bool(sig.get("has_review", False))
                or bool(sig.get("has_compile_pass", False))
                or bool(sig.get("has_test_pass", False))
            ):
                return False
        return True

    def _reconcile_active_plan_step_before_finish(
        self,
        board: dict | None = None,
        *,
        actor: str = "manager",
        source: str = "finish-gate",
    ) -> bool:
        changed = False
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        actor_key = self._sanitize_agent_role(actor) or "manager"
        for _ in range(3):
            current = self._current_plan_step_row(bb)
            if not isinstance(current, dict):
                break
            if not self._plan_step_ready_for_finish_reconcile(current, bb):
                break
            evidence = (
                self._collect_blackboard_step_evidence(current, bb)
                or self._collect_accumulated_step_evidence(current, bb)
                or f"{source}: current plan step accepted before finish"
            )
            if not self._advance_plan_step(evidence=trim(f"finish-reconcile: {evidence}", 200), actor=actor_key):
                break
            changed = True
            bb = self._ensure_blackboard()
        return changed

    def _completion_scoped_open_todo_rows(self, board: dict | None = None) -> list[dict]:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        open_rows = [
            row for row in self.todo.snapshot()
            if isinstance(row, dict)
            and self._todo_row_kind(row) != "system"
            and str(row.get("status", "pending") or "pending").strip().lower() != "completed"
        ]
        if not open_rows:
            return []
        if self._todo_has_plan_steps(bb):
            active = self._current_plan_step_row(bb)
            if not isinstance(active, dict):
                return []
            step_id = trim(str(active.get("id", "") or ""), 20)
            if not step_id:
                return []
            return [
                row for row in open_rows
                if self._todo_row_kind(row) == "plan_worker"
                and str(row.get("parent_step_id", "") or "").strip() == step_id
            ]
        route_kind = self._todo_route_kind(board=bb)
        if route_kind == "pure_sync":
            return [row for row in open_rows if self._todo_row_kind(row) == "owner_worker"]
        if route_kind == "pure_single":
            return [row for row in open_rows if self._todo_row_kind(row) == "flat"]
        return open_rows

    def _finish_gate_route_for_reason(self, reason: str, board: dict | None = None) -> dict:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        reason_key = str(reason or "").strip()
        mode = self._effective_execution_mode()
        profile = self._ensure_blackboard_task_profile(bb)
        assigned = self._sanitize_agent_role(profile.get("assigned_expert", "")) or "developer"
        if reason_key.startswith("plan-steps-incomplete:") or reason_key.startswith("worker-todo-pending:"):
            step = self._current_plan_step_row(bb)
            if isinstance(step, dict):
                snapshot = self._active_plan_progress_snapshot(bb)
                step_idx = int(snapshot.get("step_index", 0) or 0) + 1
                total = max(
                    1,
                    int(
                        bb.get("plan_step_total", 0)
                        or len([t for t in bb.get("project_todos", []) if isinstance(t, dict) and t.get("category") == "plan_step"])
                        or 1
                    ),
                )
                current_subtask = trim(str(snapshot.get("current_subtask", "") or ""), 180)
                next_pending = trim(str(snapshot.get("next_pending_subtask", "") or ""), 180)
                focus = current_subtask or next_pending
                target = self._current_plan_worker_owner(bb)
                instruction = (
                    f"Finish is blocked because the approved plan is still at step {step_idx}/{total}: "
                    f"{trim(str(snapshot.get('step_text', '') or ''), 220)}. "
                    "Continue this plan step only. "
                )
                if focus:
                    instruction += f"Current subtask: {focus}. "
                instruction += "Use TodoWrite for subtask progress; do not call finish until all plan steps are completed."
                return {
                    "target": target,
                    "instruction": trim(instruction, MANAGER_INSTRUCTION_MAX_CHARS),
                    "reason": reason_key,
                    "source": "finish-gate",
                    "is_mandatory": True,
                }
            return {
                "target": assigned,
                "instruction": "Finish is blocked by unfinished plan steps. Re-open the active plan state and continue the next concrete step.",
                "reason": reason_key,
                "source": "finish-gate",
                "is_mandatory": True,
            }
        if reason_key.startswith("deliverable-incomplete:"):
            progress = self._deliverable_progress(bb)
            unit = str(progress.get("unit", "unit") or "unit")
            produced = int(progress.get("produced", 0) or 0)
            target = int(progress.get("target", 0) or 0)
            remaining = int(progress.get("remaining", 0) or 0)
            instruction = (
                f"Finish is blocked: this task requires {target} {unit}s and only {produced} are done "
                f"({remaining} remaining). Do NOT stop or summarize early — continue producing the next "
                f"{unit} now, with its full concrete content, and keep going until all {target} are complete. "
                "Update TodoWrite as each unit is finished."
            )
            return {
                "target": self._current_plan_worker_owner(bb) or assigned,
                "instruction": trim(instruction, MANAGER_INSTRUCTION_MAX_CHARS),
                "reason": reason_key,
                "source": "finish-gate",
                "is_mandatory": True,
            }
        if reason_key.startswith("project-todo-incomplete:"):
            missing_cat = reason_key.split(":", 1)[-1] if ":" in reason_key else ""
            if missing_cat == "compile_test":
                instruction = "Compile or run a syntax/build check and record zero-error evidence before finishing."
            elif missing_cat == "min_test":
                instruction = "Run the minimal functional validation for the changed behavior and record evidence before finishing."
            else:
                instruction = "Complete the pending project validation todo and record evidence before finishing."
            return {
                "target": "developer" if mode != EXECUTION_MODE_SINGLE else assigned,
                "instruction": instruction,
                "reason": reason_key,
                "source": "finish-gate",
                "is_mandatory": True,
            }
        if reason_key == "sync-review-missing":
            return {
                "target": "reviewer",
                "instruction": (
                    "Finish is blocked until reviewer validation passes. Read the current artifacts/logs, "
                    "run or inspect validation evidence, then write review_feedback with pass/fix and evidence."
                ),
                "reason": reason_key,
                "source": "finish-gate",
                "is_mandatory": True,
            }
        if reason_key == "reviewer-summary-missing":
            return {
                "target": "reviewer",
                "instruction": (
                    "Finish is blocked because the final summary is missing or too thin. "
                    "Read blackboard evidence and call finish_task with a structured summary: changed files, "
                    "validation evidence, and residual risks or next steps."
                ),
                "reason": reason_key,
                "source": "finish-gate",
                "is_mandatory": True,
            }
        if reason_key == "blocking-error-log":
            target = "reviewer" if mode != EXECUTION_MODE_SINGLE else assigned
            return {
                "target": target,
                "instruction": "Finish is blocked by recent error logs. Diagnose the latest failing command, fix or route the fix, and rerun validation.",
                "reason": reason_key,
                "source": "finish-gate",
                "is_mandatory": True,
            }
        if reason_key in {"goal-reset-pending", "approval-stale-new-user-input"}:
            return {
                "target": assigned,
                "instruction": "A newer user instruction or goal reset invalidated completion. Continue from the latest user request with one concrete action.",
                "reason": reason_key,
                "source": "finish-gate",
                "is_mandatory": True,
            }
        return {
            "target": assigned,
            "instruction": "Finish is not accepted yet. Continue the next concrete required action and update evidence before requesting finish again.",
            "reason": reason_key or "finish-gate-blocked",
            "source": "finish-gate",
            "is_mandatory": True,
        }

    def _evaluate_finish_gate(
        self,
        board: dict | None = None,
        *,
        latest_user_ts: float | None = None,
    ) -> dict:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        can_finish, reason = self._can_auto_finish_from_approval(bb, latest_user_ts=latest_user_ts)
        if can_finish:
            profile = self._ensure_blackboard_task_profile(bb)
            task_type = str(profile.get("task_type", "general") or "general")
            open_rows = self._completion_scoped_open_todo_rows(bb)
            if open_rows and task_type != "simple_qa":
                can_finish = False
                reason = f"worker-todo-pending:{len(open_rows)}"
        if can_finish and self._manager_has_error_log(bb):
            can_finish = False
            reason = "blocking-error-log"
        return {
            "ok": bool(can_finish),
            "reason": reason,
            "route": {} if can_finish else self._finish_gate_route_for_reason(reason, bb),
        }

    def _record_finish_blocked(self, role: str, source: str, summary: str, gate: dict) -> dict:
        bb = self._ensure_blackboard()
        completion = self._normalize_completion_state(bb.get("completion", {}))
        progress_fp = self._watchdog_state_fingerprint(bb)
        same_block = (
            completion.get("gate_reason") == str(gate.get("reason", "") or "")
            and completion.get("last_progress_fp") == progress_fp
        )
        completion["state"] = "blocked"
        completion["requested_by"] = trim(str(role or "").strip(), 40)
        completion["source"] = trim(str(source or "").strip(), 80)
        completion["gate_reason"] = trim(str(gate.get("reason", "") or "").strip(), 160)
        completion["attempt_count"] = int(completion.get("attempt_count", 0) or 0) + 1
        completion["last_progress_fp"] = progress_fp
        completion["last_request_ts"] = float(now_ts())
        completion["summary"] = trim(str(summary or completion.get("summary", "") or "").strip(), 1200)
        completion["route"] = dict(gate.get("route", {}) if isinstance(gate.get("route"), dict) else {})
        bb["completion"] = completion
        self.blackboard = bb
        if same_block:
            self._blackboard_history(
                "manager",
                f"finish request repeated while blocked by {completion['gate_reason']}; reroute to concrete unblock action",
            )
        else:
            self._blackboard_history(
                "manager",
                f"finish requested by {role or 'agent'} but blocked by {completion['gate_reason']}",
            )
        return completion

    def _emit_completion_summary_bubble(self, summary: str, *, role: str = "assistant"):
        text = trim(str(summary or "").strip(), 1800)
        if not text:
            text = "Task completed."
        recent = self.messages[-6:] if isinstance(self.messages, list) else []
        if any(
            isinstance(row, dict)
            and str(row.get("role", "") or "") == "assistant"
            and str(row.get("type", "") or "") == "completion_summary"
            and str(row.get("content", "") or "").strip() == text
            for row in recent
        ):
            return
        bubble_role = self._sanitize_agent_role(role) or ("developer" if self._is_multi_agent_mode() else "")
        message = {
            "role": "assistant",
            "type": "completion_summary",
            "content": text,
            "ts": now_ts(),
        }
        if bubble_role:
            message["agent_role"] = bubble_role
        self.messages.append(message)
        self.messages = self.messages[-400:]
        payload = {
            "role": "assistant",
            "text": text,
            "summary": "completion summary",
        }
        if bubble_role:
            payload["agent_role"] = bubble_role
        self._emit("message", payload)

    def _finalize_completion_once(self, role: str, source: str, summary: str = "") -> dict:
        bb = self._ensure_blackboard()
        completion = self._normalize_completion_state(bb.get("completion", {}))
        if completion.get("state") == "completed":
            return {"stop": True, "finalized": False, "reason": "already-completed", "summary": completion.get("summary", "")}
        completion["state"] = "finalizing"
        completion["requested_by"] = trim(str(role or "").strip(), 40)
        completion["source"] = trim(str(source or "").strip(), 80)
        completion["last_request_ts"] = float(now_ts())
        bb["completion"] = completion
        self.blackboard = bb
        final_summary = trim(str(summary or "").strip(), 1200)
        if not final_summary:
            final_summary = self._auto_summary_on_finish()
        else:
            self._auto_summary_on_finish()
        self._mark_all_done_silently(final_summary)
        if bool(self.reviewer_debug_mode) and self._sanitize_agent_role(role) == "reviewer":
            self._deactivate_reviewer_debug_mode("reviewer finished")
        bb = self._ensure_blackboard()
        completion = self._normalize_completion_state(bb.get("completion", {}))
        completion["state"] = "completed"
        completion["requested_by"] = trim(str(role or "").strip(), 40)
        completion["source"] = trim(str(source or "").strip(), 80)
        completion["gate_reason"] = "ok"
        completion["finalized_at"] = float(now_ts())
        completion["summary"] = trim(final_summary, 1200)
        completion["route"] = {}
        bb["completion"] = completion
        bb["status"] = "COMPLETED"
        self.blackboard = bb
        self._blackboard_touch()
        if not str(source or "").startswith("single-direct-deliverable"):
            self._emit_completion_summary_bubble(final_summary, role=role)
        return {"stop": True, "finalized": True, "reason": "ok", "summary": final_summary}

    def _resolve_finish_request(
        self,
        role: str,
        *,
        source: str = "finish-request",
        summary: str = "",
    ) -> dict:
        role_key = self._sanitize_agent_role(role) or str(role or "").strip().lower() or "agent"
        self._invalidate_stale_approval_if_needed(
            self._ensure_blackboard(),
            latest_user_ts=self._latest_user_message_ts(),
            emit_status=False,
        )
        self._reconcile_active_plan_step_before_finish(
            self._ensure_blackboard(),
            actor=role_key,
            source=source,
        )
        gate = self._evaluate_finish_gate(self._ensure_blackboard(), latest_user_ts=self._latest_user_message_ts())
        if bool(gate.get("ok", False)):
            return self._finalize_completion_once(role_key, source, summary)
        completion = self._record_finish_blocked(role_key, source, summary, gate)
        route = completion.get("route", {}) if isinstance(completion.get("route"), dict) else {}
        target = str(route.get("target", "") or "").strip().lower()
        if target in AGENT_ROLES:
            instruction = trim(str(route.get("instruction", "") or "").strip(), MANAGER_INSTRUCTION_MAX_CHARS)
            if instruction:
                if self._is_multi_agent_mode():
                    self._append_manager_context(
                        {
                            "role": "system",
                            "content": (
                                "[finish-blocked] "
                                f"gate={completion.get('gate_reason', '')}; target={target}; "
                                f"instruction={instruction}"
                            ),
                            "ts": now_ts(),
                        }
                    )
                else:
                    self.messages.append(
                        {
                            "role": "user",
                            "content": (
                                "<finish-blocked>"
                                f"Completion gate blocked finish: {completion.get('gate_reason', '')}. "
                                f"{instruction}"
                                "</finish-blocked>"
                            ),
                            "ts": now_ts(),
                        }
                    )
        self._emit(
            "status",
            {
                "summary": (
                    f"finish blocked ({completion.get('gate_reason', '')}); "
                    f"reroute={target or '-'}"
                )
            },
        )
        return {
            "stop": False,
            "finalized": False,
            "reason": completion.get("gate_reason", ""),
            "route": route,
            "attempt_count": int(completion.get("attempt_count", 0) or 0),
        }

    def _approval_is_stale_for_latest_user(
        self,
        board: dict | None = None,
        *,
        latest_user_ts: float | None = None,
    ) -> bool:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        approval = bb.get("approval", {}) if isinstance(bb.get("approval"), dict) else {}
        if not bool(approval.get("approved", False)):
            return False
        try:
            approval_ts = float(approval.get("ts", 0.0) or 0.0)
        except Exception:
            approval_ts = 0.0
        if latest_user_ts is None:
            latest_user_ts = self._latest_user_message_ts()
        try:
            user_ts = float(latest_user_ts or 0.0)
        except Exception:
            user_ts = 0.0
        if user_ts <= 0.0:
            return False
        if approval_ts <= 0.0:
            return True
        return bool(user_ts > approval_ts + 1e-6)

    def _can_auto_finish_from_approval(
        self,
        board: dict | None = None,
        *,
        latest_user_ts: float | None = None,
    ) -> tuple[bool, str]:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        if self._runtime_goal_reset_still_pending(bb):
            return False, "goal-reset-pending"
        if self._approval_is_stale_for_latest_user(bb, latest_user_ts=latest_user_ts):
            return False, "approval-stale-new-user-input"
        # Plan step gate: if plan_step todos exist, ALL must be completed
        plan_step_todos = [
            t for t in bb.get("project_todos", [])
            if t.get("category") == "plan_step"
        ]
        if plan_step_todos:
            pending = [t for t in plan_step_todos if t.get("status") != "completed"]
            if pending:
                return False, f"plan-steps-incomplete:{len(pending)}/{len(plan_step_todos)}"
        # Project todo gate: coding tasks must pass compile + test
        profile = self._ensure_blackboard_task_profile(bb)
        task_type = str(profile.get("task_type", "general") or "general")
        exec_mode = normalize_execution_mode(
            profile.get("execution_mode", self._effective_execution_mode()),
            default=self._effective_execution_mode(),
        )
        if task_type in ("simple_code", "engineering"):
            for todo in bb.get("project_todos", []):
                if todo.get("category") in ("compile_test", "min_test") and todo.get("status") != "completed":
                    return False, f"project-todo-incomplete:{todo.get('category', '')}"
        if exec_mode == EXECUTION_MODE_SYNC and not self._manager_feedback_passed_from_blackboard(bb):
            return False, "sync-review-missing"
        # Deliverable-quota gate (Fix 2): a multi-unit generative task (e.g.
        # "write 20 chapters", "analyze 50 papers") must produce its target
        # count of REAL units before finishing — this is what stops long tasks
        # ending prematurely (虎头蛇尾). Progress is counted from evidence, not
        # model self-claims.
        progress = self._deliverable_progress(bb)
        if progress.get("active") and int(progress.get("remaining", 0) or 0) > 0:
            return False, f"deliverable-incomplete:{progress.get('produced', 0)}/{progress.get('target', 0)}"
        return True, "ok"

    def _invalidate_stale_approval_if_needed(
        self,
        board: dict | None = None,
        *,
        latest_user_ts: float | None = None,
        emit_status: bool = True,
    ) -> bool:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        if not self._approval_is_stale_for_latest_user(bb, latest_user_ts=latest_user_ts):
            return False
        prev = bb.get("approval", {}) if isinstance(bb.get("approval"), dict) else {}
        bb["approval"] = {"approved": False, "by": "", "note": "", "ts": 0.0}
        if self._normalize_blackboard_status(bb.get("status", "INITIALIZING")) == "COMPLETED":
            bb["status"] = "PAUSED"
        self.blackboard = bb
        self._blackboard_history(
            "manager",
            (
                "stale approval cleared after newer user input; "
                f"previous approver={trim(str(prev.get('by', '') or ''), 40) or '-'}"
            ),
        )
        self._sync_todos_from_blackboard(reason="approval-stale-cleared", board=bb)
        if emit_status:
            self._emit(
                "status",
                {
                    "summary": (
                        "stale approval invalidated by newer user instruction; "
                        "manager will continue execution"
                    )
                },
            )
        return True

    def _latest_agent_assistant_text(self, role: str, *, min_ts: float = 0.0) -> str:
        role_key = self._sanitize_agent_role(role)
        if not role_key:
            return ""
        for row in reversed(self._agent_context(role_key)):
            if str(row.get("role", "") or "") != "assistant":
                continue
            if float(min_ts or 0.0) > 0.0:
                try:
                    msg_ts = float(row.get("ts", 0.0) or 0.0)
                except Exception:
                    msg_ts = 0.0
                if msg_ts > 0.0 and msg_ts + 1e-6 < float(min_ts or 0.0):
                    continue
            txt = strip_thinking_content(str(row.get("content", "") or "")).strip()
            if txt:
                return txt
        return ""

    def _manager_progress_state(self, board: dict | None = None) -> str:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        # Hard guard: pending plan steps → never "done"
        plan_step_todos = [
            t for t in bb.get("project_todos", [])
            if t.get("category") == "plan_step"
        ]
        has_pending_plan_steps = plan_step_todos and any(
            t.get("status") != "completed" for t in plan_step_todos
        )
        finish_gate = self._evaluate_finish_gate(bb)
        if bool(finish_gate.get("ok", False)) and not has_pending_plan_steps:
            return "done"
        profile = self._ensure_blackboard_task_profile(bb)
        task_type = str(profile.get("task_type", "") or "")
        if task_type == "simple_qa":
            dev_text = self._latest_agent_assistant_text("developer")
            if dev_text:
                endpoint = self._detect_endpoint_intent(dev_text, None)
                if bool(endpoint.get("matched", False)):
                    return "almost_done"
                return "in_progress"
            return "initializing"
        if self._manager_has_error_log(bb):
            return "blocked"
        research_count = len(bb.get("research_notes", []) or [])
        code_count = len(bb.get("code_artifacts", {}) or [])
        feedback_count = len(bb.get("review_feedback", []) or [])
        if code_count > 0 and (self._manager_feedback_passed_from_blackboard(bb) or feedback_count > 0):
            return "almost_done"
        if code_count > 0 or research_count > 0:
            return "in_progress"
        return "initializing"

    def _blackboard_round_budget(self, board: dict | None = None) -> int:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        profile = self._ensure_blackboard_task_profile(bb)
        max_budget = max(1, int(getattr(self, "max_agent_rounds", MAX_AGENT_ROUNDS) or MAX_AGENT_ROUNDS))
        try:
            budget = int(profile.get("round_budget", max_budget) or 0)
        except Exception:
            budget = max_budget
        if budget <= 0:
            return 0
        return max(1, min(max_budget, budget))

    def _normalize_blackboard_status(self, raw: object) -> str:
        key = str(raw or "").strip().upper()
        return key if key in BLACKBOARD_STATUSES else "INITIALIZING"

    def _new_watchdog_state(self) -> dict:
        return {
            "intent_no_tool_streak": 0,
            "repeat_no_tool_streak": 0,
            "state_unchanged_streak": 0,
            "last_no_tool_text": "",
            "last_no_tool_hash": "",
            "last_state_fp": "",
            "trigger_count": 0,
            "last_trigger_reason": "",
            "last_trigger_ts": 0.0,
        }

    def _normalize_watchdog_state(self, raw: object) -> dict:
        src = raw if isinstance(raw, dict) else {}
        out = self._new_watchdog_state()
        out["intent_no_tool_streak"] = max(0, int(src.get("intent_no_tool_streak", 0) or 0))
        out["repeat_no_tool_streak"] = max(0, int(src.get("repeat_no_tool_streak", 0) or 0))
        out["state_unchanged_streak"] = max(0, int(src.get("state_unchanged_streak", 0) or 0))
        out["last_no_tool_text"] = trim(str(src.get("last_no_tool_text", "") or "").strip(), 1200)
        out["last_no_tool_hash"] = trim(str(src.get("last_no_tool_hash", "") or "").strip(), 80)
        out["last_state_fp"] = trim(str(src.get("last_state_fp", "") or "").strip(), 120)
        out["trigger_count"] = max(0, int(src.get("trigger_count", 0) or 0))
        out["last_trigger_reason"] = trim(str(src.get("last_trigger_reason", "") or "").strip(), 200)
        out["last_trigger_ts"] = float(src.get("last_trigger_ts", 0.0) or 0.0)
        return out

    def _new_decomposition_queue_state(self) -> dict:
        return {
            "active": False,
            "trigger_reason": "",
            "created_at": 0.0,
            "cursor": 0,
            "steps": [],
            "last_error": "",
            "snapshot": "",
            "decomposer_output": "",
            "focus_kind": "",
            "focus_id": "",
            "focus_epoch": 0.0,
            "plan_step_id": "",
            "plan_step_index": -1,
        }

    def _watchdog_normalize_steps(self, rows: object) -> list[dict]:
        if not isinstance(rows, list):
            return []
        out: list[dict] = []

        def _infer_target(action_type: str, instruction: str, fallback: str = "developer") -> str:
            raw = self._sanitize_agent_role(fallback) or "developer"
            low = f"{action_type} {instruction}".lower()
            if any(tok in low for tok in ("review", "verify", "validate", "test", "qa", "检查", "验证", "评审", "審查")):
                return "reviewer"
            if any(tok in low for tok in ("research", "inspect", "analy", "explore", "investigate", "分析", "调研", "調研", "探索")):
                return "explorer"
            return raw

        for idx, row in enumerate(rows[:WATCHDOG_MAX_DECOMPOSE_STEPS]):
            if not isinstance(row, dict):
                continue
            instruction = trim(
                str(
                    row.get("description", "")
                    or row.get("instruction", "")
                    or row.get("content", "")
                    or row.get("task", "")
                    or ""
                ).strip(),
                900,
            )
            if not instruction:
                continue
            action_type = trim(str(row.get("action_type", "") or "").strip(), 80)
            target = self._sanitize_agent_role(
                row.get("target", row.get("owner", row.get("role", row.get("agent", ""))))
            )
            target = target or _infer_target(action_type, instruction)
            if target == "developer" and "incremental" not in instruction.lower():
                instruction = trim(
                    (
                        f"{instruction}\n"
                        "Use incremental edits (append/targeted replace) instead of full-file overwrite unless unavoidable."
                    ),
                    1000,
                )
            try:
                step_no = int(row.get("step", idx + 1) or (idx + 1))
            except Exception:
                step_no = idx + 1
            out.append(
                {
                    "step": max(1, step_no),
                    "target": target,
                    "action_type": action_type or "execute",
                    "instruction": instruction,
                    "attempts": max(0, int(row.get("attempts", 0) or 0)),
                    "status": trim(str(row.get("status", "pending") or "pending").strip().lower(), 20) or "pending",
                    "updated_at": float(now_ts()),
                }
            )
        if not out:
            return []
        return out[:WATCHDOG_MAX_DECOMPOSE_STEPS]

    def _normalize_decomposition_queue_state(self, raw: object) -> dict:
        src = raw if isinstance(raw, dict) else {}
        out = self._new_decomposition_queue_state()
        out["active"] = bool(src.get("active", False))
        out["trigger_reason"] = trim(str(src.get("trigger_reason", "") or "").strip(), 200)
        out["created_at"] = float(src.get("created_at", 0.0) or 0.0)
        out["cursor"] = max(0, int(src.get("cursor", 0) or 0))
        out["last_error"] = trim(str(src.get("last_error", "") or "").strip(), 400)
        out["snapshot"] = trim(str(src.get("snapshot", "") or "").strip(), 4000)
        out["decomposer_output"] = trim(str(src.get("decomposer_output", "") or "").strip(), 2000)
        out["focus_kind"] = trim(str(src.get("focus_kind", "") or "").strip(), 40)
        out["focus_id"] = trim(str(src.get("focus_id", "") or "").strip(), 120)
        out["focus_epoch"] = float(src.get("focus_epoch", 0.0) or 0.0)
        out["plan_step_id"] = trim(str(src.get("plan_step_id", "") or "").strip(), 80)
        out["plan_step_index"] = int(src.get("plan_step_index")) if src.get("plan_step_index") not in (None, "") else -1
        out["steps"] = self._watchdog_normalize_steps(src.get("steps", []))
        if out["cursor"] >= len(out["steps"]):
            out["active"] = False
        return out

    def _watchdog_state_fingerprint(self, board: dict | None = None) -> str:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        profile = self._ensure_blackboard_task_profile(bb)
        step_snapshot = self._active_plan_progress_snapshot(bb)
        last_reply = bb.get("last_worker_reply", {}) if isinstance(bb.get("last_worker_reply"), dict) else {}
        last_reply_role = self._sanitize_agent_role(last_reply.get("role", ""))
        last_reply_text = trim(str(last_reply.get("text", "") or "").strip(), 240)
        payload = {
            "status": self._normalize_blackboard_status(bb.get("status", "INITIALIZING")),
            "goal": trim(str(bb.get("original_goal", "") or "").strip(), 400),
            "active_agent": self._sanitize_agent_role(bb.get("active_agent", "")),
            "delegate": self._sanitize_agent_role((bb.get("last_delegate", {}) or {}).get("target", "")),
            "research_count": len(bb.get("research_notes", []) or []),
            "artifact_count": len(bb.get("code_artifacts", {}) or {}),
            "exec_count": len(bb.get("execution_logs", []) or []),
            "review_count": len(bb.get("review_feedback", []) or []),
            "approved": bool((bb.get("approval", {}) or {}).get("approved", False)),
            "task_type": str(profile.get("task_type", "general") or "general"),
            "complexity": str(profile.get("complexity", "simple") or "simple"),
            "plan_step_id": str(step_snapshot.get("step_id", "") or ""),
            "plan_step_text": trim(str(step_snapshot.get("step_text", "") or "").strip(), 180),
            "worker_todo_count": int(step_snapshot.get("worker_todo_count", 0) or 0),
            "worker_todo_completed": int(step_snapshot.get("completed_count", 0) or 0),
            "worker_todo_in_progress": int(step_snapshot.get("in_progress_count", 0) or 0),
            "worker_todo_pending": int(step_snapshot.get("pending_count", 0) or 0),
            "current_subtask": trim(str(step_snapshot.get("current_subtask", "") or "").strip(), 180),
            "next_pending_subtask": trim(str(step_snapshot.get("next_pending_subtask", "") or "").strip(), 180),
            "last_worker_reply_role": last_reply_role,
            "last_worker_reply_text": last_reply_text,
        }
        raw = json_dumps(payload, sort_keys=True, separators=(",", ":"))
        return hashlib.sha1(safe_utf8_bytes(raw)).hexdigest()

    def _watchdog_extract_json_array(self, text: str) -> list[dict]:
        raw = str(text or "").strip()
        if not raw:
            return []
        probe_candidates: list[str] = [raw]
        fence = re.findall(r"```(?:json)?\s*([\s\S]*?)```", raw, flags=re.IGNORECASE)
        probe_candidates.extend([str(x or "").strip() for x in fence if str(x or "").strip()])
        first = raw.find("[")
        last = raw.rfind("]")
        if first >= 0 and last > first:
            probe_candidates.append(raw[first : last + 1].strip())
        for candidate in probe_candidates:
            try:
                parsed = json.loads(candidate)
            except Exception:
                continue
            if isinstance(parsed, list):
                return [dict(x) for x in parsed if isinstance(x, dict)]
        return []

    def _watchdog_intent_without_action(self, text: str) -> bool:
        clean = strip_thinking_content(str(text or "")).strip()
        if not clean:
            return False
        low = clean.lower()
        intent_markers = (
            "i will",
            "i'm going to",
            "next step",
            "plan to",
            "let me",
            "我将",
            "我會",
            "我会",
            "下一步",
            "接下来",
            "接下來",
            "计划",
            "計劃",
            "准备",
            "準備",
        )
        action_markers = (
            "wrote",
            "edited",
            "executed",
            "called",
            "ran ",
            "已完成",
            "已执行",
            "已執行",
            "已调用",
            "已調用",
            "完成了",
            "执行了",
            "執行了",
            "调用了",
            "調用了",
        )
        if any(tok in low for tok in action_markers):
            return False
        return any(tok in low for tok in intent_markers)

    def _watchdog_similarity(self, a: str, b: str) -> float:
        left = trim(strip_thinking_content(str(a or "")).strip(), 1800)
        right = trim(strip_thinking_content(str(b or "")).strip(), 1800)
        if (not left) or (not right):
            return 0.0
        return float(difflib.SequenceMatcher(None, left, right).ratio())

    def _watchdog_context_near_limit(self) -> bool:
        try:
            metrics = self._context_budget_metrics()
            limit = max(1, int(metrics.get("effective_limit", metrics.get("limit", TOKEN_THRESHOLD)) or TOKEN_THRESHOLD))
            used = int(metrics.get("used", self._estimate_tokens()) or 0)
        except Exception:
            limit = max(1, int(self.context_token_upper_bound or TOKEN_THRESHOLD))
            used = 0
        return bool(used >= int(limit * WATCHDOG_CONTEXT_NEAR_RATIO))

    def _watchdog_snapshot_payload(self, board: dict, reason: str, role: str, step: dict | None = None) -> str:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        profile = self._ensure_blackboard_task_profile(bb)
        focus = self._blackboard_focus_identity(bb)
        code_rows = sorted(
            list((bb.get("code_artifacts", {}) or {}).items()),
            key=lambda item: float((item[1] or {}).get("updated_at", 0.0) if isinstance(item[1], dict) else 0.0),
            reverse=True,
        )
        payload = {
            "objective": trim(str(bb.get("original_goal", "") or "").strip(), 1800),
            "trigger_reason": trim(str(reason or "").strip(), 200),
            "active_role": self._sanitize_agent_role(role),
            "active_focus": {
                "kind": focus.get("kind", "task"),
                "id": focus.get("id", ""),
                "index": focus.get("index", 0),
                "total": focus.get("total", 0),
                "title": trim(str(focus.get("title", "") or ""), 300),
            },
            "status": self._normalize_blackboard_status(bb.get("status", "INITIALIZING")),
            "task_profile": {
                "task_type": str(profile.get("task_type", "general") or "general"),
                "complexity": str(profile.get("complexity", "simple") or "simple"),
                "direct_objective": trim(str(profile.get("direct_objective", "") or "").strip(), 600),
            },
            "latest_worker_step": {
                "status": str((step or {}).get("status", "") or ""),
                "text": trim(str((step or {}).get("text", "") or "").strip(), 600),
            },
            "code_artifacts": [
                {
                    "path": str(path),
                    "summary": trim(str((item or {}).get("summary", "") or "").strip(), 200),
                }
                for path, item in code_rows[:6]
            ],
            "recent_execution_logs": [
                trim(str((row or {}).get("content", "") or "").strip(), 220)
                for row in (bb.get("execution_logs", []) or [])[-4:]
                if isinstance(row, dict)
            ],
            "recent_review_feedback": [
                trim(str((row or {}).get("content", "") or "").strip(), 220)
                for row in (bb.get("review_feedback", []) or [])[-4:]
                if isinstance(row, dict)
            ],
            "task_memory": trim(self._blackboard_memory_context_markdown(max_chars=1600), 1600),
        }
        return trim(json_dumps(payload, indent=2), 6000)

    def _watchdog_fallback_steps(self, board: dict, reason: str) -> list[dict]:
        profile = self._ensure_blackboard_task_profile(board)
        objective = trim(str(profile.get("direct_objective", "") or "").strip(), 280) or trim(
            str(board.get("original_goal", "") or "").strip(),
            280,
        )
        raw = [
            {
                "step": 1,
                "action_type": "research",
                "target": "explorer",
                "description": (
                    "Analyze the latest blocker quickly and write concrete constraints to blackboard "
                    f"(trigger={trim(reason, 120)})."
                ),
            },
            {
                "step": 2,
                "action_type": "implement",
                "target": "developer",
                "description": (
                    "Implement one incremental fix for the current objective and provide verifiable tool output. "
                    f"Objective: {objective}"
                ),
            },
            {
                "step": 3,
                "action_type": "validate",
                "target": "reviewer",
                "description": (
                    "Run one validation pass, provide pass/fix verdict with evidence, and handoff summary request if needed."
                ),
            },
        ]
        return self._watchdog_normalize_steps(raw)

    def _watchdog_decompose_steps(self, board: dict, reason: str, *, pinned_selection: str) -> tuple[list[dict], str, str]:
        snapshot = self._watchdog_snapshot_payload(board, reason, str(board.get("active_agent", "") or ""), None)
        objective = trim(str(board.get("original_goal", "") or "").strip(), 1600)
        system_prompt = (
            "You are a task decomposer. Your only job is to split OBJECTIVE into executable micro-steps. "
            "Return strict JSON array only: "
            "[{\"step\":1,\"action_type\":\"...\",\"target\":\"explorer|developer|reviewer\",\"description\":\"...\"}]. "
            "No markdown, no prose, no code fence."
        )
        user_prompt = (
            f"OBJECTIVE:\n{objective}\n\n"
            f"TRIGGER:\n{trim(reason, 220)}\n\n"
            "SNAPSHOT:\n"
            f"{snapshot}\n\n"
            "Rules: keep steps module-level (not line-by-line), use incremental edits, "
            "and keep total steps <= 12."
        )
        raw_text = ""
        parsed_steps: list[dict] = []
        try:
            rsp = self._chat_with_same_model_retry(
                [{"role": "user", "content": user_prompt, "ts": now_ts()}],
                tools=None,
                system=system_prompt,
                max_tokens=1200,
                think=False,
                stream_thinking=False,
                pinned_selection=pinned_selection,
                context_label="watchdog decomposer",
                retries=max(1, min(2, int(MODEL_OUTPUT_RETRY_TIMES))),
            )
            raw_text = str(rsp.get("content") or "")
            parsed_steps = self._watchdog_extract_json_array(raw_text)
        except Exception as exc:
            raw_text = f"decomposer-error: {trim(str(exc), 220)}"
            parsed_steps = []
        normalized = self._watchdog_normalize_steps(parsed_steps)
        if not normalized:
            normalized = self._watchdog_fallback_steps(board, reason)
        return normalized, snapshot, trim(raw_text, 2000)

    def _watchdog_activate_decomposition(
        self,
        board: dict,
        *,
        reason: str,
        role: str,
        step: dict | None,
        pinned_selection: str,
    ) -> bool:
        dq = self._normalize_decomposition_queue_state(board.get("decomposition_queue", {}))
        if bool(dq.get("active", False)):
            return False
        steps, snapshot, raw_text = self._watchdog_decompose_steps(
            board,
            reason,
            pinned_selection=pinned_selection,
        )
        if not steps:
            return False
        focus_fields = self._route_focus_fields(board)
        dq = {
            "active": True,
            "trigger_reason": trim(str(reason or "").strip(), 200),
            "created_at": float(now_ts()),
            "cursor": 0,
            "steps": steps,
            "last_error": "",
            "snapshot": trim(snapshot, 4000),
            "decomposer_output": trim(raw_text, 2000),
            "focus_kind": focus_fields.get("focus_kind", ""),
            "focus_id": focus_fields.get("focus_id", ""),
            "focus_epoch": focus_fields.get("focus_epoch", 0.0),
            "plan_step_id": focus_fields.get("plan_step_id", ""),
            "plan_step_index": focus_fields.get("plan_step_index", -1),
        }
        wd = self._normalize_watchdog_state(board.get("watchdog", {}))
        wd["intent_no_tool_streak"] = 0
        wd["repeat_no_tool_streak"] = 0
        board["watchdog"] = wd
        board["decomposition_queue"] = dq
        self.blackboard = board
        self._blackboard_touch()
        self._blackboard_history(
            "manager",
            trim(
                (
                    "watchdog triggered decomposition "
                    f"(reason={reason}, role={self._sanitize_agent_role(role)}, "
                    f"steps={len(steps)})"
                ),
                520,
            ),
        )
        self._emit(
            "status",
            {
                "summary": (
                    "watchdog triggered; switched to stateless executor queue "
                    f"(reason={trim(reason, 90)}, steps={len(steps)})"
                )
            },
        )
        return True

    def _watchdog_escalate_to_single_developer(self, board: dict, *, reason: str = ""):
        """Escalate repeated watchdog stalls by forcing Single+Developer mode."""
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        self.runtime_execution_mode = EXECUTION_MODE_SINGLE
        self.runtime_participants = ["developer"]
        self.runtime_assigned_expert = "developer"
        dq = self._normalize_decomposition_queue_state(bb.get("decomposition_queue", {}))
        dq["active"] = False
        bb["decomposition_queue"] = dq
        profile = self._ensure_blackboard_task_profile(bb)
        profile["execution_mode"] = EXECUTION_MODE_SINGLE
        profile["participants"] = ["developer"]
        profile["assigned_expert"] = "developer"
        bb["task_profile"] = profile
        self.blackboard = bb
        self._blackboard_touch()
        self._blackboard_history(
            "manager",
            trim(
                f"watchdog escalation: forced Single+Developer (trigger_count={int(bb.get('watchdog', {}).get('trigger_count', 0))}, reason={reason})",
                520,
            ),
        )
        self._emit(
            "status",
            {
                "summary": (
                    "watchdog escalation: multi-agent stall detected, "
                    "downgrading to Single+Developer mode"
                )
            },
        )

    def _watchdog_pick_executor_route(self, board: dict | None = None) -> tuple[dict, dict] | None:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        dq = self._normalize_decomposition_queue_state(bb.get("decomposition_queue", {}))
        if not bool(dq.get("active", False)):
            return None
        active_fields = self._route_focus_fields(bb)
        dq_focus = str(dq.get("focus_id", "") or "")
        if dq_focus and dq_focus != str(active_fields.get("focus_id", "") or ""):
            dq["active"] = False
            dq["last_error"] = "deactivated stale executor queue after active focus changed"
            bb["decomposition_queue"] = dq
            self.blackboard = bb
            self._blackboard_touch()
            self._blackboard_append_memory(
                "decision",
                "deactivated stale watchdog executor queue because active task focus changed",
                actor="manager",
                tier="long",
                board=bb,
            )
            return None
        dq_epoch = float(dq.get("focus_epoch", 0.0) or 0.0)
        active_epoch = float(active_fields.get("focus_epoch", 0.0) or 0.0)
        if dq_epoch and active_epoch and abs(dq_epoch - active_epoch) > 0.001:
            dq["active"] = False
            dq["last_error"] = "deactivated stale executor queue after focus epoch changed"
            bb["decomposition_queue"] = dq
            self.blackboard = bb
            self._blackboard_touch()
            return None
        steps = list(dq.get("steps", []) or [])
        if not steps:
            return None
        cursor = max(0, int(dq.get("cursor", 0) or 0))
        while cursor < len(steps):
            status = str((steps[cursor] or {}).get("status", "") or "").strip().lower()
            if status not in {"done", "skipped"}:
                break
            cursor += 1
        if cursor >= len(steps):
            dq["active"] = False
            dq["cursor"] = len(steps)
            bb["decomposition_queue"] = dq
            self.blackboard = bb
            self._blackboard_touch()
            return None
        dq["cursor"] = cursor
        step_row = steps[cursor] if isinstance(steps[cursor], dict) else {}
        target = self._sanitize_agent_role(step_row.get("target", "")) or "developer"
        action_type = trim(str(step_row.get("action_type", "execute") or "execute").strip(), 80) or "execute"
        step_instruction = trim(str(step_row.get("instruction", "") or "").strip(), 900)
        trigger_reason = trim(str(dq.get("trigger_reason", "") or "").strip(), 180)
        total = len(steps)
        current = cursor + 1
        profile = self._ensure_blackboard_task_profile(bb)
        task_level = int(profile.get("task_level", self.runtime_task_level or 3) or 3)
        if task_level not in TASK_LEVEL_CHOICES:
            task_level = 3
        args = {
            "target": target,
            "instruction": trim(
                (
                    f"Executor mode (stateless) step {current}/{total}. "
                    f"trigger={trigger_reason or 'watchdog'}; action_type={action_type}.\n"
                    f"{step_instruction}\n"
                    "Rules: execute one concrete tool call now, keep scope narrow, "
                    "and update blackboard evidence immediately."
                ),
                1200,
            ),
            "task_level": int(task_level),
            "task_type": trim(str(profile.get("task_type", "general") or "general"), 40),
            "complexity": trim(str(profile.get("complexity", "simple") or "simple"), 20),
            "scale_preference": trim(str(profile.get("scale_preference", "balanced") or "balanced"), 20),
            "judgement": trim(
                f"watchdog-executor-step-{current}/{total}",
                200,
            ),
            "round_budget": int(profile.get("round_budget", self.runtime_round_budget or self.max_agent_rounds) or 0),
            "direct_objective": trim(str(profile.get("direct_objective", self.runtime_direct_objective or "") or ""), 800),
            "execution_mode": normalize_execution_mode(
                profile.get("execution_mode", self._effective_execution_mode()),
                default=self._effective_execution_mode(),
            ),
            "participants": profile.get("participants", self.runtime_participants),
            "assigned_expert": profile.get("assigned_expert", self.runtime_assigned_expert or "developer"),
            "requires_user_confirmation": bool(profile.get("requires_user_confirmation", False)),
            "is_mandatory": True,
            "executor_mode": True,
            "focus_kind": active_fields.get("focus_kind", ""),
            "focus_id": active_fields.get("focus_id", ""),
            "focus_epoch": active_fields.get("focus_epoch", 0.0),
            "plan_step_id": active_fields.get("plan_step_id", ""),
            "plan_step_index": active_fields.get("plan_step_index", -1),
            "plan_step_total": active_fields.get("plan_step_total", 0),
            "plan_step_epoch": active_fields.get("plan_step_epoch", 0.0),
        }
        bb["decomposition_queue"] = dq
        self.blackboard = bb
        self._blackboard_touch()
        meta = {
            "trigger_reason": trigger_reason,
            "cursor": current,
            "total": total,
            "target": target,
            "action_type": action_type,
        }
        return args, meta

    def _watchdog_mark_step_progress(self, board: dict, role: str, step: dict | None) -> dict:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        dq = self._normalize_decomposition_queue_state(bb.get("decomposition_queue", {}))
        out = {"queue_active": bool(dq.get("active", False)), "step_advanced": False}
        if not bool(dq.get("active", False)):
            bb["decomposition_queue"] = dq
            self.blackboard = bb
            return out
        active_fields = self._route_focus_fields(bb)
        dq_focus = str(dq.get("focus_id", "") or "")
        if dq_focus and dq_focus != str(active_fields.get("focus_id", "") or ""):
            dq["active"] = False
            dq["last_error"] = "queue focus changed before worker progress accounting"
            bb["decomposition_queue"] = dq
            self.blackboard = bb
            return {"queue_active": False, "step_advanced": False}
        rows = list(dq.get("steps", []) or [])
        cursor = max(0, int(dq.get("cursor", 0) or 0))
        if cursor >= len(rows):
            dq["active"] = False
            dq["cursor"] = len(rows)
            bb["decomposition_queue"] = dq
            self.blackboard = bb
            return {"queue_active": False, "step_advanced": False}
        current = rows[cursor] if isinstance(rows[cursor], dict) else {}
        target = self._sanitize_agent_role(current.get("target", "")) or "developer"
        role_key = self._sanitize_agent_role(role)
        if target != role_key:
            bb["decomposition_queue"] = dq
            self.blackboard = bb
            return out
        status = str((step or {}).get("status", "") or "").strip().lower()
        text = trim(strip_thinking_content(str((step or {}).get("text", "") or "").strip()), 1200)
        tool_results = (step or {}).get("tool_results", []) if isinstance((step or {}).get("tool_results"), list) else []
        has_ok_tool = any(isinstance(row, dict) and bool(row.get("ok", False)) for row in tool_results)
        success = bool(status == "tools" and has_ok_tool)
        if (not success) and status == "no-tools" and role_key in {"explorer", "reviewer"} and len(text) >= 120:
            success = True
        attempts = max(0, int(current.get("attempts", 0) or 0)) + 1
        current["attempts"] = attempts
        current["updated_at"] = float(now_ts())
        if success:
            current["status"] = "done"
            dq["cursor"] = cursor + 1
            out["step_advanced"] = True
            dq["last_error"] = ""
        elif status in {"no-tools", "tools", "skip"}:
            if attempts >= int(WATCHDOG_STEP_MAX_ATTEMPTS):
                current["status"] = "skipped"
                dq["cursor"] = cursor + 1
                out["step_advanced"] = True
                dq["last_error"] = trim(
                    f"step {cursor + 1} skipped after {attempts} attempts ({status})",
                    300,
                )
            else:
                current["status"] = "retry"
                dq["last_error"] = trim(
                    f"step {cursor + 1} retry pending ({status})",
                    300,
                )
        rows[cursor] = current
        dq["steps"] = rows
        if int(dq.get("cursor", 0) or 0) >= len(rows):
            dq["active"] = False
            out["queue_active"] = False
            self._emit("status", {"summary": "stateless executor queue drained; returning to normal manager routing"})
        else:
            out["queue_active"] = bool(dq.get("active", False))
        bb["decomposition_queue"] = dq
        self.blackboard = bb
        return out

    def _watchdog_process_worker_step(
        self,
        board: dict,
        *,
        role: str,
        step: dict,
        state_changed: bool,
        pinned_selection: str,
    ) -> dict:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        wd = self._normalize_watchdog_state(bb.get("watchdog", {}))
        dq = self._normalize_decomposition_queue_state(bb.get("decomposition_queue", {}))
        status = str((step or {}).get("status", "") or "").strip().lower()
        text = trim(strip_thinking_content(str((step or {}).get("text", "") or "").strip()), 1200)
        wd["last_state_fp"] = self._watchdog_state_fingerprint(bb)
        if state_changed:
            wd["state_unchanged_streak"] = 0
        else:
            wd["state_unchanged_streak"] = max(0, int(wd.get("state_unchanged_streak", 0) or 0)) + 1
        if status == "tools":
            wd["intent_no_tool_streak"] = 0
            wd["repeat_no_tool_streak"] = 0
            wd["last_no_tool_text"] = ""
            wd["last_no_tool_hash"] = ""
        elif status == "no-tools":
            if self._watchdog_intent_without_action(text):
                wd["intent_no_tool_streak"] = max(0, int(wd.get("intent_no_tool_streak", 0) or 0)) + 1
            else:
                wd["intent_no_tool_streak"] = max(0, int(wd.get("intent_no_tool_streak", 0) or 0) - 1)
            prev_text = str(wd.get("last_no_tool_text", "") or "")
            sim = self._watchdog_similarity(prev_text, text)
            if sim >= float(WATCHDOG_REPEAT_SIMILARITY_THRESHOLD):
                wd["repeat_no_tool_streak"] = max(0, int(wd.get("repeat_no_tool_streak", 0) or 0)) + 1
            else:
                wd["repeat_no_tool_streak"] = 0
            wd["last_no_tool_text"] = text
            wd["last_no_tool_hash"] = hashlib.sha1(safe_utf8_bytes(text)).hexdigest() if text else ""
        else:
            wd["intent_no_tool_streak"] = max(0, int(wd.get("intent_no_tool_streak", 0) or 0) - 1)
            wd["repeat_no_tool_streak"] = max(0, int(wd.get("repeat_no_tool_streak", 0) or 0) - 1)
        bb["watchdog"] = wd
        bb["decomposition_queue"] = dq
        self.blackboard = bb
        progress_row = self._watchdog_mark_step_progress(bb, role, step)
        bb = self._ensure_blackboard()
        dq = self._normalize_decomposition_queue_state(bb.get("decomposition_queue", {}))
        trigger_reason = ""
        _is_single = self._effective_execution_mode() == EXECUTION_MODE_SINGLE
        _intent_th = WATCHDOG_INTENT_NO_TOOL_THRESHOLD_SINGLE if _is_single else WATCHDOG_INTENT_NO_TOOL_THRESHOLD
        _repeat_th = WATCHDOG_REPEAT_NO_TOOL_THRESHOLD_SINGLE if _is_single else WATCHDOG_REPEAT_NO_TOOL_THRESHOLD
        if not bool(dq.get("active", False)):
            if int(wd.get("intent_no_tool_streak", 0) or 0) >= int(_intent_th):
                trigger_reason = "intent-without-tool-call"
            elif int(wd.get("repeat_no_tool_streak", 0) or 0) >= int(_repeat_th):
                trigger_reason = "repeated-no-tool-reply"
            elif (
                self._watchdog_context_near_limit()
                and int(wd.get("state_unchanged_streak", 0) or 0) >= int(WATCHDOG_CONTEXT_STALL_THRESHOLD)
            ):
                trigger_reason = "context-threshold-no-state-change"
            elif (
                status in {"no-tools", "skip"}
                and int(wd.get("state_unchanged_streak", 0) or 0) >= int(WATCHDOG_STATE_STALL_THRESHOLD)
            ):
                trigger_reason = "state-unchanged-stall"
        triggered = False
        if trigger_reason:
            try:
                last_trigger_ts = float(wd.get("last_trigger_ts", 0.0) or 0.0)
            except Exception:
                last_trigger_ts = 0.0
            if now_ts() - last_trigger_ts >= 1.0:
                wd["trigger_count"] = max(0, int(wd.get("trigger_count", 0) or 0)) + 1
                wd["last_trigger_reason"] = trim(str(trigger_reason or "").strip(), 200)
                wd["last_trigger_ts"] = float(now_ts())
                bb["watchdog"] = wd
                self.blackboard = bb
                self._blackboard_touch()
                # Failure ledger: record stall event
                self._ledger_record_stall(trigger_reason, "unresolved")
                if int(wd["trigger_count"]) >= 2:
                    _wd_sev = self._bump_stall_severity("watchdog", STALL_SEVERITY_WEIGHT_WATCHDOG)
                    if _wd_sev >= STALL_SEVERITY_ESCALATION_THRESHOLD:
                        if not self._escalate_stall_to_plan_mode(
                            "watchdog", last_fault_reason=trigger_reason, pinned_selection=pinned_selection,
                        ):
                            self._watchdog_escalate_to_single_developer(bb, reason=trigger_reason)
                    else:
                        self._watchdog_escalate_to_single_developer(bb, reason=trigger_reason)
                else:
                    triggered = self._watchdog_activate_decomposition(
                        bb,
                        reason=trigger_reason,
                        role=role,
                        step=step,
                        pinned_selection=pinned_selection,
                    )
                bb = self._ensure_blackboard()
        bb["watchdog"] = self._normalize_watchdog_state(bb.get("watchdog", wd))
        bb["decomposition_queue"] = self._normalize_decomposition_queue_state(bb.get("decomposition_queue", dq))
        self.blackboard = bb
        self._blackboard_touch()
        return {
            "triggered": bool(triggered),
            "trigger_reason": trigger_reason,
            "queue_active": bool((bb.get("decomposition_queue", {}) or {}).get("active", False)),
            "step_advanced": bool(progress_row.get("step_advanced", False)),
        }

    def _watchdog_execute_queue_step(self, *, pinned_selection: str) -> dict:
        board = self._ensure_blackboard()
        pick = self._watchdog_pick_executor_route(board)
        if not pick:
            dq = self._normalize_decomposition_queue_state(board.get("decomposition_queue", {}))
            return {"executed": False, "queue_active": bool(dq.get("active", False)), "stop_run": False, "interrupted": False}
        queue_args, meta = pick
        role = self._sanitize_agent_role((queue_args or {}).get("target", "")) or "developer"
        instruction = trim(str((queue_args or {}).get("instruction", "") or "").strip(), MANAGER_INSTRUCTION_MAX_CHARS)
        if not instruction:
            instruction = (
                "Executor mode step: call one concrete tool now, keep scope narrow, and update blackboard evidence."
            )
        self._inject_manager_instruction(role, instruction, is_mandatory=True, executor_mode=True)
        if role == "explorer":
            self._blackboard_set_status("RESEARCHING")
        elif role == "developer":
            self._blackboard_set_status("CODING")
        elif role == "reviewer":
            self._blackboard_set_status("REVIEWING")
        board_before_fp = self._watchdog_state_fingerprint(self._ensure_blackboard())
        step = self._multi_agent_turn(
            role,
            pinned_selection=pinned_selection,
            media_inputs_round=None,
        )
        safe_step = step if isinstance(step, dict) else {}
        self._blackboard_update_from_worker_step(role, safe_step)
        board_after = self._ensure_blackboard()
        board_after_fp = self._watchdog_state_fingerprint(board_after)
        wd_event = self._watchdog_process_worker_step(
            board_after,
            role=role,
            step=safe_step,
            state_changed=bool(board_after_fp != board_before_fp),
            pinned_selection=pinned_selection,
        )
        status = str(safe_step.get("status", "") or "").strip().lower()
        interrupted = bool(status == "interrupted")
        stop_run = False
        finish_gate_reason = ""
        if status == "tools" and bool(safe_step.get("stop_due_to_finish", False)):
            note = f"{self._agent_display_name(role)} signaled finish via tool."
            finish_result = self._resolve_finish_request(role, source="executor-finish-tool", summary=note)
            stop_run = bool(finish_result.get("stop", False))
            finish_gate_reason = str(finish_result.get("reason", "") or "")
        dq = self._normalize_decomposition_queue_state(self._ensure_blackboard().get("decomposition_queue", {}))
        return {
            "executed": True,
            "queue_active": bool(dq.get("active", False)),
            "stop_run": bool(stop_run),
            "interrupted": bool(interrupted),
            "role": role,
            "status": status,
            "wd_event": wd_event,
            "trigger_reason": trim(str(meta.get("trigger_reason", "") or "").strip(), 120),
            "finish_gate_reason": finish_gate_reason,
        }

    def _new_completion_state(self) -> dict:
        return {
            "state": "working",
            "requested_by": "",
            "source": "",
            "gate_reason": "",
            "attempt_count": 0,
            "last_progress_fp": "",
            "last_request_ts": 0.0,
            "finalized_at": 0.0,
            "summary": "",
            "route": {},
        }

    def _normalize_completion_state(self, raw: object) -> dict:
        src = raw if isinstance(raw, dict) else {}
        state = str(src.get("state", "working") or "working").strip().lower()
        if state not in {"working", "finish_requested", "blocked", "finalizing", "completed"}:
            state = "working"
        route_src = src.get("route", {}) if isinstance(src.get("route", {}), dict) else {}
        route = {
            "target": trim(str(route_src.get("target", "") or "").strip().lower(), 40),
            "instruction": trim(str(route_src.get("instruction", "") or "").strip(), MANAGER_INSTRUCTION_MAX_CHARS),
            "reason": trim(str(route_src.get("reason", "") or "").strip(), 300),
            "source": trim(str(route_src.get("source", "") or "").strip(), 80),
            "is_mandatory": _to_bool_like(route_src.get("is_mandatory", False), default=False),
        }
        if route["target"] not in MANAGER_ROUTE_TARGETS:
            route["target"] = ""
        return {
            "state": state,
            "requested_by": trim(str(src.get("requested_by", "") or "").strip(), 40),
            "source": trim(str(src.get("source", "") or "").strip(), 80),
            "gate_reason": trim(str(src.get("gate_reason", "") or "").strip(), 160),
            "attempt_count": max(0, int(src.get("attempt_count", 0) or 0)),
            "last_progress_fp": trim(str(src.get("last_progress_fp", "") or "").strip(), 80),
            "last_request_ts": float(src.get("last_request_ts", 0.0) or 0.0),
            "finalized_at": float(src.get("finalized_at", 0.0) or 0.0),
            "summary": trim(str(src.get("summary", "") or "").strip(), 1200),
            "route": route,
        }

    def _new_blackboard(self, goal: str = "") -> dict:
        profile = self._normalize_task_profile(goal, {})
        progress = "done" if str(profile.get("task_type", "") or "") == "simple_qa" and not str(goal or "").strip() else "initializing"
        return {
            "version": 1,
            "updated_at": float(now_ts()),
            "original_goal": trim(str(goal or "").strip(), 4000),
            "research_notes": [],
            "code_artifacts": {},
            "execution_logs": [],
            "review_feedback": [],
            "conversation_history": [],
            "plan_worker_todos": {},
            "status": "INITIALIZING",
            "task_epoch": float(now_ts()),
            "focus": {
                "kind": "task",
                "id": "",
                "index": 0,
                "total": 0,
                "epoch": 0.0,
                "title": "",
            },
            "memory": {
                "short": [],
                "mid": {},
                "long": [],
                "index": {},
            },
            "approval": {
                "approved": False,
                "by": "",
                "note": "",
                "ts": 0.0,
            },
            "completion": self._new_completion_state(),
            "manager_cycles": 0,
            "manager_summary_attempts": 0,
            "active_agent": "",
            "last_delegate": {
                "target": "",
                "instruction": "",
                "reason": "",
                "source": "",
                "progress_fp": "",
                "is_mandatory": False,
                "ts": 0.0,
            },
            "task_profile": profile,
            "manager_judgement": {
                "task_type": str(profile.get("task_type", "general")),
                "complexity": str(profile.get("complexity", "simple")),
                "scale_preference": str(profile.get("scale_preference", "balanced") or "balanced"),
                "progress": progress,
                "remaining_rounds": (
                    -1
                    if int(profile.get("round_budget", 0) or 0) <= 0
                    else int(profile.get("round_budget", 1) or 1)
                ),
                "updated_at": float(now_ts()),
            },
            "last_worker_reply": {
                "role": "",
                "text": "",
                "ts": 0.0,
            },
            "project_todos": [],
            "watchdog": self._new_watchdog_state(),
            "decomposition_queue": self._new_decomposition_queue_state(),
            "failure_ledger": {
                "attempted_fixes": [],
                "compilation_errors": [],
                "errors": [],
                "repeated_delegations": [],
                "stall_events": [],
                "tool_call_fingerprints": [],
            },
            "checkpoints": [],
            "persisted_manager_routes": [],
        }

    def _normalize_blackboard(self, raw: object) -> dict:
        src = raw if isinstance(raw, dict) else {}
        board = self._new_blackboard(str(src.get("original_goal", "") or ""))
        try:
            board["version"] = int(src.get("version", 1) or 1)
        except Exception:
            board["version"] = 1
        board["updated_at"] = float(src.get("updated_at", now_ts()) or now_ts())
        board["status"] = self._normalize_blackboard_status(src.get("status", board["status"]))
        try:
            board["task_epoch"] = float(src.get("task_epoch", board.get("task_epoch", 0.0)) or board.get("task_epoch", 0.0) or now_ts())
        except Exception:
            board["task_epoch"] = float(now_ts())
        board["manager_cycles"] = max(0, int(src.get("manager_cycles", 0) or 0))
        board["manager_summary_attempts"] = max(0, int(src.get("manager_summary_attempts", 0) or 0))
        board["active_agent"] = self._sanitize_agent_role(src.get("active_agent", ""))
        raw_delegate = src.get("last_delegate", {})
        if isinstance(raw_delegate, dict):
            board["last_delegate"] = {
                "target": str(raw_delegate.get("target", "") or "").strip().lower(),
                "instruction": trim(str(raw_delegate.get("instruction", "") or "").strip(), MANAGER_INSTRUCTION_MAX_CHARS),
                "reason": trim(str(raw_delegate.get("reason", "") or "").strip(), 600),
                "source": trim(str(raw_delegate.get("source", "") or "").strip(), 40),
                "progress_fp": trim(str(raw_delegate.get("progress_fp", "") or "").strip(), 80),
                "is_mandatory": _to_bool_like(raw_delegate.get("is_mandatory", False), default=False),
                "ts": float(raw_delegate.get("ts", 0.0) or 0.0),
                "focus_kind": trim(str(raw_delegate.get("focus_kind", "") or "").strip(), 40),
                "focus_id": trim(str(raw_delegate.get("focus_id", "") or "").strip(), 120),
                "focus_epoch": float(raw_delegate.get("focus_epoch", 0.0) or 0.0),
                "plan_step_id": trim(str(raw_delegate.get("plan_step_id", "") or "").strip(), 40),
                "plan_step_index": int(raw_delegate.get("plan_step_index")) if raw_delegate.get("plan_step_index") not in (None, "") else -1,
                "plan_step_total": int(raw_delegate.get("plan_step_total", 0) or 0),
                "plan_step_epoch": float(raw_delegate.get("plan_step_epoch", 0.0) or 0.0),
            }
        raw_approval = src.get("approval", {})
        if isinstance(raw_approval, dict):
            board["approval"] = {
                "approved": bool(raw_approval.get("approved", False)),
                "by": trim(str(raw_approval.get("by", "") or "").strip(), 60),
                "note": trim(str(raw_approval.get("note", "") or "").strip(), 1000),
                "ts": float(raw_approval.get("ts", 0.0) or 0.0),
            }
        board["completion"] = self._normalize_completion_state(src.get("completion", {}))
        board["task_profile"] = self._normalize_task_profile(
            str(board.get("original_goal", "") or ""),
            src.get("task_profile", {}),
        )
        raw_judgement = src.get("manager_judgement", {})
        if isinstance(raw_judgement, dict):
            board["manager_judgement"] = {
                "task_type": trim(
                    str(raw_judgement.get("task_type", board["task_profile"].get("task_type", "")) or "").strip(),
                    40,
                ),
                "complexity": (
                    str(
                        raw_judgement.get(
                            "complexity",
                            board["task_profile"].get("complexity", "simple"),
                        )
                        or ""
                    )
                    .strip()
                    .lower()
                ),
                "scale_preference": (
                    str(
                        raw_judgement.get(
                            "scale_preference",
                            board["task_profile"].get("scale_preference", "balanced"),
                        )
                        or "balanced"
                    )
                    .strip()
                    .lower()
                ),
                "progress": trim(str(raw_judgement.get("progress", "initializing") or "").strip().lower(), 40),
                "remaining_rounds": max(
                    -1,
                    int(
                        raw_judgement.get(
                            "remaining_rounds",
                            (
                                -1
                                if int(board["task_profile"].get("round_budget", 0) or 0) <= 0
                                else board["task_profile"].get("round_budget", self.max_agent_rounds)
                            ),
                        )
                        if raw_judgement.get("remaining_rounds", None) is not None
                        else (
                            -1
                            if int(board["task_profile"].get("round_budget", 0) or 0) <= 0
                            else int(board["task_profile"].get("round_budget", self.max_agent_rounds) or 0)
                        )
                    ),
                ),
                "updated_at": float(raw_judgement.get("updated_at", now_ts()) or now_ts()),
            }
        else:
            board["manager_judgement"] = {
                "task_type": str(board["task_profile"].get("task_type", "")),
                "complexity": str(board["task_profile"].get("complexity", "")),
                "scale_preference": str(board["task_profile"].get("scale_preference", "balanced") or "balanced"),
                "progress": "initializing",
                "remaining_rounds": (
                    -1
                    if int(board["task_profile"].get("round_budget", 0) or 0) <= 0
                    else int(board["task_profile"].get("round_budget", self.max_agent_rounds) or 0)
                ),
                "updated_at": float(now_ts()),
            }
        raw_last_reply = src.get("last_worker_reply", {})
        if isinstance(raw_last_reply, dict):
            board["last_worker_reply"] = {
                "role": self._sanitize_agent_role(raw_last_reply.get("role", "")),
                "text": trim(str(raw_last_reply.get("text", "") or "").strip(), 3000),
                "ts": float(raw_last_reply.get("ts", 0.0) or 0.0),
            }

        def _clean_rows(rows: object, *, key: str = "content", actor_key: str = "actor") -> list[dict]:
            out: list[dict] = []
            if not isinstance(rows, list):
                return out
            for row in rows[-(BLACKBOARD_MAX_LOG_ENTRIES * 2) :]:
                if not isinstance(row, dict):
                    continue
                txt = trim(str(row.get(key, "") or "").strip(), BLACKBOARD_MAX_TEXT)
                if not txt:
                    continue
                clean_row = {
                    "ts": float(row.get("ts", now_ts()) or now_ts()),
                    "actor": trim(str(row.get(actor_key, "") or "").strip(), 40),
                    key: txt,
                }
                for meta_key in ("focus_kind", "focus_id", "focus_epoch", "plan_step_id", "plan_step_index"):
                    if meta_key not in row:
                        continue
                    if meta_key == "plan_step_index":
                        try:
                            clean_row[meta_key] = int(row.get(meta_key, -1) or -1)
                        except Exception:
                            clean_row[meta_key] = -1
                    elif meta_key == "focus_epoch":
                        try:
                            clean_row[meta_key] = float(row.get(meta_key, 0.0) or 0.0)
                        except Exception:
                            clean_row[meta_key] = 0.0
                    else:
                        clean_row[meta_key] = trim(str(row.get(meta_key, "") or "").strip(), 120)
                out.append(clean_row)
            return out[-BLACKBOARD_MAX_LOG_ENTRIES:]

        board["research_notes"] = _clean_rows(src.get("research_notes", []), key="content", actor_key="actor")
        board["execution_logs"] = _clean_rows(src.get("execution_logs", []), key="content", actor_key="actor")
        board["review_feedback"] = _clean_rows(src.get("review_feedback", []), key="content", actor_key="actor")
        board["conversation_history"] = _clean_rows(src.get("conversation_history", []), key="content", actor_key="actor")
        raw_worker_todos = src.get("plan_worker_todos")
        if isinstance(raw_worker_todos, dict):
            clean_worker_todos: dict[str, list[dict]] = {}
            for raw_step_id, raw_rows in list(raw_worker_todos.items())[:80]:
                step_id = trim(str(raw_step_id or "").strip(), 40)
                if not step_id or not isinstance(raw_rows, list):
                    continue
                clean_rows: list[dict] = []
                for row in raw_rows[-12:]:
                    if not isinstance(row, dict):
                        continue
                    raw_content = str(row.get("content", "") or "").strip()
                    parsed_status, parsed_content = split_todo_status_text(raw_content)
                    content = trim(normalize_work_text(parsed_content or raw_content) or (parsed_content or raw_content), 360)
                    if not content:
                        continue
                    raw_status = str(row.get("status", "") or "").strip().lower().replace("-", "_").replace(" ", "_")
                    status = self._normalize_todo_status_value(row.get("status", ""), parsed_status or "pending")
                    if parsed_status and raw_status in {"", "todo", "pending"}:
                        status = parsed_status
                    if status == "blocked":
                        status = "pending"
                    clean_rows.append({
                        "content": content,
                        "status": status,
                        "owner": self._sanitize_agent_role(row.get("owner", "")) or "developer",
                        "parent_step_id": trim(str(row.get("parent_step_id", "") or step_id), 40) or step_id,
                        "created_at": float(row.get("created_at", 0.0) or 0.0),
                        "updated_at": float(row.get("updated_at", 0.0) or 0.0),
                        "completed_at": float(row.get("completed_at", 0.0) or 0.0) if row.get("completed_at") else None,
                        "completed_by": trim(str(row.get("completed_by", "") or ""), 40),
                        "evidence": trim(str(row.get("evidence", "") or ""), 300),
                    })
                if clean_rows:
                    clean_worker_todos[step_id] = clean_rows
            if clean_worker_todos:
                board["plan_worker_todos"] = clean_worker_todos
        raw_artifacts = src.get("code_artifacts", {})
        artifacts: dict[str, dict] = {}
        if isinstance(raw_artifacts, dict):
            for p, row in list(raw_artifacts.items())[:320]:
                rel = normalize_rel_preview_path(str(p or "")) or trim(str(p or "").strip(), 280)
                if not rel:
                    continue
                if self._is_plan_infrastructure_path(rel):
                    continue
                item = row if isinstance(row, dict) else {}
                summary = trim(str(item.get("summary", "") or "").strip(), BLACKBOARD_MAX_TEXT)
                if not summary:
                    continue
                artifacts[rel] = {
                    "summary": summary,
                    "last_actor": trim(str(item.get("last_actor", "") or "").strip(), 40),
                    "updated_at": float(item.get("updated_at", now_ts()) or now_ts()),
                    "change_count": max(1, int(item.get("change_count", 1) or 1)),
                    "focus_id": trim(str(item.get("focus_id", "") or "").strip(), 120),
                    "focus_kind": trim(str(item.get("focus_kind", "") or "").strip(), 40),
                    "plan_step_id": trim(str(item.get("plan_step_id", "") or "").strip(), 40),
                }
        board["code_artifacts"] = artifacts
        if not isinstance(bb_src_todos := src.get("project_todos"), list):
            board["project_todos"] = []
        else:
            clean_todos = []
            import re as _re_norm
            _mid_re_norm = _re_norm.compile(r"(?<=\S)\s+(\d+\.\d+\s)")
            for pt in bb_src_todos[:40]:
                if not isinstance(pt, dict):
                    continue
                raw_content = trim(normalize_embedded_newlines(pt.get("content", "")), PLAN_STEP_FULL_CONTENT_MAX_CHARS)
                raw_full = trim(normalize_embedded_newlines(pt.get("full_content", "")), PLAN_STEP_FULL_CONTENT_MAX_CHARS)
                # Migration: if full_content is empty but content has sub-steps, auto-split
                if not raw_full and raw_content and pt.get("category") == "plan_step":
                    normalized = _mid_re_norm.sub(r"\n\1", raw_content)
                    if "\n" in normalized:
                        raw_full = normalized
                        raw_content = normalized.split("\n")[0].strip()
                clean_todos.append({
                    "id": trim(str(pt.get("id", "") or ""), 20),
                    "content": trim(raw_content, 400),
                    "full_content": trim(raw_full, PLAN_STEP_FULL_CONTENT_MAX_CHARS),
                    "status": str(pt.get("status", "pending") or "pending") if str(pt.get("status", "pending") or "pending") in ("pending", "in_progress", "completed") else "pending",
                    "category": trim(str(pt.get("category", "") or ""), 40),
                    "plan_step_index": int(pt.get("plan_step_index", -1)) if pt.get("plan_step_index") is not None else -1,
                    "created_at": float(pt.get("created_at", 0.0) or 0.0),
                    "activated_at": float(pt.get("activated_at", 0.0) or 0.0) if pt.get("activated_at") else None,
                    "completed_at": float(pt.get("completed_at", 0.0) or 0.0) if pt.get("completed_at") else None,
                    "completed_by": trim(str(pt.get("completed_by", "") or ""), 40),
                    "evidence": trim(str(pt.get("evidence", "") or ""), 200),
                })
            clean_todos, todos_changed, removed_plan_fragments = self._sanitize_project_plan_todos(clean_todos)
            if todos_changed:
                hist = board.get("conversation_history", [])
                if isinstance(hist, list):
                    hist.append({
                        "actor": "manager",
                        "content": (
                            "normalized plan todos: removed numeric/text fragments "
                            f"({', '.join(removed_plan_fragments[:4]) or 'renumbered'})"
                        ),
                        "ts": float(now_ts()),
                    })
                    board["conversation_history"] = hist[-120:]
            board["project_todos"] = clean_todos
        # Preserve plan step cursor/total (used by _advance_plan_step and UI progress)
        raw_cursor = src.get("plan_step_cursor")
        if raw_cursor is not None:
            try:
                board["plan_step_cursor"] = int(raw_cursor)
            except Exception:
                pass
        raw_total = src.get("plan_step_total")
        if raw_total is not None:
            try:
                board["plan_step_total"] = int(raw_total)
            except Exception:
                pass
        plan_row_count = len([
            t for t in (board.get("project_todos", []) if isinstance(board.get("project_todos"), list) else [])
            if isinstance(t, dict) and t.get("category") == "plan_step"
        ])
        if plan_row_count > 0:
            board["plan_step_total"] = plan_row_count
            # Canonical invariant (shared with advance/reconcile): single
            # lowest-index active step, cursor derived from its index. Operates
            # in-place on the board being built; does not touch self.blackboard.
            self._normalize_plan_step_progress(board)
        board["watchdog"] = self._normalize_watchdog_state(src.get("watchdog", {}))
        board["decomposition_queue"] = self._normalize_decomposition_queue_state(
            src.get("decomposition_queue", {})
        )
        # Preserve plan-mode data through normalization
        raw_plan = src.get("plan")
        if isinstance(raw_plan, dict):
            plan_clean = dict(raw_plan)
            if isinstance(plan_clean.get("steps"), list):
                plan_clean["steps"] = self._group_plan_steps(plan_clean.get("steps", []))
            plan_clean["charter"] = self._normalize_plan_charter(plan_clean.get("charter", {}))
            if not plan_clean["charter"]:
                plan_clean["charter"] = self._build_plan_charter(
                    str(plan_clean.get("chosen", "") or ""),
                    {
                        "id": str(plan_clean.get("chosen", "") or ""),
                        "title": str(plan_clean.get("title", "") or ""),
                        "summary": str(plan_clean.get("summary", "") or ""),
                    },
                    board=board,
                    grouped_steps=plan_clean.get("steps", []),
                )
            plan_clean["step_results"] = self._normalize_plan_step_results(plan_clean.get("step_results", {}))
            board["plan"] = plan_clean
        # Preserve failure_ledger, checkpoints, persisted_manager_routes
        raw_fl = src.get("failure_ledger")
        board["failure_ledger"] = self._normalize_failure_ledger(raw_fl) if isinstance(raw_fl, dict) else {
            "attempted_fixes": [],
            "compilation_errors": [],
            "errors": [],
            "repeated_delegations": [],
            "stall_events": [],
            "tool_call_fingerprints": [],
        }
        raw_cp = src.get("checkpoints")
        board["checkpoints"] = list(raw_cp)[-CHECKPOINT_MAX_COUNT:] if isinstance(raw_cp, list) else []
        raw_pmr = src.get("persisted_manager_routes")
        board["persisted_manager_routes"] = list(raw_pmr)[-PERSISTED_ROUTES_MAX:] if isinstance(raw_pmr, list) else []
        # Preserve loaded_skills across normalization
        raw_loaded_skills = src.get("loaded_skills")
        if isinstance(raw_loaded_skills, dict) and raw_loaded_skills:
            clean_skills: dict[str, dict] = {}
            for skey, sinfo in list(raw_loaded_skills.items())[:10]:
                if isinstance(sinfo, dict):
                    clean_skills[str(skey)] = {
                        "loaded_at": float(sinfo.get("loaded_at", 0.0) or 0.0),
                        "size": int(sinfo.get("size", 0) or 0),
                        "preview": trim(str(sinfo.get("preview", "") or ""), 300),
                    }
            if clean_skills:
                board["loaded_skills"] = clean_skills
        goal_sig = trim(str(src.get("loaded_skills_goal_sig", "") or ""), 80)
        if goal_sig:
            board["loaded_skills_goal_sig"] = goal_sig
        goal_preview = trim(str(src.get("loaded_skills_goal_preview", "") or ""), 240)
        if goal_preview:
            board["loaded_skills_goal_preview"] = goal_preview
        # Preserve step_files registry across normalization
        raw_step_files = src.get("step_files")
        if isinstance(raw_step_files, dict):
            clean_sf: dict[str, list] = {}
            for sf_key, sf_entries in raw_step_files.items():
                if isinstance(sf_entries, list):
                    clean_sf[str(sf_key)] = sf_entries[-30:]
            if clean_sf:
                board["step_files"] = clean_sf
        board["focus"] = self._blackboard_focus_identity(board)
        board["memory"] = self._normalize_blackboard_memory(src.get("memory", {}))
        return board

    def _blackboard_focus_identity(self, board: dict | None = None) -> dict:
        bb = board if isinstance(board, dict) else (self.blackboard if isinstance(getattr(self, "blackboard", None), dict) else {})
        current = self._current_plan_step_row(bb) if isinstance(bb, dict) else None
        if isinstance(current, dict) and current.get("category") == "plan_step":
            idx = int(current.get("plan_step_index", 0) or 0)
            total = int(bb.get("plan_step_total", 0) or 0)
            if total <= 0:
                todos = bb.get("project_todos", []) if isinstance(bb.get("project_todos", []), list) else []
                total = len([t for t in todos if isinstance(t, dict) and t.get("category") == "plan_step"])
            step_id = trim(str(current.get("id", "") or f"step:{idx + 1}").strip(), 80)
            epoch = float(current.get("activated_at", 0.0) or current.get("created_at", 0.0) or 0.0)
            title = trim(str(current.get("content", "") or "").strip(), 360)
            full_text = trim(
                normalize_embedded_newlines(current.get("full_content", "") or current.get("content", "") or "").strip(),
                1200,
            )
            return {
                "kind": "plan_step",
                "id": step_id,
                "index": idx,
                "total": total,
                "epoch": epoch,
                "title": title,
                "full_text": full_text,
            }
        profile = bb.get("task_profile", {}) if isinstance(bb.get("task_profile"), dict) else {}
        goal = trim(str(bb.get("original_goal", "") or "").strip(), 1200) if isinstance(bb, dict) else ""
        direct = trim(str(profile.get("direct_objective", "") or "").strip(), 800)
        seed = f"{goal}\n{direct}".strip() or "session-task"
        focus_id = "task:" + hashlib.sha1(seed.encode("utf-8", errors="replace")).hexdigest()[:14]
        epoch = float((bb or {}).get("task_epoch", 0.0) or 0.0)
        title = trim(direct or goal or "current task", 360)
        return {
            "kind": "task",
            "id": focus_id,
            "index": 0,
            "total": 0,
            "epoch": epoch,
            "title": title,
            "full_text": trim(direct or goal, 1200),
        }

    def _normalize_blackboard_memory(self, raw: object) -> dict:
        src = raw if isinstance(raw, dict) else {}

        def _clean_paths(value: object) -> list[str]:
            rows = value if isinstance(value, list) else []
            out: list[str] = []
            for item in rows[:16]:
                rel = trim(str(item or "").replace("\\", "/").strip(), 300)
                if rel and rel not in out:
                    out.append(rel)
            return out

        def _clean_row(row: object, *, default_tier: str = "short") -> dict | None:
            if not isinstance(row, dict):
                return None
            summary = trim(str(row.get("summary", row.get("content", "")) or "").strip(), 900)
            if not summary:
                return None
            tier = str(row.get("tier", default_tier) or default_tier).strip().lower()
            if tier not in {"short", "mid", "long"}:
                tier = default_tier
            ts = float(row.get("ts", row.get("updated_at", now_ts())) or now_ts())
            mid = trim(str(row.get("id", "") or "").strip(), 40)
            if not mid:
                raw_id = f"{ts}|{row.get('actor','')}|{summary[:120]}"
                mid = hashlib.sha1(raw_id.encode("utf-8", errors="replace")).hexdigest()[:16]
            return {
                "id": mid,
                "ts": ts,
                "tier": tier,
                "kind": trim(str(row.get("kind", "note") or "note").strip(), 80),
                "actor": trim(str(row.get("actor", "") or "").strip(), 40),
                "summary": summary,
                "tool": trim(str(row.get("tool", "") or "").strip(), 80),
                "command": trim(str(row.get("command", "") or "").strip(), 500),
                "paths": _clean_paths(row.get("paths", row.get("related_paths", []))),
                "focus_kind": trim(str(row.get("focus_kind", "") or "").strip(), 40),
                "focus_id": trim(str(row.get("focus_id", "") or "").strip(), 120),
                "focus_epoch": float(row.get("focus_epoch", 0.0) or 0.0),
                "plan_step_id": trim(str(row.get("plan_step_id", "") or "").strip(), 80),
                "plan_step_index": int(row.get("plan_step_index")) if row.get("plan_step_index") not in (None, "") else -1,
            }

        short = []
        for row in (src.get("short", []) if isinstance(src.get("short", []), list) else [])[-(BLACKBOARD_MEMORY_SHORT_MAX * 2) :]:
            clean = _clean_row(row, default_tier="short")
            if clean:
                short.append(clean)
        short = short[-BLACKBOARD_MEMORY_SHORT_MAX:]

        mid: dict[str, dict] = {}
        raw_mid = src.get("mid", {})
        if isinstance(raw_mid, dict):
            for focus_id, bucket in list(raw_mid.items())[-(BLACKBOARD_MEMORY_MID_MAX_STEPS * 2) :]:
                fid = trim(str(focus_id or "").strip(), 120)
                if not fid or not isinstance(bucket, dict):
                    continue
                items = []
                for item in (bucket.get("items", []) if isinstance(bucket.get("items", []), list) else [])[-(BLACKBOARD_MEMORY_MID_ITEMS_PER_STEP * 2) :]:
                    clean = _clean_row(item, default_tier="mid")
                    if clean:
                        clean["tier"] = "mid"
                        items.append(clean)
                mid[fid] = {
                    "focus_id": fid,
                    "focus_kind": trim(str(bucket.get("focus_kind", "") or "").strip(), 40),
                    "title": trim(str(bucket.get("title", "") or "").strip(), 360),
                    "summary": trim(str(bucket.get("summary", "") or "").strip(), 1200),
                    "updated_at": float(bucket.get("updated_at", 0.0) or 0.0),
                    "items": items[-BLACKBOARD_MEMORY_MID_ITEMS_PER_STEP:],
                }
        if len(mid) > BLACKBOARD_MEMORY_MID_MAX_STEPS:
            rows = sorted(mid.items(), key=lambda item: float((item[1] or {}).get("updated_at", 0.0) or 0.0))
            mid = dict(rows[-BLACKBOARD_MEMORY_MID_MAX_STEPS:])

        long_rows = []
        for row in (src.get("long", []) if isinstance(src.get("long", []), list) else [])[-(BLACKBOARD_MEMORY_LONG_MAX * 2) :]:
            clean = _clean_row(row, default_tier="long")
            if clean:
                clean["tier"] = "long"
                long_rows.append(clean)
        long_rows = long_rows[-BLACKBOARD_MEMORY_LONG_MAX:]

        index: dict[str, dict] = {}
        raw_index = src.get("index", {})
        if isinstance(raw_index, dict):
            for key, value in list(raw_index.items())[-(BLACKBOARD_MEMORY_INDEX_MAX * 2) :]:
                k = trim(str(key or "").replace("\\", "/").strip(), 360)
                if not k or not isinstance(value, dict):
                    continue
                ids = value.get("ids", [])
                index[k] = {
                    "ids": [trim(str(x or "").strip(), 40) for x in (ids if isinstance(ids, list) else [])[-8:] if str(x or "").strip()],
                    "last_summary": trim(str(value.get("last_summary", "") or "").strip(), 360),
                    "last_ts": float(value.get("last_ts", 0.0) or 0.0),
                    "focus_id": trim(str(value.get("focus_id", "") or "").strip(), 120),
                }
        if len(index) > BLACKBOARD_MEMORY_INDEX_MAX:
            rows = sorted(index.items(), key=lambda item: float((item[1] or {}).get("last_ts", 0.0) or 0.0))
            index = dict(rows[-BLACKBOARD_MEMORY_INDEX_MAX:])
        return {"short": short, "mid": mid, "long": long_rows, "index": index}

    def _blackboard_memory_budget(self) -> dict:
        try:
            budget = self._tool_memory_budget()
        except Exception:
            budget = {"items": 12, "chars": 3600, "tier": 0}
        tier = int(budget.get("tier", 0) or 0)
        return {
            "short": max(12, min(BLACKBOARD_MEMORY_SHORT_MAX, int(budget.get("items", 12) or 12) * 4)),
            "mid_items": max(6, min(BLACKBOARD_MEMORY_MID_ITEMS_PER_STEP, int(budget.get("items", 12) or 12) + 2)),
            "long": max(16, min(BLACKBOARD_MEMORY_LONG_MAX, int(budget.get("items", 12) or 12) * (3 if tier <= 1 else 2))),
            "chars": max(1600, min(6000, int(budget.get("chars", 3600) or 3600))),
        }

    def _blackboard_append_memory(
        self,
        kind: str,
        summary: str,
        *,
        actor: str = "",
        paths: list[str] | None = None,
        tool: str = "",
        command: str = "",
        tier: str = "short",
        board: dict | None = None,
    ) -> dict | None:
        txt = trim(str(summary or "").strip(), 900)
        if not txt:
            return None
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        focus = self._blackboard_focus_identity(bb)
        focus_id = str(focus.get("id", "") or "")
        focus_kind = str(focus.get("kind", "") or "")
        step_id = focus_id if focus_kind == "plan_step" else ""
        path_rows: list[str] = []
        for item in list(paths or []):
            rel = trim(str(item or "").replace("\\", "/").strip(), 300)
            if rel and rel not in path_rows:
                path_rows.append(rel)
        now_tick = float(now_ts())
        raw_id = f"{focus_id}|{kind}|{actor}|{tool}|{command}|{txt[:200]}|{now_tick}"
        memory_id = hashlib.sha1(raw_id.encode("utf-8", errors="replace")).hexdigest()[:16]
        row = {
            "id": memory_id,
            "ts": now_tick,
            "tier": "short",
            "kind": trim(str(kind or "note").strip(), 80),
            "actor": trim(str(actor or "").strip(), 40),
            "summary": txt,
            "tool": trim(str(tool or "").strip(), 80),
            "command": trim(str(command or "").strip(), 500),
            "paths": path_rows[:12],
            "focus_kind": focus_kind,
            "focus_id": focus_id,
            "focus_epoch": float(focus.get("epoch", 0.0) or 0.0),
            "plan_step_id": step_id,
            "plan_step_index": int(focus.get("index")) if focus.get("index") not in (None, "") else -1,
        }
        memory = self._normalize_blackboard_memory(bb.get("memory", {}))
        budget = self._blackboard_memory_budget()
        short_rows = list(memory.get("short", []))
        short_rows.append(dict(row))
        memory["short"] = short_rows[-int(budget.get("short", BLACKBOARD_MEMORY_SHORT_MAX)) :]

        if focus_id:
            mid = dict(memory.get("mid", {}))
            bucket = dict(mid.get(focus_id, {})) if isinstance(mid.get(focus_id, {}), dict) else {}
            bucket_items = list(bucket.get("items", [])) if isinstance(bucket.get("items", []), list) else []
            mid_row = dict(row)
            mid_row["tier"] = "mid"
            bucket_items.append(mid_row)
            bucket["focus_id"] = focus_id
            bucket["focus_kind"] = focus_kind
            bucket["title"] = trim(str(focus.get("title", "") or ""), 360)
            bucket["summary"] = trim(txt if not bucket.get("summary") else f"{bucket.get('summary')}; {txt}", 1200)
            bucket["updated_at"] = now_tick
            bucket["items"] = bucket_items[-int(budget.get("mid_items", BLACKBOARD_MEMORY_MID_ITEMS_PER_STEP)) :]
            mid[focus_id] = bucket
            if len(mid) > BLACKBOARD_MEMORY_MID_MAX_STEPS:
                rows = sorted(mid.items(), key=lambda item: float((item[1] or {}).get("updated_at", 0.0) or 0.0))
                mid = dict(rows[-BLACKBOARD_MEMORY_MID_MAX_STEPS:])
            memory["mid"] = mid

        long_kinds = {
            "artifact",
            "file_patch",
            "validation",
            "command_error",
            "edit_error",
            "review",
            "decision",
            "step_transition",
            "skill_loaded",
            "finish",
        }
        if str(tier or "").strip().lower() == "long" or str(kind or "").strip().lower() in long_kinds:
            long_rows = list(memory.get("long", []))
            long_row = dict(row)
            long_row["tier"] = "long"
            long_rows.append(long_row)
            memory["long"] = long_rows[-int(budget.get("long", BLACKBOARD_MEMORY_LONG_MAX)) :]

        index = dict(memory.get("index", {}))
        index_keys = list(path_rows)
        if command:
            index_keys.append("cmd:" + trim(str(command or ""), 300))
        for idx_key in index_keys:
            if not idx_key:
                continue
            prev = dict(index.get(idx_key, {})) if isinstance(index.get(idx_key, {}), dict) else {}
            ids = list(prev.get("ids", [])) if isinstance(prev.get("ids", []), list) else []
            ids.append(memory_id)
            index[idx_key] = {
                "ids": ids[-8:],
                "last_summary": txt,
                "last_ts": now_tick,
                "focus_id": focus_id,
            }
        if len(index) > BLACKBOARD_MEMORY_INDEX_MAX:
            rows = sorted(index.items(), key=lambda item: float((item[1] or {}).get("last_ts", 0.0) or 0.0))
            index = dict(rows[-BLACKBOARD_MEMORY_INDEX_MAX:])
        memory["index"] = index
        bb["memory"] = memory
        bb["focus"] = focus
        self.blackboard = bb
        self._blackboard_touch()
        return row

    def _blackboard_memory_context_markdown(self, *, for_role: str = "", max_chars: int | None = None) -> str:
        bb = self._ensure_blackboard()
        focus = self._blackboard_focus_identity(bb)
        memory = self._normalize_blackboard_memory(bb.get("memory", {}))
        budget = self._blackboard_memory_budget()
        char_budget = int(max_chars or budget.get("chars", 3200) or 3200)
        focus_id = str(focus.get("id", "") or "")
        lines = [
            "## Task Memory",
            (
                f"- active_focus: {focus.get('kind', 'task')} "
                f"{focus_id or '(none)'}"
                + (f" step={(int(focus.get('index')) if focus.get('index') not in (None, '') else -1) + 1}/{int(focus.get('total', 0) or 0)}" if focus.get("kind") == "plan_step" else "")
                + f" | {trim(str(focus.get('title', '') or ''), 180)}"
            ),
            "- cooperation_rule: all agents work on this shared focus; do not advance a private parallel task.",
        ]
        mid = memory.get("mid", {}) if isinstance(memory.get("mid", {}), dict) else {}
        bucket = mid.get(focus_id, {}) if focus_id and isinstance(mid.get(focus_id, {}), dict) else {}
        if bucket:
            summary = trim(str(bucket.get("summary", "") or ""), 420)
            if summary:
                lines.append(f"- focus_summary: {summary}")
            items = bucket.get("items", []) if isinstance(bucket.get("items", []), list) else []
            if items:
                lines.append("### Active Focus Evidence")
                for row in items[-6:]:
                    if not isinstance(row, dict):
                        continue
                    actor = trim(str(row.get("actor", "") or ""), 24) or "agent"
                    kind = trim(str(row.get("kind", "note") or "note"), 32)
                    text = trim(str(row.get("summary", "") or ""), 240)
                    paths = row.get("paths", []) if isinstance(row.get("paths", []), list) else []
                    path_note = f" [{', '.join(paths[:3])}]" if paths else ""
                    lines.append(f"- [{actor}/{kind}] {text}{path_note}")
        short_rows = [
            row for row in (memory.get("short", []) if isinstance(memory.get("short", []), list) else [])
            if isinstance(row, dict) and (not focus_id or str(row.get("focus_id", "") or "") == focus_id)
        ]
        if short_rows and not bucket:
            lines.append("### Recent Focus Evidence")
            for row in short_rows[-5:]:
                actor = trim(str(row.get("actor", "") or ""), 24) or "agent"
                kind = trim(str(row.get("kind", "note") or "note"), 32)
                lines.append(f"- [{actor}/{kind}] {trim(str(row.get('summary', '') or ''), 220)}")
        long_rows = memory.get("long", []) if isinstance(memory.get("long", []), list) else []
        if long_rows:
            lines.append("### Stable Cross-Step Memory")
            for row in long_rows[-5:]:
                if not isinstance(row, dict):
                    continue
                kind = trim(str(row.get("kind", "memory") or "memory"), 32)
                actor = trim(str(row.get("actor", "") or ""), 24) or "agent"
                lines.append(f"- [{actor}/{kind}] {trim(str(row.get('summary', '') or ''), 220)}")
        return trim("\n".join(lines), char_budget)

    def _route_focus_fields(self, board: dict | None = None) -> dict:
        focus = self._blackboard_focus_identity(board)
        fields = {
            "focus_kind": str(focus.get("kind", "") or ""),
            "focus_id": str(focus.get("id", "") or ""),
            "focus_epoch": float(focus.get("epoch", 0.0) or 0.0),
            "plan_step_id": "",
            "plan_step_index": -1,
            "plan_step_total": 0,
            "plan_step_epoch": 0.0,
        }
        if fields["focus_kind"] == "plan_step":
            fields["plan_step_id"] = fields["focus_id"]
            fields["plan_step_index"] = int(focus.get("index")) if focus.get("index") not in (None, "") else -1
            fields["plan_step_total"] = int(focus.get("total", 0) or 0)
            fields["plan_step_epoch"] = float(focus.get("epoch", 0.0) or 0.0)
        return fields

    def _route_matches_active_focus(self, route: dict | None, board: dict | None = None) -> bool:
        if not isinstance(route, dict):
            return False
        fields = self._route_focus_fields(board)
        route_focus = str(route.get("focus_id", "") or "")
        if not route_focus:
            return True
        if route_focus != str(fields.get("focus_id", "") or ""):
            return False
        route_epoch = float(route.get("focus_epoch", 0.0) or route.get("plan_step_epoch", 0.0) or 0.0)
        active_epoch = float(fields.get("focus_epoch", 0.0) or fields.get("plan_step_epoch", 0.0) or 0.0)
        if route_epoch and active_epoch and abs(route_epoch - active_epoch) > 0.001:
            return False
        return True

    def _agentbus_envelope_matches_active_focus(self, envelope: dict, board: dict | None = None) -> bool:
        """Return whether an agent-bus handoff belongs to the current focus.

        Plan-step execution is focus-scoped. A handoff created for step N must
        not wake a worker after the plan has advanced to step N+1; otherwise a
        stale repair hint can overwrite the active step and make the run appear
        to jump or regress. Legacy envelopes without focus metadata are allowed
        only when no plan step is active.
        """
        if not isinstance(envelope, dict):
            return False
        fields = self._route_focus_fields(board)
        active_kind = str(fields.get("focus_kind", "") or "")
        active_focus = str(fields.get("focus_id", "") or "")
        active_step = str(fields.get("plan_step_id", "") or active_focus)
        env_focus = str(envelope.get("focus_id", "") or "")
        env_step = str(envelope.get("plan_step_id", "") or "")
        if active_kind == "plan_step":
            if not env_focus and not env_step:
                return False
            if env_step and env_step != active_step:
                return False
            if env_focus and env_focus != active_focus:
                return False
            try:
                env_epoch = float(envelope.get("focus_epoch", 0.0) or envelope.get("plan_step_epoch", 0.0) or 0.0)
                active_epoch = float(fields.get("focus_epoch", 0.0) or fields.get("plan_step_epoch", 0.0) or 0.0)
            except Exception:
                env_epoch = 0.0
                active_epoch = 0.0
            if env_epoch and active_epoch and abs(env_epoch - active_epoch) > 0.001:
                return False
            return True
        if env_focus and active_focus and env_focus != active_focus:
            return False
        return True

    def _normalize_failure_ledger(self, raw: dict) -> dict:
        fl: dict = {
            "attempted_fixes": [],
            "compilation_errors": [],
            "errors": [],
            "repeated_delegations": [],
            "stall_events": [],
            "tool_call_fingerprints": [],
        }
        if not isinstance(raw, dict):
            return fl
        def _safe_list(key: str, max_len: int) -> list[dict]:
            items = raw.get(key)
            if not isinstance(items, list):
                return []
            out: list[dict] = []
            for item in items[-max_len:]:
                if isinstance(item, dict):
                    out.append(item)
            return out
        fl["attempted_fixes"] = _safe_list("attempted_fixes", FAILURE_LEDGER_MAX_FIXES)
        fl["compilation_errors"] = _safe_list("compilation_errors", FAILURE_LEDGER_MAX_COMPILE_ERRORS)
        fl["errors"] = _safe_list("errors", FAILURE_LEDGER_MAX_ERRORS)
        fl["repeated_delegations"] = _safe_list("repeated_delegations", FAILURE_LEDGER_MAX_DELEGATIONS)
        fl["stall_events"] = _safe_list("stall_events", FAILURE_LEDGER_MAX_STALLS)
        fl["tool_call_fingerprints"] = _safe_list("tool_call_fingerprints", FAILURE_LEDGER_MAX_TOOL_FPS)
        return fl

    def _ledger_record_fix_attempt(self, file: str, error: str, fix: str, result: str, actor: str):
        bb = self._ensure_blackboard()
        fl = bb.get("failure_ledger")
        if not isinstance(fl, dict):
            return
        fixes = fl.get("attempted_fixes", [])
        focus = self._blackboard_focus_identity(bb)
        fixes.append({
            "file": trim(str(file or ""), 260),
            "error": trim(str(error or ""), 400),
            "fix": trim(str(fix or ""), 400),
            "result": trim(str(result or ""), 200),
            "actor": trim(str(actor or ""), 40),
            "round": int(getattr(self, "agent_round_index", 0) or 0),
            "ts": float(now_ts()),
            "focus_id": str(focus.get("id", "") or ""),
            "focus_kind": str(focus.get("kind", "") or ""),
            "plan_step_id": str(focus.get("id", "") or "") if str(focus.get("kind", "") or "") == "plan_step" else "",
        })
        fl["attempted_fixes"] = fixes[-FAILURE_LEDGER_MAX_FIXES:]
        bb["failure_ledger"] = fl
        self.blackboard = bb

    def _ledger_update_fix_attempt_status(self, file: str, new_status: str):
        """Update status of most recent fix_attempt for a file."""
        bb = self._ensure_blackboard()
        fl = bb.get("failure_ledger")
        if not isinstance(fl, dict):
            return
        fixes = fl.get("attempted_fixes", [])
        focus = self._blackboard_focus_identity(bb)
        current_step_id = str(focus.get("id", "") or "") if str(focus.get("kind", "") or "") == "plan_step" else ""
        for fx in reversed(fixes):
            if not isinstance(fx, dict):
                continue
            if current_step_id and str(fx.get("plan_step_id", "") or "") != current_step_id:
                continue
            fx_file = str(fx.get("file", "") or "")
            if fx_file and (fx_file.endswith(file) or file.endswith(fx_file)):
                if fx.get("result") in ("pending", "applied"):
                    fx["result"] = new_status
                    break
        fl["attempted_fixes"] = fixes
        bb["failure_ledger"] = fl
        self.blackboard = bb

    def _ledger_verify_fix_attempts_on_success(self, category: str):
        """After successful bash, mark 'applied' fix_attempts as verified."""
        bb = self._ensure_blackboard()
        fl = bb.get("failure_ledger")
        if not isinstance(fl, dict):
            return
        fixes = fl.get("attempted_fixes", [])
        focus = self._blackboard_focus_identity(bb)
        current_step_id = str(focus.get("id", "") or "") if str(focus.get("kind", "") or "") == "plan_step" else ""
        for fx in fixes:
            if not isinstance(fx, dict):
                continue
            if current_step_id and str(fx.get("plan_step_id", "") or "") != current_step_id:
                continue
            if fx.get("result") == "applied":
                fx["result"] = f"verified({category})"
        fl["attempted_fixes"] = fixes
        bb["failure_ledger"] = fl
        self.blackboard = bb

    def _ledger_mark_fix_attempts_failed(self, category: str, error_msg: str):
        """After failed bash, mark 'applied' fix_attempts as failed."""
        bb = self._ensure_blackboard()
        fl = bb.get("failure_ledger")
        if not isinstance(fl, dict):
            return
        fixes = fl.get("attempted_fixes", [])
        focus = self._blackboard_focus_identity(bb)
        current_step_id = str(focus.get("id", "") or "") if str(focus.get("kind", "") or "") == "plan_step" else ""
        for fx in fixes:
            if not isinstance(fx, dict):
                continue
            if current_step_id and str(fx.get("plan_step_id", "") or "") != current_step_id:
                continue
            if fx.get("result") == "applied":
                fx["result"] = f"failed({category}): {trim(error_msg, 120)}"
        fl["attempted_fixes"] = fixes
        bb["failure_ledger"] = fl
        self.blackboard = bb

    def _continuation_failure_briefing(self) -> str:
        """Generate failure context summary for continuation scenarios."""
        bb = self._ensure_blackboard()
        fl = bb.get("failure_ledger", {})
        if not isinstance(fl, dict):
            return ""
        lines = []
        # Edit stalls
        if self.developer_edit_fail_streaks:
            stuck = [f"{k} ({v} failures)" for k, v in self.developer_edit_fail_streaks.items()]
            lines.append(f"Edit stalls: {'; '.join(stuck)}")
        # Failed fixes
        fixes = fl.get("attempted_fixes", [])
        failed = [fx for fx in fixes if isinstance(fx, dict) and "failed" in str(fx.get("result", "") or "").lower()]
        if failed:
            lines.append("Failed fixes:")
            for fx in failed[-3:]:
                lines.append(f"  - {trim(str(fx.get('file','')),80)}: {trim(str(fx.get('result','')),120)}")
        # Unresolved errors
        unresolved = [e for e in fl.get("errors", []) if isinstance(e, dict) and int(e.get("count", 0) or 0) > 0]
        if unresolved:
            lines.append("Unresolved errors:")
            for e in unresolved[:3]:
                lines.append(f"  - [{e.get('category','')}] {e.get('file','')}: {trim(str(e.get('error_msg','')),150)}")
        if not lines:
            return ""
        return "FAILURE CONTEXT (from previous attempt):\n" + "\n".join(lines) + "\n"

    # --- Unified error detection helpers ---

    def _detect_error_category(self, cmd_str: str) -> str | None:
        """Match a command string against ERROR_CATEGORY_DEFS, return first matching category name."""
        cmd_lower = str(cmd_str or "").lower()
        for cat_name, cat_def in ERROR_CATEGORY_DEFS:
            if any(kw in cmd_lower for kw in cat_def.get("cmd_keywords", [])):
                return cat_name
        return None

    def _check_output_has_errors(self, output: str, category: str) -> bool:
        """Check if output contains error patterns for the given category."""
        out_lower = str(output or "").lower()
        cat_def = dict(ERROR_CATEGORY_DEFS).get(category, {})
        return any(pat.lower() in out_lower for pat in cat_def.get("output_patterns", []))

    def _extract_error_lines(self, output: str, category: str, max_lines: int = 3) -> list[tuple[str, str]]:
        """Scan output lines for error patterns, return [(file_hint, error_line), ...]."""
        cat_def = dict(ERROR_CATEGORY_DEFS).get(category, {})
        patterns = [p.lower() for p in cat_def.get("output_patterns", [])]
        results: list[tuple[str, str]] = []
        for ln in str(output or "").split("\n"):
            if any(pat in ln.lower() for pat in patterns):
                file_hint = ""
                parts = ln.split(":")
                if len(parts) >= 2 and ("." in parts[0] or "/" in parts[0]):
                    file_hint = parts[0].strip()
                results.append((file_hint, ln.strip()))
                if len(results) >= max_lines:
                    break
        return results

    # --- Unified error ledger record / clear / sync helpers ---

    def _ledger_record_error(self, category: str, file: str, error_msg: str):
        """Record an error into fl['errors'] with category field. Dedup by fingerprint."""
        bb = self._ensure_blackboard()
        fl = bb.get("failure_ledger")
        if not isinstance(fl, dict):
            return
        errors = fl.get("errors", [])
        focus = self._blackboard_focus_identity(bb)
        now_tick = float(now_ts())
        fp = hashlib.sha1(safe_utf8_bytes(str(category or "") + str(file or "") + str(error_msg or ""))).hexdigest()[:12]
        for entry in errors:
            if entry.get("fingerprint") == fp:
                entry["count"] = int(entry.get("count", 1) or 1) + 1
                entry["last_round"] = int(getattr(self, "agent_round_index", 0) or 0)
                entry["last_ts"] = now_tick
                entry["focus_id"] = str(focus.get("id", "") or entry.get("focus_id", "") or "")
                entry["focus_kind"] = str(focus.get("kind", "") or entry.get("focus_kind", "") or "")
                entry["plan_step_id"] = str(focus.get("id", "") or "") if str(focus.get("kind", "") or "") == "plan_step" else ""
                fl["errors"] = errors
                bb["failure_ledger"] = fl
                self.blackboard = bb
                self._sync_compilation_errors_compat()
                return
        errors.append({
            "fingerprint": fp,
            "category": str(category or ""),
            "file": trim(str(file or ""), 260),
            "error_msg": trim(str(error_msg or ""), 400),
            "count": 1,
            "first_round": int(getattr(self, "agent_round_index", 0) or 0),
            "last_round": int(getattr(self, "agent_round_index", 0) or 0),
            "first_ts": now_tick,
            "last_ts": now_tick,
            "focus_id": str(focus.get("id", "") or ""),
            "focus_kind": str(focus.get("kind", "") or ""),
            "plan_step_id": str(focus.get("id", "") or "") if str(focus.get("kind", "") or "") == "plan_step" else "",
        })
        fl["errors"] = errors[-FAILURE_LEDGER_MAX_ERRORS:]
        bb["failure_ledger"] = fl
        self.blackboard = bb
        self._sync_compilation_errors_compat()

    def _ledger_clear_errors(self, category: str | None = None):
        """Clear errors from fl['errors']. If category given, only that category; else all."""
        bb = self._ensure_blackboard()
        fl = bb.get("failure_ledger")
        if not isinstance(fl, dict):
            return
        if category is None:
            fl["errors"] = []
            fl["attempted_fixes"] = []
        else:
            fl["errors"] = [e for e in fl.get("errors", []) if e.get("category") != category]
            # Clear attempted_fixes that match files in the cleared category
            fl["attempted_fixes"] = [
                fx for fx in fl.get("attempted_fixes", [])
                if not (isinstance(fx, dict) and fx.get("category") == category)
            ]
        bb["failure_ledger"] = fl
        self.blackboard = bb
        self._sync_compilation_errors_compat()

    def _sync_compilation_errors_compat(self):
        """Sync fl['compilation_errors'] from fl['errors'] where category=='compilation' for backward compat."""
        bb = self._ensure_blackboard()
        fl = bb.get("failure_ledger")
        if not isinstance(fl, dict):
            return
        fl["compilation_errors"] = [
            e for e in fl.get("errors", [])
            if isinstance(e, dict) and e.get("category") == "compilation"
        ]
        bb["failure_ledger"] = fl
        self.blackboard = bb

    # --- Thin wrappers kept for backward compatibility ---

    def _ledger_record_compile_error(self, file: str, error_msg: str):
        self._ledger_record_error("compilation", file, error_msg)

    def _ledger_clear_compile_errors(self):
        self._ledger_clear_errors("compilation")

    # --- Unified tool-result error processing ---

    def _process_tool_result_errors(self, name: str, args: dict, output: str, ok: bool, role_key: str):
        """Detect and record errors from tool results, or clear on success."""
        # Handle edit_file mismatch failures separately because they often need
        # targeted recovery rather than generic command classification.
        if name == "edit_file" and isinstance(args, dict):
            edit_path = str(args.get("path", "") or "").strip()
            if not ok and "text not found" in str(output or "").lower():
                self._ledger_record_error("edit_mismatch", edit_path or "unknown", trim(str(output or ""), 300))
                count = int(self.developer_edit_fail_streaks.get(edit_path, 0) or 0) + 1
                self.developer_edit_fail_streaks[edit_path] = count
                self.developer_edit_last_diag[edit_path] = trim(str(output or ""), 500)
                if count >= 2:
                    self._inject_edit_recovery_hint(edit_path, count, str(output or ""), role_key)
            elif ok and edit_path:
                self.developer_edit_fail_streaks.pop(edit_path, None)
                self.developer_edit_last_diag.pop(edit_path, None)
                if not self.developer_edit_fail_streaks:
                    self._ledger_clear_errors("edit_mismatch")
                self._ledger_update_fix_attempt_status(edit_path, "applied")
            return

        # For shell results, classify the command and update the shared error ledger.
        if name not in {"bash", "worktree_run"} or not isinstance(args, dict):
            return
        cmd_str = str(args.get("command", "") or "").lower()
        category = self._detect_error_category(cmd_str)
        if not category:
            return
        if not ok:
            error_lines = self._extract_error_lines(str(output or ""), category)
            for file_hint, err_line in error_lines:
                self._ledger_record_error(category, file_hint or cmd_str[:80], trim(err_line, 300))
            self._ledger_mark_fix_attempts_failed(category, trim(str(output or ""), 200))
        else:
            out_lower = str(output or "").lower()
            cat_def = dict(ERROR_CATEGORY_DEFS).get(category, {})
            negatives = cat_def.get("success_negatives", [])
            if not any(neg.lower() in out_lower for neg in negatives):
                self._ledger_clear_errors(category)
                # Auto-deactivate reviewer debug mode when errors are resolved
                if bool(self.reviewer_debug_mode) and not self._manager_has_error_log():
                    self._deactivate_reviewer_debug_mode("errors resolved")
                self._ledger_verify_fix_attempts_on_success(category)

    # --- Consolidated error-context assembly for recovery prompts ---

    def _recent_error_context(self, max_chars: int = 800) -> str:
        """Build context string from all error categories in fl['errors']."""
        bb = self._ensure_blackboard()
        lines: list[str] = []
        focus = self._blackboard_focus_identity(bb)
        current_step_id = str(focus.get("id", "") or "") if str(focus.get("kind", "") or "") == "plan_step" else ""
        try:
            current_epoch = float(focus.get("epoch", 0.0) or 0.0)
        except Exception:
            current_epoch = 0.0
        fl = bb.get("failure_ledger", {})
        if isinstance(fl, dict):
            all_errors = fl.get("errors", [])
            unresolved = [e for e in all_errors if isinstance(e, dict) and int(e.get("count", 0) or 0) > 0]
            if current_step_id:
                filtered_unresolved: list[dict] = []
                for e in unresolved:
                    err_step_id = str(e.get("plan_step_id", "") or "")
                    if err_step_id and err_step_id != current_step_id:
                        continue
                    try:
                        err_ts = float(e.get("last_ts", 0.0) or 0.0)
                    except Exception:
                        err_ts = 0.0
                    if current_epoch > 0 and err_ts > 0 and err_ts + 1e-6 < current_epoch:
                        continue
                    filtered_unresolved.append(e)
                unresolved = filtered_unresolved
            if unresolved:
                # Group by category
                by_cat: dict[str, list] = {}
                for e in unresolved:
                    cat = str(e.get("category", "unknown") or "unknown")
                    by_cat.setdefault(cat, []).append(e)
                cat_labels = dict(ERROR_CATEGORY_DEFS)
                for cat, errs in by_cat.items():
                    label = cat_labels.get(cat, {}).get("label", cat.upper()) if cat in cat_labels else cat.upper()
                    lines.append(f"UNRESOLVED {label.upper()}:")
                    for e in errs[:5]:
                        f = str(e.get("file", "") or "")
                        msg = str(e.get("error_msg", "") or "")
                        cnt = int(e.get("count", 1) or 1)
                        lines.append(f"  [{f}] {trim(msg, 200)} (seen {cnt}x)")
            fixes = fl.get("attempted_fixes", [])
            if current_step_id:
                fixes = [
                    fx for fx in fixes
                    if isinstance(fx, dict) and str(fx.get("plan_step_id", "") or "") == current_step_id
                ]
            if fixes:
                lines.append("PREVIOUSLY ATTEMPTED FIXES (all failed):")
                for fx in fixes[-3:]:
                    if isinstance(fx, dict):
                        lines.append(f"  - {trim(str(fx.get('fix', '') or ''), 120)} -> {trim(str(fx.get('result', '') or ''), 60)}")
        logs = bb.get("execution_logs", []) if isinstance(bb.get("execution_logs"), list) else []
        _all_kw = (
            "error:", "fatal error", "syntax error", "compile error", "build failed",
            "traceback", "exception", "failed", "panic:", "FAIL:", "AssertionError",
        )
        last_error_text = ""
        last_error_ts = 0.0
        last_success_ts = 0.0
        for entry in reversed(logs[-6:]):
            if not isinstance(entry, dict):
                continue
            row_step_id = str(entry.get("plan_step_id", "") or "")
            if current_step_id and row_step_id and row_step_id != current_step_id:
                continue
            try:
                entry_ts = float(entry.get("ts", 0.0) or 0.0)
            except Exception:
                entry_ts = 0.0
            if current_step_id and current_epoch > 0 and entry_ts > 0 and entry_ts + 1e-6 < current_epoch:
                continue
            if self._is_plan_infrastructure_tool_error(
                str(entry.get("tool", "") or ""),
                entry.get("args", {}) if isinstance(entry.get("args", {}), dict) else {},
                entry.get("content", ""),
            ):
                continue
            if ".clouds_coder/plan.md" in str(entry.get("content", "") or "").lower():
                continue
            if self._execution_log_entry_is_success_evidence(entry):
                try:
                    last_success_ts = max(last_success_ts, float(entry.get("ts", 0.0) or 0.0))
                except Exception:
                    pass
                break
            txt = str(entry.get("content", "") or "")
            if self._execution_log_entry_is_blocking_error(entry) or any(kw in txt.lower() for kw in _all_kw):
                last_error_text = txt
                try:
                    last_error_ts = float(entry.get("ts", 0.0) or 0.0)
                except Exception:
                    last_error_ts = 0.0
                break
        if last_error_text and (last_success_ts <= 0.0 or last_error_ts <= 0.0 or last_error_ts + 1e-6 >= last_success_ts):
            lines.append(f"LAST ERROR OUTPUT:\n{trim(last_error_text, 400)}")
        if not lines:
            return ""
        return trim("\n".join(lines), max_chars)

    def _recent_compile_error_context(self, max_chars: int = 800) -> str:
        return self._recent_error_context(max_chars=max_chars)

    def _ledger_record_delegation(self, target: str, instruction: str):
        bb = self._ensure_blackboard()
        fl = bb.get("failure_ledger")
        if not isinstance(fl, dict):
            return
        delegations = fl.get("repeated_delegations", [])
        progress_fp = self._watchdog_state_fingerprint(bb)
        fp = hashlib.sha1(safe_utf8_bytes(str(instruction or "") + "|" + progress_fp)).hexdigest()[:12]
        for entry in delegations:
            if entry.get("instruction_hash") == fp and entry.get("target") == target:
                entry["count"] = int(entry.get("count", 1) or 1) + 1
                entry["last_round"] = int(getattr(self, "agent_round_index", 0) or 0)
                fl["repeated_delegations"] = delegations
                bb["failure_ledger"] = fl
                self.blackboard = bb
                return
        delegations.append({
            "target": trim(str(target or ""), 40),
            "instruction_hash": fp,
            "instruction_preview": trim(str(instruction or ""), 200),
            "progress_fp": progress_fp,
            "count": 1,
            "first_round": int(getattr(self, "agent_round_index", 0) or 0),
            "last_round": int(getattr(self, "agent_round_index", 0) or 0),
        })
        fl["repeated_delegations"] = delegations[-FAILURE_LEDGER_MAX_DELEGATIONS:]
        bb["failure_ledger"] = fl
        self.blackboard = bb

    def _ledger_record_stall(self, reason: str, resolution: str):
        bb = self._ensure_blackboard()
        fl = bb.get("failure_ledger")
        if not isinstance(fl, dict):
            return
        stalls = fl.get("stall_events", [])
        stalls.append({
            "reason": trim(str(reason or ""), 200),
            "resolution": trim(str(resolution or ""), 200),
            "round": int(getattr(self, "agent_round_index", 0) or 0),
            "ts": float(now_ts()),
        })
        fl["stall_events"] = stalls[-FAILURE_LEDGER_MAX_STALLS:]
        bb["failure_ledger"] = fl
        self.blackboard = bb

    def _ledger_record_tool_call(self, tool_name: str, args: dict):
        bb = self._ensure_blackboard()
        fl = bb.get("failure_ledger")
        if not isinstance(fl, dict):
            return
        fps = fl.get("tool_call_fingerprints", [])
        try:
            args_str = json_dumps(args) if isinstance(args, dict) else str(args or "")
        except Exception:
            args_str = str(args or "")
        fp = hashlib.sha1(safe_utf8_bytes(str(tool_name or "") + args_str)).hexdigest()[:16]
        for entry in fps:
            if entry.get("fingerprint") == fp:
                entry["count"] = int(entry.get("count", 1) or 1) + 1
                entry["last_round"] = int(getattr(self, "agent_round_index", 0) or 0)
                fl["tool_call_fingerprints"] = fps
                bb["failure_ledger"] = fl
                self.blackboard = bb
                return
        fps.append({
            "fingerprint": fp,
            "tool_name": trim(str(tool_name or ""), 60),
            "count": 1,
            "first_round": int(getattr(self, "agent_round_index", 0) or 0),
            "last_round": int(getattr(self, "agent_round_index", 0) or 0),
        })
        fl["tool_call_fingerprints"] = fps[-FAILURE_LEDGER_MAX_TOOL_FPS:]
        bb["failure_ledger"] = fl
        self.blackboard = bb

    def _ensure_blackboard(self) -> dict:
        if not isinstance(self.blackboard, dict) or not self.blackboard:
            self.blackboard = self._new_blackboard(self._latest_user_goal_text())
        self.blackboard = self._normalize_blackboard(self.blackboard)
        return self.blackboard

    def _blackboard_touch(self):
        board = self._ensure_blackboard()
        board["updated_at"] = float(now_ts())
        self.blackboard = board

    def _save_blackboard(self, bb: dict):
        """Persist a blackboard dict as the current blackboard and touch updated_at."""
        if isinstance(bb, dict):
            bb["updated_at"] = float(now_ts())
            self.blackboard = bb

    def _blackboard_reset_for_goal(self, goal: str, *, preserve_active_state: bool = False):
        # Preserve plan state when safe, but refresh loaded skills on goal change.
        old_bb = self._ensure_blackboard()
        preserved_skills = old_bb.get("loaded_skills", {})
        preserved_skills_sig = str(old_bb.get("loaded_skills_goal_sig", "") or "")
        preserved_previous_context = (
            dict(old_bb.get("previous_task_context", {}))
            if isinstance(old_bb.get("previous_task_context", {}), dict)
            else {}
        )
        new_goal_sig = self._loaded_skills_goal_signature(goal)
        preserved_plan = old_bb.get("plan", {})
        preserved_todos = old_bb.get("project_todos", [])
        preserved_cursor = old_bb.get("plan_step_cursor", None)
        preserved_total = old_bb.get("plan_step_total", None)
        self.blackboard = self._new_blackboard(goal)
        if (
            isinstance(preserved_skills, dict)
            and preserved_skills
            and preserved_skills_sig
            and preserved_skills_sig == new_goal_sig
        ):
            self.blackboard["loaded_skills"] = preserved_skills
            self.blackboard["loaded_skills_goal_sig"] = preserved_skills_sig
            self.blackboard["loaded_skills_goal_preview"] = trim(str(goal or ""), 240)
        if preserved_previous_context:
            self.blackboard["previous_task_context"] = preserved_previous_context
        # Restore plan state if plan is active (any phase) or todos have pending work
        has_active_plan = (
            isinstance(preserved_plan, dict)
            and preserved_plan.get("phase") in ("executing", "research", "synthesis", "awaiting_choice")
        )
        has_active_todos = isinstance(preserved_todos, list) and any(
            t.get("status") != "completed" for t in preserved_todos if isinstance(t, dict)
        )
        if preserve_active_state and (has_active_plan or has_active_todos):
            if isinstance(preserved_plan, dict):
                self.blackboard["plan"] = preserved_plan
            if isinstance(preserved_todos, list) and preserved_todos:
                self.blackboard["project_todos"] = preserved_todos
            if preserved_cursor is not None:
                self.blackboard["plan_step_cursor"] = preserved_cursor
            if preserved_total is not None:
                self.blackboard["plan_step_total"] = preserved_total
        self.manager_context = []
        try:
            self.contexts = {role: [] for role in AGENT_ROLES}
        except Exception:
            pass
        blocked_roles = set(AGENT_ROLES) | {"manager", "planner"}
        self.agent_messages = [
            m for m in self.agent_messages
            if str(m.get("agent_role", "") or "") not in blocked_roles
        ]
        self.manager_routes = []
        self.agent_bus_messages = []
        self._blackboard_history("manager", f"new goal accepted: {trim(goal, 300)}")
        self._sync_todos_from_blackboard(reason="goal-reset", board=self.blackboard)

    def _blackboard_history(self, actor: str, content: str):
        txt = trim(str(content or "").strip(), BLACKBOARD_MAX_TEXT)
        if not txt:
            return
        board = self._ensure_blackboard()
        rows = list(board.get("conversation_history", []))
        rows.append({"ts": float(now_ts()), "actor": trim(str(actor or "").strip(), 40), "content": txt})
        board["conversation_history"] = rows[-BLACKBOARD_MAX_LOG_ENTRIES:]
        self._blackboard_touch()

    def _blackboard_append_section(self, section: str, actor: str, content: str):
        key = str(section or "").strip()
        _ALLOWED = {"research_notes", "execution_logs", "review_feedback",
                     "plan_findings", "plan_proposal", "plan_steps", "plan_risks",
                     "skill_analysis"}
        if key not in _ALLOWED:
            return
        txt = trim(str(content or "").strip(), BLACKBOARD_MAX_TEXT)
        if not txt:
            return
        board = self._ensure_blackboard()
        rows = list(board.get(key, []))
        focus = self._blackboard_focus_identity(board)
        row = {
            "ts": float(now_ts()),
            "actor": trim(str(actor or "").strip(), 40),
            "content": txt,
            "focus_kind": str(focus.get("kind", "") or ""),
            "focus_id": str(focus.get("id", "") or ""),
            "focus_epoch": float(focus.get("epoch", 0.0) or 0.0),
            "plan_step_id": str(focus.get("id", "") or "") if str(focus.get("kind", "") or "") == "plan_step" else "",
            "plan_step_index": int(focus.get("index")) if focus.get("index") not in (None, "") else -1,
        }
        rows.append(row)
        board[key] = rows[-BLACKBOARD_MAX_LOG_ENTRIES:]
        self.blackboard = board
        section_kind = {
            "research_notes": "research",
            "execution_logs": "execution",
            "review_feedback": "review",
            "skill_analysis": "skill_loaded",
            "plan_findings": "decision",
            "plan_proposal": "decision",
            "plan_steps": "decision",
            "plan_risks": "decision",
        }.get(key, "note")
        self._blackboard_append_memory(section_kind, txt, actor=actor, tier="short", board=board)

    def _blackboard_upsert_artifact(self, rel_path: str, summary: str, actor: str):
        path = normalize_rel_preview_path(str(rel_path or "")) or trim(str(rel_path or "").strip(), 280)
        if not path:
            return
        txt = trim(str(summary or "").strip(), BLACKBOARD_MAX_TEXT)
        if not txt:
            return
        board = self._ensure_blackboard()
        focus = self._blackboard_focus_identity(board)
        artifacts = dict(board.get("code_artifacts", {}))
        prev = artifacts.get(path, {}) if isinstance(artifacts.get(path), dict) else {}
        artifacts[path] = {
            "summary": txt,
            "last_actor": trim(str(actor or "").strip(), 40),
            "updated_at": float(now_ts()),
            "change_count": max(1, int(prev.get("change_count", 0) or 0) + 1),
            "focus_kind": str(focus.get("kind", "") or ""),
            "focus_id": str(focus.get("id", "") or ""),
            "plan_step_id": str(focus.get("id", "") or "") if str(focus.get("kind", "") or "") == "plan_step" else "",
        }
        if len(artifacts) > 240:
            rows = sorted(artifacts.items(), key=lambda item: float(item[1].get("updated_at", 0.0) or 0.0))
            artifacts = dict(rows[-240:])
        board["code_artifacts"] = artifacts
        self.blackboard = board
        self._blackboard_append_memory("artifact", txt, actor=actor, paths=[path], tier="long", board=board)

    def _todo_owner_display_name(self, owner: str) -> str:
        return self._agent_display_name(owner)

    def _todo_stage_focus_owner(self, board: dict | None = None) -> str:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        approval = bb.get("approval", {}) if isinstance(bb.get("approval"), dict) else {}
        if bool(approval.get("approved", False)):
            return ""
        delegate = bb.get("last_delegate", {}) if isinstance(bb.get("last_delegate"), dict) else {}
        delegate_target = self._sanitize_agent_role(delegate.get("target", ""))
        if delegate_target:
            return delegate_target
        active = self._sanitize_agent_role(bb.get("active_agent", ""))
        if active:
            return active
        profile = self._ensure_blackboard_task_profile(bb)
        mode = normalize_execution_mode(
            profile.get("execution_mode", self._effective_execution_mode()),
            default=self._effective_execution_mode(),
        )
        if mode == EXECUTION_MODE_SINGLE:
            expert = self._sanitize_agent_role(profile.get("assigned_expert", self.runtime_assigned_expert))
            if expert:
                return expert
        status = self._normalize_blackboard_status(bb.get("status", "INITIALIZING"))
        if status in {"INITIALIZING", "PAUSED"}:
            return "manager"
        if status == "RESEARCHING":
            return "explorer"
        if status == "CODING":
            return "developer"
        if status in {"TESTING", "REVIEWING"}:
            return "reviewer"
        return "manager"

    def _todo_node_anchor(self, board: dict | None = None) -> tuple[str, float, dict]:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        delegate = bb.get("last_delegate", {}) if isinstance(bb.get("last_delegate"), dict) else {}
        try:
            anchor_ts = float(delegate.get("ts", 0.0) or 0.0)
        except Exception:
            anchor_ts = 0.0
        if anchor_ts <= 0.0:
            profile = self._ensure_blackboard_task_profile(bb)
            try:
                anchor_ts = float(profile.get("updated_at", 0.0) or 0.0)
            except Exception:
                anchor_ts = 0.0
        if anchor_ts <= 0.0:
            try:
                anchor_ts = float(bb.get("updated_at", 0.0) or 0.0)
            except Exception:
                anchor_ts = 0.0
        cycle = max(0, int(bb.get("manager_cycles", 0) or 0))
        target = self._sanitize_agent_role(delegate.get("target", ""))
        anchor_id = f"n{cycle}:{target or '-'}:{int(anchor_ts)}"
        return anchor_id, float(anchor_ts), delegate

    def _todo_owner_has_node_evidence(
        self,
        owner: str,
        anchor_ts: float,
        board: dict | None = None,
    ) -> bool:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        role = str(owner or "").strip().lower()
        if role not in {"manager", "explorer", "developer", "reviewer"}:
            return False
        since = max(0.0, float(anchor_ts or 0.0))

        def _rows_hit(rows: object, actor: str = "") -> bool:
            arr = rows if isinstance(rows, list) else []
            actor_key = str(actor or "").strip().lower()
            for row in reversed(arr):
                if not isinstance(row, dict):
                    continue
                try:
                    ts = float(row.get("ts", 0.0) or 0.0)
                except Exception:
                    ts = 0.0
                if ts + 1e-6 < since:
                    break
                if actor_key and str(row.get("actor", "") or "").strip().lower() != actor_key:
                    continue
                if str(row.get("content", "") or "").strip():
                    return True
            return False

        last_reply = bb.get("last_worker_reply", {}) if isinstance(bb.get("last_worker_reply"), dict) else {}
        last_role = self._sanitize_agent_role(last_reply.get("role", ""))
        try:
            last_ts = float(last_reply.get("ts", 0.0) or 0.0)
        except Exception:
            last_ts = 0.0
        last_text = str(last_reply.get("text", "") or "").strip()
        if last_role == role and last_ts + 1e-6 >= since and last_text:
            return True

        if role == "manager":
            delegate = bb.get("last_delegate", {}) if isinstance(bb.get("last_delegate"), dict) else {}
            target = self._sanitize_agent_role(delegate.get("target", ""))
            try:
                delegate_ts = float(delegate.get("ts", 0.0) or 0.0)
            except Exception:
                delegate_ts = 0.0
            return bool(target and delegate_ts + 1e-6 >= since)

        if role == "explorer":
            return (
                _rows_hit(bb.get("research_notes", []), actor="explorer")
                or _rows_hit(bb.get("execution_logs", []), actor="explorer")
            )

        if role == "developer":
            artifacts = bb.get("code_artifacts", {}) if isinstance(bb.get("code_artifacts"), dict) else {}
            for item in artifacts.values():
                if not isinstance(item, dict):
                    continue
                if str(item.get("last_actor", "") or "").strip().lower() != "developer":
                    continue
                try:
                    updated_at = float(item.get("updated_at", 0.0) or 0.0)
                except Exception:
                    updated_at = 0.0
                if updated_at + 1e-6 >= since:
                    return True
            return _rows_hit(bb.get("execution_logs", []), actor="developer")

        approval = bb.get("approval", {}) if isinstance(bb.get("approval"), dict) else {}
        if bool(approval.get("approved", False)):
            try:
                approval_ts = float(approval.get("ts", 0.0) or 0.0)
            except Exception:
                approval_ts = 0.0
            if approval_ts + 1e-6 >= since:
                return True
        return (
            _rows_hit(bb.get("review_feedback", []), actor="reviewer")
            or _rows_hit(bb.get("execution_logs", []), actor="reviewer")
        )

    def _todo_owner_rows_from_blackboard(self, board: dict | None = None) -> list[dict]:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        profile = self._ensure_blackboard_task_profile(bb)
        approval = bb.get("approval", {}) if isinstance(bb.get("approval"), dict) else {}
        approved = bool(approval.get("approved", False))
        task_type = str(profile.get("task_type", "general") or "general")
        mode = normalize_execution_mode(
            profile.get("execution_mode", self._effective_execution_mode()),
            default=self._effective_execution_mode(),
        )
        assigned = self._sanitize_agent_role(profile.get("assigned_expert", self.runtime_assigned_expert)) or "developer"
        participants: list[str] = []
        raw_participants = profile.get("participants", self.runtime_participants)
        if isinstance(raw_participants, list):
            for item in raw_participants:
                role = self._sanitize_agent_role(item)
                if role and role not in participants:
                    participants.append(role)
        if mode == EXECUTION_MODE_SINGLE:
            participants = [assigned]
        if not participants:
            participants = [assigned]
        owners = ["manager"] + [role for role in participants if role not in {"manager"}]
        owners_unique: list[str] = []
        for owner in owners:
            if owner and owner not in owners_unique:
                owners_unique.append(owner)
        owners = owners_unique

        anchor_id, anchor_ts, delegate = self._todo_node_anchor(bb)
        delegate_target = self._sanitize_agent_role(delegate.get("target", ""))
        objective = trim(str(profile.get("direct_objective", "") or "").strip(), 220)
        instruction = trim(str(delegate.get("instruction", "") or "").strip(), 220)
        node_topic = objective or instruction or trim(str(bb.get("original_goal", "") or "").strip(), 220)

        def _owner_desc(owner: str) -> str:
            if owner == "manager":
                if delegate_target:
                    return self._ui_text(
                        "node_desc_manager_active",
                        target=self._agent_display_name(delegate_target),
                    )
                return self._ui_text("node_desc_manager")
            if owner == "explorer":
                if delegate_target == "explorer":
                    return self._ui_text("node_desc_explorer_active")
                return self._ui_text("node_desc_explorer")
            if owner == "developer":
                if delegate_target == "developer":
                    return self._ui_text("node_desc_developer_active")
                return self._ui_text("node_desc_developer")
            if owner == "reviewer":
                if delegate_target == "reviewer":
                    return self._ui_text("node_desc_reviewer_active")
                return self._ui_text("node_desc_reviewer")
            return self._ui_text("node_desc_generic")

        finish_ok, _ = self._can_auto_finish_from_approval(bb)
        rows: list[dict] = []
        for owner in owners:
            key = f"bb:node:{anchor_id}:owner:{owner}"
            desc = _owner_desc(owner)
            label = self._todo_owner_display_name(owner)
            content = f"[{label}] {desc}"
            if finish_ok and approved:
                done = True
            elif owner == "manager":
                done = bool(delegate_target) and anchor_ts > 0.0
            else:
                done = self._todo_owner_has_node_evidence(owner, anchor_ts, bb)
            if task_type == "simple_qa" and owner == "reviewer" and (not done):
                done = self._todo_owner_has_node_evidence("developer", anchor_ts, bb)
            row_status = "completed" if bool(done) else "pending"
            rows.append(
                {
                    "key": key,
                    "owner": owner,
                    "content": content,
                    "status": row_status,
                    "activeForm": f"Pending ({label}): {desc}",
                }
            )

        focus = self._todo_stage_focus_owner(bb)
        if focus and focus not in owners:
            focus = ""
        if focus:
            for row in rows:
                if str(row.get("owner", "") or "").strip().lower() == focus and row.get("status") != "completed":
                    row["status"] = "in_progress"
                    break
        if not any(str(x.get("status", "")) == "in_progress" for x in rows):
            for row in rows:
                if row.get("status") == "pending":
                    row["status"] = "in_progress"
                    break

        for row in rows:
            owner = str(row.get("owner", "") or "")
            label = self._todo_owner_display_name(owner)
            text = str(row.get("content", "") or "")
            text = re.sub(r"^\[[^\]]+\]\s*", "", text).strip() or text
            status_value = str(row.get("status", "pending") or "pending")
            topic_suffix = ""
            if node_topic and status_value == "in_progress":
                topic_suffix = self._ui_text("todo_node_suffix", topic=trim(node_topic, 140))
            if status_value == "in_progress":
                row["activeForm"] = self._ui_text(
                    "todo_working_owner",
                    owner=label,
                    content=f"{text}{topic_suffix}",
                )
            elif status_value == "completed":
                row["activeForm"] = self._ui_text("todo_completed_owner", owner=label, content=text)
            else:
                row["activeForm"] = self._ui_text("todo_pending_owner", owner=label, content=text)
        return rows

    # --- Project-level todo generation and status tracking ---

    def _generate_project_todos_from_profile(self, board: dict | None = None) -> list[dict]:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        profile = self._ensure_blackboard_task_profile(bb)
        task_type = str(profile.get("task_type", "general") or "general")
        objective = trim(str(profile.get("direct_objective", "") or ""), 200)

        if task_type == "simple_qa":
            return [
                {
                    "content": self._ui_text("project_answer_objective", objective=objective)
                    if objective
                    else self._ui_text("project_answer_default"),
                    "category": "implement",
                }
            ]

        if task_type in ("simple_code", "engineering"):
            return [
                {"content": self._ui_text("project_analyze_requirements"), "category": "setup"},
                {
                    "content": self._ui_text("project_implement_objective", objective=objective)
                    if objective
                    else self._ui_text("project_implement_default"),
                    "category": "implement",
                },
                {"content": self._ui_text("project_compile_check"), "category": "compile_test"},
                {"content": self._ui_text("project_min_test"), "category": "min_test"},
            ]

        if task_type == "research":
            return [
                {
                    "content": self._ui_text("project_research_objective", objective=objective)
                    if objective
                    else self._ui_text("project_research_default"),
                    "category": "implement",
                },
                {"content": self._ui_text("project_research_summary"), "category": "review"},
            ]

        return [
            {
                "content": self._ui_text("project_execute_objective", objective=objective)
                if objective
                else self._ui_text("project_execute_default"),
                "category": "implement",
            }
        ]

    def _init_project_todos(self, board: dict | None = None):
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        if bb.get("project_todos"):
            return
        # When an approved plan already exists, derive project todos from plan steps first.
        plan = bb.get("plan", {})
        if isinstance(plan, dict) and plan.get("phase") == "executing" and plan.get("steps"):
            plan_todos = self._build_plan_todos_from_steps(plan.get("steps", []), limit=40)
            if plan_todos:
                bb["project_todos"] = plan_todos
                bb["plan_step_cursor"] = 0
                bb["plan_step_total"] = len(plan_todos)
                self.blackboard = bb
                self._blackboard_touch()
                return
        raw = self._generate_project_todos_from_profile(bb)
        bb["project_todos"] = [
            {
                "id": f"pt:{i:03d}",
                "content": t["content"],
                "status": "pending",
                "category": t["category"],
                "created_at": float(now_ts()),
                "completed_at": None,
                "completed_by": "",
                "evidence": "",
            }
            for i, t in enumerate(raw)
        ]
        self.blackboard = bb
        self._blackboard_touch()

    def _bootstrap_sync_plan_steps_if_needed(self, board: dict | None = None, *, reason: str = "") -> bool:
        # Do not synthesize project plan steps for ordinary sync/multi-agent runs.
        # Runtime-generated generic steps such as "Clarify / Produce / Review"
        # create a second authority beside the model's own task reasoning and
        # have repeatedly caused workers to optimize for bookkeeping instead of
        # the user's concrete deliverable. Approved user/plan-mode plans are
        # still represented through _build_plan_todos_from_steps().
        return False
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        profile = self._ensure_blackboard_task_profile(bb)
        mode = normalize_execution_mode(
            profile.get("execution_mode", self._effective_execution_mode()),
            default=self._effective_execution_mode(),
        )
        if mode != EXECUTION_MODE_SYNC:
            return False
        complexity = normalize_task_complexity(profile.get("complexity", "simple"), default="simple")
        if not task_complexity_at_least(complexity, "moderate"):
            return False
        todos = bb.get("project_todos", []) if isinstance(bb.get("project_todos"), list) else []
        if any(isinstance(row, dict) and str(row.get("category", "") or "") == "plan_step" for row in todos):
            return False
        plan = bb.get("plan", {}) if isinstance(bb.get("plan"), dict) else {}
        if str(plan.get("phase", "") or "").strip().lower() == "executing" and plan.get("steps"):
            return False
        objective = trim(
            str(profile.get("direct_objective", "") or bb.get("original_goal", "") or "").strip(),
            300,
        )
        task_type = str(profile.get("task_type", "general") or "general").strip().lower()
        raw = self._generate_project_todos_from_profile(bb)
        raw_items = [
            trim(str(item.get("content", "") or "").strip(), 260)
            for item in raw
            if isinstance(item, dict) and str(item.get("content", "") or "").strip()
        ]
        if len(raw_items) <= 1:
            if task_type == "research":
                raw_items = [
                    f"Gather and organize evidence for: {objective or 'the request'}",
                    "Synthesize findings into the requested format",
                    "Review coverage and fill any missing points",
                ]
            elif task_type in {"simple_code", "engineering"}:
                raw_items = [
                    f"Inspect relevant files and constraints for: {objective or 'the change'}",
                    "Implement the requested change with concrete file edits",
                    "Run focused validation and fix any failures",
                    "Summarize changed files and remaining risks",
                ]
            else:
                raw_items = [
                    f"Clarify deliverable shape and reusable context for: {objective or 'the request'}",
                    "Produce the requested deliverable with concrete tool output",
                    "Review the result against the latest user request and revise if needed",
                ]
        now_value = float(now_ts())
        plan_rows = []
        for idx, item in enumerate(raw_items[:5]):
            text = trim(str(item or "").strip(), 320)
            if not text:
                continue
            plan_rows.append(
                {
                    "id": f"sync:{idx:03d}",
                    "content": f"{idx + 1}. {text}",
                    "full_content": text,
                    "status": "in_progress" if idx == 0 else "pending",
                    "category": "plan_step",
                    "owner": "manager",
                    "plan_step_index": idx,
                    "created_at": now_value,
                    "activated_at": now_value if idx == 0 else None,
                    "completed_at": None,
                    "completed_by": "",
                    "evidence": "",
                    "source": "sync-bootstrap",
                }
            )
        if not plan_rows:
            return False
        other_rows = [
            row for row in todos
            if isinstance(row, dict) and str(row.get("category", "") or "") != "plan_step"
        ]
        bb["project_todos"] = plan_rows + other_rows
        bb["plan_step_cursor"] = 0
        bb["plan_step_total"] = len(plan_rows)
        bb["plan"] = {
            "phase": "executing",
            "source": "sync-bootstrap",
            "steps": [str(row.get("full_content", "") or row.get("content", "")) for row in plan_rows],
        }
        bb["focus"] = self._blackboard_focus_identity(bb)
        self.blackboard = bb
        self._blackboard_touch()
        self._sync_todos_from_blackboard(reason=reason or "sync-bootstrap-plan-steps", board=bb)
        self._append_manager_context(
            {
                "role": "system",
                "content": (
                    "[sync-bootstrap] Runtime created internal plan-step todos for this sync task. "
                    "Delegate the active step only and require workers to update TodoWrite before finishing."
                ),
                "ts": now_ts(),
                "agent_role": "manager",
            }
        )
        self._emit(
            "status",
            {
                "summary": (
                    "sync task todos bootstrapped "
                    f"(steps={len(plan_rows)}, reason={trim(str(reason or 'sync-bootstrap'), 80)})"
                )
            },
        )
        return True

    def _has_compile_pass_evidence(self, board: dict | None = None) -> bool:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        logs = bb.get("execution_logs", []) if isinstance(bb.get("execution_logs"), list) else []
        if not logs:
            return False
        positive = ("compiled successfully", "build successful", "0 error", "编译成功",
                     "syntax ok", "no errors", "build succeeded", "compilation successful")
        negative = ("error:", "fatal error", "syntax error", "compile error", "build failed")
        for entry in reversed(logs[-6:]):
            txt = str((entry or {}).get("content", "") or "").lower() if isinstance(entry, dict) else str(entry or "").lower()
            if not txt:
                continue
            if any(neg in txt for neg in negative):
                continue
            if any(pos in txt for pos in positive):
                return True
        return False

    def _tool_result_output_excerpt(self, item: dict, max_chars: int = 160) -> str:
        if not isinstance(item, dict):
            return ""
        raw = trim(str(item.get("output", "") or "").strip(), max_chars * 2)
        if not raw:
            return ""
        clean, _ = filter_runtime_noise_lines(raw)
        text = trim(clean.replace("\r\n", "\n"), max_chars * 2)
        if not text:
            return ""
        lines = [ln.strip() for ln in text.split("\n") if ln.strip()]
        if not lines:
            return ""
        return trim(lines[0], max_chars)

    def _tool_result_has_positive_retrieval_signal(self, item: dict) -> bool:
        if not isinstance(item, dict) or not item.get("ok", False):
            return False
        if str(item.get("name", "") or "") not in {"query_code_library", "query_knowledge_library", "agent_web_search"}:
            return False
        raw = str(item.get("output", "") or "")
        low = raw.lower()
        if not raw.strip():
            return False
        negative_markers = (
            "evidence_status=miss",
            "results=0",
            "documents=0",
            "chunks=0",
            "暂无足够证据",
            "no results",
            "not found",
            "timed out",
            "url_error",
            "network",
        )
        if any(marker in low for marker in negative_markers):
            return False
        if re.search(r"\bresults\s*=\s*[1-9]\d*\b", low):
            return True
        if re.search(r"\bconfidence\s*=\s*(?:0\.[1-9]\d*|[1-9]\d*(?:\.\d+)?)\b", low):
            return True
        return len(raw.strip()) >= 120

    def _plan_text_file_content_subject(self, text: object) -> bool:
        low = str(text or "").lower()
        return any(
            tok in low
            for tok in (
                "文件", "目录", "路径", "文档", "正文", "大纲", "章节", "字数", "标题", "段落",
                "内容", "清单", "列表", "表格", "报告", "稿", "设定", "角色", "markdown",
                ".md", ".txt", ".csv", ".json", ".yaml", ".yml", ".toml", ".ini",
                "file", "directory", "path", "document", "chapter", "outline", "content",
                "word count", "title", "section", "report", "ファイル", "ディレクトリ",
            )
        )

    def _plan_text_runtime_subject(self, text: object) -> bool:
        low = str(text or "").lower()
        return any(
            tok in low
            for tok in (
                "代码", "前端", "后端", "组件", "接口", "服务", "程序", "模块", "函数", "类",
                "依赖", "编译", "构建", "测试", "浏览器", "控制台", "webgl", "shader",
                "api", "ui", "web", "app", "service", "script", "package", "dependency",
                "npm", "node", "python", "pytest", "ruff", "unit", "integration", "server",
                ".py", ".js", ".ts", ".tsx", ".jsx", ".css", ".html", ".go", ".rs", ".java",
                ".cpp", ".c", ".h", ".hpp", ".f90", ".glsl",
            )
        )

    def _plan_text_explicit_runtime_check(self, text: object) -> bool:
        low = str(text or "").lower()
        return any(
            tok in low
            for tok in (
                "测试", "測試", "构建", "编译", "运行测试", "运行构建", "启动服务", "浏览器检查",
                "控制台", "http", "200", "pytest", "test", "build", "compile", "playwright",
                "browser", "server", "curl", "node --check", "npm run", "ruff",
            )
        )

    def _plan_text_prefers_file_content_evidence(self, text: object) -> bool:
        return self._plan_text_file_content_subject(text) and not (
            self._plan_text_runtime_subject(text) or self._plan_text_explicit_runtime_check(text)
        )

    def _tool_results_have_validation_evidence(self, plan_step: dict, results: list[dict]) -> bool:
        """Return whether current tool output is useful candidate evidence.

        This is intentionally not an acceptance decision. Plan-step completion is
        decided by accumulated evidence, optional semantic audit, and any explicit human block.
        """
        if not isinstance(plan_step, dict):
            return False
        rows = [r for r in (results or []) if isinstance(r, dict) and r.get("ok", False)]
        if not rows:
            return False
        step_text = str(plan_step.get("full_content", "") or plan_step.get("content", "") or "").lower()
        phase = self._plan_step_phase_hint(step_text)
        wrote_files = any(str(r.get("name", "")) in ("write_file", "edit_file") for r in rows)
        read_back = any(
            str(r.get("name", "")) == "read_file"
            and not self._is_plan_infrastructure_read_result(r)
            and bool(self._tool_result_output_excerpt(r, 140))
            for r in rows
        )
        positive_retrieval_signal = any(self._tool_result_has_positive_retrieval_signal(r) for r in rows)
        blackboard_write_signal = any(
            str(r.get("name", "")) == "write_to_blackboard"
            for r in rows
        )
        blackboard_read_signal = any(str(r.get("name", "")) == "read_from_blackboard" for r in rows)
        bash_rows = [r for r in rows if str(r.get("name", "")) == "bash"]
        observed_signal = False
        compile_signal = False
        test_signal = False
        negative_hints = ("error:", "failed", "failure", "traceback", "fatal error", "assertionerror", "exception")
        compile_hints = ("compiled successfully", "build successful", "build succeeded", "syntax ok", "lint passed", "no issues found", "0 errors")
        test_hints = (
            "test passed", "tests passed", "all tests passed", "0 failed", "100%", "ok", "success",
            "http 200", "200 ok", "node --check", "syntax ok", "selftest", "playwright", "screenshot",
            "dom", "canvas", "browser", "页面正常", "验证通过",
        )
        validation_cmd_tokens = ("pytest", "test", "unittest", "jest", "vitest", "cargo test", "go test", "build", "compile", "lint", "run")
        for row in bash_rows:
            cmd = str(row.get("args", {}).get("command", "") or "").strip().lower()
            raw_output = str(row.get("output", "") or "")
            clean_output, _ = filter_runtime_noise_lines(raw_output)
            excerpt = self._tool_result_output_excerpt(row, 180)
            low = trim((clean_output or excerpt).lower(), 4000)
            cmd_is_validation = self._command_looks_like_validation(cmd) or any(tok in cmd for tok in validation_cmd_tokens)
            output_has_positive = bool(low) and (
                any(tok in low for tok in compile_hints)
                or any(tok in low for tok in test_hints)
                or bool(re.search(r"\b(?:http\s*)?200\b", low))
                or bool(re.search(r"\bexit\s*[:=]\s*0\b", low))
            )
            if (cmd_is_validation or output_has_positive) and low and not any(neg in low for neg in negative_hints):
                observed_signal = True
            if low and any(tok in low for tok in compile_hints) and not any(neg in low for neg in negative_hints):
                compile_signal = True
            if low and any(tok in low for tok in test_hints) and not any(neg in low for neg in negative_hints):
                test_signal = True
        wants_test = phase in ("test", "review") or any(
            tok in step_text for tok in ("test", "pytest", "unit", "integration", "验证", "測試", "测试", "回归", "assert")
        )
        wants_runtime_validation = wants_test or phase == "implement" or any(
            tok in step_text for tok in ("verify", "validation", "check", "lint", "build", "compile", "运行", "校验", "檢查")
        )
        if self._plan_text_prefers_file_content_evidence(step_text):
            wants_test = False
            wants_runtime_validation = False
        if wants_test:
            return test_signal or (bool(bash_rows) and observed_signal)
        if phase == "implement":
            if self._plan_text_prefers_file_content_evidence(step_text):
                return wrote_files or read_back or blackboard_write_signal or observed_signal
            return wrote_files and (compile_signal or test_signal or observed_signal)
        if phase in ("research", "design"):
            return wrote_files or read_back or positive_retrieval_signal or blackboard_write_signal or observed_signal
        if wants_runtime_validation:
            return observed_signal or read_back or positive_retrieval_signal or blackboard_write_signal
        return wrote_files or read_back or positive_retrieval_signal or blackboard_write_signal or blackboard_read_signal or observed_signal

    def _plan_step_activation_ts(self, plan_step: dict) -> float:
        if not isinstance(plan_step, dict):
            return 0.0
        try:
            activated = float(plan_step.get("activated_at", 0.0) or 0.0)
        except Exception:
            activated = 0.0
        if activated > 0:
            return activated
        try:
            return float(plan_step.get("created_at", 0.0) or 0.0)
        except Exception:
            return 0.0

    def _plan_step_blackboard_signals(
        self,
        plan_step: dict,
        board: dict | None = None,
        *,
        since_ts_override: float | None = None,
    ) -> dict:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        step_id = trim(str((plan_step or {}).get("id", "") or ""), 20)
        since_ts = self._plan_step_activation_ts(plan_step)
        if since_ts_override is not None:
            try:
                override_ts = float(since_ts_override or 0.0)
            except Exception:
                override_ts = 0.0
            if override_ts > 0:
                since_ts = max(float(since_ts or 0.0), override_ts)

        def _rows_since(rows: object) -> list[dict]:
            out: list[dict] = []
            if not isinstance(rows, list):
                return out
            for row in rows:
                if not isinstance(row, dict):
                    continue
                txt = trim(str(row.get("content", "") or "").strip(), 1200)
                if not txt:
                    continue
                txt_low = txt.lower()
                if PLAN_FILE_RELATIVE_PATH in txt_low or ".clouds_coder\\plan.md" in txt_low:
                    continue
                row_step = str(row.get("plan_step_id", "") or "").strip()
                if step_id and row_step and row_step != step_id:
                    continue
                try:
                    ts = float(row.get("ts", 0.0) or 0.0)
                except Exception:
                    ts = 0.0
                if since_ts > 0 and ts > 0 and ts + 1e-6 < since_ts:
                    continue
                out.append({"ts": ts, "content": txt, "actor": trim(str(row.get("actor", "") or ""), 40)})
            return out

        def _recent_excerpt(rows: list[dict], max_chars: int = 120) -> str:
            if not rows:
                return ""
            return trim(str(rows[-1].get("content", "") or "").replace("\r\n", "\n"), max_chars)

        negative_hints = ("error:", "failed", "failure", "traceback", "fatal error", "assertionerror", "exception")
        compile_hints = ("compiled successfully", "build successful", "build succeeded", "syntax ok", "lint passed", "no issues found", "0 errors", "编译成功")
        test_hints = ("test passed", "tests passed", "all tests passed", "0 failed", "100%", "ok", "success", "测试通过")

        step_files_raw = bb.get("step_files", {}) if isinstance(bb.get("step_files"), dict) else {}
        step_entries = step_files_raw.get(step_id, []) if step_id and isinstance(step_files_raw.get(step_id), list) else []
        filtered_entries: list[dict] = []
        for entry in step_entries:
            if not isinstance(entry, dict):
                continue
            if self._is_plan_infrastructure_path(entry.get("path", "")):
                continue
            try:
                ts = float(entry.get("ts", 0.0) or 0.0)
            except Exception:
                ts = 0.0
            if since_ts > 0 and ts > 0 and ts + 1e-6 < since_ts:
                continue
            filtered_entries.append(entry)
        step_entries = filtered_entries

        artifact_rows: list[dict] = []
        raw_artifacts = bb.get("code_artifacts", {}) if isinstance(bb.get("code_artifacts"), dict) else {}
        for path, meta in raw_artifacts.items():
            if not isinstance(meta, dict):
                continue
            if self._is_plan_infrastructure_path(path):
                continue
            meta_step = str(meta.get("plan_step_id", "") or "").strip()
            if step_id and meta_step and meta_step != step_id:
                continue
            try:
                ts = float(meta.get("updated_at", 0.0) or 0.0)
            except Exception:
                ts = 0.0
            if since_ts > 0 and ts > 0 and ts + 1e-6 < since_ts:
                continue
            artifact_rows.append({
                "path": trim(str(path or "").strip(), 240),
                "summary": trim(str(meta.get("summary", "") or "").strip(), 200),
                "updated_at": ts,
            })

        research_rows = _rows_since(bb.get("research_notes", []))
        exec_rows = _rows_since(bb.get("execution_logs", []))
        review_rows = _rows_since(bb.get("review_feedback", []))

        file_ops = {
            trim(str(entry.get("op", "") or "").strip(), 40)
            for entry in step_entries
            if isinstance(entry, dict)
        }
        has_write = any(op in {"write_file", "edit_file"} for op in file_ops) or bool(artifact_rows)
        has_read = "read_file" in file_ops

        def _has_positive(rows: list[dict], hints: tuple[str, ...]) -> bool:
            for row in reversed(rows[-6:]):
                low = str(row.get("content", "") or "").lower()
                if not low or any(neg in low for neg in negative_hints):
                    continue
                if any(tok in low for tok in hints):
                    return True
            return False

        def _has_observed(rows: list[dict]) -> bool:
            for row in reversed(rows[-6:]):
                low = str(row.get("content", "") or "").lower()
                if not low or any(neg in low for neg in negative_hints):
                    continue
                if self._execution_log_count_search_zero_ok(row):
                    return True
                if (
                    self._command_looks_like_validation(low)
                    or any(tok in low for tok in compile_hints)
                    or any(tok in low for tok in test_hints)
                    or re.search(r"\b(?:http\s*)?200\b", low)
                    or re.search(r"\bexit\s*[:=]\s*0\b", low)
                ):
                    return True
            return False

        recent_files = [row.get("path", "") for row in artifact_rows[-4:] if row.get("path")]
        if not recent_files:
            recent_files = [
                trim(str(entry.get("path", "") or "").strip(), 240)
                for entry in step_entries[-4:]
                if isinstance(entry, dict) and str(entry.get("path", "") or "").strip()
            ]

        return {
            "since_ts": since_ts,
            "has_write": has_write,
            "has_read": has_read,
            "has_research": bool(research_rows),
            "has_exec": _has_observed(exec_rows),
            "has_review": _has_observed(review_rows),
            "has_compile_pass": _has_positive(exec_rows + review_rows, compile_hints),
            "has_test_pass": _has_positive(exec_rows + review_rows, test_hints),
            "recent_files": list(dict.fromkeys(recent_files))[-4:],
            "recent_exec_excerpt": _recent_excerpt(exec_rows, 140),
            "recent_review_excerpt": _recent_excerpt(review_rows, 140),
            "recent_research_excerpt": _recent_excerpt(research_rows, 140),
        }

    def _plan_step_has_blackboard_evidence(self, plan_step: dict, board: dict | None = None) -> bool:
        """Return whether blackboard history has candidate evidence for review."""
        if not isinstance(plan_step, dict):
            return False
        sig = self._plan_step_blackboard_signals(plan_step, board)
        step_text = str(plan_step.get("full_content", "") or plan_step.get("content", "") or "").lower()
        phase = self._plan_step_phase_hint(step_text)
        wants_test = phase in ("test", "review") or any(
            tok in step_text for tok in ("test", "pytest", "unit", "integration", "验证", "測試", "测试", "回归", "assert")
        )
        wants_runtime_validation = wants_test or phase == "implement" or any(
            tok in step_text for tok in ("verify", "validation", "check", "lint", "build", "compile", "运行", "校验", "檢查")
        )
        if self._plan_text_prefers_file_content_evidence(step_text):
            wants_test = False
            wants_runtime_validation = False
        if wants_test:
            return sig["has_test_pass"] or sig["has_exec"] or sig["has_review"]
        if phase == "implement":
            if self._plan_text_prefers_file_content_evidence(step_text):
                return sig["has_write"] or sig["has_read"] or sig["has_exec"] or sig["has_review"]
            return sig["has_write"] and (
                sig["has_compile_pass"] or sig["has_test_pass"] or sig["has_exec"] or sig["has_review"]
            )
        if phase in ("research", "design"):
            return sig["has_research"] or sig["has_read"] or sig["has_exec"] or sig["has_write"]
        if wants_runtime_validation:
            return sig["has_exec"] or sig["has_read"] or sig["has_review"]
        return sig["has_write"] or sig["has_read"] or sig["has_research"] or sig["has_exec"] or sig["has_review"]

    # Metric families whose numeric threshold is a genuine QUALITY bar (not an
    # index/version/count). Used by _extract_acceptance_target.
    _ACCEPTANCE_METRIC_TERMS = (
        "误差", "相对误差", "绝对误差", "偏差", "error", "rel_err", "relative error",
        "abs error", "absolute error", "deviation", "residual", "残差",
        "coverage", "覆盖率", "覆盖", "accuracy", "准确率", "準確率", "精度", "精确度",
        "precision", "recall", "f1", "tolerance", "容差", "误差率", "错误率", "loss",
        "rmse", "mae", "mse", "perplexity", "困惑度",
    )

    def _acceptance_target_source_text(self, plan_step: dict, acceptance_row: dict | None = None) -> str:
        parts = [
            str((plan_step or {}).get("full_content", "") or (plan_step or {}).get("content", "") or ""),
        ]
        if isinstance(acceptance_row, dict):
            parts.append(str(acceptance_row.get("content", "") or ""))
        return "\n".join(p for p in parts if p)

    @staticmethod
    def _numeric_equivalent(raw: str, target: float) -> bool:
        try:
            value = float(str(raw or "").strip())
        except Exception:
            return False
        scale = max(1.0, abs(float(target)))
        return abs(value - float(target)) <= max(1e-9, scale * 1e-9)

    def _acceptance_text_has_explicit_target(self, target: dict, text: str) -> bool:
        if not isinstance(target, dict) or not str(text or "").strip():
            return False
        try:
            value = float(target.get("value"))
        except Exception:
            return False
        metric = str(target.get("metric", "") or "").strip().lower()
        metric_terms = [metric] if metric else []
        metric_terms.extend(str(term).lower() for term in self._ACCEPTANCE_METRIC_TERMS)
        metric_terms = [term for term in dict.fromkeys(metric_terms) if term]
        comparison_terms = (
            "<=", ">=", "<", ">", "≤", "≥", "below", "under", "less than", "at most",
            "no more than", "above", "greater than", "at least", "不超过", "不高于",
            "至多", "至少", "不低于", "大于", "小于", "超过", "高于", "低于",
            "以内", "以下", "以上", "阈值", "门限", "质量线", "tolerance", "threshold",
        )
        ordinal_terms = (
            "step", "subtask", "task", "todo", "chapter", "section", "item",
            "步骤", "子任务", "任务", "编号", "第", "章", "节", "小节",
        )
        src = str(text or "")
        for match in re.finditer(r"(?<![\d.])(\d+(?:\.\d+)?)(?![\d.])", src):
            if not self._numeric_equivalent(match.group(1), value):
                continue
            line_start = src.rfind("\n", 0, match.start()) + 1
            line_end = src.find("\n", match.end())
            if line_end < 0:
                line_end = len(src)
            line = src[line_start:line_end]
            line_low = line.lower()
            prefix = src[line_start:match.start()]
            # List labels such as "9.2 xxx", "9.2) xxx", or "Step 9.2" are
            # ordinals, not thresholds. They must not become quality bars.
            if re.match(r"^\s*(?:[-*•]\s*)?\d+(?:\.\d+)+[.)、:\s-]*", line):
                if not any(term in line_low for term in comparison_terms):
                    continue
            if any(term in prefix.lower()[-24:] for term in ordinal_terms):
                if not any(term in line_low for term in comparison_terms):
                    continue
            context = src[max(0, match.start() - 80): min(len(src), match.end() + 80)].lower()
            if not any(term in context for term in metric_terms):
                continue
            if not any(term in context for term in comparison_terms):
                continue
            return True
        return False

    def _acceptance_target_candidate_valid(
        self,
        target: dict,
        plan_step: dict,
        acceptance_row: dict | None = None,
    ) -> bool:
        if not isinstance(target, dict) or target.get("kind") != "numeric":
            return False
        op = str(target.get("op", "") or "").strip()
        if op not in ("<", "<=", ">", ">=", "=="):
            return False
        metric = str(target.get("metric", "") or "").strip().lower()
        if not metric or metric == "target":
            return False
        try:
            float(target.get("value"))
        except Exception:
            return False
        text = self._acceptance_target_source_text(plan_step, acceptance_row)
        return self._acceptance_text_has_explicit_target(target, text)

    def _resolve_acceptance_target(self, plan_step: dict, acceptance_row: dict | None = None) -> dict:
        """Resolve the step's measurable QUALITY bar, LLM-primary with a regex
        fallback (Fix 5). Cached per step id — the bar is a property of the step
        and does not change round to round, so this costs at most one LLM call
        per step, off the hot path.

        Returns {kind:"numeric", metric, op, value, unit, desc, source} or {}.
        The model PERCEIVES whether the step has a measurable bar (self-awareness)
        rather than relying only on hardcoded metric keywords; regex is the
        deterministic safety net when the LLM is unavailable or unsure."""
        step_id = str((plan_step or {}).get("id", "") or "")
        cache = getattr(self, "_acceptance_target_cache", None)
        if cache is None:
            cache = {}
            self._acceptance_target_cache = cache
        if step_id and step_id in cache:
            cached = dict(cache[step_id])
            if cached and not self._acceptance_target_candidate_valid(cached, plan_step, acceptance_row):
                cache.pop(step_id, None)
                return {}
            return cached
        llm = self._llm_acceptance_target(plan_step, acceptance_row)
        resolved = llm if llm else self._extract_acceptance_target(plan_step, acceptance_row)
        if resolved and not self._acceptance_target_candidate_valid(resolved, plan_step, acceptance_row):
            resolved = {}
        if resolved and not resolved.get("source"):
            resolved["source"] = "llm" if llm else "regex"
        if step_id:
            cache[step_id] = dict(resolved)
        return dict(resolved)

    def _llm_acceptance_target(self, plan_step: dict, acceptance_row: dict | None = None) -> dict:
        """LLM-primary perception of a measurable quality bar in the step text.
        Returns a numeric-target dict or {} (no bar / unavailable / low
        confidence → caller falls back to regex then category-only)."""
        text = trim(self._acceptance_target_source_text(plan_step, acceptance_row), 900)
        if not text.strip():
            return {}
        try:
            prompt = (
                "/no_think\n"
                "Read this plan step + its acceptance check. Does it state a MEASURABLE numeric quality bar "
                "that a result must satisfy (e.g. error < 2%, coverage >= 90%, accuracy >= 0.95, latency < 100ms, "
                "exit code 0)? A plain count/index/version/list label/subtask number (like 'chapter 20', "
                "'write 5 files', 'python 3.11', 'Step 9.2', '子任务 9.2') is NOT a quality bar. "
                "Only return has_bar=true when the text explicitly contains the metric, comparison, and value.\n\n"
                f"STEP:\n{text}\n\n"
                "Reply ONLY JSON. If there IS a measurable numeric bar:\n"
                '{\"has_bar\": true, \"metric\": \"<what is measured, e.g. relative error>\", '
                '\"op\": \"<|<=|>|>=|==\", \"value\": <number>, \"unit\": \"<% or empty>\", '
                '\"quote\": \"<the exact source phrase containing metric+comparison+value>\"}\n'
                "If there is NO measurable numeric bar: {\"has_bar\": false}"
            )
            resp = self.ollama.chat(
                [{"role": "user", "content": prompt}],
                system="/no_think\nDetect a measurable numeric quality bar in a task step. Reply ONLY valid JSON.",
                max_tokens=120,
                think=False,
            )
            import json
            raw = str(resp.get("content", "") or resp.get("text", "") or "").strip()
            if "{" not in raw or "}" not in raw:
                return {}
            data = json.loads(raw[raw.index("{"):raw.rindex("}") + 1])
            if not isinstance(data, dict) or not bool(data.get("has_bar", False)):
                return {}
            op = str(data.get("op", "") or "").strip()
            if op not in ("<", "<=", ">", ">=", "=="):
                return {}
            try:
                value = float(data.get("value"))
            except Exception:
                return {}
            unit = str(data.get("unit", "") or "").strip()
            return {
                "kind": "numeric",
                "metric": trim(str(data.get("metric", "") or "").strip().lower(), 60) or "target",
                "op": op,
                "value": value,
                "unit": "%" if "%" in unit or "percent" in unit.lower() else "",
                "desc": trim(text, 120),
                "raw": trim(str(data.get("quote", "") or "").strip(), 120),
                "source": "llm",
            }
        except Exception:
            return {}

    def _extract_acceptance_target(self, plan_step: dict, acceptance_row: dict | None = None) -> dict:
        """Regex FALLBACK for _resolve_acceptance_target (Fix 5). Extracts an
        explicit numeric QUALITY target from the step + acceptance text when the
        LLM layer is unavailable. Returns {kind:"numeric", metric, op, value,
        unit, raw} or {}.

        Only matches a comparison operator adjacent to a known quality-metric
        term (误差/error/coverage/accuracy/tolerance/…) so plain counts, indices,
        and version numbers are NOT mistaken for a quality bar."""
        parts = [
            str((plan_step or {}).get("full_content", "") or (plan_step or {}).get("content", "") or ""),
        ]
        if isinstance(acceptance_row, dict):
            parts.append(str(acceptance_row.get("content", "") or ""))
        text = "\n".join(p for p in parts if p)
        if not text.strip():
            return {}
        low = text.lower()
        metric_alt = "|".join(re.escape(t) for t in self._ACCEPTANCE_METRIC_TERMS)
        best: dict = {}
        # metric ... op value   (e.g. "误差 < 2%", "error below 1%", "coverage > 90%")
        pat_fwd = re.compile(
            r"(" + metric_alt + r")\s*(?:[:：=]?\s*)?(<=|>=|<|>|≤|≥|below|under|less than|at most|no more than|不超过|不高于|至多|至少|不低于|大于|小于|超过|高于|低于)?\s*(\d+(?:\.\d+)?)\s*(%|percent|个百分点)?",
            re.IGNORECASE,
        )
        # op value ... metric   (e.g. "< 2% 误差", "below 1% error")
        pat_bwd = re.compile(
            r"(<=|>=|<|>|≤|≥|below|under|less than|at most|no more than|至多|不超过)\s*(\d+(?:\.\d+)?)\s*(%|percent)?\s*(?:的\s*)?(" + metric_alt + r")",
            re.IGNORECASE,
        )
        word_op = {
            "不超过": "<=", "不高于": "<=", "至多": "<=", "no more than": "<=", "at most": "<=",
            "below": "<", "under": "<", "less than": "<", "小于": "<", "低于": "<",
            "大于": ">", "超过": ">", "高于": ">", "至少": ">=", "不低于": ">=",
        }
        def _norm_op(raw_op: str, metric: str) -> str:
            o = (raw_op or "").strip().lower()
            o = word_op.get(o, o)
            o = {"≤": "<=", "≥": ">="}.get(o, o)
            if o in ("<", ">", "<=", ">="):
                return o
            # No explicit operator: infer from metric semantics.
            m = metric.lower()
            if any(k in m for k in ("coverage", "覆盖", "accuracy", "准确", "準確", "精度", "精确", "precision", "recall", "f1")):
                return ">="  # higher is better
            return "<="  # error/deviation/loss/tolerance: lower is better
        for m in pat_fwd.finditer(low):
            metric, raw_op, val, unit = m.group(1), m.group(2), m.group(3), m.group(4)
            if not raw_op:
                continue
            try:
                value = float(val)
            except Exception:
                continue
            best = {
                "kind": "numeric",
                "metric": metric,
                "op": _norm_op(raw_op, metric),
                "value": value,
                "unit": "%" if unit and ("%" in unit or "percent" in unit or "百分点" in unit) else "",
                "raw": trim(m.group(0), 80),
            }
            break
        if not best:
            for m in pat_bwd.finditer(low):
                raw_op, val, unit, metric = m.group(1), m.group(2), m.group(3), m.group(4)
                try:
                    value = float(val)
                except Exception:
                    continue
                best = {
                    "kind": "numeric",
                    "metric": metric,
                    "op": _norm_op(raw_op, metric),
                    "value": value,
                    "unit": "%" if unit and ("%" in unit or "percent" in unit) else "",
                    "raw": trim(m.group(0), 80),
                }
                break
        return best

    def _acceptance_metric_terms_for_target(self, target: dict) -> list[str]:
        metric = str((target or {}).get("metric", "") or "").strip().lower()
        terms = [metric] if metric else []
        if any(term in metric for term in ("误差", "error", "err", "deviation", "residual", "rmse", "mae", "mse")):
            terms.extend(
                [
                    "误差",
                    "相对误差",
                    "绝对误差",
                    "error",
                    "err",
                    "relative error",
                    "absolute error",
                    "density_l2_error",
                    "density l2 error",
                    "l2 error",
                    "peak error",
                    "rmse",
                    "mae",
                    "residual",
                ]
            )
        if any(term in metric for term in ("coverage", "覆盖")):
            terms.extend(["coverage", "覆盖率", "覆盖"])
        if any(term in metric for term in ("accuracy", "准确", "精度", "precision", "recall", "f1")):
            terms.extend(["accuracy", "准确率", "精度", "precision", "recall", "f1"])
        if any(term in metric for term in ("loss", "损失")):
            terms.extend(["loss", "损失"])
        return [term for term in dict.fromkeys(terms) if term]

    @staticmethod
    def _target_metric_is_file_size(target: dict) -> bool:
        metric = str((target or {}).get("metric", "") or "").strip().lower()
        return any(term in metric for term in ("size", "bytes", "byte", "文件大小", "字节"))

    def _command_is_file_listing_for_acceptance(self, command: str) -> bool:
        low = str(command or "").strip().lower()
        if not low:
            return False
        try:
            tokens = shlex.split(low)
        except Exception:
            tokens = low.split()
        if not tokens:
            return False
        while tokens and re.match(r"^[a-z_][a-z0-9_]*=", tokens[0]):
            tokens = tokens[1:]
        if not tokens:
            return False
        cmd = Path(tokens[0]).name.lower()
        if cmd in {"bash", "sh", "zsh", "cmd", "powershell", "pwsh"} and any(tok in {"-c", "/c"} for tok in tokens[1:]):
            for idx, tok in enumerate(tokens[1:], start=1):
                if tok in {"-c", "/c"} and idx + 1 < len(tokens):
                    return self._command_is_file_listing_for_acceptance(tokens[idx + 1])
        return cmd in {"ls", "dir", "find", "stat", "du"} or (
            cmd == "wc" and any(tok in {"-c", "--bytes"} for tok in tokens[1:])
        )

    def _target_evidence_text_relevant(self, target: dict, command: str, text: str) -> bool:
        raw = str(text or "")
        if not raw.strip():
            return False
        low = raw.lower()
        metric_terms = self._acceptance_metric_terms_for_target(target)
        has_metric = any(term in low for term in metric_terms)
        validation_markers = (
            "acceptance_check",
            "all_pass",
            "pass_",
            "checks passed",
            "tests passed",
            "验证通过",
            "quality",
            "metric",
            "measurement",
        )
        command_low = str(command or "").lower()
        is_listing = self._command_is_file_listing_for_acceptance(command_low)
        if is_listing and not self._target_metric_is_file_size(target) and not has_metric:
            return False
        if has_metric:
            return True
        if any(marker in low for marker in validation_markers):
            return True
        if "python" in command_low and (
            "acceptance" in command_low
            or "verify" in command_low
            or "validation" in command_low
            or "check" in command_low
        ):
            return True
        return False

    def _acceptance_target_evidence_rows(self, target: dict, bb: dict, results: list[dict]) -> list[dict]:
        rows: list[dict] = []

        def _add(source: str, command: str, text: str):
            clean, _ = filter_runtime_noise_lines(str(text or ""))
            clean = trim(clean.replace("\r\n", "\n"), 2400)
            if not clean:
                return
            if not self._target_evidence_text_relevant(target, command, clean):
                return
            rows.append(
                {
                    "source": source,
                    "command": trim(str(command or ""), 500),
                    "text": clean,
                }
            )

        for row in (results or []):
            if not isinstance(row, dict):
                continue
            name = str(row.get("name", "") or "")
            if name not in {"bash", "worktree_run", "background_run"}:
                continue
            args = row.get("args", {}) if isinstance(row.get("args"), dict) else {}
            command = str(row.get("command", "") or args.get("command", "") or "")
            _add("current_tool", command, str(row.get("output", "") or ""))

        logs = bb.get("execution_logs", []) if isinstance(bb.get("execution_logs"), list) else []
        for row in logs[-10:]:
            if not isinstance(row, dict):
                continue
            content = str(row.get("content", "") or "")
            first = content.replace("\r\n", "\n").split("\n", 1)[0].strip()
            command = first.split(" ", 1)[1] if first.startswith(("bash ", "worktree_run ", "background_run ")) and " " in first else first
            _add("execution_log", command, content)

        deduped: list[dict] = []
        seen: set[str] = set()
        for row in rows:
            key = hashlib.sha1(safe_utf8_bytes(str(row.get("command", "")) + "\n" + str(row.get("text", "")))).hexdigest()[:16]
            if key in seen:
                continue
            seen.add(key)
            deduped.append(row)
        return deduped[-8:]

    def _llm_acceptance_quote_supported(
        self,
        target: dict,
        evidence_rows: list[dict],
        quote: str,
        measured: float,
    ) -> bool:
        quote = trim(str(quote or ""), 300)
        if quote and self._target_evidence_text_relevant(target, "", quote):
            return True
        metric_terms = self._acceptance_metric_terms_for_target(target)
        metric_terms = [str(term).lower() for term in metric_terms if str(term or "").strip()]
        number_token = re.compile(
            r"(?<![A-Za-z0-9_.])(-?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)(?![A-Za-z0-9_.])"
        )
        try:
            quote_number = float(quote.rstrip("%")) if quote else None
        except Exception:
            quote_number = None
        for row in evidence_rows:
            text = str(row.get("text", "") or "")
            for line in text.replace("\r\n", "\n").split("\n"):
                line_low = line.lower()
                if not any(term in line_low for term in metric_terms):
                    continue
                numeric_matches = [match.group(1) for match in number_token.finditer(line)]
                if quote and quote in line and (
                    quote_number is None
                    or any(self._numeric_equivalent(raw, quote_number) for raw in numeric_matches)
                ):
                    return True
                if any(self._numeric_equivalent(raw, measured) for raw in numeric_matches):
                    return True
        return False

    def _llm_acceptance_target_verdict(self, target: dict, evidence_rows: list[dict]) -> dict:
        if not evidence_rows:
            return {"met": None, "measured": None, "source": "none", "evidence": ""}
        try:
            target_payload = {
                "metric": str(target.get("metric", "") or ""),
                "op": str(target.get("op", "") or ""),
                "value": target.get("value"),
                "unit": str(target.get("unit", "") or ""),
                "raw": str(target.get("raw", "") or ""),
            }
            evidence_payload = [
                {
                    "source": str(row.get("source", "") or ""),
                    "command": trim(str(row.get("command", "") or ""), 260),
                    "text": trim(str(row.get("text", "") or ""), 1200),
                }
                for row in evidence_rows[-6:]
                if isinstance(row, dict)
            ]
            prompt = (
                "/no_think\n"
                "You are validating a numeric acceptance target from concrete tool evidence. "
                "Actively find the measured value for the requested metric, then compare it to the target.\n\n"
                "Rules:\n"
                "- Use ONLY values that are explicitly tied to the requested metric in the evidence.\n"
                "- Ignore file sizes, byte counts, line numbers, timestamps, iteration counts, list indices, subtask numbers, and version numbers unless the metric itself is file size.\n"
                "- If the evidence only proves a non-numeric condition (for example files exist) but has no measured value for this metric, return measurable=false.\n"
                "- If a validator says all_pass=true and also reports the metric value, use that metric value.\n\n"
                f"TARGET:\n{json_dumps(target_payload, ensure_ascii=False)}\n\n"
                f"EVIDENCE:\n{json_dumps(evidence_payload, ensure_ascii=False, indent=2)}\n\n"
                "Reply ONLY JSON: "
                "{\"measurable\": true/false, \"measured\": <number|null>, \"met\": true/false|null, "
                "\"quote\": \"<exact evidence phrase used>\", \"reason\": \"<short>\"}"
            )
            resp = self.ollama.chat(
                [{"role": "user", "content": prompt}],
                system="/no_think\nVerify numeric acceptance targets from evidence. Reply ONLY valid JSON.",
                max_tokens=180,
                think=False,
            )
            import json
            raw = str(resp.get("content", "") or resp.get("text", "") or "").strip()
            if "{" not in raw or "}" not in raw:
                return {"met": None, "measured": None, "source": "llm-unparseable", "evidence": ""}
            data = json.loads(raw[raw.index("{"):raw.rindex("}") + 1])
            if not isinstance(data, dict) or not bool(data.get("measurable", False)):
                return {"met": None, "measured": None, "source": "llm", "evidence": trim(str(data.get("reason", "") if isinstance(data, dict) else ""), 240)}
            measured = data.get("measured")
            try:
                measured_float = float(measured)
            except Exception:
                return {"met": None, "measured": None, "source": "llm", "evidence": trim(str(data.get("reason", "") or ""), 240)}
            quote = trim(str(data.get("quote", "") or ""), 300)
            if not self._llm_acceptance_quote_supported(target, evidence_rows, quote, measured_float):
                return {"met": None, "measured": None, "source": "llm-rejected", "evidence": quote}
            met = data.get("met", None)
            if met is not None:
                met = bool(met)
            return {
                "met": met,
                "measured": measured_float,
                "source": "llm",
                "evidence": quote or trim(str(data.get("reason", "") or ""), 240),
            }
        except Exception:
            return {"met": None, "measured": None, "source": "llm-error", "evidence": ""}

    def _deterministic_acceptance_target_met(self, target: dict, evidence_rows: list[dict]) -> dict:
        if not evidence_rows:
            return {"met": None, "measured": None, "source": "deterministic", "evidence": ""}
        op = str(target.get("op", "<=") or "<=")
        value = float(target.get("value", 0.0) or 0.0)
        metric_terms = self._acceptance_metric_terms_for_target(target)
        metric_terms = sorted((t for t in dict.fromkeys(metric_terms) if t), key=len, reverse=True)
        metric_alt = "|".join(re.escape(t) for t in metric_terms)
        if not metric_alt:
            return {"met": None, "measured": None, "source": "deterministic", "evidence": ""}
        number_pat = r"(-?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)\s*(%|percent|pct|个百分点)?"
        metric_suffix_pat = r"(?:\s*\((?:%|percent|pct)\)|[_\-\s]*(?:pct|percent|percentage|百分比))?"
        separator_pat = r"\s*(?::|：|=|≈|~|->|=>|\bis\b|\bwas\b|为|是|约为|约)\s*"
        metric_value = re.compile(
            r"(?<![A-Za-z0-9])(?:"
            + metric_alt
            + r")"
            + metric_suffix_pat
            + separator_pat
            + number_pat,
            re.IGNORECASE,
        )
        value_metric = re.compile(
            r"(?<![A-Za-z0-9])"
            + number_pat
            + r"\s*(?:for|as|of|on|的)?\s*(?:"
            + metric_alt
            + r")"
            + metric_suffix_pat
            + r"(?![A-Za-z0-9])",
            re.IGNORECASE,
        )
        measured_rows: list[tuple[float, str]] = []
        for row in evidence_rows:
            text = str(row.get("text", "") or "")
            for line in text.replace("\r\n", "\n").split("\n"):
                line = line.strip()
                if not line:
                    continue
                for pattern in (metric_value, value_metric):
                    for match in pattern.finditer(line):
                        try:
                            measured_rows.append((float(match.group(1)), trim(match.group(0), 180)))
                        except Exception:
                            pass
        if not measured_rows:
            return {"met": None, "measured": None, "source": "deterministic", "evidence": ""}
        higher_better = op in (">", ">=")
        measured, quote = (min(measured_rows, key=lambda row: row[0]) if higher_better else max(measured_rows, key=lambda row: row[0]))
        if op == "<":
            met = measured < value
        elif op == "<=":
            met = measured <= value
        elif op == ">":
            met = measured > value
        elif op == ">=":
            met = measured >= value
        elif op == "==":
            met = abs(measured - value) <= max(1e-9, abs(value) * 1e-9)
        else:
            met = None
        return {"met": met, "measured": measured, "source": "deterministic", "evidence": quote}

    def _acceptance_target_met(self, target: dict, bb: dict, results: list[dict]) -> dict:
        """Measure whether an extracted numeric quality target is actually met,
        from metric-specific evidence. LLM actively identifies the measured value
        first; deterministic regex is only a fallback over pre-filtered validator
        output. Returns {met: True|False|None, measured}. None = not measurable
        → caller falls back to category-only behavior (never a false block)."""
        if not isinstance(target, dict) or target.get("kind") != "numeric":
            return {"met": None, "measured": None}
        try:
            evidence_rows = self._acceptance_target_evidence_rows(target, bb, results)
        except Exception:
            evidence_rows = []
        llm_verdict = self._llm_acceptance_target_verdict(target, evidence_rows)
        if llm_verdict.get("met") is not None:
            return llm_verdict
        fallback = self._deterministic_acceptance_target_met(target, evidence_rows)
        if fallback.get("met") is not None:
            return fallback
        return {
            "met": None,
            "measured": None,
            "source": llm_verdict.get("source", "none") or fallback.get("source", "none"),
            "evidence": llm_verdict.get("evidence", "") or fallback.get("evidence", ""),
        }

    def _track_step_outcome_progress(self, plan_step: dict, bb: dict, gate: dict | None = None) -> dict:
        """Track OUTCOME progress for an in_progress step that did NOT advance
        this round, and escalate on a real deadlock (Fix 6).

        The existing repair-signature guard (`_repair_progress_signature`) only
        runs inside `_acceptance_gate_handle_failure`, which itself only fires
        when `subtasks_done and not gate_ok`. A single-agent worker that never
        marks its acceptance subtask done (because it honestly knows the result
        misses the bar) therefore has NO stall counter at all, and loops forever
        while changing its approach each round. This tracker runs EVERY
        non-advancing round the step is in_progress and measures OUTCOME, not
        approach: more completed subtasks, or a measured value that moved toward
        the quality bar. Approach churn alone is NOT progress.

        Returns {stuck_n, escalated}."""
        step_id = str((plan_step or {}).get("id", "") or "")
        if not step_id:
            return {"stuck_n": 0, "escalated": False}
        completed = 0
        try:
            rows = self._active_plan_worker_todo_rows(step_id, role="")
            completed = sum(
                1 for r in rows if str(r.get("status", "") or "").strip().lower() == "completed"
            )
        except Exception:
            completed = 0
        # Measured value toward the quality bar (if any).
        measured = None
        op = ""
        try:
            target = self._resolve_acceptance_target(plan_step, (gate or {}).get("acceptance", {}) if isinstance(gate, dict) else {})
            if target:
                op = str(target.get("op", "") or "")
                verdict = self._acceptance_target_met(target, bb, [])
                measured = verdict.get("measured")
        except Exception:
            measured = None
        best_done_attr = f"_step_best_done_{step_id}"
        best_meas_attr = f"_step_best_meas_{step_id}"
        stuck_attr = f"_step_stuck_n_{step_id}"
        prev_best_done = int(getattr(self, best_done_attr, -1))
        prev_best_meas = getattr(self, best_meas_attr, None)
        improved = False
        if completed > prev_best_done:
            improved = True
        elif measured is not None:
            if prev_best_meas is None:
                improved = True
            elif op in (">", ">="):
                improved = measured > float(prev_best_meas)
            else:  # lower is better (error/deviation/loss/tolerance) or unknown
                improved = measured < float(prev_best_meas)
        if improved:
            setattr(self, best_done_attr, max(prev_best_done, completed))
            if measured is not None:
                if prev_best_meas is None:
                    setattr(self, best_meas_attr, measured)
                elif op in (">", ">="):
                    setattr(self, best_meas_attr, max(float(prev_best_meas), measured))
                else:
                    setattr(self, best_meas_attr, min(float(prev_best_meas), measured))
            setattr(self, stuck_attr, 0)
            return {"stuck_n": 0, "escalated": False}
        stuck_n = int(getattr(self, stuck_attr, 0) or 0) + 1
        setattr(self, stuck_attr, stuck_n)
        escalated = False
        if stuck_n >= STEP_ACTIVE_STALL_CEILING:
            try:
                self.stall_severity_sources.append(
                    f"step-outcome-stall:{step_id}:{stuck_n}"
                )
            except Exception:
                pass
            escalated = bool(
                self._escalate_stall_to_plan_mode(
                    trigger_source=f"step-outcome-stall:{step_id}",
                    last_fault_reason=str((gate or {}).get("reason", "") or "step outcome not improving"),
                )
            )
            if escalated:
                setattr(self, stuck_attr, 0)
        return {"stuck_n": stuck_n, "escalated": escalated}

    def _llm_acceptance_failure_verdict(self, exec_text: str) -> dict:
        """LLM-primary perception (Fix 5 steer): does this acceptance-check output
        report that the check FAILED? Semantic self-awareness is the right judge
        here — a script's output can report failure in unbounded ways ("residual
        exceeds tolerance", "did not converge", "3 of 12 assertions broke") that no
        regex enumerates. Returns {failed: True/False/None, marker}. None = model
        unavailable/uncertain → caller falls back to the lexical scan."""
        text = trim(str(exec_text or "").strip(), 1400)
        if not text:
            return {"failed": None, "marker": ""}
        try:
            prompt = (
                "/no_think\n"
                "This is the OUTPUT of an acceptance/verification check that was just run for a task step. "
                "Decide whether the output reports that the check FAILED (an assertion broke, a test failed, a "
                "convergence/tolerance/quality target was NOT met, a non-zero failure count, an error/traceback "
                "that means the check did not pass). A clean pass, a zero failure count, or output that merely "
                "mentions the word 'error' while still passing is NOT a failure.\n\n"
                f"OUTPUT:\n{text}\n\n"
                "Reply ONLY JSON: {\"failed\": true/false, \"marker\": \"<short quote of the failure line, or empty>\"}"
            )
            resp = self.ollama.chat(
                [{"role": "user", "content": prompt}],
                system="/no_think\nJudge whether a check's output reports failure. Reply ONLY valid JSON.",
                max_tokens=120,
                think=False,
            )
            import json
            raw = str(resp.get("content", "") or resp.get("text", "") or "").strip()
            if "{" not in raw or "}" not in raw:
                return {"failed": None, "marker": ""}
            data = json.loads(raw[raw.index("{"):raw.rindex("}") + 1])
            if not isinstance(data, dict) or "failed" not in data:
                return {"failed": None, "marker": ""}
            failed = bool(data.get("failed", False))
            return {"failed": failed, "marker": trim(str(data.get("marker", "") or "").strip(), 60)}
        except Exception:
            return {"failed": None, "marker": ""}

    def _acceptance_context_expects_zero_count(self, text: str) -> bool:
        low = str(text or "").lower()
        if not low.strip():
            return False
        zero_terms = (
            "zero", "none", "no ", "without", "absence", "absent",
            "无", "沒有", "没有", "不得", "不能", "未出现", "不应", "不應",
        )
        count_terms = ("count", "matches", "grep", "rg", "数量", "个数", "處數", "处数", "匹配", "残留")
        has_zero = bool(re.search(r"(?<![\d.])0(?:\.0+)?(?![\d.])", low)) or any(term in low for term in zero_terms)
        if any(term in low for term in count_terms) and has_zero:
            return True
        return has_zero

    def _acceptance_results_structural_failure(self, rows: list[dict], acceptance_context: str = "") -> dict:
        expects_zero_count = self._acceptance_context_expects_zero_count(acceptance_context)
        for row in rows:
            if not isinstance(row, dict):
                continue
            name = str(row.get("name", "") or "")
            if name not in {"bash", "worktree_run", "background_run"}:
                continue
            args = row.get("args", {}) if isinstance(row.get("args"), dict) else {}
            command = str(row.get("command", "") or args.get("command", "") or "")
            output = str(row.get("output", "") or "")
            exit_code = self._coerce_exit_code(row.get("exit_code"))
            positive_count = self._count_search_output_has_positive_count(command, output)
            if positive_count is not None:
                if positive_count == 0:
                    continue
                if expects_zero_count:
                    return {
                        "failed": True,
                        "marker": f"count-search={positive_count}",
                        "excerpt": trim(output, 120),
                        "source": "structural",
                        "command": trim(command, 500),
                        "exit_code": exit_code,
                    }
            if exit_code is not None and exit_code != 0:
                if self._count_search_output_is_zero(command, output):
                    continue
                excerpt = trim(output, 120) or f"exit={exit_code}"
                return {
                    "failed": True,
                    "marker": f"exit={exit_code}",
                    "excerpt": excerpt,
                    "source": "structural",
                    "command": trim(command, 500),
                    "exit_code": exit_code,
                }
        return {"failed": False, "marker": "", "excerpt": "", "source": "structural"}

    def _acceptance_results_lexical_failure(self, rows: list[dict]) -> dict:
        """Lexical FALLBACK for _acceptance_results_show_failure. Scans exec output
        for an explicit failure marker while excluding common false positives
        ("0 checks failed", "failed=0"). Used only when LLM perception is
        unavailable/uncertain."""
        fail_pat = re.compile(
            r"(?i)("
            r"checks?\s+failed"
            r"|\bassertion(?:error)?\s+fail"
            r"|\bassertionerror\b"
            r"|\bfailed\s*:\s*[1-9]"
            r"|\b[1-9]\d*\s+(?:checks?|tests?|assertions?)\s+failed"
            r"|\btest(?:s)?\s+failed"
            r"|\b(?:验收|驗収|驗證|校验|校驗)?\s*(?:未通过|未通過|不通过|不通過|失败|失敗)"
            r"|\bFAIL(?:ED)?\b(?!\s*=\s*0)(?!\s*:\s*0)"
            r"|traceback \(most recent call last\)"
            r"|\b(?:not|did\s+not)\s+converge(?:d)?\b"
            r"|\bnot\s+converged\b"
            r"|\b(?:does\s+not|did\s+not|failed\s+to)\s+meet\b"
            r"|\bexceeds?\s+(?:the\s+)?(?:tolerance|threshold|limit)\b"
            r"|\bout\s+of\s+tolerance\b"
            r")"
        )
        benign_pat = re.compile(
            r"(?i)("
            r"\b0\s+(?:checks?|tests?|assertions?)\s+failed"
            r"|failed\s*[=:]\s*0"
            r"|\bno\s+(?:checks?|tests?|assertions?|errors?)\s+failed"
            r"|\bnone\s+failed"
            r"|\b0\s+fail"
            r")"
        )
        for row in rows:
            name = str(row.get("name", "") or "")
            if name not in {"bash", "worktree_run", "background_run"}:
                continue
            args = row.get("args", {}) if isinstance(row.get("args"), dict) else {}
            command = trim(str(row.get("command", "") or args.get("command", "") or ""), 500)
            exit_code = self._coerce_exit_code(row.get("exit_code"))
            raw = str(row.get("output", "") or "")
            if not raw.strip():
                continue
            for line in raw.replace("\r\n", "\n").split("\n"):
                s = line.strip()
                if not s:
                    continue
                if benign_pat.search(s):
                    continue
                partial = re.search(r"(?i)\b(\d+)\s*/\s*(\d+)\s+checks?\s+(?:pass|passed)\b", s)
                if not partial:
                    partial = re.search(r"(?i)\b(\d+)\s+of\s+(\d+)\s+checks?\s+(?:pass|passed)\b", s)
                if partial:
                    try:
                        passed = int(partial.group(1))
                        total = int(partial.group(2))
                    except Exception:
                        passed = total = 0
                    if total > 0 and passed < total:
                        return {
                            "failed": True,
                            "marker": trim(partial.group(0), 40),
                            "excerpt": trim(s, 120),
                            "command": command,
                            "exit_code": exit_code,
                        }
                m = fail_pat.search(s)
                if m:
                    return {
                        "failed": True,
                        "marker": trim(m.group(0), 40),
                        "excerpt": trim(s, 120),
                        "command": command,
                        "exit_code": exit_code,
                    }
        return {"failed": False, "marker": "", "excerpt": ""}

    def _acceptance_results_show_failure(self, results: list[dict], acceptance_context: str = "") -> dict:
        """F10: did this turn's acceptance check report a FAILURE?

        LLM-primary (per the Fix 5 steer): the model perceives failure from the
        check output first, because failure is reported in unbounded natural ways.
        The lexical scan is only a fallback for when the model is unavailable or
        uncertain. This stops the gate being gamed by a script that prints an
        `ALL CHECKS PASSED` banner while a real check failed, and stops a genuine
        `1 CHECKS FAILED` from being rationalized away and advanced past.

        Returns {failed: bool, marker: str, excerpt: str, source: str}."""
        rows = [r for r in (results or []) if isinstance(r, dict)]
        if not rows:
            return {"failed": False, "marker": "", "excerpt": "", "source": "none"}
        exec_rows = [r for r in rows if str(r.get("name", "") or "") in {"bash", "worktree_run", "background_run"}]
        if not exec_rows:
            return {"failed": False, "marker": "", "excerpt": "", "source": "none"}
        structural = self._acceptance_results_structural_failure(exec_rows, acceptance_context)
        if structural.get("failed"):
            return structural
        # Concatenate this turn's exec output for the LLM to perceive as a whole.
        exec_text = "\n".join(
            trim(str(r.get("output", "") or "").strip(), 900)
            for r in exec_rows
            if str(r.get("output", "") or "").strip()
        ).strip()
        verdict = {"failed": None, "marker": ""}
        if exec_text:
            verdict = self._llm_acceptance_failure_verdict(exec_text)
            if verdict.get("failed") is True:
                marker = verdict.get("marker", "") or "check reported failure"
                first = exec_rows[0] if exec_rows else {}
                first_args = first.get("args", {}) if isinstance(first.get("args"), dict) else {}
                return {
                    "failed": True,
                    "marker": marker,
                    "excerpt": marker,
                    "source": "llm",
                    "command": trim(str(first.get("command", "") or first_args.get("command", "") or ""), 500),
                    "exit_code": self._coerce_exit_code(first.get("exit_code")),
                }
        # Lexical hard markers still run after the LLM. They catch deterministic
        # validator phrases and protect against a false-negative LLM pass verdict.
        fb = self._acceptance_results_lexical_failure(exec_rows)
        if fb.get("failed"):
            fb["source"] = "lexical"
            return fb
        if verdict.get("failed") is False:
            return {"failed": False, "marker": "", "excerpt": "", "source": "llm"}
        fb["source"] = "lexical"
        return fb

    def _plan_step_acceptance_gate_status(
        self,
        plan_step: dict,
        worker_step: dict | None = None,
        board: dict | None = None,
    ) -> dict:
        """Return the final acceptance-subtask gate status for a plan step."""
        if not isinstance(plan_step, dict):
            return {"ok": False, "reason": "missing-plan-step"}
        step_id = trim(str(plan_step.get("id", "") or ""), 20)
        if not step_id:
            return {"ok": False, "reason": "missing-plan-step-id"}
        rows = self._active_plan_worker_todo_rows(step_id, role="")
        if not rows:
            return {"ok": False, "reason": "missing-step-local-subtasks"}
        acceptance_rows = [
            row for row in rows
            if self._is_plan_step_acceptance_subtask(row.get("content", ""))
        ]
        if not acceptance_rows:
            return {"ok": False, "reason": "missing-final-acceptance-subtask"}
        acceptance = dict(acceptance_rows[-1])
        if str(acceptance.get("status", "") or "").strip().lower() != "completed":
            return {
                "ok": False,
                "reason": "final-acceptance-subtask-not-completed",
                "acceptance": acceptance,
            }
        text = str(acceptance.get("content", "") or "").strip().lower()
        if not text:
            return {"ok": False, "reason": "empty-final-acceptance-subtask", "acceptance": acceptance}

        raw_results = [
            row for row in ((worker_step or {}).get("tool_results", []) if isinstance(worker_step, dict) else [])
            if isinstance(row, dict)
        ]
        results = [row for row in raw_results if row.get("ok", False)]
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        try:
            ts_candidates = []
            for ts_key in ("created_at", "started_at", "in_progress_at", "updated_at", "completed_at"):
                try:
                    ts_value = float(acceptance.get(ts_key, 0.0) or 0.0)
                except Exception:
                    ts_value = 0.0
                if ts_value > 0:
                    ts_candidates.append(ts_value)
            acceptance_started_ts = min(ts_candidates) if ts_candidates else 0.0
        except Exception:
            acceptance_started_ts = 0.0
        sig = self._plan_step_blackboard_signals(
            plan_step,
            bb,
            since_ts_override=acceptance_started_ts,
        )
        has_current_read = any(
            str(row.get("name", "") or "") == "read_file"
            and not self._is_plan_infrastructure_read_result(row)
            and bool(self._tool_result_output_excerpt(row, 80))
            for row in results
        )
        has_current_exec = any(str(row.get("name", "") or "") in {"bash", "worktree_run", "background_run"} for row in results)
        has_current_validation = self._tool_results_have_validation_evidence(plan_step, results)
        has_current_retrieval = any(self._tool_result_has_positive_retrieval_signal(row) for row in results)
        has_current_blackboard_acceptance = any(
            str(row.get("name", "") or "") == "write_to_blackboard"
            and any(marker in str(row.get("args", {})).lower() for marker in ("验收", "驗收", "acceptance", "受入確認"))
            for row in results
        )

        wants_file_inspection = any(
            tok in text
            for tok in (
                "读取", "检查", "文件", "目录", "路径", "选择器", "read", "inspect", "file",
                "directory", "path", "selector", "檢查", "讀取", "確認", "ファイル", "ディレクトリ",
            )
        ) or self._plan_text_file_content_subject(text)
        wants_runtime = self._plan_text_explicit_runtime_check(text) or (
            any(tok in text for tok in ("运行", "执行", "run", "実行"))
            and self._plan_text_runtime_subject(text)
        )
        if wants_file_inspection and self._plan_text_prefers_file_content_evidence(text):
            wants_runtime = False
        wants_research = any(
            tok in text
            for tok in (
                "检索", "搜索", "研究", "调研", "资料", "来源", "引用", "research", "search",
                "source", "citation", "evidence chain", "搜集", "收集", "調査", "検索",
            )
        )
        wants_blackboard_record = any(
            tok in text
            for tok in ("黑板", "blackboard", "记录", "記錄", "record", "status", "review_feedback")
        )

        current_match = False
        blackboard_match = False
        expected = "generic-observable-check"
        if wants_runtime:
            expected = "runtime/test/build/browser execution evidence"
            current_match = bool(has_current_validation or has_current_exec)
            blackboard_match = bool(sig.get("has_exec") or sig.get("has_review"))
        elif wants_file_inspection:
            expected = "file/path/directory inspection evidence"
            current_match = bool(has_current_read or has_current_exec)
            blackboard_match = bool(sig.get("has_read") or sig.get("has_exec") or sig.get("has_review"))
        elif wants_research:
            expected = "research/retrieval evidence"
            current_match = bool(has_current_retrieval or has_current_read)
            blackboard_match = bool(sig.get("has_research") or sig.get("has_read") or sig.get("has_review"))
        elif wants_blackboard_record:
            expected = "blackboard acceptance record"
            current_match = bool(has_current_blackboard_acceptance or has_current_validation)
            blackboard_match = bool(sig.get("has_exec") or sig.get("has_review") or sig.get("has_research"))
        else:
            current_match = bool(has_current_validation or has_current_read or has_current_exec or has_current_retrieval)
            blackboard_match = bool(sig.get("has_exec") or sig.get("has_review") or sig.get("has_read") or sig.get("has_research"))

        # During a live worker/single-agent turn, the acceptance action should
        # normally be visible in this turn's tool_results. Blackboard fallback is
        # for finish/resume reconciliation where current tool_results are no
        # longer available but the step-scoped evidence has already been recorded.
        #
        # F9: previously this wiped blackboard_match whenever ANY tool_results
        # existed this turn. That broke prose/derivation steps: a worker that
        # produced its acceptance evidence in a PRIOR round (recorded on the
        # blackboard) and merely ran an unrelated tool this round would be told
        # `final-acceptance-evidence-missing`, forcing redundant repair rounds
        # (observed: sync run looped repair round 4/6 on already-passing steps).
        # Only discard the blackboard fallback when this turn's OWN evidence
        # already satisfies the category (current_match) — i.e. we don't need the
        # fallback anyway. If this turn's tools don't match the category, keep the
        # recorded blackboard evidence rather than falsely declaring it missing.
        if results and current_match:
            blackboard_match = False
        # F10: an explicit failure signal in this turn's own tool output blocks
        # acceptance regardless of category match. A worker cannot pass a step by
        # running a validator that prints `CHECKS FAILED` (or by cherry-printing a
        # PASS banner while a real check failed). This runs before the
        # category/target verdicts so a genuine failure is never rationalized away.
        if raw_results:
            acceptance_context = "\n".join(
                part
                for part in (
                    str(plan_step.get("full_content", "") or plan_step.get("content", "") or ""),
                    str(acceptance.get("content", "") or ""),
                )
                if part
            )
            failure = self._acceptance_results_show_failure(
                raw_results,
                acceptance_context=acceptance_context,
            )
            if failure.get("failed"):
                return {
                    "ok": False,
                    "reason": f"acceptance-check-reported-failure:{failure.get('marker', '')}",
                    "expected": expected,
                    "failure_excerpt": failure.get("excerpt", ""),
                    "failure_command": failure.get("command", ""),
                    "failure_exit_code": failure.get("exit_code"),
                    "failure_source": failure.get("source", ""),
                    "acceptance": acceptance,
                }
        # Quality-aware enforcement (Fix 5): if the step/acceptance text states an
        # explicit numeric quality bar (e.g. "误差 < 2%"), a category match is NOT
        # enough — the measured result must actually meet the bar. This stops a
        # worker from passing a 23% result just because a check ran. When the bar
        # is unmeasurable, fall back to category-only (never a false block).
        target = self._resolve_acceptance_target(plan_step, acceptance)
        if target and (current_match or blackboard_match):
            verdict = self._acceptance_target_met(target, bb, results)
            if verdict.get("met") is False:
                unit = str(target.get("unit", "") or "")
                measured = verdict.get("measured")
                return {
                    "ok": False,
                    "reason": (
                        "acceptance-target-unmet:"
                        f"{measured}{unit} vs {target.get('op', '<=')}{target.get('value')}{unit}"
                    ),
                    "expected": expected,
                    "target": target,
                    "measured": measured,
                    "acceptance": acceptance,
                }
        if current_match:
            return {
                "ok": True,
                "reason": "current-tool-evidence-matches-final-acceptance",
                "source": "current_tool_results",
                "expected": expected,
                "target": target or None,
                "acceptance": acceptance,
            }
        if blackboard_match:
            return {
                "ok": True,
                "reason": "blackboard-evidence-matches-final-acceptance",
                "source": "blackboard",
                "expected": expected,
                "target": target or None,
                "acceptance": acceptance,
            }
        return {
            "ok": False,
            "reason": "final-acceptance-evidence-missing",
            "expected": expected,
            "acceptance": acceptance,
        }

    def _plan_step_acceptance_gate_passed(
        self,
        plan_step: dict,
        worker_step: dict | None = None,
        board: dict | None = None,
    ) -> bool:
        """Hard gate: the final acceptance subtask must be completed with matching tool evidence."""
        return bool(self._plan_step_acceptance_gate_status(plan_step, worker_step, board).get("ok", False))

    def _acceptance_gate_failure_context(
        self,
        plan_step: dict,
        gate: dict | None,
        bb: dict | None = None,
        *,
        max_chars: int = 1200,
    ) -> str:
        gate_row = gate if isinstance(gate, dict) else {}
        board = bb if isinstance(bb, dict) else self._ensure_blackboard()
        lines: list[str] = []
        reason = trim(str(gate_row.get("reason", "") or ""), 220)
        expected = trim(str(gate_row.get("expected", "") or ""), 220)
        if reason:
            lines.append(f"gate_reason: {reason}")
        if expected:
            lines.append(f"expected_evidence: {expected}")
        acceptance = gate_row.get("acceptance", {}) if isinstance(gate_row.get("acceptance"), dict) else {}
        acceptance_text = trim(str(acceptance.get("content", "") or ""), 260)
        if acceptance_text:
            lines.append(f"acceptance_subtask: {acceptance_text}")
        command = trim(str(gate_row.get("failure_command", "") or ""), 700)
        if command:
            lines.append(f"failed_command: {command}")
        if gate_row.get("failure_exit_code") not in (None, ""):
            lines.append(f"failed_exit_code: {gate_row.get('failure_exit_code')}")
        excerpt = trim(str(gate_row.get("failure_excerpt", "") or ""), 500)
        if excerpt:
            lines.append(f"failure_excerpt: {excerpt}")
        target = gate_row.get("target", {}) if isinstance(gate_row.get("target"), dict) else {}
        if target:
            bar = f"{target.get('metric', 'target')} {target.get('op', '<=')}{target.get('value')}{target.get('unit', '')}"
            measured = gate_row.get("measured", None)
            lines.append(f"quality_bar: {trim(bar, 180)}; measured={measured}")
        try:
            sig = self._plan_step_blackboard_signals(plan_step, board)
            if sig.get("recent_exec_excerpt"):
                lines.append(f"recent_step_exec: {trim(str(sig.get('recent_exec_excerpt', '')), 260)}")
            if sig.get("recent_review_excerpt"):
                lines.append(f"recent_step_review: {trim(str(sig.get('recent_review_excerpt', '')), 220)}")
        except Exception:
            pass
        return trim("\n".join(lines), max_chars)

    def _inject_acceptance_gate_rework_hint(
        self,
        plan_step: dict,
        gate: dict | None = None,
        *,
        target_roles: tuple[str, ...] = (),
    ) -> bool:
        if not isinstance(plan_step, dict):
            return False
        step_id = trim(str(plan_step.get("id", "") or ""), 20)
        if not step_id:
            return False
        _flag = f"_acceptance_gate_hint_ts_{step_id}"
        try:
            last_ts = float(getattr(self, _flag, 0.0) or 0.0)
        except Exception:
            last_ts = 0.0
        if float(now_ts()) - last_ts < 20.0:
            return False
        try:
            setattr(self, _flag, float(now_ts()))
        except Exception:
            pass
        gate_row = gate if isinstance(gate, dict) else self._plan_step_acceptance_gate_status(plan_step)
        acceptance = gate_row.get("acceptance", {}) if isinstance(gate_row.get("acceptance"), dict) else {}
        acceptance_text = trim(str(acceptance.get("content", "") or ""), 300)
        reason = trim(str(gate_row.get("reason", "") or "final-acceptance-gate-failed"), 160)
        expected = trim(str(gate_row.get("expected", "") or ""), 180)
        step_label = trim(str(plan_step.get("content", "") or ""), 160)
        # Concrete what+how spec (same heuristic the gate uses) so the worker
        # knows exactly which action produces passing evidence.
        try:
            guidance = self._plan_step_acceptance_guidance(plan_step)
        except Exception:
            guidance = {}
        guidance_line = ""
        if guidance:
            guidance_line = (
                f"WHAT to verify: {guidance.get('what', '')} "
                f"HOW: {guidance.get('how', '')} "
                f"EXAMPLE ACTION: {guidance.get('example', '')} "
            )
        # Show what evidence the step has ALREADY accumulated, so the worker can
        # see the gap instead of redoing everything.
        try:
            already = self._collect_accumulated_step_evidence(plan_step, self._ensure_blackboard())
        except Exception:
            already = ""
        already_line = f"Evidence already on record: {already}. " if already and already != "accumulated-step-evidence" else ""
        failure_context = self._acceptance_gate_failure_context(plan_step, gate_row, self._ensure_blackboard(), max_chars=900)
        failure_line = f"FAILED ACCEPTANCE CONTEXT:\n{failure_context}\n" if failure_context else ""
        roles = tuple(
            role for role in (self._sanitize_agent_role(x) for x in target_roles)
            if role
        )
        if not roles and self._is_multi_agent_mode():
            roles = (self._current_plan_worker_owner(),)
        content = (
            "<acceptance-required>\n"
            f"Stay on the current plan step: {step_label}. "
            "The final acceptance subtask is a normal step-local TodoWrite task, but the plan step cannot advance until its check action has matching tool or blackboard evidence in THIS turn. "
            f"Gate reason: {reason}. "
            f"{('Expected evidence: ' + expected + '. ') if expected else ''}"
            f"{guidance_line}"
            f"{already_line}"
            f"{failure_line}"
            f"{('Final acceptance subtask: ' + acceptance_text + '. ') if acceptance_text else ''}"
            "Now CALL THE TOOL described under HOW/EXAMPLE ACTION (do not just describe it), confirm the success signal in its output, "
            "then update the same acceptance TodoWrite row to completed. If the check FAILS, fix the underlying problem first, then re-run the check. "
            "Do not skip to another plan step and do not edit .clouds_coder/plan.md directly.\n"
            "</acceptance-required>"
        )
        return self._append_plan_guidance_bubble(
            content,
            target_roles=roles,
            summary="acceptance gate requires evidence",
        )

    def _repair_progress_signature(self, plan_step: dict, gate: dict, bb: dict) -> str:
        """A stable signature of the current failure state for a step.

        If this signature CHANGES between repair rounds, the agent is making
        progress (different error, different gate reason, new evidence) → keep
        repairing without bound. If it stays IDENTICAL for N consecutive rounds,
        the repair loop is truly deadlocked → escalate to the user. This is what
        lets us "repair forever while progressing, escalate only on a real stall"
        instead of force-advancing.
        """
        import hashlib
        reason = str((gate or {}).get("reason", "") or "")
        # Recent step-scoped error context (categories + messages + last error).
        try:
            err_ctx = self._recent_error_context(max_chars=600)
        except Exception:
            err_ctx = ""
        # Evidence signature: which signal kinds are currently present.
        try:
            sig = self._plan_step_blackboard_signals(plan_step, bb)
            ev = "".join(
                k[0] for k in ("has_write", "has_read", "has_exec", "has_review", "has_research")
                if sig.get(k)
            )
        except Exception:
            ev = ""
        # Completed subtask count (progress within the step).
        try:
            step_id = str((plan_step or {}).get("id", "") or "")
            rows = self._active_plan_worker_todo_rows(step_id, role="")
            done_n = sum(1 for r in rows if str(r.get("status", "") or "").lower() == "completed")
        except Exception:
            done_n = 0
        raw = f"{reason}|{ev}|{done_n}|{err_ctx}"
        return hashlib.sha1(raw.encode("utf-8", "ignore")).hexdigest()[:16]

    def _diagnose_acceptance_gate_failure(self, plan_step: dict, gate: dict, bb: dict) -> dict:
        """Map a gate failure to an actionable repair spec.

        Returns: {root_cause, repair_action, fixer_role, error_category, error_context}
        Routing is driven by the gate's `reason` plus the failure ledger so the
        worker is told the real root cause and a concrete next action, not just
        "record evidence".
        """
        reason = str((gate or {}).get("reason", "") or "")
        try:
            error_context = self._recent_error_context(max_chars=700)
        except Exception:
            error_context = ""
        try:
            failure_context = self._acceptance_gate_failure_context(plan_step, gate, bb, max_chars=900)
        except Exception:
            failure_context = ""
        if failure_context:
            error_context = trim(
                (error_context + "\n\n" if error_context else "")
                + "FAILED ACCEPTANCE CONTEXT:\n"
                + failure_context,
                1400,
            )
        # Pick the dominant error category from the ledger, if any.
        error_category = ""
        try:
            fl = bb.get("failure_ledger", {}) if isinstance(bb.get("failure_ledger"), dict) else {}
            errs = [e for e in fl.get("errors", []) if isinstance(e, dict) and int(e.get("count", 0) or 0) > 0]
            if errs:
                error_category = str(sorted(errs, key=lambda e: int(e.get("count", 0) or 0))[-1].get("category", "") or "")
        except Exception:
            error_category = ""

        if reason in ("missing-step-local-subtasks",):
            return {
                "root_cause": "No step-local subtasks exist; the worker never broke the step down.",
                "repair_action": "Call TodoWrite now to create 3-6 step-local subtasks (parent_step_id set), the last one a concrete acceptance check.",
                "fixer_role": self._current_plan_worker_owner(bb),
                "error_category": error_category,
                "error_context": error_context,
            }
        if reason in ("missing-final-acceptance-subtask", "empty-final-acceptance-subtask"):
            return {
                "root_cause": "The step has subtasks but no concrete final acceptance check.",
                "repair_action": "Add a final TodoWrite subtask that performs the acceptance check (run/read/search) with a concrete success signal.",
                "fixer_role": self._current_plan_worker_owner(bb),
                "error_category": error_category,
                "error_context": error_context,
            }
        if reason in ("final-acceptance-subtask-not-completed",):
            return {
                "root_cause": "The acceptance check subtask exists but was never actually executed.",
                "repair_action": "Execute the acceptance check with a real tool call now (do not just mark it done), confirm the success signal, then complete it.",
                "fixer_role": self._current_plan_worker_owner(bb),
                "error_category": error_category,
                "error_context": error_context,
            }
        if reason.startswith("acceptance-target-unmet:"):
            # The check ran but the measured result misses the stated quality bar
            # (e.g. 23% error vs the required <1%). This is NOT a "record evidence"
            # problem — the deliverable itself is not good enough yet.
            target = (gate or {}).get("target", {}) if isinstance((gate or {}).get("target"), dict) else {}
            bar = f"{target.get('op', '<=')}{target.get('value', '')}{target.get('unit', '')}".strip()
            measured = (gate or {}).get("measured")
            repair_action = (
                f"The acceptance check ran but the result ({measured}{target.get('unit', '')}) does NOT meet the "
                f"required quality bar ({target.get('metric', 'target')} {bar}). Do NOT advance or mark this "
                "accepted. Diagnose WHY the quality bar is missed (algorithm/params/precision/bug), FIX the "
                "underlying cause, re-run the check, and only complete the acceptance subtask once the measured "
                f"value actually satisfies {bar}."
            )
            if error_category:
                repair_action += f" (dominant failure category: '{error_category}'; do not repeat a failed fix.)"
            return {
                "root_cause": f"Deliverable misses its quality bar ({target.get('metric', 'target')} {bar}); measured {measured}{target.get('unit', '')}.",
                "repair_action": repair_action,
                "fixer_role": "reviewer" if (self._is_multi_agent_mode() and self.reviewer_debug_mode) else self._current_plan_worker_owner(bb),
                "error_category": error_category or "quality-bar",
                "error_context": error_context,
            }
        if reason.startswith("acceptance-check-reported-failure:"):
            # F10: the acceptance check ran and its own output reported a failure
            # (e.g. `1 CHECKS FAILED`, an AssertionError, a non-zero failed count).
            # This must never be rationalized away as "an arbitrary threshold" and
            # advanced past.
            excerpt = str((gate or {}).get("failure_excerpt", "") or "")
            command = str((gate or {}).get("failure_command", "") or "")
            repair_action = (
                "The acceptance check EXECUTED but its own output reported a FAILURE"
                + (f" (\"{excerpt}\")" if excerpt else "")
                + ". Do NOT advance or mark this step accepted. Read the failing output, fix the underlying "
                "cause (or, if the failing assertion is genuinely wrong/too strict, correct the check itself "
                "and justify why in one line), then re-run until the check reports no failures."
            )
            if self._command_looks_like_count_search(command):
                repair_action += (
                    " Because this was a count-search check, if the count is positive first re-run the same "
                    "pattern with line output (for example grep -n or rg -n) to identify the exact offending "
                    "lines, then edit only those real matches."
                )
            if error_category:
                repair_action += f" (dominant failure category: '{error_category}'; do not repeat a failed fix.)"
            return {
                "root_cause": "The acceptance check ran but reported a failure signal in its output.",
                "repair_action": repair_action,
                "fixer_role": self._current_plan_worker_owner(bb),
                "error_category": error_category or "check-failed",
                "error_context": error_context,
            }
        # final-acceptance-evidence-missing (and anything else): genuine failure or
        # the check ran but failed. Route to active repair (reviewer-debug in MA).
        repair_action = (
            "Diagnose the underlying problem, FIX it directly (edit code / re-run the command), "
            "then re-run the acceptance check and confirm a clean success signal."
        )
        if error_category:
            repair_action = (
                f"The dominant failure category is '{error_category}'. " + repair_action
                + " Do NOT repeat any fix already listed as failed above."
            )
        return {
            "root_cause": "The acceptance check did not produce passing evidence — likely a real error to fix.",
            "repair_action": repair_action,
            "fixer_role": "reviewer" if (self._is_multi_agent_mode() and self.reviewer_debug_mode) else self._current_plan_worker_owner(bb),
            "error_category": error_category,
            "error_context": error_context,
        }

    def _seed_repair_directive(self, plan_step: dict, diagnosis: dict, bb: dict, *, round_no: int) -> bool:
        """Inject a concrete, root-cause-driven repair directive for the fixer.

        Carries the diagnosed root cause, the exact repair action, the dominant
        error category, and the already-failed fix history (so the worker does
        not repeat a fix that has already failed). In multi-agent mode this is
        scoped to the fixer role (reviewer in debug mode).
        """
        if not isinstance(plan_step, dict) or not isinstance(diagnosis, dict):
            return False
        step_label = trim(str(plan_step.get("content", "") or ""), 160)
        root = trim(str(diagnosis.get("root_cause", "") or ""), 240)
        action = trim(str(diagnosis.get("repair_action", "") or ""), 900)
        err_ctx = trim(str(diagnosis.get("error_context", "") or ""), 1400)
        fixer = self._sanitize_agent_role(str(diagnosis.get("fixer_role", "") or "")) or self._current_plan_worker_owner(bb)
        roles = (fixer,) if fixer else ()
        debug_note = ""
        if fixer == "reviewer" and self.reviewer_debug_mode:
            debug_note = (
                "You are in REVIEWER DEBUG MODE: you may read_file, then fix directly with edit_file/write_file, "
                "then bash to verify. "
            )
        err_block = f"\nKNOWN ERRORS / FAILED FIXES (do not repeat):\n{err_ctx}\n" if err_ctx else ""
        content = (
            "<acceptance-repair>\n"
            f"Plan step still failing acceptance (repair round {round_no}): {step_label}\n"
            f"ROOT CAUSE: {root}\n"
            f"REQUIRED REPAIR: {action}\n"
            f"{debug_note}"
            f"{err_block}"
            "Make a REAL change with concrete tools, then re-run the acceptance check this same turn and confirm the success signal. "
            "Do not advance the plan or edit .clouds_coder/plan.md directly; just fix and re-verify.\n"
            "</acceptance-repair>"
        )
        return self._append_plan_guidance_bubble(
            content,
            target_roles=roles,
            summary=f"acceptance repair directive (round {round_no})",
        )

    def _acceptance_gate_handle_failure(
        self,
        plan_step: dict,
        gate: dict,
        bb: dict,
        *,
        actor: str = "developer",
        target_roles: tuple[str, ...] = (),
    ) -> bool:
        """Drive a stuck step through diagnose → repair → re-verify instead of
        force-advancing. Returns True only when the step GENUINELY passed (the
        semantic judge confirmed real evidence); never force-advances.

        Flow:
          1. Below threshold: inject the concrete rework hint (normal path).
          2. At/after threshold: run a strict semantic judge over the actual
             evidence — if it confirms the step is genuinely done (heuristic was a
             false-negative), advance as `semantic-verified`. This strengthens
             verification; it is NOT a bypass (the judge cites real evidence).
          3. Otherwise the failure is real: enable reviewer-debug (multi-agent),
             diagnose the root cause from the gate reason + failure ledger, and
             seed a concrete repair directive to the fixer. Re-verify next turn.
          4. Keep repairing as long as the repair-progress signature changes
             (still making progress). Only when it stays IDENTICAL for
             ACCEPTANCE_GATE_HARD_CEILING consecutive rounds (a true deadlock) do
             we escalate to plan-mode recovery and surface options to the user.
        """
        step_id = trim(str((plan_step or {}).get("id", "") or ""), 40)
        if not step_id:
            self._inject_acceptance_gate_rework_hint(plan_step, gate, target_roles=target_roles)
            return False
        attr = f"_acceptance_gate_fail_n_{step_id}"
        try:
            count = int(getattr(self, attr, 0) or 0) + 1
        except Exception:
            count = 1
        try:
            setattr(self, attr, count)
        except Exception:
            pass

        # Below threshold: a plain rework hint is enough; give the worker a chance.
        if count < ACCEPTANCE_GATE_STALL_THRESHOLD:
            self._inject_acceptance_gate_rework_hint(plan_step, gate, target_roles=target_roles)
            return False

        # Step 2 — STRENGTHEN VERIFICATION: strict semantic judge over real evidence.
        # This corrects heuristic false-negatives (e.g. tests passed but output had
        # the word "failed"). A high/medium-confidence PASS that cites evidence is a
        # genuine verification, so the step advances as semantic-verified.
        try:
            verdict = self._acceptance_semantic_judge(plan_step, gate, bb)
        except Exception:
            verdict = {"passed": False, "confidence": "low", "evidence": "", "rework_items": []}
        if verdict.get("passed") and str(verdict.get("confidence", "")).lower() in ("high", "medium"):
            note = (
                f"acceptance gate semantic-verified after {count} heuristic failures "
                f"(confidence={verdict.get('confidence')}): {trim(str(verdict.get('evidence', '') or ''), 200)}"
            )
            self._blackboard_append_memory("decision", note, actor="reviewer", tier="long", board=bb)
            self._emit("status", {"summary": "step verified by semantic judge (heuristic false-negative corrected)"})
            advanced = self._advance_plan_step(
                evidence=trim(f"[semantic-verified] {verdict.get('evidence', '')}", 200),
                actor=str(actor or "reviewer"),
            )
            if advanced:
                for _a in (attr, f"_acceptance_gate_nopro_n_{step_id}", f"_acceptance_gate_sig_{step_id}"):
                    try:
                        if hasattr(self, _a):
                            delattr(self, _a)
                    except Exception:
                        pass
                try:
                    self._inject_current_plan_step_execution_hints()
                except Exception:
                    pass
            return bool(advanced)

        # Step 3 — REAL FAILURE: enable reviewer-debug so a second role can fix directly.
        if self._is_multi_agent_mode() and not self.reviewer_debug_mode:
            self.reviewer_debug_mode = True
            self._blackboard_append_memory(
                "decision",
                f"acceptance gate failed {count}x on step; enabled reviewer-debug mode to actively diagnose and fix",
                actor="manager",
                tier="long",
                board=bb,
            )
            self._emit("status", {"summary": "acceptance gate failing — reviewer debug mode enabled to fix the blocker"})

        # Track repair progress: a changing signature means we are still making
        # headway; an unchanged signature means the loop is deadlocked.
        sig_attr = f"_acceptance_gate_sig_{step_id}"
        nopro_attr = f"_acceptance_gate_nopro_n_{step_id}"
        try:
            new_sig = self._repair_progress_signature(plan_step, gate, bb)
        except Exception:
            new_sig = ""
        prev_sig = str(getattr(self, sig_attr, "") or "")
        if new_sig and new_sig == prev_sig:
            no_progress = int(getattr(self, nopro_attr, 0) or 0) + 1
        else:
            no_progress = 0
        try:
            setattr(self, sig_attr, new_sig)
            setattr(self, nopro_attr, no_progress)
        except Exception:
            pass

        # Step 4 — TRUE DEADLOCK: only escalate to the user (never force-advance).
        if no_progress >= ACCEPTANCE_GATE_HARD_CEILING:
            verdict_items = verdict.get("rework_items") or []
            self._blackboard_append_memory(
                "decision",
                (
                    f"acceptance repair deadlocked ({no_progress} rounds with no progress) on step; "
                    f"escalating to plan-mode recovery for user decision. Outstanding: "
                    f"{trim('; '.join(verdict_items) or str(gate.get('reason', '')), 200)}"
                ),
                actor="manager",
                tier="long",
                board=bb,
            )
            self._ledger_record_stall("acceptance-gate-deadlock", "plan-mode-escalation")
            self._emit("status", {"summary": "acceptance repair deadlocked — escalating to recovery options for your decision"})
            try:
                escalated = self._escalate_stall_to_plan_mode(
                    "acceptance-gate-deadlock",
                    fault_counter=no_progress,
                    last_fault_reason=trim(str(gate.get("reason", "") or "acceptance-gate-deadlock"), 160),
                )
            except Exception:
                escalated = False
            if not escalated:
                # Plan-mode unavailable (e.g. user disabled it): keep the strongest
                # repair directive active rather than silently advancing.
                diagnosis = self._diagnose_acceptance_gate_failure(plan_step, gate, bb)
                self._seed_repair_directive(plan_step, diagnosis, bb, round_no=count)
            return False

        # Otherwise: diagnose root cause and seed a concrete repair directive, then
        # let the fixer act next turn. Repair continues unbounded while progressing.
        diagnosis = self._diagnose_acceptance_gate_failure(plan_step, gate, bb)
        if not self._seed_repair_directive(plan_step, diagnosis, bb, round_no=count):
            # Fall back to the standard rework hint if the directive was throttled.
            self._inject_acceptance_gate_rework_hint(plan_step, gate, target_roles=target_roles)
        return False

    def _step_has_accumulated_evidence(self, plan_step: dict, bb: dict | None = None) -> bool:
        """Check whether a step has accumulated candidate evidence across turns."""
        if not isinstance(plan_step, dict):
            return False
        step_text = str(plan_step.get("full_content", "") or plan_step.get("content", "") or "").lower()
        phase = self._plan_step_phase_hint(step_text)
        if phase in {"implement", "test", "review"}:
            return self._plan_step_has_blackboard_evidence(plan_step, bb)
        sig = self._plan_step_blackboard_signals(plan_step, bb)
        return sig["has_write"] or sig["has_exec"] or sig["has_research"]

    def _collect_accumulated_step_evidence(self, plan_step: dict, bb: dict | None = None) -> str:
        """Fix 1 support: Collect evidence summary from accumulated step history (across all turns)."""
        if not isinstance(plan_step, dict):
            return ""
        sig = self._plan_step_blackboard_signals(plan_step, bb)
        parts: list[str] = []
        if sig.get("recent_files"):
            parts.append("files: " + ", ".join(sig["recent_files"][:4]))
        if sig.get("recent_exec_excerpt"):
            parts.append("exec: " + trim(sig["recent_exec_excerpt"], 80))
        if sig.get("recent_research_excerpt"):
            parts.append("research: " + trim(sig["recent_research_excerpt"], 80))
        return trim("; ".join(parts) or "accumulated-step-evidence", 200)

    def _collect_blackboard_step_evidence(self, plan_step: dict, board: dict | None = None) -> str:
        sig = self._plan_step_blackboard_signals(plan_step, board)
        parts: list[str] = []
        if sig.get("recent_files"):
            parts.append("files: " + ", ".join(sig["recent_files"][:3]))
        if sig.get("recent_exec_excerpt"):
            parts.append(f"logs: {sig['recent_exec_excerpt']}")
        if sig.get("recent_review_excerpt"):
            parts.append(f"review: {sig['recent_review_excerpt']}")
        if sig.get("recent_research_excerpt"):
            parts.append(f"notes: {sig['recent_research_excerpt']}")
        return trim("; ".join(parts), 200)

    def _extract_plan_step_referenced_paths(self, text: object, *, limit: int = 24) -> list[str]:
        src = normalize_embedded_newlines(text)
        if not src:
            return []
        candidates: list[str] = []
        for match in re.finditer(r"`([^`]{1,260})`", src):
            candidates.append(str(match.group(1) or ""))
        candidates.extend(
            re.findall(
                r"(?<![\w./-])([A-Za-z0-9_.@+~-]+(?:/[A-Za-z0-9_.@+~ -]+)+)(?![\w./-])",
                src,
            )
        )
        out: list[str] = []
        deny_prefixes = {
            "python",
            "python3",
            "bash",
            "pytest",
            "grep",
            "find",
            "cat",
            "echo",
            "mkdir",
            "touch",
            "ls",
        }
        for raw in candidates:
            item = str(raw or "").strip().strip("'\"")
            if not item or "://" in item:
                continue
            if item.split(None, 1)[0].strip().lower() in deny_prefixes:
                continue
            if not ("/" in item or re.search(r"\.[A-Za-z0-9]{1,8}$", item)):
                continue
            rel = normalize_rel_preview_path(item.replace("\\", "/"))
            if not rel or self._is_plan_infrastructure_path(rel):
                continue
            if rel not in out:
                out.append(rel)
            if len(out) >= max(1, int(limit or 24)):
                break
        return out

    @staticmethod
    def _semantic_path_key(path_text: object) -> str:
        rel = normalize_rel_preview_path(str(path_text or "").replace("\\", "/")).lower()
        if not rel:
            return ""
        path = PurePosixPath(rel)
        stem = path.stem
        suffix = path.suffix.lower()
        parent = "/".join(path.parts[:-1])
        compact_parent = re.sub(r"[^a-z0-9\u4e00-\u9fff]+", "", parent)
        compact_stem = re.sub(r"[^a-z0-9\u4e00-\u9fff]+", "", stem)
        return f"{compact_parent}/{compact_stem}{suffix}"

    @staticmethod
    def _semantic_path_score(expected: str, actual: str) -> tuple[float, str]:
        exp = normalize_rel_preview_path(expected).lower()
        act = normalize_rel_preview_path(actual).lower()
        if not exp or not act:
            return 0.0, ""
        if exp == act:
            return 1.0, "exact"
        exp_path = PurePosixPath(exp)
        act_path = PurePosixPath(act)
        exp_key = SessionState._semantic_path_key(exp)
        act_key = SessionState._semantic_path_key(act)
        if exp_key and exp_key == act_key:
            return 0.96, "separator-insensitive path match"
        exp_stem = re.sub(r"[^a-z0-9\u4e00-\u9fff]+", "", exp_path.stem.lower())
        act_stem = re.sub(r"[^a-z0-9\u4e00-\u9fff]+", "", act_path.stem.lower())
        same_parent = exp_path.parent.as_posix() == act_path.parent.as_posix()
        same_suffix = exp_path.suffix.lower() == act_path.suffix.lower()
        if exp_stem and act_stem and same_parent and same_suffix:
            if exp_stem == act_stem:
                return 0.94, "separator-insensitive filename match"
            ratio = difflib.SequenceMatcher(None, exp_stem, act_stem).ratio()
            if ratio >= 0.76:
                return 0.72 + (ratio - 0.76) * 0.5, "similar filename in expected directory"
        exp_parts = set(re.findall(r"[a-z0-9\u4e00-\u9fff]+", exp_path.stem.lower()))
        act_parts = set(re.findall(r"[a-z0-9\u4e00-\u9fff]+", act_path.stem.lower()))
        if exp_parts and act_parts:
            overlap = len(exp_parts & act_parts) / max(1, len(exp_parts | act_parts))
            if same_parent and same_suffix and overlap >= 0.5:
                return 0.62 + overlap * 0.2, "token-overlap filename match"
        return 0.0, ""

    def _workspace_text_files_for_review(self, *, limit: int = 480) -> list[str]:
        rows: list[str] = []
        skip_dirs = {
            ".clouds_coder",
            ".git",
            "__pycache__",
            "node_modules",
            ".venv",
            "venv",
            "dist",
            "build",
        }
        text_suffixes = {
            ".md",
            ".txt",
            ".py",
            ".js",
            ".ts",
            ".tsx",
            ".jsx",
            ".json",
            ".yaml",
            ".yml",
            ".html",
            ".css",
            ".csv",
            ".toml",
        }
        try:
            for root, dirs, files in os.walk(self.files_root):
                dirs[:] = [d for d in dirs if d not in skip_dirs and not d.startswith(".")]
                for name in files:
                    if len(rows) >= max(1, int(limit or 480)):
                        return rows
                    if name.startswith("."):
                        continue
                    fp = Path(root) / name
                    if fp.suffix.lower() not in text_suffixes:
                        continue
                    try:
                        if fp.stat().st_size > 300_000:
                            continue
                        rel = self._session_rel(fp)
                    except Exception:
                        continue
                    if rel and not self._is_plan_infrastructure_path(rel):
                        rows.append(rel)
        except Exception:
            return rows
        return rows

    def _plan_step_quality_path_inference(
        self,
        plan_step: dict,
        known_paths: list[str],
        *,
        max_candidates: int = 10,
    ) -> dict:
        step_text = str((plan_step or {}).get("full_content", "") or (plan_step or {}).get("content", "") or "")
        expected_paths = self._extract_plan_step_referenced_paths(step_text)
        known = [
            normalize_rel_preview_path(str(p or ""))
            for p in (known_paths if isinstance(known_paths, list) else [])
            if normalize_rel_preview_path(str(p or ""))
        ]
        workspace_paths = self._workspace_text_files_for_review()
        search_paths = list(dict.fromkeys(known + workspace_paths))
        expected_rows: list[dict] = []
        semantic_candidates: list[dict] = []
        candidate_paths: list[str] = []
        for expected in expected_paths:
            exists = False
            try:
                exists = self._session_path(expected).exists()
            except Exception:
                exists = False
            scored: list[tuple[float, str, str]] = []
            for actual in search_paths:
                score, reason = self._semantic_path_score(expected, actual)
                if score >= 0.62:
                    scored.append((score, actual, reason))
            scored.sort(key=lambda row: row[0], reverse=True)
            candidates = [
                {"path": actual, "score": round(float(score), 3), "reason": reason}
                for score, actual, reason in scored[:4]
                if actual != expected or not exists
            ]
            expected_rows.append(
                {
                    "path": expected,
                    "exists": bool(exists),
                    "similar_existing": candidates,
                }
            )
            for score, actual, reason in scored[:4]:
                if actual not in candidate_paths:
                    candidate_paths.append(actual)
                semantic_candidates.append(
                    {
                        "expected": expected,
                        "actual": actual,
                        "score": round(float(score), 3),
                        "reason": reason,
                        "expected_exists": bool(exists),
                    }
                )
                if len(semantic_candidates) >= max(1, int(max_candidates or 10)):
                    break
        return {
            "expected_artifacts": expected_rows,
            "semantic_candidate_files": semantic_candidates[: max(1, int(max_candidates or 10))],
            "candidate_paths": candidate_paths[: max(1, int(max_candidates or 10))],
        }

    def _plan_step_quality_review_paths(self, plan_step: dict, worker_step: dict, bb: dict) -> list[str]:
        step_id = trim(str((plan_step or {}).get("id", "") or "").strip(), 80)
        since_ts = self._plan_step_activation_ts(plan_step)
        paths: list[str] = []

        def _add(raw: object):
            rel = normalize_rel_preview_path(str(raw or "").replace("\\", "/").strip()) or trim(
                str(raw or "").replace("\\", "/").strip(),
                300,
            )
            if not rel or self._is_plan_infrastructure_path(rel):
                return
            if rel not in paths:
                paths.append(rel)

        step_files = bb.get("step_files", {}) if isinstance(bb.get("step_files"), dict) else {}
        entries = step_files.get(step_id, []) if step_id and isinstance(step_files.get(step_id), list) else []
        for entry in entries[-20:]:
            if not isinstance(entry, dict):
                _add(entry)
                continue
            try:
                ts = float(entry.get("ts", 0.0) or 0.0)
            except Exception:
                ts = 0.0
            if since_ts > 0 and ts > 0 and ts + 1e-6 < since_ts:
                continue
            _add(entry.get("path", ""))

        artifacts = bb.get("code_artifacts", {}) if isinstance(bb.get("code_artifacts"), dict) else {}
        artifact_rows: list[tuple[float, str]] = []
        for path, meta in artifacts.items():
            if not isinstance(meta, dict):
                continue
            meta_step = str(meta.get("plan_step_id", "") or "").strip()
            try:
                ts = float(meta.get("updated_at", 0.0) or 0.0)
            except Exception:
                ts = 0.0
            if step_id and meta_step and meta_step != step_id:
                continue
            if not meta_step and since_ts > 0 and ts > 0 and ts + 1e-6 < since_ts:
                continue
            artifact_rows.append((ts, str(path or "")))
        for _ts, path in sorted(artifact_rows, reverse=True)[:8]:
            _add(path)

        for result in (worker_step or {}).get("tool_results", []) or []:
            if not isinstance(result, dict) or not result.get("ok", False):
                continue
            name = str(result.get("name", "") or "")
            args = result.get("args", {}) if isinstance(result.get("args"), dict) else {}
            if name in {"read_file", "write_file", "edit_file"}:
                _add(args.get("path", "") or args.get("file_path", ""))
            elif name in {"bash", "worktree_run", "background_run"}:
                for path in self._bash_file_read_targets(str(args.get("command", "") or ""))[:6]:
                    _add(path)
        path_inference = self._plan_step_quality_path_inference(plan_step, paths)
        for path in path_inference.get("candidate_paths", []) if isinstance(path_inference, dict) else []:
            _add(path)
        return paths[:8]

    def _plan_step_quality_file_excerpts(self, paths: list[str], *, max_files: int = 5, max_chars: int = 1600) -> list[dict]:
        excerpts: list[dict] = []
        for rel in paths[: max(1, int(max_files or 5))]:
            try:
                path = self._session_path(rel)
            except Exception:
                continue
            text = try_read_text(path, max_bytes=120_000)
            if text is None:
                continue
            excerpts.append({
                "path": rel,
                "excerpt": trim(text.replace("\r\n", "\n"), max_chars),
            })
        return excerpts

    def _plan_step_quality_recent_rows(
        self,
        bb: dict,
        section: str,
        plan_step: dict,
        *,
        limit: int = 6,
        max_chars: int = 500,
    ) -> list[dict]:
        rows = bb.get(section, []) if isinstance(bb.get(section), list) else []
        if not rows:
            return []
        step_id = trim(str((plan_step or {}).get("id", "") or "").strip(), 80)
        since_ts = self._plan_step_activation_ts(plan_step)
        matched: list[dict] = []
        fallback: list[dict] = []
        for row in rows[-40:]:
            if not isinstance(row, dict):
                continue
            txt = trim(str(row.get("content", "") or "").strip(), max_chars)
            if not txt:
                continue
            clean = {
                "actor": trim(str(row.get("actor", "") or "").strip(), 40),
                "content": txt,
            }
            try:
                ts = float(row.get("ts", 0.0) or 0.0)
            except Exception:
                ts = 0.0
            row_step = str(row.get("plan_step_id", "") or "").strip()
            if step_id and row_step == step_id:
                matched.append(clean)
            elif step_id and row_step and row_step != step_id:
                continue
            elif since_ts > 0 and ts > 0 and ts + 1e-6 >= since_ts:
                matched.append(clean)
            else:
                fallback.append(clean)
        if matched:
            return matched[-max(1, int(limit or 6)) :]
        if step_id:
            return []
        return fallback[-max(1, int(limit or 6)) :]

    def _build_plan_step_quality_review_context(
        self,
        plan_step: dict,
        worker_step: dict,
        bb: dict,
        candidate_evidence: dict | None = None,
    ) -> str:
        profile = self._ensure_blackboard_task_profile(bb)
        step_id = trim(str((plan_step or {}).get("id", "") or "").strip(), 80)
        step_text = trim(
            str((plan_step or {}).get("full_content", "") or (plan_step or {}).get("content", "") or "").strip(),
            1800,
        )
        rows = self._active_plan_worker_todo_rows(step_id, role="") if step_id else []
        subtasks = [
            {
                "status": trim(str(row.get("status", "") or "").strip(), 30),
                "owner": trim(str(row.get("owner", "") or "").strip(), 40),
                "content": trim(str(row.get("content", "") or "").strip(), 180),
            }
            for row in rows[:12]
            if isinstance(row, dict) and str(row.get("content", "") or "").strip()
        ]

        tool_rows: list[dict] = []
        for result in (worker_step or {}).get("tool_results", []) or []:
            if not isinstance(result, dict):
                continue
            name = trim(str(result.get("name", "") or "").strip(), 60)
            args = result.get("args", {}) if isinstance(result.get("args"), dict) else {}
            row = {
                "name": name,
                "ok": bool(result.get("ok", False)),
                "path": trim(str(args.get("path", "") or args.get("file_path", "") or "").strip(), 240),
                "command": trim(str(args.get("command", "") or "").strip(), 260),
                "output_excerpt": self._tool_result_output_excerpt(result, 260),
            }
            tool_rows.append(row)
            if len(tool_rows) >= 12:
                break

        paths = self._plan_step_quality_review_paths(plan_step, worker_step, bb)
        path_inference = self._plan_step_quality_path_inference(plan_step, paths)
        inferred_paths = [
            normalize_rel_preview_path(str(inferred_path or ""))
            for inferred_path in (path_inference.get("candidate_paths", []) if isinstance(path_inference, dict) else [])
            if normalize_rel_preview_path(str(inferred_path or ""))
        ]
        paths = list(dict.fromkeys(inferred_paths + paths))[:8]
        context = {
            "objective": trim(str(bb.get("original_goal", "") or self._latest_user_goal_text() or "").strip(), 2000),
            "direct_objective": trim(str(profile.get("direct_objective", self.runtime_direct_objective or "") or "").strip(), 900),
            "plan_step": {
                "id": step_id,
                "index": int((plan_step or {}).get("plan_step_index", -1) or -1),
                "text": step_text,
                "phase_hint": self._plan_step_phase_hint(step_text.lower()),
            },
            "candidate_evidence": candidate_evidence or {},
            "worker_reply": trim(str((worker_step or {}).get("text", "") or "").strip(), 1200),
            "tool_results": tool_rows,
            "subtasks": subtasks,
            "artifact_path_inference": {
                "expected_artifacts": path_inference.get("expected_artifacts", []) if isinstance(path_inference, dict) else [],
                "semantic_candidate_files": path_inference.get("semantic_candidate_files", []) if isinstance(path_inference, dict) else [],
                "review_instruction": (
                    "If an expected artifact path is missing but semantic_candidate_files contains near-equivalent files, "
                    "evaluate whether those files collectively satisfy the step's real deliverable. Treat naming drift as a "
                    "repairable artifact issue, not automatic failure, unless downstream compatibility or the user explicitly requires the exact path."
                ),
            },
            "recent_files": paths,
            "file_excerpts": self._plan_step_quality_file_excerpts(paths),
            "recent_execution_logs": self._plan_step_quality_recent_rows(bb, "execution_logs", plan_step),
            "recent_review_feedback": self._plan_step_quality_recent_rows(bb, "review_feedback", plan_step),
            "recent_research_notes": self._plan_step_quality_recent_rows(bb, "research_notes", plan_step, limit=4),
            "recent_errors": self._recent_error_context(max_chars=900),
        }
        return trim(json_dumps(context, indent=2), 12000)

