    def _has_test_pass_evidence(self, board: dict | None = None) -> bool:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        logs = bb.get("execution_logs", []) if isinstance(bb.get("execution_logs"), list) else []
        feedback = bb.get("review_feedback", []) if isinstance(bb.get("review_feedback"), list) else []
        positive = ("test passed", "tests passed", "测试通过", "运行正常",
                     "all tests pass", "ok", "passed", "test succeeded")
        negative = ("failed", "error", "failure", "测试失败")
        combined = list(logs[-6:]) + list(feedback[-4:])
        for entry in reversed(combined[-8:]):
            txt = str((entry or {}).get("content", "") or "").lower() if isinstance(entry, dict) else str(entry or "").lower()
            if not txt:
                continue
            if any(neg in txt for neg in negative):
                continue
            if any(pos in txt for pos in positive):
                return True
        return False

    def _update_project_todo_status(self, board: dict | None = None):
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        todos = bb.get("project_todos", [])
        if not todos:
            return
        code_count = len(bb.get("code_artifacts", {}) or {})
        research_count = len(bb.get("research_notes", []) or [])
        exec_count = len(bb.get("execution_logs", []) or [])
        feedback_pass = self._manager_feedback_passed_from_blackboard(bb)

        for todo in todos:
            if todo.get("status") == "completed":
                continue
            cat = todo.get("category", "")
            if cat == "plan_step" and todo.get("status") == "in_progress" and not todo.get("activated_at"):
                step_idx = int(todo.get("plan_step_index", 0) or 0)
                prior_done_ts = [
                    float(t.get("completed_at", 0.0) or 0.0)
                    for t in todos
                    if t.get("category") == "plan_step"
                    and int(t.get("plan_step_index", 0) or 0) < step_idx
                    and t.get("completed_at")
                ]
                todo["activated_at"] = (
                    max(prior_done_ts)
                    if prior_done_ts
                    else (float(todo.get("created_at", 0.0) or 0.0) or float(now_ts()))
                )
            if cat == "setup" and (research_count > 0 or code_count > 0):
                todo.update(
                    status="completed",
                    completed_at=float(now_ts()),
                    evidence=self._ui_text("evidence_structure_analyzed"),
                )
            elif cat == "implement" and code_count > 0 and (exec_count > 0 or feedback_pass):
                todo.update(
                    status="completed",
                    completed_at=float(now_ts()),
                    completed_by="developer",
                    evidence=trim(
                        f"{self._ui_text('evidence_files_produced', count=code_count)} + observable execution evidence",
                        200,
                    ),
                )
            elif cat == "compile_test" and self._has_compile_pass_evidence(bb):
                todo.update(
                    status="completed",
                    completed_at=float(now_ts()),
                    evidence=self._ui_text("evidence_compile_passed"),
                )
            elif cat == "min_test" and self._has_test_pass_evidence(bb):
                todo.update(
                    status="completed",
                    completed_at=float(now_ts()),
                    evidence=self._ui_text("evidence_test_passed"),
                )
            elif cat == "review" and feedback_pass:
                todo.update(
                    status="completed",
                    completed_at=float(now_ts()),
                    evidence=self._ui_text("evidence_review_passed"),
                )
            elif cat == "plan_step":
                # Plan steps are never auto-completed here; only _advance_plan_step
                # may close them. Activation of the next eligible step is deferred
                # to _normalize_plan_step_progress (called below) so this path uses
                # the exact same invariant as advance/restore.
                pass

        if not any(t.get("status") == "in_progress" for t in todos):
            for t in todos:
                if t.get("status") == "pending":
                    t["status"] = "in_progress"
                    if not t.get("activated_at"):
                        t["activated_at"] = float(now_ts())
                    break

        bb["project_todos"] = todos
        # Canonical plan-step invariant: single lowest-index active step + derived
        # cursor. Shared with advance/restore so all paths agree on "current step".
        self._normalize_plan_step_progress(bb)
        todos = bb.get("project_todos", todos)
        self.blackboard = bb

    # --- Step advancement inference ------------------------------------------
    # Decide whether manager/developer text is valid evidence that the current
    # plan step has already finished, rather than a forward-looking dispatch.
    def _instruction_implies_step_advance(self, instruction: str, reason: str = "") -> bool:
        """Detect if manager instruction semantically implies current plan step is done."""
        bb = self._ensure_blackboard()
        plan_steps = [t for t in bb.get("project_todos", []) if t.get("category") == "plan_step"]
        if not plan_steps:
            return False
        # Must have an in_progress step to advance
        current = None
        for t in plan_steps:
            if t.get("status") == "in_progress":
                current = t
                break
        if not current:
            return False
        text = (str(instruction or "") + " " + str(reason or "")).lower()
        # Completion evidence must be backward-looking: the text must state that
        # the current step already passed or finished.
        step_done_patterns = (
            "审查通过", "通过审查", "已通过", "已完成", "完成了",
            "step completed", "step done", "step passed",
            "阶段完成", "阶段通过", "phase complete",
            "步骤 1.1 已完成", "步骤 1.2 已完成", "步骤 1.3 已完成",
            "步骤 1.4 已完成", "步骤 1.5 已完成",
        )
        # Forward-looking dispatch phrases are intentionally excluded here.
        # "start/proceed to step ..." only routes work; it does not prove that
        # the current step completed successfully.
        import re
        current_idx = int(current.get("plan_step_index", 0) or 0)
        # Only treat "move to step N" as advancement evidence when it skips
        # beyond the immediate next step; otherwise it is likely normal routing.
        next_step_pattern = re.search(
            r'(?:进入|enter|move\s+to|start|proceed\s+to)\s*(?:step\s*)?(\d+)',
            text, re.IGNORECASE
        )
        if next_step_pattern:
            mentioned_step = int(next_step_pattern.group(1))
            if mentioned_step > current_idx + 2:  # must skip at least 2 ahead to be meaningful
                return True
        # Mixed phrases such as "finished current step, start next step" only
        # count when the completed step index matches the active step exactly.
        step_ref = re.search(r'(?:完成|finished|done)\s*步骤\s*1\.(\d+)', text)
        if step_ref:
            ref_sub = int(step_ref.group(1))
            if ref_sub == current_idx + 1:  # explicitly says current step (1-based) is done
                return True
        return any(pat in text for pat in step_done_patterns)

    def _normalize_plan_step_progress(self, bb: dict | None = None) -> dict:
        """Single authority for the plan-step progress invariant.

        Enforces, over all `plan_step` todos:
          - ordered by plan_step_index;
          - AT MOST one in_progress (if several, keep the lowest index, demote
            the rest to pending);
          - if NONE is in_progress, activate the lowest-index non-completed step;
          - plan_step_cursor is DERIVED from the active step's index (never an
            independent +1), and plan_step_total reflects the row count.

        This is the canonical rule shared by advance / reconcile / restore so the
        three paths can never disagree on "which step is current" (the cause of
        same-tick contradictory switch notices and step-skips). It NEVER marks a
        step completed — only advance does that. Returns the active step dict (or
        {} when all steps are done).
        """
        bb = bb if isinstance(bb, dict) else self._ensure_blackboard()
        todos = bb.get("project_todos", []) if isinstance(bb.get("project_todos"), list) else []
        plan_rows = [
            t for t in todos
            if isinstance(t, dict) and str(t.get("category", "") or "") == "plan_step"
        ]
        if not plan_rows:
            return {}
        plan_rows.sort(key=lambda r: int(r.get("plan_step_index", 0) or 0))

        # Collapse multiple in_progress down to the lowest-index one.
        active_rows = [r for r in plan_rows if str(r.get("status", "") or "") == "in_progress"]
        if len(active_rows) > 1:
            keep = min(active_rows, key=lambda r: int(r.get("plan_step_index", 0) or 0))
            keep_id = id(keep)
            for row in active_rows:
                if id(row) != keep_id:
                    row["status"] = "pending"
                    row["activated_at"] = None

        # If nothing is active, activate the lowest-index non-completed step.
        if not any(str(r.get("status", "") or "") == "in_progress" for r in plan_rows):
            nxt = next((r for r in plan_rows if str(r.get("status", "") or "") != "completed"), None)
            if nxt is not None:
                nxt["status"] = "in_progress"
                if not nxt.get("activated_at"):
                    nxt["activated_at"] = float(now_ts())

        active_step = next((r for r in plan_rows if str(r.get("status", "") or "") == "in_progress"), None)
        if active_step is not None:
            bb["plan_step_cursor"] = int(active_step.get("plan_step_index", 0) or 0)
        else:
            bb["plan_step_cursor"] = len(plan_rows)
        bb["plan_step_total"] = len(plan_rows)
        # Only adopt as the live blackboard when operating on it directly; callers
        # building a fresh board (e.g. _normalize_blackboard) manage assignment.
        if bb is getattr(self, "blackboard", None):
            self.blackboard = bb
        return active_step if isinstance(active_step, dict) else {}

    def _advance_plan_step(self, evidence: str = "", actor: str = "developer"):
        bb = self._ensure_blackboard()
        todos = bb.get("project_todos", [])
        if not todos:
            return False
        # Defensive: if plan-step state was corrupted (e.g. several in_progress at
        # once), normalize to the single lowest-index active step BEFORE deciding
        # what to complete, so we never advance off a dirty state.
        self._normalize_plan_step_progress(bb)
        todos = bb.get("project_todos", todos)
        current = None
        for t in todos:
            if t.get("category") == "plan_step" and t.get("status") == "in_progress":
                current = t
                break
        if not current:
            return False
        previous_focus = self._blackboard_focus_identity(bb)
        # Fix 5c: Reset TodoWrite loop counter on step advancement
        try:
            self._todowrite_step_counter.clear()
        except Exception:
            pass
        current["status"] = "completed"
        current["completed_at"] = float(now_ts())
        current["completed_by"] = actor
        current["evidence"] = trim(str(evidence or "").strip(), 200) or self._ui_text("step_completed_evidence")
        try:
            self._record_plan_step_result(current, evidence=evidence, actor=actor, board=bb)
            bb = self._ensure_blackboard()
            todos = bb.get("project_todos", todos)
        except Exception:
            pass
        # Clear single-mode validation gate flags for the completed step
        try:
            _completed_id = str(current.get("id", "") or "")
            for _attr_name in (f"_smvg_{_completed_id}", f"_smvg_ts_{_completed_id}", f"_smvg_n_{_completed_id}", f"_sync_exec_gate_n_{_completed_id}", f"_sync_sv_ts_{_completed_id}"):
                try:
                    delattr(self, _attr_name)
                except AttributeError:
                    pass
        except Exception:
            pass
        # Activate the next step via the canonical invariant: lowest-index
        # non-completed step becomes in_progress, cursor derived from its index.
        # (Never "first pending in list order" + independent cursor+1, which could
        # skip a step left in a non-pending state by a prior reconcile/rescue.)
        next_step = self._normalize_plan_step_progress(bb)
        next_step = next_step if isinstance(next_step, dict) and next_step else None
        if next_step:
            try:
                self._ensure_worker_todos_for_plan_step(next_step, force_refresh=False, owner=self._current_plan_worker_owner())
            except Exception:
                pass
            step_idx = int(next_step.get("plan_step_index", 0) or 0) + 1
            total = int(bb.get("plan_step_total", len(todos)) or len(todos))
            self._emit("status", {
                "summary": self._ui_text(
                    "plan_step_summary",
                    step=step_idx,
                    total=total,
                    content=trim(str(next_step.get("content", "") or ""), 120),
                )
            })
        new_focus = self._blackboard_focus_identity(bb)
        bb["focus"] = new_focus
        dq = self._normalize_decomposition_queue_state(bb.get("decomposition_queue", {}))
        if bool(dq.get("active", False)):
            dq_focus = str(dq.get("focus_id", "") or "")
            prev_id = str(previous_focus.get("id", "") or "")
            if (not dq_focus) or dq_focus == prev_id:
                dq["active"] = False
                dq["last_error"] = "deactivated because active plan step advanced"
                bb["decomposition_queue"] = dq
        bb["last_step_transition"] = {
            "from_focus_id": str(previous_focus.get("id", "") or ""),
            "to_focus_id": str(new_focus.get("id", "") or ""),
            "from_title": trim(str(previous_focus.get("title", "") or ""), 240),
            "to_title": trim(str(new_focus.get("title", "") or ""), 240),
            "actor": trim(str(actor or "").strip(), 40),
            "evidence": trim(str(evidence or "").strip(), 300),
            "ts": float(now_ts()),
        }
        self.blackboard = bb
        self._blackboard_touch()
        self._blackboard_append_memory(
            "step_transition",
            (
                f"plan step advanced from {trim(str(previous_focus.get('title', '') or ''), 160)} "
                f"to {trim(str(new_focus.get('title', '') or 'complete'), 160)}; "
                f"evidence={trim(str(evidence or ''), 180)}"
            ),
            actor=actor,
            tier="long",
        )
        # Persist step status change to plan.md
        try:
            self._update_plan_file_step_status()
        except Exception:
            pass  # Plan file update is best-effort
        # Close worker subtasks linked to the completed plan step. If the model
        # skipped detailed todo bookkeeping but the step was accepted by real
        # evidence, the UI should not keep stale pending/in_progress rows.
        completed_step_id = str(current.get("id", "") or "")
        try:
            _snap = self.todo.snapshot()
            _changed = False
            _closed_at = float(now_ts())
            for _row in _snap:
                if not isinstance(_row, dict):
                    continue
                if str(_row.get("parent_step_id", "") or "") != completed_step_id:
                    continue
                if str(_row.get("status", "") or "").lower() == "completed":
                    continue
                _row["status"] = "completed"
                _row["completed_at"] = _closed_at
                _row["completed_by"] = actor
                _row["evidence"] = trim(str(evidence or "closed with accepted plan step"), 200)
                _changed = True
            if _changed:
                with self.todo.lock:
                    self.todo.items = _snap
        except Exception:
            pass
        # Immediately sync todos so UI reflects plan step advancement
        _next_idx = int(next_step.get("plan_step_index", 0) or 0) + 1 if isinstance(next_step, dict) and next_step else int(bb.get("plan_step_cursor", 0) or 0)
        self._sync_todos_from_blackboard(reason=f"plan-step-advanced:{_next_idx}", board=bb)
        # Inject hint for the next step (works in both single and multi-agent mode).
        # Dedup against the last-hinted step id so one transition emits one notice.
        if next_step and str(getattr(self, "_last_step_hint_id", "") or "") != str(next_step.get("id", "") or ""):
            try:
                _ns_idx = int(next_step.get("plan_step_index", 0) or 0) + 1
                _ns_total = int(bb.get("plan_step_total", 0) or 0)
                _ns_text = trim(str(next_step.get("content", "") or ""), 200)
                _ns_id = str(next_step.get("id", "") or "")
                _ns_label = self._ui_text("plan_step_label", step=_ns_idx, total=_ns_total)
                _hint = self._ui_text(
                    "plan_step_hint",
                    step_label=_ns_label,
                    step_text=_ns_text,
                    plan_path=PLAN_FILE_RELATIVE_PATH,
                    parent_step_id=_ns_id,
                )
                target_roles: tuple[str, ...] = ()
                if self._is_multi_agent_mode():
                    active_role = str(bb.get("active_agent", "") or actor)
                    if active_role:
                        target_roles = (active_role,)
                if self._append_plan_guidance_bubble(
                    _hint,
                    target_roles=target_roles,
                    summary=f"plan step bubble injected ({_ns_idx}/{_ns_total})",
                ):
                    if _ns_id:
                        self._last_step_hint_id = _ns_id
            except Exception:
                pass
        return True

    def _plan_step_advance_decision(
        self, current: dict, evidence_input: dict, bb: dict, *, mode: str
    ) -> dict:
        """Single authority for the plan-step advance judgment shared by the
        single-agent and sync/multi-agent paths.

        Both callers previously computed the same evidence signals but combined
        them into DIFFERENT should-advance rules (single-agent: 2 paths + a
        `_gate_blocked` flag; sync: 5 OR'd paths). That divergence let the same
        step advance in one mode and stall in the other. This function computes
        the signals ONCE and applies ONE unified rule, so sync is a strict
        extension of single-agent. Callers keep only their own dispatch/role
        routing (single→"single"/developer; sync→route.target) and any
        manager-request bookkeeping.

        `mode` is "single" or "sync". `evidence_input` is the worker_step dict
        (sync) or {"tool_results": [...]} (single) — both expose `tool_results`
        and are accepted by the gate/evidence helpers unchanged.

        Returns: {should_advance, needs_repair, gate, gate_ok, reason, signals}.
        """
        results = (
            evidence_input.get("tool_results", []) or []
            if isinstance(evidence_input, dict)
            else []
        )
        step_content = str(
            current.get("full_content", "") or current.get("content", "") or ""
        ).lower()
        phase = self._plan_step_phase_hint(step_content)
        wrote_files = any(
            isinstance(r, dict)
            and r.get("ok", False)
            and str(r.get("name", "")) in ("write_file", "edit_file")
            for r in results
        )
        ran_bash_ok = any(
            isinstance(r, dict) and r.get("ok", False) and str(r.get("name", "")) == "bash"
            for r in results
        )
        validation_ok_current = self._tool_results_have_validation_evidence(current, results)
        validation_ok_blackboard = self._plan_step_has_blackboard_evidence(current, bb)
        validation_ok = validation_ok_current or validation_ok_blackboard
        # single-agent historically read the verified tag without the agent-message
        # window; sync passed messages=self.agent_messages. Preserve that.
        if mode == "sync":
            verified_tag_current = self._check_step_verified_tag(current, messages=self.agent_messages)
        else:
            verified_tag_current = self._check_step_verified_tag(current)
        bb_sig = self._plan_step_blackboard_signals(current, bb)
        phase_evidence = False
        if phase in ("research", "design") and validation_ok:
            phase_evidence = True
        elif phase == "implement" and (
            (wrote_files and validation_ok_current)
            or (bb_sig["has_write"] and validation_ok_blackboard)
        ):
            phase_evidence = True
        elif phase in ("test", "review") and (
            (ran_bash_ok and validation_ok_current)
            or ((bb_sig["has_exec"] or bb_sig["has_review"]) and validation_ok_blackboard)
        ):
            phase_evidence = True
        subtasks_all_done = self._step_subtasks_all_completed(current)
        _has_subtasks = bool(
            self._active_plan_worker_todo_rows(str(current.get("id", "") or ""), role="")
        )
        accumulated_evidence_path = subtasks_all_done and self._step_has_accumulated_evidence(
            current, bb
        )
        explicit_verified_path = (
            subtasks_all_done
            and verified_tag_current
            and (validation_ok_blackboard or self._step_has_accumulated_evidence(current, bb))
        )
        acceptance_gate = self._plan_step_acceptance_gate_status(current, evidence_input, bb)
        acceptance_gate_ok = bool(acceptance_gate.get("ok", False))
        worker_produced_output = self._worker_step_has_evidence(evidence_input)
        # Unified strong-evidence rule (superset of both prior rules): the
        # step-local subtask chain is complete, the final acceptance gate passed,
        # AND at least one concrete evidence form exists. Manager requests and
        # phase heuristics never bypass an incomplete subtask chain or a failed gate.
        should_advance = bool(
            subtasks_all_done
            and acceptance_gate_ok
            and (
                validation_ok
                or phase_evidence
                or accumulated_evidence_path
                or explicit_verified_path
            )
        )
        # Explicit structured-verification-tag path for subtask-complete steps.
        # It never bypasses missing step-local subtasks or a failed final gate.
        gate_blocked = bool(subtasks_all_done and not acceptance_gate_ok)
        if not should_advance and not gate_blocked:
            if (
                verified_tag_current
                and subtasks_all_done
                and (validation_ok or self._step_has_accumulated_evidence(current, bb))
            ):
                should_advance = True
        return {
            "should_advance": should_advance,
            "needs_repair": gate_blocked,
            "gate": acceptance_gate,
            "gate_ok": acceptance_gate_ok,
            "reason": str(acceptance_gate.get("reason", "") or ""),
            "signals": {
                "subtasks_all_done": subtasks_all_done,
                "has_subtasks": _has_subtasks,
                "worker_produced_output": worker_produced_output,
                "phase_evidence": phase_evidence,
                "validation_ok": validation_ok,
                "validation_ok_blackboard": validation_ok_blackboard,
                "verified_tag": verified_tag_current,
                "phase": phase,
            },
        }

    def _post_execution_plan_step_check(self, route: dict, worker_step: dict):
        """After worker execution, check if current plan step should advance based on evidence."""
        bb = self._ensure_blackboard()
        current = next(
            (t for t in bb.get("project_todos", [])
             if t.get("category") == "plan_step" and t.get("status") == "in_progress"),
            None,
        )
        if not current:
            # No plan steps — detect finish_current_task for pure-sync mode coordination.
            # Sets sync_worker_round_done flag so the sync loop can signal the manager.
            # Only reachable in pure sync mode (no plan steps); plan+sync always has `current`
            # set, so this branch never executes for plan modes.
            results = worker_step.get("tool_results", []) or []
            called_finish = any(
                isinstance(r, dict) and r.get("ok")
                and str(r.get("name", "")) in ("finish_current_task", "finish_task")
                for r in results
            )
            if called_finish:
                bb["sync_worker_round_done"] = True
                self._save_blackboard(bb)
            return
        if isinstance(route, dict) and route.get("focus_id") and not self._route_matches_active_focus(route, bb):
            self._blackboard_append_memory(
                "decision",
                "ignored post-execution plan advancement from a stale delegate focus",
                actor="manager",
                tier="long",
            )
            return
        # Parity with single-agent (Fix 1): bootstrap step-local subtasks when the
        # active step has none. Single-agent does this in _single_agent_plan_step_check
        # (:42564); multi-agent never did, so the acceptance gate's
        # "missing-step-local-subtasks" reason could never resolve and the run stalled
        # at step end. Auto-create the subtask chain so the gate has something to pass.
        _cur_step_id = str(current.get("id", "") or "")
        if _cur_step_id and not self._active_plan_worker_todo_rows(_cur_step_id, role=""):
            try:
                if self._ensure_worker_todos_for_plan_step(
                    current, force_refresh=False, owner=self._current_plan_worker_owner()
                ):
                    self._emit(
                        "status",
                        {"summary": "plan subtasks auto-created by runtime bootstrap (multi-agent)"},
                    )
            except Exception as exc:
                self._emit("status", {"summary": f"plan subtask bootstrap failed: {trim(str(exc), 120)}"})
        # Unified advance decision (Fix 1): shared authority with single-agent.
        manager_requested = bool(route.get("advance_plan_step_requested", False))
        decision = self._plan_step_advance_decision(current, worker_step, bb, mode="sync")
        has_strong_evidence = bool(decision["should_advance"])
        subtasks_all_done = bool(decision["signals"]["subtasks_all_done"])
        _has_subtasks = bool(decision["signals"]["has_subtasks"])
        worker_produced_output = bool(decision["signals"]["worker_produced_output"])
        acceptance_gate = decision["gate"]
        acceptance_gate_ok = bool(decision["gate_ok"])
        if manager_requested and worker_produced_output and not subtasks_all_done and _has_subtasks:
            self._blackboard_append_memory(
                "decision",
                "ignored plan advancement request because step-local subtasks are incomplete",
                actor="manager",
                tier="long",
            )
        if manager_requested and subtasks_all_done and not acceptance_gate_ok:
            self._blackboard_append_memory(
                "decision",
                (
                    "ignored plan advancement request because final acceptance subtask gate failed: "
                    f"{trim(str(acceptance_gate.get('reason', '') or ''), 160)}"
                ),
                actor="manager",
                tier="long",
            )
        if has_strong_evidence:
            evidence = self._collect_step_evidence(current, worker_step)
            # Clear sync exec gate counter on successful advance
            try:
                _sync_clear = f"_sync_exec_gate_n_{str(current.get('id', '') or '')}"
                if hasattr(self, _sync_clear):
                    delattr(self, _sync_clear)
            except Exception:
                pass
            self._advance_plan_step(
                evidence=evidence,
                actor=str(route.get("target", "developer") or "developer"),
            )
        else:
            if subtasks_all_done and not acceptance_gate_ok:
                target_role = self._sanitize_agent_role(str(route.get("target", "") or ""))
                # Drive diagnose→repair→re-verify; returns True only on a genuine
                # (semantic-verified) pass. Never force-advances.
                if self._acceptance_gate_handle_failure(
                    current,
                    acceptance_gate,
                    bb,
                    actor=str(route.get("target", "developer") or "developer"),
                    target_roles=((target_role,) if target_role else ()),
                ):
                    return  # step genuinely passed via semantic judge
            # Outcome-progress deadlock guard (Fix 6): runs every non-advancing
            # round regardless of whether subtasks are done, so a step that keeps
            # producing output but never improves its OUTCOME escalates instead
            # of looping forever.
            self._track_step_outcome_progress(current, bb, acceptance_gate)
            self._inject_rework_if_needed(current, worker_step)

    def _worker_step_has_evidence(self, step: dict) -> bool:
        """Check if worker step produced concrete tool outputs."""
        results = step.get("tool_results", []) or []
        return any(
            r.get("ok", False)
            and (
                str(r.get("name", "")) in (
                    "write_file", "edit_file", "bash",
                    "write_to_blackboard", "read_from_blackboard", "agent_web_search",
                    "query_code_library", "query_knowledge_library",
                )
                or (
                    str(r.get("name", "")) == "read_file"
                    and not self._is_plan_infrastructure_read_result(r)
                )
            )
            for r in results
            if isinstance(r, dict)
        )

    def _is_plan_infrastructure_read_result(self, result: dict) -> bool:
        if not isinstance(result, dict):
            return False
        if str(result.get("name", "") or "") != "read_file":
            return False
        args = result.get("args", {}) if isinstance(result.get("args"), dict) else {}
        path = str(args.get("path", "") or args.get("file_path", "") or "").replace("\\", "/")
        if not path:
            return False
        return (
            (path.endswith("plan.md") and ".clouds_coder/" in path)
            or ".clouds_coder/skills_cache/" in path
            or path.endswith("/.clouds_coder/skills_cache")
        )

    def _step_subtasks_all_completed(self, plan_step: dict) -> bool:
        """Check if all worker subtasks linked to this plan step are completed.
        Filters out cross-step subtasks (e.g., 2.1 under step 1) to prevent blocking.
        Fix 6: Also excludes 'next-step intent' items that were added alongside completed items."""
        step_id = str(plan_step.get("id", "") or "")
        if not step_id:
            return False
        worker_items = self._active_plan_worker_todo_rows(step_id, role="")
        if not worker_items:
            expected = self._extract_plan_step_subtasks(plan_step, limit=6)
            if expected:
                return False
            # Approved plan steps are executed through step-local worker
            # subtasks. If none exist yet, the bootstrap/LLM decomposition path
            # must run before this step can be considered complete.
            return False
        # Extract major step number from plan step content (e.g., "1. Project init" → "1")
        import re
        step_content = str(plan_step.get("full_content", "") or plan_step.get("content", "") or "")
        _m = re.match(r"^(\d+)\.", step_content.strip())
        active_major = _m.group(1) if _m else ""
        # Filter out cross-step subtasks (N.M where N != active major)
        if active_major:
            _cross_re = re.compile(r"^(\d+)\.\d+\s")
            relevant = []
            for r in worker_items:
                rc = str(r.get("content", "") or "").strip()
                cm = _cross_re.match(rc)
                if cm and cm.group(1) != active_major:
                    continue  # Skip cross-step items — don't let them block advancement
                relevant.append(r)
            if relevant:
                worker_items = relevant
        # Fix 6: Exclude "next-step intent" pending items when all other items are completed.
        # When the worker completes step N and creates step N+1 subtasks in the same TodoWrite call,
        # the new pending items get parent_step_id of step N, blocking its advancement.
        completed_items = [r for r in worker_items if str(r.get("status", "")).lower() == "completed"]
        pending_items = [r for r in worker_items if str(r.get("status", "")).lower() != "completed"]
        if completed_items and pending_items:
            expected_subtasks = self._extract_plan_step_subtasks(plan_step, limit=7)
            expected_ids: set[str] = set()
            for item in expected_subtasks:
                mm = re.match(r"^(\d+\.\d+)\b", str(item or "").strip())
                if mm:
                    expected_ids.add(mm.group(1))
            if expected_ids:
                completed_ids: set[str] = set()
                pending_expected: list[dict] = []
                for row in completed_items:
                    mm = re.match(r"^(\d+\.\d+)\b", str(row.get("content", "") or "").strip())
                    if mm:
                        completed_ids.add(mm.group(1))
                for row in pending_items:
                    mm = re.match(r"^(\d+\.\d+)\b", str(row.get("content", "") or "").strip())
                    if mm and mm.group(1) in expected_ids:
                        pending_expected.append(row)
                if expected_ids.issubset(completed_ids) and not pending_expected:
                    worker_items = completed_items
                    pending_items = []
            # Check if pending items are content-wise duplicates of completed items
            # (indicating the worker re-sent the same items but some got stuck as pending)
            completed_content = {
                normalize_work_text(str(r.get("content", ""))).strip().lower()
                for r in completed_items
                if str(r.get("content", "") or "").strip()
            }
            truly_new_pending = [
                r for r in pending_items
                if normalize_work_text(str(r.get("content", ""))).strip().lower() not in completed_content
            ]
            # If all pending items are duplicates of completed items, they don't block
            if not truly_new_pending:
                worker_items = completed_items
            # If there are truly new pending items but all original items are done,
            # check if the new items match future plan step content
            elif truly_new_pending and len(completed_items) >= 2:
                bb = self._ensure_blackboard()
                future_step_content = set()
                found_current = False
                for t in bb.get("project_todos", []):
                    if not isinstance(t, dict) or t.get("category") != "plan_step":
                        continue
                    if str(t.get("id", "") or "") == step_id:
                        found_current = True
                        continue
                    if found_current:
                        fc = str(t.get("full_content", "") or t.get("content", "") or "").strip().lower()
                        future_step_content.add(fc)
                        for line in fc.split("\n"):
                            sl = line.strip().lower()
                            if sl:
                                future_step_content.add(sl)
                if future_step_content:
                    _still_blocking = []
                    for pi in truly_new_pending:
                        pc = normalize_work_text(str(pi.get("content", ""))).strip().lower()
                        # Check if this pending item's content appears in any future step
                        is_future = any(pc in fsc or fsc in pc for fsc in future_step_content if len(fsc) > 4)
                        if not is_future:
                            _still_blocking.append(pi)
                    if not _still_blocking:
                        worker_items = completed_items
        all_marked_done = all(str(r.get("status", "")).lower() == "completed" for r in worker_items)
        if not all_marked_done:
            return False
        return True

    def _verify_subtasks_acceptance(self, subtasks: list[dict], step_id: str, bb: dict) -> list[str]:
        """Verify each completed subtask has real evidence. Returns list of unverified subtask descriptions.
        Checks step_files and execution_logs against what each subtask's content implies."""
        import re
        # Gather accumulated evidence for this step
        step_files_raw = bb.get("step_files", {}) if isinstance(bb.get("step_files"), dict) else {}
        step_entries = step_files_raw.get(step_id, []) if step_id and isinstance(step_files_raw.get(step_id), list) else []
        written_paths = set()
        for entry in step_entries:
            if isinstance(entry, dict) and str(entry.get("op", "")) in ("write_file", "edit_file"):
                written_paths.add(str(entry.get("path", "") or "").strip().lower())
        # Gather bash execution evidence
        exec_logs = bb.get("execution_logs", [])
        if not isinstance(exec_logs, list):
            exec_logs = []
        bash_outputs_lower = []
        for log in exec_logs[-30:]:
            if isinstance(log, dict):
                c = str(log.get("content", "") or "").lower()
                if c:
                    bash_outputs_lower.append(c)
        all_bash_text = " ".join(bash_outputs_lower)
        negative_hints = ("error:", "failed", "failure", "traceback", "fatal", "not found",
                          "no such file", "command not found", "permission denied")
        has_bash_failure = any(neg in all_bash_text for neg in negative_hints)
        # Define acceptance patterns from subtask content
        _file_create_re = re.compile(
            r"(?:创建|生成|编写|写入|create|write|generate|implement|scaffold)\s+(.+?)(?:\s|$|，|。|,|\()",
            re.IGNORECASE,
        )
        _run_test_kw = ("运行", "测试", "验证", "test", "pytest", "verify", "validate",
                        "run", "check", "确认", "检查")
        _compile_kw = ("编译", "构建", "compile", "build", "cmake", "make", "gcc", "gfortran")
        _install_kw = ("安装", "install", "pip install", "npm install", "apt install")
        unverified: list[str] = []
        for st in subtasks:
            content = str(st.get("content", "") or "").strip()
            if not content:
                continue
            content_lower = content.lower()
            # Rule 1: If subtask mentions creating a file, check it was actually written
            m = _file_create_re.search(content)
            if m:
                target = m.group(1).strip().strip("\"'`").lower()
                # Extract just filename from path-like strings
                if "/" in target:
                    target_parts = [p for p in target.split("/") if p.strip()]
                    target_name = target_parts[-1] if target_parts else target
                else:
                    target_name = target
                if target_name and len(target_name) > 2:
                    found = any(target_name in wp for wp in written_paths)
                    if not found:
                        unverified.append(f"file not created: {target_name}")
                        continue
            # Rule 2: If subtask mentions testing/running/verifying, check bash was executed
            if any(kw in content_lower for kw in _run_test_kw):
                if not bash_outputs_lower:
                    unverified.append(f"no bash execution for: {trim(content, 60)}")
                    continue
                # Check for test failures in recent bash output
                if has_bash_failure and any(kw in content_lower for kw in ("test", "测试", "pytest")):
                    # Only block if failure keywords appear near test-related content
                    test_related_failures = any(
                        ("test" in line or "pytest" in line or "assert" in line)
                        and any(neg in line for neg in negative_hints)
                        for line in bash_outputs_lower[-10:]
                    )
                    if test_related_failures:
                        unverified.append(f"test failures detected for: {trim(content, 60)}")
                        continue
            # Rule 3: If subtask mentions compiling/building, check bash + no compile errors
            if any(kw in content_lower for kw in _compile_kw):
                if not bash_outputs_lower:
                    unverified.append(f"no bash execution for compile: {trim(content, 60)}")
                    continue
                compile_failures = any(
                    any(neg in line for neg in ("error:", "failed", "failure"))
                    and any(kw in line for kw in ("compil", "build", "cmake", "make", "link"))
                    for line in bash_outputs_lower[-10:]
                )
                if compile_failures:
                    unverified.append(f"compile failures for: {trim(content, 60)}")
                    continue
            # Rule 4: If subtask mentions installing, check bash was run
            if any(kw in content_lower for kw in _install_kw):
                if not bash_outputs_lower:
                    unverified.append(f"no bash for install: {trim(content, 60)}")
                    continue
            # If none of the specific rules matched, the subtask is considered verified
            # (generic subtasks like "design" or "analyze" don't need tool evidence)
        return unverified

    def _inject_rework_if_needed(self, plan_step: dict, worker_step: dict):
        """When subtasks are marked completed but acceptance fails, inject rework instruction.
        Prevents the system from getting stuck or silently skipping unfinished work."""
        try:
            step_id = str(plan_step.get("id", "") or "")
            if not step_id:
                return
            rows = self._active_plan_worker_todo_rows(step_id, role="")
            completed_rows = [r for r in rows if str(r.get("status", "")).lower() == "completed"]
            if not completed_rows:
                return
            bb = self._ensure_blackboard()
            failures = self._verify_subtasks_acceptance(completed_rows, step_id, bb)
            if not failures:
                return
            # LLM-based acceptance check: semantic analysis over heuristics
            llm_verdict = self._llm_verify_subtask_acceptance(plan_step, completed_rows, bb)
            if llm_verdict.get("all_passed", False):
                return
            rework_items = llm_verdict.get("rework_items", failures)
            if not rework_items:
                return
            # Rate-limit rework injection
            _rework_key = f"_rework_injected_{step_id}"
            _last_rework = getattr(self, _rework_key, 0.0)
            if float(now_ts()) - float(_last_rework) < 30.0:
                return
            setattr(self, _rework_key, float(now_ts()))
            step_label = trim(str(plan_step.get("content", "") or ""), 80)
            rework_text = (
                f"<step-rework>\n"
                f"Step \"{step_label}\" acceptance check FAILED. "
                f"The following subtasks were marked completed but did not pass verification:\n"
            )
            for i, item in enumerate(rework_items[:5]):
                rework_text += f"  {i+1}. {trim(str(item), 120)}\n"
            rework_text += (
                "\nACTION REQUIRED: Fix these issues NOW before the step can advance.\n"
                "- For missing files: create them with write_file\n"
                "- For failed tests/builds: run the command again and fix errors\n"
                "- For unverified installs: re-run the install command\n"
                "After fixing, update TodoWrite to reflect the corrected state.\n"
                "</step-rework>"
            )
            # Revert false "completed" status back to in_progress
            _snap = self.todo.snapshot()
            _modified = False
            for row in _snap:
                if not isinstance(row, dict):
                    continue
                if str(row.get("parent_step_id", "") or "") != step_id:
                    continue
                if str(row.get("status", "")).lower() != "completed":
                    continue
                rc = str(row.get("content", "") or "").strip().lower()
                for fail in rework_items:
                    fail_lower = str(fail).lower()
                    if rc and (rc[:20] in fail_lower or any(w in fail_lower for w in rc.split()[:3] if len(w) > 3)):
                        row["status"] = "in_progress"
                        _modified = True
                        break
            if _modified:
                try:
                    self.todo.update(_snap)
                except Exception:
                    pass
            target_roles: tuple[str, ...] = ()
            if self._is_multi_agent_mode():
                active_role = str(bb.get("active_agent", "") or "developer")
                if active_role:
                    target_roles = (active_role,)
            self._append_plan_guidance_bubble(
                rework_text,
                target_roles=target_roles,
                summary=f"step rework: {len(rework_items)} items failed acceptance",
            )
        except Exception:
            pass

    def _llm_verify_subtask_acceptance(self, plan_step: dict, completed_subtasks: list[dict], bb: dict) -> dict:
        """Use LLM semantic analysis to verify if subtasks are truly completed.
        Returns {"all_passed": bool, "rework_items": list[str]}."""
        try:
            step_id = str(plan_step.get("id", "") or "")
            step_files_raw = bb.get("step_files", {}) if isinstance(bb.get("step_files"), dict) else {}
            step_entries = step_files_raw.get(step_id, []) if step_id else []
            files_summary = []
            for entry in (step_entries[-15:] if isinstance(step_entries, list) else []):
                if isinstance(entry, dict):
                    files_summary.append(f"{entry.get('op','?')}: {entry.get('path','?')}")
            exec_logs = bb.get("execution_logs", [])
            recent_exec = []
            for log in (exec_logs[-8:] if isinstance(exec_logs, list) else []):
                if isinstance(log, dict):
                    c = trim(str(log.get("content", "") or ""), 200)
                    if c:
                        recent_exec.append(c)
            subtask_list = "\n".join(
                f"- [{str(st.get('status','')).upper()}] {trim(str(st.get('content','') or ''), 120)}"
                for st in completed_subtasks[:8]
            )
            prompt = (
                "Analyze whether these subtasks are TRULY completed based on the evidence.\n\n"
                f"SUBTASKS:\n{subtask_list}\n\n"
                f"FILES CREATED/MODIFIED:\n{chr(10).join(files_summary[-10:]) or '(none)'}\n\n"
                f"RECENT EXECUTION OUTPUT:\n{chr(10).join(recent_exec[-5:]) or '(none)'}\n\n"
                "For each subtask, determine if it's genuinely done:\n"
                "- File creation tasks: was the file actually created?\n"
                "- Test/verify tasks: was a test/command actually run? Did it pass?\n"
                "- Build/compile tasks: was compilation attempted? Any errors?\n"
                "- Install tasks: was the install command run?\n\n"
                "Reply ONLY as JSON: {\"all_passed\": true/false, \"rework_items\": [\"description of what failed\"]}\n"
                "If all subtasks pass, return {\"all_passed\": true, \"rework_items\": []}"
            )
            resp = self.ollama.chat(
                [{"role": "user", "content": prompt}],
                system=self._inject_runtime_environment_context("You are a strict QA reviewer. Verify task completion against evidence. Reply ONLY valid JSON."),
                max_tokens=300,
                think=False,
            )
            import json
            text = str(resp.get("text", "") or "").strip()
            if "{" in text:
                json_str = text[text.index("{"):text.rindex("}") + 1]
                result = json.loads(json_str)
                if isinstance(result, dict):
                    return {
                        "all_passed": bool(result.get("all_passed", False)),
                        "rework_items": list(result.get("rework_items", [])),
                    }
        except Exception:
            pass
        return {"all_passed": False, "rework_items": []}

    def _acceptance_semantic_judge(
        self,
        plan_step: dict,
        gate: dict,
        bb: dict,
        worker_step: dict | None = None,
    ) -> dict:
        """Strict LLM judge that decides whether a step GENUINELY meets its
        acceptance criteria, used when the heuristic gate keeps failing.

        The heuristic gate (`_plan_step_acceptance_gate_status`) matches evidence
        by keyword and CAN false-negative (e.g. tests passed but output contains
        the word "failed" in a warning, or the worker used a different-but-valid
        check). This judge reads the ACTUAL evidence and renders a verdict, so a
        genuinely-complete step advances as semantic-verified rather than looping.
        It is intentionally strict: it must PASS only on concrete evidence, never
        on a completion claim. Returns:
          {passed: bool, confidence: "high"|"medium"|"low",
           evidence: str, rework_items: list[str]}
        """
        default = {"passed": False, "confidence": "low", "evidence": "", "rework_items": []}
        try:
            step_text = trim(
                normalize_embedded_newlines(
                    str(plan_step.get("full_content", "") or plan_step.get("content", "") or "")
                ),
                700,
            )
            step_id = str(plan_step.get("id", "") or "")
            guidance = {}
            try:
                guidance = self._plan_step_acceptance_guidance(plan_step)
            except Exception:
                guidance = {}
            gate_reason = trim(str((gate or {}).get("reason", "") or ""), 120)
            gate_expected = trim(str((gate or {}).get("expected", "") or ""), 160)
            # Quality bar (Fix 5): if the step has a measurable target, the judge
            # must check the measured result against it, not just "did a check run".
            target = {}
            try:
                target = self._resolve_acceptance_target(plan_step, (gate or {}).get("acceptance", {}))
            except Exception:
                target = {}
            bar_line = ""
            if target:
                bar_line = (
                    f"REQUIRED QUALITY BAR: {target.get('metric','target')} "
                    f"{target.get('op','<=')} {target.get('value')}{target.get('unit','')}. "
                    "PASS only if the measured result actually satisfies this bar; "
                    "a result that merely ran but misses the bar is a FAIL.\n"
                )

            # Acceptance subtask text (what the worker said it would verify).
            acceptance = (gate or {}).get("acceptance", {}) if isinstance((gate or {}).get("acceptance"), dict) else {}
            acceptance_text = trim(str(acceptance.get("content", "") or ""), 240)

            # Concrete evidence: files touched, execution logs, current tool results.
            step_files_raw = bb.get("step_files", {}) if isinstance(bb.get("step_files"), dict) else {}
            step_entries = step_files_raw.get(step_id, []) if step_id else []
            files_summary = [
                f"{entry.get('op','?')}: {entry.get('path','?')}"
                for entry in (step_entries[-15:] if isinstance(step_entries, list) else [])
                if isinstance(entry, dict)
            ]
            exec_logs = bb.get("execution_logs", []) if isinstance(bb.get("execution_logs"), list) else []
            recent_exec = []
            since_ts = self._plan_step_activation_ts(plan_step)
            for log in exec_logs[-10:]:
                if not isinstance(log, dict):
                    continue
                row_step_id = str(log.get("plan_step_id", "") or "")
                if row_step_id and row_step_id != step_id:
                    continue
                try:
                    log_ts = float(log.get("ts", 0.0) or 0.0)
                except Exception:
                    log_ts = 0.0
                if (not row_step_id) and since_ts > 0 and log_ts > 0 and log_ts + 1e-6 < since_ts:
                    continue
                c = trim(str(log.get("content", "") or ""), 240)
                if c:
                    recent_exec.append(c)
            cur_results = []
            if isinstance(worker_step, dict):
                for r in (worker_step.get("tool_results", []) or []):
                    if isinstance(r, dict) and r.get("ok", False):
                        nm = str(r.get("name", "") or "")
                        ex = self._tool_result_output_excerpt(r, 160)
                        cur_results.append(f"{nm}: {ex}" if ex else nm)

            prompt = (
                "A heuristic acceptance gate flagged this plan step as NOT verified, but the heuristic "
                "matches evidence by keyword and can be a FALSE NEGATIVE. As a strict QA judge, read the "
                "ACTUAL evidence below and decide whether the step genuinely meets its acceptance criteria.\n\n"
                f"PLAN STEP: {step_text}\n"
                f"ACCEPTANCE CHECK (what should be verified): {acceptance_text or guidance.get('what','')}\n"
                f"EXPECTED EVIDENCE KIND: {gate_expected or guidance.get('evidence_kind','')}\n"
                f"GATE FAILURE REASON: {gate_reason}\n"
                f"{bar_line}\n"
                f"FILES CREATED/MODIFIED FOR THIS STEP:\n{chr(10).join(files_summary[-12:]) or '(none)'}\n\n"
                f"EXECUTION OUTPUT (this step):\n{chr(10).join(recent_exec[-6:]) or '(none)'}\n\n"
                f"CURRENT-TURN TOOL RESULTS:\n{chr(10).join(cur_results[-6:]) or '(none)'}\n\n"
                "Decide STRICTLY:\n"
                "- PASS only if concrete evidence shows the step's deliverable exists AND is correct "
                "(e.g. file truly created with the right content; test/build actually ran and succeeded; "
                "exit code 0; research produced cited findings). A warning word like 'failed' inside "
                "otherwise-successful output is NOT a failure.\n"
                "- FAIL if the deliverable is missing, the check never ran, or evidence shows a real error.\n"
                "- Never PASS on a mere claim without evidence.\n\n"
                "Reply ONLY as JSON: "
                "{\"passed\": true/false, \"confidence\": \"high|medium|low\", "
                "\"evidence\": \"<cite the specific evidence you relied on>\", "
                "\"rework_items\": [\"<what concretely must still be fixed if FAIL>\"]}"
            )
            resp = self.ollama.chat(
                [{"role": "user", "content": prompt}],
                system=self._inject_runtime_environment_context(
                    "You are a strict, evidence-driven QA judge for plan-step acceptance. "
                    "You correct heuristic false-negatives but never rubber-stamp unproven claims. Reply ONLY valid JSON."
                ),
                max_tokens=400,
                think=False,
            )
            import json
            text = str(resp.get("content", "") or resp.get("text", "") or "").strip()
            if "{" in text and "}" in text:
                result = json.loads(text[text.index("{"):text.rindex("}") + 1])
                if isinstance(result, dict):
                    conf = str(result.get("confidence", "low") or "low").strip().lower()
                    if conf not in ("high", "medium", "low"):
                        conf = "low"
                    return {
                        "passed": bool(result.get("passed", False)),
                        "confidence": conf,
                        "evidence": trim(str(result.get("evidence", "") or ""), 300),
                        "rework_items": [trim(str(x), 200) for x in (result.get("rework_items", []) or [])][:6],
                    }
        except Exception:
            pass
        return default

    def _collect_step_evidence(self, plan_step: dict, worker_step: dict) -> str:
        """Collect evidence summary from worker step for plan step completion."""
        parts = []
        results = worker_step.get("tool_results", []) or []
        for r in results:
            if not isinstance(r, dict) or not r.get("ok", False):
                continue
            name = str(r.get("name", ""))
            if name in ("write_file", "edit_file"):
                path = str(r.get("args", {}).get("path", "") or "")
                parts.append(f"{name}: {path}")
            elif name == "bash":
                cmd = trim(str(r.get("args", {}).get("command", "") or ""), 80)
                out = self._tool_result_output_excerpt(r, 120)
                parts.append(f"bash: {cmd}" + (f" => {out}" if out else ""))
            elif name == "read_file":
                path = str(r.get("args", {}).get("path", "") or "")
                # Skip plan-infrastructure reads — not meaningful implementation evidence
                _p = str(path)
                if (_p.endswith("plan.md") and ".clouds_coder" in _p) or ".clouds_coder/skills_cache/" in _p:
                    continue
                out = self._tool_result_output_excerpt(r, 90)
                parts.append(f"read: {path}" + (f" => {out}" if out else ""))
            elif name in ("write_to_blackboard", "read_from_blackboard", "query_code_library", "query_knowledge_library", "agent_web_search"):
                out = self._tool_result_output_excerpt(r, 100)
                parts.append(f"{name}" + (f": {out}" if out else ""))
        if not parts:
            bb_evidence = self._collect_blackboard_step_evidence(plan_step)
            if bb_evidence:
                return bb_evidence
        return trim("; ".join(parts) or "post-execution evidence", 200)

    def _get_active_plan_step(self, board: dict | None = None) -> dict | None:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        todos = bb.get("project_todos", []) if isinstance(bb.get("project_todos", []), list) else []
        for todo in todos:
            if isinstance(todo, dict) and todo.get("category") == "plan_step" and todo.get("status") == "in_progress":
                return todo
        return None

    def _plan_step_ordinal(self, plan_step: dict | None, board: dict | None = None) -> int:
        """1-based ordinal N used as the prefix in worker subtasks 'N.M'.

        Derived from the step's plan_step_index (authoritative), falling back to
        the numeric suffix of a 'pt:NNN' id, then to the step's position among
        plan_step todos. Returns 1 when nothing is determinable so numbering is
        always present (never blank).
        """
        if not isinstance(plan_step, dict):
            return 1
        idx = plan_step.get("plan_step_index", None)
        try:
            if idx is not None and int(idx) >= 0:
                return int(idx) + 1
        except Exception:
            pass
        sid = str(plan_step.get("id", "") or "")
        m = re.match(r"^pt:(\d+)$", sid)
        if m:
            try:
                return int(m.group(1)) + 1
            except Exception:
                pass
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        todos = bb.get("project_todos", []) if isinstance(bb.get("project_todos"), list) else []
        pos = 0
        for todo in todos:
            if isinstance(todo, dict) and todo.get("category") == "plan_step":
                pos += 1
                if str(todo.get("id", "") or "") == sid:
                    return pos
        return 1

    def _current_plan_worker_owner(self, board: dict | None = None) -> str:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        delegate = bb.get("last_delegate", {}) if isinstance(bb.get("last_delegate"), dict) else {}
        candidates = [
            str(self.active_agent_role or "").strip().lower(),
            str(bb.get("active_agent", "") or "").strip().lower(),
            str(delegate.get("target", "") or "").strip().lower(),
        ]
        for cand in candidates:
            if cand in {"developer", "explorer", "reviewer"}:
                return cand
        return "developer"

    def _get_plan_step_by_id(self, step_id: str, board: dict | None = None) -> dict | None:
        step_key = trim(str(step_id or "").strip(), 40)
        if not step_key:
            return None
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        todos = bb.get("project_todos", []) if isinstance(bb.get("project_todos", []), list) else []
        for todo in todos:
            if (
                isinstance(todo, dict)
                and str(todo.get("category", "") or "") == "plan_step"
                and trim(str(todo.get("id", "") or "").strip(), 40) == step_key
            ):
                return todo
        return None

    def _plan_todo_compare_forms(self, text: object) -> set[str]:
        import re

        raw = normalize_embedded_newlines(normalize_work_text(str(text or "")) or str(text or "")).strip()
        if not raw:
            return set()
        first = next((ln.strip() for ln in raw.splitlines() if ln.strip()), raw)
        _status, parsed = split_todo_status_text(first)
        base = parsed or first
        forms: set[str] = set()

        def _clean(value: str) -> str:
            val = normalize_work_text(value) or value
            val = re.sub(r"\s+", " ", val.strip().lower())
            val = re.sub(r"^(?:[-*•]\s*)?(?:\[[x >_]\]\s*)+", "", val).strip()
            val = re.sub(r"^#+\s*", "", val).strip()
            return val

        current = _clean(base)
        while current and current not in forms:
            forms.add(current)
            stripped = re.sub(
                r"^(?:(?:step|步骤|步驟|阶段|階段)\s*)?\d+\s*[：:]\s*",
                "",
                current,
                flags=re.IGNORECASE,
            ).strip()
            stripped = re.sub(r"^(?:step|步骤|步驟|阶段|階段)\s*\d+[\.\)．、]\s*", "", stripped, flags=re.IGNORECASE).strip()
            stripped = re.sub(r"^\d+[\.\)．、]\s+", "", stripped).strip()
            stripped = _clean(stripped)
            if stripped == current:
                break
            current = stripped
        return {form for form in forms if len(form) >= 2}

    def _plan_worker_row_duplicates_parent_step(self, row: dict | None, plan_step: dict | None) -> bool:
        if not isinstance(row, dict) or not isinstance(plan_step, dict):
            return False
        content = normalize_embedded_newlines(str(row.get("content", "") or "")).strip()
        if not content or self._is_plan_step_acceptance_subtask(content):
            return False
        marker = self._plan_line_marker(content)
        if isinstance(marker, dict) and marker.get("kind") == "sub":
            return False
        step_texts = [
            str(plan_step.get("content", "") or ""),
            str(plan_step.get("full_content", "") or ""),
        ]
        step_forms: set[str] = set()
        for text in step_texts:
            if not text:
                continue
            step_forms.update(self._plan_todo_compare_forms(text))
            first = next((ln.strip() for ln in normalize_embedded_newlines(text).splitlines() if ln.strip()), "")
            if first:
                step_forms.update(self._plan_todo_compare_forms(first))
        row_forms = self._plan_todo_compare_forms(content)
        if not row_forms or not step_forms:
            return False
        if row_forms.intersection(step_forms):
            return True
        if isinstance(marker, dict) and marker.get("kind") == "major":
            try:
                row_major = int(marker.get("major", 0) or 0)
                step_index = int(plan_step.get("plan_step_index", -1) or -1) + 1
            except Exception:
                row_major = 0
                step_index = -1
            marker_title_forms = self._plan_todo_compare_forms(str(marker.get("title", "") or ""))
            if row_major > 0 and row_major == step_index and marker_title_forms.intersection(step_forms):
                return True
        return False

    def _filter_parent_step_duplicate_worker_rows(
        self,
        rows: list[dict],
        plan_step: dict | None,
    ) -> list[dict]:
        if not isinstance(rows, list) or not isinstance(plan_step, dict):
            return list(rows or [])
        return [
            dict(row)
            for row in rows
            if isinstance(row, dict) and not self._plan_worker_row_duplicates_parent_step(row, plan_step)
        ]

    def _active_plan_worker_todo_rows(self, step_id: str, role: str = "") -> list[dict]:
        step_key = str(step_id or "").strip()
        if not step_key:
            return []
        role_key = self._sanitize_agent_role(role)
        all_rows: list[dict] = []
        for row in self.todo.snapshot():
            if not isinstance(row, dict):
                continue
            if str(row.get("parent_step_id", "") or "").strip() != step_key:
                continue
            owner = str(row.get("owner", "") or "").strip().lower()
            if owner not in {"developer", "explorer", "reviewer"}:
                continue
            all_rows.append(dict(row))
        if not all_rows:
            return self._plan_worker_todo_rows_from_blackboard(step_key, role=role_key)
        plan_step = self._get_plan_step_by_id(step_key)
        all_rows = self._filter_parent_step_duplicate_worker_rows(all_rows, plan_step)
        rows = [r for r in all_rows if str(r.get("owner", "") or "").strip().lower() == role_key] if role_key else list(all_rows)
        if role_key and not rows:
            rows = list(all_rows)
        rows.sort(key=self._plan_worker_todo_sort_key)
        return rows

    def _plan_worker_todo_rows_from_blackboard(self, step_id: str, role: str = "", board: dict | None = None) -> list[dict]:
        step_key = trim(str(step_id or "").strip(), 40)
        if not step_key:
            return []
        bb = board if isinstance(board, dict) else (self.blackboard if isinstance(getattr(self, "blackboard", None), dict) else {})
        mirror = bb.get("plan_worker_todos", {}) if isinstance(bb.get("plan_worker_todos"), dict) else {}
        raw_rows = mirror.get(step_key, []) if isinstance(mirror.get(step_key), list) else []
        role_key = self._sanitize_agent_role(role)
        rows: list[dict] = []
        for row in raw_rows:
            if not isinstance(row, dict):
                continue
            owner = self._sanitize_agent_role(row.get("owner", "")) or "developer"
            if role_key and owner != role_key:
                continue
            raw_content = str(row.get("content", "") or "").strip()
            parsed_status, parsed_content = split_todo_status_text(raw_content)
            content = trim(normalize_work_text(parsed_content or raw_content) or (parsed_content or raw_content), 360)
            if not content:
                continue
            raw_status = str(row.get("status", "") or "").strip().lower().replace("-", "_").replace(" ", "_")
            status = self._normalize_todo_status_value(row.get("status", ""), parsed_status or "pending")
            if parsed_status and raw_status in {"", "todo", "pending"}:
                status = parsed_status
            if status == "blocked":
                status = "pending"
            rows.append({
                "content": content,
                "status": status,
                "owner": owner,
                "parent_step_id": step_key,
                "created_at": float(row.get("created_at", 0.0) or 0.0),
                "updated_at": float(row.get("updated_at", 0.0) or 0.0),
                "completed_at": float(row.get("completed_at", 0.0) or 0.0) if row.get("completed_at") else None,
                "completed_by": trim(str(row.get("completed_by", "") or ""), 40),
                "evidence": trim(str(row.get("evidence", "") or ""), 300),
            })
        plan_step = self._get_plan_step_by_id(step_key, bb)
        rows = self._filter_parent_step_duplicate_worker_rows(rows, plan_step)
        if role_key and not rows:
            return self._plan_worker_todo_rows_from_blackboard(step_key, role="", board=bb)
        rows.sort(key=self._plan_worker_todo_sort_key)
        return rows

    def _sync_plan_worker_todos_to_blackboard(
        self,
        step_id: str = "",
        *,
        rows: list[dict] | None = None,
        board: dict | None = None,
    ) -> bool:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        mirror = dict(bb.get("plan_worker_todos", {}) if isinstance(bb.get("plan_worker_todos"), dict) else {})
        worker_owners = {"developer", "explorer", "reviewer"}
        step_filter = trim(str(step_id or "").strip(), 40)
        src_rows = rows if isinstance(rows, list) else self.todo.snapshot()
        grouped: dict[str, list[dict]] = {}
        plan_step_cache: dict[str, dict | None] = {}
        for raw in src_rows:
            if not isinstance(raw, dict):
                continue
            owner = self._sanitize_agent_role(raw.get("owner", "")) or ""
            parent = trim(str(raw.get("parent_step_id", "") or "").strip(), 40)
            if owner not in worker_owners or not parent:
                continue
            if step_filter and parent != step_filter:
                continue
            raw_content = str(raw.get("content", "") or "").strip()
            parsed_status, parsed_content = split_todo_status_text(raw_content)
            content = trim(normalize_work_text(parsed_content or raw_content) or (parsed_content or raw_content), 360)
            if not content:
                continue
            raw_status = str(raw.get("status", "") or "").strip().lower().replace("-", "_").replace(" ", "_")
            status = self._normalize_todo_status_value(raw.get("status", ""), parsed_status or "pending")
            if parsed_status and raw_status in {"", "todo", "pending"}:
                status = parsed_status
            if status == "blocked":
                status = "pending"
            if parent not in plan_step_cache:
                plan_step_cache[parent] = self._get_plan_step_by_id(parent, bb)
            if self._plan_worker_row_duplicates_parent_step(
                {"content": content, "parent_step_id": parent, "owner": owner},
                plan_step_cache.get(parent),
            ):
                continue
            item = {
                "content": content,
                "status": status,
                "owner": owner,
                "parent_step_id": parent,
                "created_at": float(raw.get("created_at", 0.0) or 0.0),
                "updated_at": float(raw.get("updated_at", 0.0) or 0.0),
                "completed_at": float(raw.get("completed_at", 0.0) or 0.0) if raw.get("completed_at") else None,
                "completed_by": trim(str(raw.get("completed_by", "") or ""), 40),
                "evidence": trim(str(raw.get("evidence", "") or ""), 300),
            }
            grouped.setdefault(parent, []).append(item)
        target_steps = {step_filter} if step_filter else set(grouped.keys())
        if not step_filter:
            target_steps.update(
                trim(str(row.get("parent_step_id", "") or "").strip(), 40)
                for row in src_rows
                if isinstance(row, dict)
                and self._sanitize_agent_role(row.get("owner", "")) in worker_owners
                and str(row.get("parent_step_id", "") or "").strip()
            )
        changed = False
        for parent in sorted(x for x in target_steps if x):
            clean_rows = grouped.get(parent, [])
            if parent not in plan_step_cache:
                plan_step_cache[parent] = self._get_plan_step_by_id(parent, bb)
            clean_rows = self._filter_parent_step_duplicate_worker_rows(clean_rows, plan_step_cache.get(parent))
            clean_rows.sort(key=self._plan_worker_todo_sort_key)
            if clean_rows:
                if mirror.get(parent) != clean_rows:
                    mirror[parent] = clean_rows
                    changed = True
            elif parent in mirror:
                mirror.pop(parent, None)
                changed = True
        if changed:
            bb["plan_worker_todos"] = mirror
            bb["updated_at"] = float(now_ts())
            self.blackboard = bb
        return changed

    def _reconcile_plan_worker_todos_with_blackboard(
        self,
        step_id: str,
        *,
        board: dict | None = None,
    ) -> bool:
        step_key = trim(str(step_id or "").strip(), 20)
        if not step_key:
            return False
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        mirror_rows = self._plan_worker_todo_rows_from_blackboard(step_key, role="", board=bb)
        worker_owners = {"developer", "explorer", "reviewer"}
        plan_step = self._get_plan_step_by_id(step_key, bb)
        memory_rows = [
            dict(row) for row in self.todo.snapshot()
            if isinstance(row, dict)
            and str(row.get("owner", "") or "").strip().lower() in worker_owners
            and trim(str(row.get("parent_step_id", "") or "").strip(), 20) == step_key
        ]
        memory_rows = self._filter_parent_step_duplicate_worker_rows(memory_rows, plan_step)
        if not mirror_rows:
            mirror = bb.get("plan_worker_todos", {}) if isinstance(bb.get("plan_worker_todos"), dict) else {}
            raw_mirror = mirror.get(step_key, []) if isinstance(mirror.get(step_key), list) else []
            if raw_mirror or memory_rows:
                return self._sync_plan_worker_todos_to_blackboard(step_key, rows=memory_rows, board=bb)
            return False
        before = [
            (
                self._plan_worker_todo_identity(row),
                str(row.get("status", "") or "").strip().lower(),
                str(row.get("owner", "") or "").strip().lower(),
                trim(str(row.get("parent_step_id", "") or "").strip(), 20),
            )
            for row in memory_rows
        ]
        role_key = self._current_plan_worker_owner(bb)
        self._merge_plan_worker_todo_items(mirror_rows + memory_rows, role=role_key)
        after_rows = [
            dict(row) for row in self.todo.snapshot()
            if isinstance(row, dict)
            and str(row.get("owner", "") or "").strip().lower() in worker_owners
            and trim(str(row.get("parent_step_id", "") or "").strip(), 20) == step_key
        ]
        after_rows = self._filter_parent_step_duplicate_worker_rows(after_rows, plan_step)
        after = [
            (
                self._plan_worker_todo_identity(row),
                str(row.get("status", "") or "").strip().lower(),
                str(row.get("owner", "") or "").strip().lower(),
                trim(str(row.get("parent_step_id", "") or "").strip(), 20),
            )
            for row in after_rows
        ]
        return before != after

    def _active_plan_step_has_worker_todos(self, role: str = "") -> bool:
        step = self._get_active_plan_step()
        if not isinstance(step, dict):
            return False
        step_id = str(step.get("id", "") or "").strip()
        if not step_id:
            return False
        return bool(self._active_plan_worker_todo_rows(step_id, role=role))

    def _bridge_flat_todos_to_active_plan_step(
        self,
        rows: list[dict] | None,
        board: dict | None = None,
    ) -> tuple[list[dict], bool]:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        step = self._get_active_plan_step(bb)
        if not isinstance(step, dict):
            return (list(rows or []), False)
        step_id = trim(str(step.get("id", "") or ""), 20)
        if not step_id:
            return (list(rows or []), False)
        snap = [dict(row) for row in (rows or []) if isinstance(row, dict)]
        if not snap:
            return (snap, False)
        worker_owners = {"developer", "explorer", "reviewer"}
        if any(str(row.get("parent_step_id", "") or "").strip() for row in snap):
            return (snap, False)
        if any(
            str(row.get("owner", "") or "").strip().lower() in worker_owners
            and str(row.get("parent_step_id", "") or "").strip() == step_id
            for row in snap
        ):
            return (snap, False)
        owner_key = self._current_plan_worker_owner(bb)
        bridged: list[dict] = []
        migrated = False
        for row in snap:
            key = trim(str(row.get("key", "") or "").strip(), 120)
            if key.startswith("bb:"):
                bridged.append(dict(row))
                continue
            content = normalize_work_text(str(row.get("content", "") or "")) or str(row.get("content", "") or "").strip()
            if not content:
                continue
            new_row = dict(row)
            new_row["content"] = content
            new_row["parent_step_id"] = step_id
            owner = str(new_row.get("owner", "") or "").strip().lower()
            if owner not in worker_owners:
                new_row["owner"] = owner_key
            bridged.append(new_row)
            migrated = True
        return (bridged, migrated)

    def _active_plan_progress_snapshot(self, board: dict | None = None) -> dict:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        step = self._current_plan_step_row(bb)
        if not isinstance(step, dict):
            return {
                "step_id": "",
                "step_index": 0,
                "step_text": "",
                "expected_count": 0,
                "worker_todo_count": 0,
                "completed_count": 0,
                "in_progress_count": 0,
                "pending_count": 0,
                "current_subtask": "",
                "next_pending_subtask": "",
                "owners": [],
            }
        step_id = trim(str(step.get("id", "") or ""), 20)
        rows = self._active_plan_worker_todo_rows(step_id, role="") if step_id else []
        expected = self._extract_plan_step_subtasks(step, limit=6)
        completed_count = 0
        in_progress_count = 0
        pending_count = 0
        current_subtask = ""
        next_pending_subtask = ""
        owners: set[str] = set()
        for row in rows:
            status = str(row.get("status", "pending") or "pending").strip().lower()
            content = trim(str(row.get("content", "") or "").strip(), 220)
            owner = self._sanitize_agent_role(row.get("owner", ""))
            if owner:
                owners.add(owner)
            if status == "completed":
                completed_count += 1
            elif status == "in_progress":
                in_progress_count += 1
                if content and not current_subtask:
                    current_subtask = content
            else:
                pending_count += 1
                if content and not next_pending_subtask:
                    next_pending_subtask = content
        return {
            "step_id": step_id,
            "step_index": max(0, int(step.get("plan_step_index", 0) or 0)),
            "step_text": self._current_plan_step_text(bb),
            "expected_count": len(expected),
            "worker_todo_count": len(rows),
            "completed_count": completed_count,
            "in_progress_count": in_progress_count,
            "pending_count": pending_count,
            "current_subtask": current_subtask,
            "next_pending_subtask": next_pending_subtask,
            "owners": sorted(owners),
        }

    def _manager_worker_progress_capsule(self, role: str, step: dict, board: dict | None = None) -> str:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        role_key = self._sanitize_agent_role(role) or "developer"
        safe_step = step if isinstance(step, dict) else {}
        snapshot = self._active_plan_progress_snapshot(bb)
        tool_results = safe_step.get("tool_results", []) or []
        tool_names: list[str] = []
        for item in tool_results:
            if not isinstance(item, dict):
                continue
            name = str(item.get("name", "") or "").strip()
            if not name or name in tool_names:
                continue
            tool_names.append(name)
            if len(tool_names) >= 5:
                break
        parts = [
            f"[worker-progress] owner={role_key}",
            f"status={trim(str(safe_step.get('status', '') or ''), 40) or '-'}",
        ]
        if tool_names:
            parts.append("tools=" + ",".join(tool_names))
        step_text = trim(str(snapshot.get("step_text", "") or ""), 180)
        if step_text:
            parts.append(f"step={step_text}")
        todo_state = (
            f"todos={int(snapshot.get('completed_count', 0) or 0)}/"
            f"{int(snapshot.get('in_progress_count', 0) or 0)}/"
            f"{int(snapshot.get('pending_count', 0) or 0)}"
        )
        if int(snapshot.get("worker_todo_count", 0) or 0) > 0:
            parts.append(todo_state)
        focus = trim(str(snapshot.get("current_subtask", "") or ""), 160)
        if focus:
            parts.append(f"focus={focus}")
        elif str(snapshot.get("next_pending_subtask", "") or "").strip():
            parts.append(f"next={trim(str(snapshot.get('next_pending_subtask', '') or ''), 160)}")
        current_step = self._current_plan_step_row(bb)
        if isinstance(current_step, dict):
            evidence = self._collect_blackboard_step_evidence(current_step, bb)
            if evidence:
                parts.append(f"evidence={trim(evidence, 180)}")
            if self._step_subtasks_all_completed(current_step) and self._plan_step_acceptance_gate_passed(current_step, None, bb):
                parts.append("acceptance=ready")
        reply = bb.get("last_worker_reply", {}) if isinstance(bb.get("last_worker_reply"), dict) else {}
        if self._sanitize_agent_role(reply.get("role", "")) == role_key:
            reply_text = trim(str(reply.get("text", "") or "").strip(), 180)
            if reply_text:
                parts.append(f"reply={reply_text}")
        return trim(" | ".join(parts), 1600)

    def _manager_recovery_route_for_repeated_delegate(self, route: dict, board: dict | None = None) -> dict:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        row = dict(route or {})
        step = self._current_plan_step_row(bb)
        if not isinstance(step, dict):
            row["target"] = "developer"
            row["instruction"] = (
                "Recovery routing after repeated identical delegation. "
                "Continue the current objective with one concrete tool action and write observable progress."
            )
            row["reason"] = trim(f"{row.get('reason', '')}|loop-recovery-no-plan-step", 600)
            row["source"] = "loop-recovery"
            row["is_mandatory"] = True
            return row
        snapshot = self._active_plan_progress_snapshot(bb)
        step_text = trim(str(snapshot.get("step_text", "") or ""), 220)
        full_text = self._current_plan_step_full_text(bb, max_len=600)
        phase = self._plan_step_phase_hint(full_text)
        current_subtask = trim(str(snapshot.get("current_subtask", "") or ""), 180)
        next_pending = trim(str(snapshot.get("next_pending_subtask", "") or ""), 180)
        subtasks_done = self._step_subtasks_all_completed(step)
        has_evidence = self._plan_step_has_blackboard_evidence(step, bb)
        reviewer_available = True
        profile = self._ensure_blackboard_task_profile(bb)
        participants = profile.get("participants", []) if isinstance(profile.get("participants"), list) else []
        participants_norm = [self._sanitize_agent_role(x) for x in participants]
        participants_norm = [x for x in participants_norm if x]
        if participants_norm:
            reviewer_available = "reviewer" in participants_norm
        if subtasks_done and has_evidence and reviewer_available:
            row["target"] = "reviewer"
            row["instruction"] = trim(
                (
                    "Recovery routing after repeated identical delegation. "
                    f"Validate ONLY the current plan step: {step_text}. "
                    "Worker subtasks are complete and blackboard evidence already exists. "
                    "Run acceptance for this step only, record pass/fix with concrete evidence, and do not jump ahead."
                ),
                1200,
            )
            row["reason"] = trim(f"{row.get('reason', '')}|loop-recovery-acceptance", 600)
            row["source"] = "loop-recovery"
            row["is_mandatory"] = True
            return row
        default_owner = "explorer" if phase in {"research", "design"} else "developer"
        owner = self._sanitize_agent_role(row.get("target", "")) or self._current_plan_worker_owner(bb)
        if owner not in {"developer", "explorer"}:
            owner = default_owner
        if current_subtask:
            action_text = f"Continue ONLY the current in_progress subtask: {current_subtask}."
        elif next_pending:
            action_text = f"Resume the next pending subtask: {next_pending}."
        else:
            action_text = "Continue the current plan step with one concrete tool action."
        evidence_text = ""
        if has_evidence:
            evidence_text = (
                " Blackboard already contains partial evidence for this step; build on that work instead of restarting."
            )
        row["target"] = owner
        row["instruction"] = trim(
            (
                "Recovery routing after repeated identical delegation. "
                f"Stay on the current plan step: {step_text}. "
                f"{action_text} "
                "Do not branch to a different step or restate the whole plan. "
                "After the subtask is finished, immediately call TodoWrite to mark it completed and move the next subtask to in_progress."
                f"{evidence_text}"
            ),
            1200,
        )
        row["reason"] = trim(f"{row.get('reason', '')}|loop-recovery-execute", 600)
        row["source"] = "loop-recovery"
        row["is_mandatory"] = True
        return row

    def _todo_has_plan_steps(self, board: dict | None = None) -> bool:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        todos = bb.get("project_todos", []) if isinstance(bb.get("project_todos"), list) else []
        return any(
            isinstance(todo, dict) and todo.get("category") == "plan_step"
            for todo in todos
        )

    def _todo_worker_role_hint(self, role: str = "", board: dict | None = None) -> str:
        role_key = self._sanitize_agent_role(role)
        if role_key in {"developer", "explorer", "reviewer"}:
            return role_key
        return self._current_plan_worker_owner(board)

    def _todo_route_kind(self, role: str = "", board: dict | None = None) -> str:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        if self._todo_has_plan_steps(bb):
            return "plan_sync" if self._is_multi_agent_mode() else "plan_single"
        role_key = self._todo_worker_role_hint(role, bb)
        if self._is_multi_agent_mode() and role_key in {"developer", "explorer", "reviewer"}:
            return "pure_sync"
        return "pure_single"

    def _todo_row_kind(self, row: dict | None) -> str:
        if not isinstance(row, dict):
            return ""
        key = str(row.get("key", "") or "").strip()
        if key.startswith("bb:"):
            return "system"
        owner = str(row.get("owner", "") or "").strip().lower()
        parent_step_id = str(row.get("parent_step_id", "") or "").strip()
        if owner in {"developer", "explorer", "reviewer"} and parent_step_id:
            return "plan_worker"
        if owner in {"developer", "explorer", "reviewer"}:
            return "owner_worker"
        return "flat"

    def _normalize_todo_status_value(self, value: object, default: str = "pending") -> str:
        raw = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
        aliases = {
            "todo": "pending",
            "[_]": "pending",
            "[]": "pending",
            "[ ]": "pending",
            "doing": "in_progress",
            "working": "in_progress",
            "inprogress": "in_progress",
            "in_progress": "in_progress",
            "[>]": "in_progress",
            ">": "in_progress",
            "done": "completed",
            "finish": "completed",
            "finished": "completed",
            "[x]": "completed",
            "x": "completed",
        }
        status = aliases.get(raw, raw or default)
        if status in {"pending", "in_progress", "completed", "blocked"}:
            return status
        return default

    def _normalize_plan_worker_todo_input(
        self,
        item: object,
        *,
        step_id: str,
        role_key: str,
        default_status: str = "pending",
    ) -> dict:
        worker_owners = {"developer", "explorer", "reviewer"}
        step_key = trim(str(step_id or "").strip(), 20)
        owner_hint = self._sanitize_agent_role(role_key) or self._current_plan_worker_owner()
        if isinstance(item, str):
            raw: dict = {"content": item}
        elif isinstance(item, dict):
            raw = dict(item)
        else:
            raw = {"content": str(item or "").strip()}
        key = trim(str(raw.get("key", "") or "").strip(), 120)
        if key.startswith("bb:"):
            return raw
        raw_content = str(raw.get("content", raw.get("text", raw.get("title", ""))) or "").strip()
        parsed_status, parsed_content = split_todo_status_text(raw_content)
        content = normalize_work_text(parsed_content or raw_content) or (parsed_content or raw_content)
        content = trim(str(content or "").strip(), 500)
        if not content:
            return {}
        raw_status = str(raw.get("status", raw.get("state", "")) or "").strip()
        raw_status_key = raw_status.lower().replace("-", "_").replace(" ", "_")
        status = self._normalize_todo_status_value(raw_status, parsed_status or default_status)
        if parsed_status and raw_status_key in {"", "todo", "pending"}:
            status = parsed_status
        if status == "blocked":
            status = "pending"
        owner = self._sanitize_agent_role(raw.get("owner", "")) or owner_hint
        if owner not in worker_owners:
            owner = owner_hint
        parent_step_id = trim(str(raw.get("parent_step_id", "") or step_key), 20) or step_key
        row: dict = {
            "content": content,
            "status": status,
            "owner": owner,
        }
        if parent_step_id:
            row["parent_step_id"] = parent_step_id
        active_form = str(raw.get("activeForm", raw.get("active_form", "")) or "").strip()
        if active_form:
            row["activeForm"] = active_form
        for meta_key in ("created_at", "updated_at", "completed_at", "completed_by", "evidence"):
            if meta_key in raw and raw.get(meta_key) not in (None, ""):
                row[meta_key] = raw.get(meta_key)
        return row

    def _plan_worker_todo_sort_key(self, row: dict | None) -> tuple:
        import re

        if not isinstance(row, dict):
            return (9999, 9999, 9, 0.0, "")
        content = normalize_work_text(str(row.get("content", "") or "")) or str(row.get("content", "") or "")
        text = content.strip()
        low = text.lower()
        match = re.match(r"^(\d+)\.(\d+)\b", low)
        if match:
            major = int(match.group(1))
            minor = int(match.group(2))
        elif self._is_plan_step_acceptance_subtask(text):
            major = 9998
            minor = 9998
        else:
            major = 9999
            minor = 9999
        status_order = {"completed": 0, "in_progress": 1, "pending": 2, "blocked": 3}
        status = self._normalize_todo_status_value(row.get("status", ""), "pending")
        try:
            created_at = float(row.get("created_at", 0.0) or 0.0)
        except Exception:
            created_at = 0.0
        return (
            major,
            minor,
            status_order.get(status, 9),
            created_at,
            str(row.get("owner", "") or "").strip().lower(),
            low,
        )

    def _todo_route_rows(
        self,
        route_kind: str,
        *,
        rows: list[dict] | None = None,
        role: str = "",
        board: dict | None = None,
    ) -> list[dict]:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        snap = [dict(row) for row in (rows if isinstance(rows, list) else self.todo.snapshot()) if isinstance(row, dict)]
        if route_kind in {"plan_single", "plan_sync"}:
            step = self._get_active_plan_step(bb)
            step_id = trim(str((step or {}).get("id", "") or ""), 20)
            if not step_id:
                return []
            return [
                row for row in snap
                if self._todo_row_kind(row) == "plan_worker"
                and str(row.get("parent_step_id", "") or "").strip() == step_id
            ]
        if route_kind == "pure_sync":
            role_key = self._todo_worker_role_hint(role, bb)
            owner_rows = [row for row in snap if self._todo_row_kind(row) == "owner_worker"]
            if role_key in {"developer", "explorer", "reviewer"}:
                scoped = [
                    row for row in owner_rows
                    if str(row.get("owner", "") or "").strip().lower() == role_key
                ]
                if scoped:
                    return scoped
            return owner_rows
        if route_kind == "pure_single":
            return [row for row in snap if self._todo_row_kind(row) == "flat"]
        return []

    def _filter_plan_fragment_todo_rows(self, rows: list[dict]) -> list[dict]:
        if not isinstance(rows, list) or len(rows) <= 1:
            return list(rows or [])
        out: list[dict] = []
        expected = 1
        candidate_count = len(rows)
        for row in rows:
            if not isinstance(row, dict):
                continue
            content = normalize_embedded_newlines(row.get("content", "") or "").strip()
            marker = self._plan_line_marker(content)
            if self._plan_marker_is_sequence_outlier(
                marker,
                expected_number=expected,
                candidate_count=candidate_count,
            ):
                continue
            out.append(row)
            if isinstance(marker, dict) and marker.get("kind") == "major":
                number = int(marker.get("major", expected) or expected)
                if number >= expected:
                    expected = number + 1
        return out

    def _todo_runtime_has_worker_rows(self, role: str = "") -> bool:
        route_kind = self._todo_route_kind(role=role)
        return bool(self._todo_route_rows(route_kind, role=role))

    def _merge_todo_signal_rows(self, items: list[dict], role: str = "", board: dict | None = None) -> str:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        role_key = self._sanitize_agent_role(role)
        route_kind = self._todo_route_kind(role=role_key, board=bb)
        step = self._get_active_plan_step(bb) if route_kind in {"plan_single", "plan_sync"} else None
        step_id = trim(str((step or {}).get("id", "") or ""), 20)
        normalized: list[dict] = []
        for item in items or []:
            if not isinstance(item, dict):
                continue
            row = dict(item)
            if role_key in {"developer", "explorer", "reviewer"} and not str(row.get("owner", "") or "").strip():
                row["owner"] = role_key
            if step_id and not str(row.get("parent_step_id", "") or "").strip():
                row["parent_step_id"] = step_id
            normalized.append(row)
        if not normalized:
            return self.todo.no_changes_text()
        if route_kind in {"plan_single", "plan_sync"}:
            return self._merge_plan_worker_todo_items(normalized, role=role_key)
        if route_kind == "pure_sync":
            return self._merge_owner_scoped_todo_items(normalized, role=role_key)
        return self._merge_flat_todo_items(normalized, role=role_key)

    def _plan_worker_todo_identity(self, row: dict | None) -> str:
        import re

        if not isinstance(row, dict):
            return ""
        content = normalize_work_text(str(row.get("content", "") or "")) or str(row.get("content", "") or "")
        content = re.sub(r"\s+", " ", content.strip().lower())
        if not content:
            return ""
        parent_step_id = trim(str(row.get("parent_step_id", "") or "").strip(), 40)
        if parent_step_id and self._is_plan_step_acceptance_subtask(content):
            return f"acceptance:{parent_step_id}"
        match = re.match(r"^(\d+\.\d+)\b", content)
        if match:
            return f"substep:{match.group(1)}"
        return f"text:{content}"

    def _flat_todo_identity(self, row: dict | None) -> str:
        import re

        if not isinstance(row, dict):
            return ""
        key = trim(str(row.get("key", "") or "").strip(), 120)
        if key.startswith("bb:"):
            return f"system:{key}"
        content = normalize_work_text(str(row.get("content", "") or "")) or str(row.get("content", "") or "")
        content = re.sub(r"\s+", " ", content.strip().lower())
        if not content:
            return ""
        match = re.match(r"^(\d+\.\d+)\b", content)
        if match:
            return f"substep:{match.group(1)}"
        return f"text:{content}"

    def _merge_flat_todo_items(self, items: list[dict], role: str = "") -> str:
        if not isinstance(items, list):
            raise ValueError("items must be array")
        role_key = self._sanitize_agent_role(role)
        existing = self.todo.snapshot()
        route_existing = self._todo_route_rows("pure_single", rows=existing, role=role_key)
        existing_by_identity: dict[str, dict] = {}
        preserved_system: list[dict] = []
        for row in existing:
            if self._todo_row_kind(row) != "system":
                continue
            preserved_system.append(dict(row))
        for row in route_existing:
            if not isinstance(row, dict):
                continue
            identity = self._flat_todo_identity(row)
            if not identity:
                continue
            if identity not in existing_by_identity:
                existing_by_identity[identity] = dict(row)

        status_alias = {
            "todo": "pending",
            "[_]": "pending",
            "[]": "pending",
            "[ ]": "pending",
            "doing": "in_progress",
            "inprogress": "in_progress",
            "in-progress": "in_progress",
            "[>]": "in_progress",
            ">": "in_progress",
            "done": "completed",
            "finish": "completed",
            "finished": "completed",
            "[x]": "completed",
            "x": "completed",
        }
        passthrough_rows: list[dict] = []
        merged_rows: list[dict] = []
        seen_identities: set[str] = set()
        for idx, item in enumerate(items):
            if isinstance(item, str):
                raw = {"content": item}
            elif isinstance(item, dict):
                raw = dict(item)
            else:
                raise ValueError(f"item {idx}: invalid type")
            key = trim(str(raw.get("key", "") or "").strip(), 120)
            if key.startswith("bb:"):
                passthrough_rows.append(raw)
                continue
            raw_content = str(raw.get("content", raw.get("text", raw.get("title", "")))).strip()
            content = normalize_work_text(raw_content) or raw_content
            if not content:
                continue
            normalized: dict[str, object] = {"content": content}
            raw_status = str(raw.get("status", raw.get("state", "")) or "").strip().lower()
            if raw_status:
                normalized["status"] = status_alias.get(raw_status, raw_status)
            owner = str(raw.get("owner", "") or "").strip().lower()
            if owner in {"manager", "explorer", "developer", "reviewer"}:
                normalized["owner"] = owner
            elif role_key == "manager" and owner == "":
                normalized["owner"] = role_key
            active_form = str(raw.get("activeForm", raw.get("active_form", "")) or "").strip()
            if active_form:
                normalized["activeForm"] = active_form
            identity = self._flat_todo_identity(normalized)
            if not identity:
                identity = f"ad-hoc:{idx}:{trim(content, 80)}"
            merged = dict(existing_by_identity.get(identity, {}))
            if "activeForm" not in normalized:
                merged.pop("activeForm", None)
            merged.update(normalized)
            if identity in seen_identities:
                continue
            seen_identities.add(identity)
            merged_rows.append(merged)
        return self.todo.update(preserved_system + passthrough_rows + merged_rows)

    # --- Active-step worker todo reconciliation -------------------------------
    # Merge worker-submitted subtasks into the active plan step while
    # preserving canonical identities and preventing duplicate rewrites.
    def _merge_plan_worker_todo_items(self, items: list[dict], role: str = "") -> str:
        if not isinstance(items, list):
            raise ValueError("items must be array")
        active_step = self._get_active_plan_step()
        if not isinstance(active_step, dict):
            return self.todo.update(items)
        step_id = trim(str(active_step.get("id", "") or ""), 20)
        if not step_id:
            return self.todo.update(items)
        role_key = self._sanitize_agent_role(role) or self._current_plan_worker_owner()
        existing = self.todo.snapshot()
        preserved: list[dict] = []
        target_rows: list[dict] = []
        worker_owners = {"developer", "explorer", "reviewer"}
        for row in existing:
            if not isinstance(row, dict):
                continue
            row_kind = self._todo_row_kind(row)
            if row_kind == "system":
                preserved.append(dict(row))
                continue
            if row_kind != "plan_worker":
                continue
            owner = str(row.get("owner", "") or "").strip().lower()
            row_step_id = trim(str(row.get("parent_step_id", "") or ""), 20)
            if owner in worker_owners and row_step_id == step_id:
                target_rows.append(dict(row))
            else:
                preserved.append(dict(row))

        merged_by_identity: dict[str, dict] = {}
        ordered_identities: list[str] = []
        # Fix 2: Compute existing identities for next-step detection
        _existing_identities: set[str] = set()
        for row in target_rows:
            identity = self._plan_worker_todo_identity(row)
            if not identity:
                continue
            _existing_identities.add(identity)
            if identity not in merged_by_identity:
                merged_by_identity[identity] = dict(row)
                ordered_identities.append(identity)

        # Build a reverse map from normalized core content to canonical
        # identity so free-text restatements collapse onto existing subtasks.
        import re as _re_todo
        _core_to_identity: dict[str, str] = {}
        for row in target_rows:
            identity = self._plan_worker_todo_identity(row)
            if not identity:
                continue
            raw_c = normalize_work_text(str(row.get("content", "") or ""))
            core_c = _re_todo.sub(r"^\d+\.\d+\s+", "", raw_c)  # strip "N.M " prefix
            core_c = _re_todo.sub(r"\s*\([^)]{0,120}\)\s*$", "", core_c)  # strip " (...)" suffix
            core_c = _re_todo.sub(r"\s+", " ", core_c.strip().lower())
            if core_c and len(core_c) >= 4:
                _core_to_identity.setdefault(core_c, identity)

        incoming_normalized: list[dict] = []
        for idx, item in enumerate(items):
            if not isinstance(item, (str, dict)):
                raise ValueError(f"item {idx}: invalid type")
            raw = self._normalize_plan_worker_todo_input(
                item,
                step_id=step_id,
                role_key=role_key,
                default_status="pending",
            )
            if not raw:
                continue
            key = trim(str(raw.get("key", "") or "").strip(), 120)
            if key.startswith("bb:"):
                incoming_normalized.append(raw)
                continue
            parent_step_id = trim(str(raw.get("parent_step_id", "") or ""), 20)
            if not parent_step_id:
                raw["parent_step_id"] = step_id
            if self._plan_worker_row_duplicates_parent_step(raw, active_step):
                continue
            incoming_normalized.append(raw)

        passthrough_rows = [row for row in incoming_normalized if str(row.get("key", "") or "").startswith("bb:")]
        incoming_worker_rows = [row for row in incoming_normalized if not str(row.get("key", "") or "").startswith("bb:")]

        for row in incoming_worker_rows:
            identity = self._plan_worker_todo_identity(row)
            if not identity:
                identity = f"ad-hoc:{len(ordered_identities)}:{trim(str(row.get('content', '') or ''), 80)}"
            # Allow free-text items to resolve onto numbered substeps when the
            # normalized core content already exists under a canonical identity.
            if identity.startswith("text:") and identity not in merged_by_identity:
                text_core = identity[5:]
                # Also try without a leading "N.M " numbering prefix
                stripped_core = _re_todo.sub(r"^\d+\.\d+\s+", "", text_core).strip()
                for check_core in [text_core, stripped_core]:
                    if check_core in _core_to_identity:
                        identity = _core_to_identity[check_core]
                        break
            merged = dict(merged_by_identity.get(identity, {}))
            row_existed = bool(merged)
            prev_owner = self._sanitize_agent_role(merged.get("owner", ""))
            prev_status = self._normalize_todo_status_value(merged.get("status", ""), "")
            incoming_status = self._normalize_todo_status_value(row.get("status", ""), "pending")
            if "activeForm" not in row and "active_form" not in row:
                merged.pop("activeForm", None)
            prev_content = str(merged.get("content", "") or "")
            # Preserve completion attribution BEFORE the blanket update so a bare
            # cross-role re-mark can't drop it (F12).
            prev_completion = {
                k: merged.get(k)
                for k in ("completed_at", "completed_by", "evidence", "updated_at")
                if merged.get(k) not in (None, "")
            }
            merged.update(row)
            if incoming_status:
                merged["status"] = incoming_status
            # Step-local progress is monotonic. A compact/resume or role change
            # may cause a worker to resend the whole subtask list from 4.1, but
            # that must not reopen completed work or demote the active subtask.
            if prev_status == "completed" and incoming_status != "completed":
                merged["status"] = "completed"
                for field in ("completed_at", "completed_by", "evidence", "updated_at"):
                    if field in merged_by_identity.get(identity, {}) and field not in row:
                        merged[field] = merged_by_identity[identity].get(field)
                if prev_content and len(prev_content) > len(str(row.get("content", "") or "")):
                    merged["content"] = prev_content
            elif prev_status == "in_progress" and incoming_status == "pending":
                merged["status"] = "in_progress"
                if prev_content and len(prev_content) > len(str(row.get("content", "") or "")):
                    merged["content"] = prev_content
            # F12: owner is a property of who OWNS the subtask (its creator/worker),
            # NOT of whoever last touched the row. A reviewer re-marking the
            # developer's acceptance row must not flip its owner dev→reviewer —
            # that flip made _sync_plan_worker_todos_to_blackboard see a spurious
            # diff and re-write the mirror every cross-role turn (redundant
            # TodoWrite churn). Preserve the existing owner; only a genuinely new
            # row takes the writer's role.
            if row_existed and prev_owner:
                merged["owner"] = prev_owner
            else:
                merged["owner"] = str(merged.get("owner", "") or role_key).strip().lower() or role_key
            # F12: when an already-completed row is re-affirmed completed without
            # fresh attribution, keep the original completed_by/at/evidence so the
            # row stays byte-identical (no spurious mirror diff, no lost credit).
            if prev_status == "completed" and incoming_status == "completed":
                for field, val in prev_completion.items():
                    if row.get(field) in (None, ""):
                        merged[field] = val
            merged["parent_step_id"] = trim(str(merged.get("parent_step_id", "") or step_id), 20) or step_id
            # Fix 2 support: Timestamp new items for next-step detection
            if identity not in _existing_identities and "created_at" not in merged:
                merged["created_at"] = float(now_ts())
            if str(merged.get("status", "")).lower() == "completed" and "updated_at" not in merged:
                merged["updated_at"] = float(now_ts())
            merged_by_identity[identity] = merged
            if identity not in ordered_identities:
                ordered_identities.append(identity)

        merged_target_rows = [merged_by_identity[i] for i in ordered_identities if i in merged_by_identity]
        merged_target_rows = self._filter_parent_step_duplicate_worker_rows(merged_target_rows, active_step)

        # Fix 4: Content-based deduplication to prevent duplicate subtasks from accumulating
        _seen_content: set[str] = set()
        _deduped_target: list[dict] = []
        for row in merged_target_rows:
            _ck = normalize_work_text(str(row.get("content", ""))).strip().lower()
            if _ck in _seen_content:
                continue
            _seen_content.add(_ck)
            _deduped_target.append(row)
        merged_target_rows = _deduped_target

        # Fix 2: Detect "next-step intent" — if all existing items are completed,
        # new pending items that don't match existing identities are for the next step.
        # Remove their parent_step_id so they don't block current step advancement.
        _all_existing_done = (
            bool(target_rows) and
            all(str(r.get("status", "")).lower() == "completed" for r in target_rows)
        )
        if _all_existing_done:
            for row in merged_target_rows:
                _rid = self._plan_worker_todo_identity(row)
                if (_rid and _rid not in _existing_identities
                        and str(row.get("status", "")).lower() != "completed"):
                    row.pop("parent_step_id", None)  # Not for current step

        current_step_rows = [
            row for row in merged_target_rows
            if trim(str(row.get("parent_step_id", "") or ""), 20) == step_id
        ]
        detached_rows = [
            row for row in merged_target_rows
            if trim(str(row.get("parent_step_id", "") or ""), 20) != step_id
        ]
        current_step_rows = self._plan_worker_rows_with_acceptance(
            active_step,
            current_step_rows,
            expected=[str(row.get("content", "") or "") for row in current_step_rows],
            owner=role_key,
        )
        merged_target_rows = current_step_rows + detached_rows

        # Insert merged_target_rows right after the active plan step's bb: row in preserved,
        # so subtasks appear nested under their parent step rather than at the list bottom.
        _step_key = str(active_step.get("key", "") or "")
        _insert_idx = len(preserved)  # fallback: append at end
        if _step_key:
            for _i, _r in enumerate(preserved):
                if str(_r.get("key", "") or "") == _step_key:
                    _insert_idx = _i + 1
                    break
        final_rows = preserved[:_insert_idx] + passthrough_rows + merged_target_rows + preserved[_insert_idx:]
        result = self.todo.update(final_rows)
        try:
            self._sync_plan_worker_todos_to_blackboard(step_id)
            self._update_plan_file_step_status()
        except Exception:
            pass
        # Read-before-write closure: echo the canonical, renumbered subtask list
        # back as the tool result so the model SEES the reconciled arrangement it
        # just produced (numbering, statuses, the single acceptance gate) rather
        # than guessing. This is what keeps subsequent TodoWrite calls aligned to
        # the canonical N.M scheme instead of inventing a parallel set.
        canonical = self._render_plan_worker_todo_canonical(step_id, current_step_rows)
        if canonical:
            return f"{result}\n\n{canonical}"
        return result

    def _render_plan_worker_todo_canonical(self, step_id: str, rows: list[dict]) -> str:
        """Render the current step's canonical subtask list for the tool result.

        Shows exactly what the runtime stored after reconciliation+renumbering, so
        the worker can continue the in_progress item instead of restating work.
        """
        try:
            ordered = [r for r in (rows or []) if isinstance(r, dict)]
            if not ordered:
                ordered = self._active_plan_worker_todo_rows(step_id, role="")
            if not ordered:
                return ""
            _mark = {"completed": "[x]", "in_progress": "[>]", "pending": "[ ]", "blocked": "[!]"}
            lines = ["CANONICAL SUBTASKS for the active step (continue the [>] item; do not renumber or restate):"]
            for r in ordered:
                st = str(r.get("status", "pending") or "pending").strip().lower()
                content = normalize_embedded_newlines(str(r.get("content", "") or "")).split("\n", 1)[0].strip()
                lines.append(f"  {_mark.get(st, '[ ]')} {trim(content, 140)}")
            return "\n".join(lines)
        except Exception:
            return ""

    def _merge_owner_scoped_todo_items(self, items: list[dict], role: str = "") -> str:
        if not isinstance(items, list):
            raise ValueError("items must be array")
        role_key = self._sanitize_agent_role(role)
        if role_key not in {"developer", "explorer", "reviewer"}:
            return self.todo.update(items)
        existing = self.todo.snapshot()
        preserved: list[dict] = []
        for row in existing:
            if not isinstance(row, dict):
                continue
            key = str(row.get("key", "") or "").strip()
            owner = str(row.get("owner", "") or "").strip().lower()
            if key.startswith("bb:"):
                preserved.append(dict(row))
                continue
            if owner == role_key:
                continue
            preserved.append(dict(row))
        normalized: list[dict] = []
        for idx, item in enumerate(items):
            if isinstance(item, str):
                row = {"content": item, "status": "pending"}
            elif isinstance(item, dict):
                row = dict(item)
            else:
                raise ValueError(f"item {idx}: invalid type")
            if str(row.get("key", "") or "").startswith("bb:"):
                normalized.append(row)
                continue
            row["owner"] = role_key
            normalized.append(row)
        return self.todo.update(preserved + normalized)

    def _append_instruction_bubble(self, content: str, *, target_roles: tuple[str, ...] = (), summary: str = "") -> bool:
        text = trim(str(content or "").strip(), PLAN_NOTICE_BODY_MAX_CHARS)
        if not text:
            return False
        recent = self.messages[-8:]
        if any(str(row.get("content", "") or "").strip() == text for row in recent if isinstance(row, dict)):
            return False
        stamp = now_ts()
        self.messages.append({"role": "user", "content": text, "ts": stamp})
        for role in target_roles:
            self._append_agent_context_message(
                role,
                {
                    "role": "system",
                    "content": text,
                    "ts": stamp,
                    "agent_role": role,
                },
                mirror_to_global=False,
            )
        if summary:
            self._emit("status", {"summary": trim(summary, 120)})
        return True

    def _wrapped_control_block(self, content: str) -> tuple[str, str]:
        text = str(content or "").strip()
        if not text:
            return ("", "")
        m = re.fullmatch(r"<([a-zA-Z0-9_-]+)>\s*([\s\S]*?)\s*</\1>", text)
        if not m:
            return ("", text)
        return (str(m.group(1) or "").strip().lower(), str(m.group(2) or "").strip())

    def _build_plan_guidance_notice_data(self, content: str, *, summary: str = "") -> dict:
        text = trim(str(content or "").strip(), PLAN_NOTICE_BODY_MAX_CHARS)
        if not text:
            return {}
        lang = normalize_ui_language(getattr(self, "ui_language", DEFAULT_UI_LANGUAGE))
        if lang == "zh-CN":
            title = "计划执行提示"
            note = "当前计划步骤与 Todo 规则已同步到本轮执行上下文。"
        elif lang == "zh-TW":
            title = "計畫執行提示"
            note = "目前計畫步驟與 Todo 規則已同步到本輪執行上下文。"
        elif lang == "ja":
            title = "計画実行ガイド"
            note = "現在の計画ステップと Todo ルールは今回の実行コンテキストへ同期されました。"
        else:
            title = "Plan Execution Guidance"
            note = "The active plan step and Todo rules were synced into the current execution context."
        control_tag, control_body = self._wrapped_control_block(text)
        notice_kind = "plan_notice"
        display_body = control_body if control_tag else text
        if control_tag == "todo-focus":
            notice_kind = "todo_focus"
            if lang == "zh-CN":
                title = "Todo 焦点"
                note = "当前 in_progress 子任务已同步为本轮执行焦点。"
            elif lang == "zh-TW":
                title = "Todo 焦點"
                note = "目前 in_progress 子任務已同步為本輪執行焦點。"
            elif lang == "ja":
                title = "Todo フォーカス"
                note = "現在の in_progress サブタスクを今回の実行フォーカスとして同期しました。"
            else:
                title = "Todo Focus"
                note = "The current in_progress subtask was synced as the execution focus."
        elif control_tag == "reminder":
            notice_kind = "reminder"
        bb = self._ensure_blackboard()
        step = self._current_plan_step_row(bb)
        total = int(bb.get("plan_step_total", 0) or 0)
        step_idx = int(step.get("plan_step_index", 0) or 0) + 1 if isinstance(step, dict) else 0
        step_text = trim(str(step.get("content", "") or ""), 160) if isinstance(step, dict) else ""
        step_id = str(step.get("id", "") or "") if isinstance(step, dict) else ""
        step_label = (
            self._ui_text("plan_step_label", step=step_idx, total=max(1, total))
            if step_idx > 0
            else ""
        )
        subtitle_parts = [part for part in (step_label, step_text) if part]
        subtitle = " · ".join(subtitle_parts) or trim(str(summary or ""), 120) or PLAN_FILE_RELATIVE_PATH
        pills: list[dict] = []
        if step_label:
            pills.append({"text": step_label, "tone": "info"})
        if control_tag:
            pills.append({"text": control_tag, "tone": "neutral", "mono": True})
        if step_id:
            pills.append({"text": step_id, "tone": "neutral", "mono": True})
        rows = [{"label": "plan.md", "value": PLAN_FILE_RELATIVE_PATH, "mono": True}]
        if step_id:
            rows.append({"label": "parent_step_id", "value": step_id, "mono": True})
        return {
            "kind": notice_kind,
            "control_tag": control_tag,
            "title": title,
            "subtitle": subtitle,
            "note": note,
            "body": display_body,
            "pills": pills,
            "rows": rows,
        }

    def _append_plan_guidance_bubble(self, content: str, *, target_roles: tuple[str, ...] = (), summary: str = "") -> bool:
        if str(self.plan_mode_user_preference or "auto").strip().lower() == "off":
            return False
        if not isinstance(self._current_plan_step_row(self._ensure_blackboard()), dict):
            return False
        text = trim(str(content or "").strip(), PLAN_NOTICE_BODY_MAX_CHARS)
        if not text:
            return False
        recent = self.messages[-10:]
        if any(str(row.get("content", "") or "").strip() == text for row in recent if isinstance(row, dict)):
            return False
        stamp = now_ts()
        notice_data = self._build_plan_guidance_notice_data(text, summary=summary)
        self.messages.append({"role": "user", "content": text, "ts": stamp, "_ui_hidden": True})
        self.messages.append(
            {
                "role": "system",
                "content": "",
                "ts": stamp,
                "type": "plan_notice",
                "agent_role": "planner",
                "data": notice_data,
            }
        )
        self._emit(
            "message",
            {
                "role": "system",
                "type": "plan_notice",
                "text": "",
                "data": notice_data,
                "agent_role": "planner",
                "summary": trim(summary or str(notice_data.get("subtitle", "") or "plan guidance"), 120),
            },
        )
        for role in target_roles:
            self._append_agent_context_message(
                role,
                {
                    "role": "system",
                    "content": text,
                    "ts": stamp,
                    "agent_role": role,
                },
                mirror_to_global=False,
            )
        return True

    def _build_plan_todo_reminder_text(self, plan_step: dict, *, missing_subtasks: bool = False) -> str:
        if missing_subtasks:
            return (
                "<reminder>"
                "No current-step subtasks are active. First call TodoWrite for this plan step only, "
                "using parent_step_id for every row and exactly one in_progress item."
                "</reminder>"
            )
        return (
            "<reminder>"
            "Existing todos are active for this step; update TodoWrite only when real status changes."
            "</reminder>"
        )

    def _plan_todo_discipline_prompt(self, role: str = "", *, for_manager: bool = False) -> str:
        step = self._get_active_plan_step()
        if not isinstance(step, dict):
            return ""
        step_id = trim(str(step.get("id", "") or ""), 20)
        step_idx = int(step.get("plan_step_index", 0) or 0) + 1
        step_text = trim(str(step.get("content", "") or ""), 220)
        rows = self._active_plan_worker_todo_rows(step_id, role=role)
        current = next((r for r in rows if str(r.get("status", "") or "").strip().lower() == "in_progress"), None)
        pending = [r for r in rows if str(r.get("status", "") or "").strip().lower() == "pending"]
        completed = [r for r in rows if str(r.get("status", "") or "").strip().lower() == "completed"]
        current_text = str((current or {}).get("content", "") or "")
        current_is_acceptance = self._is_plan_step_acceptance_subtask(current_text)
        acceptance_terms = self._plan_step_acceptance_terms()
        acceptance_hint = (
            f"The final subtask must be a semantic {acceptance_terms['prefix']} item with a concrete check action and evidence shape. "
        )
        if current_is_acceptance:
            acceptance_hint += (
                "The current subtask is the acceptance gate: execute the check, record evidence, and only mark it completed when it passes. "
            )
        else:
            acceptance_hint += (
                "Do not delegate reviewer-style validation before the current work subtask is completed; continue executable work first. "
            )
        continuity = self._plan_continuity_context_block(max_chars=4200, include_steps=False)
        continuity_note = (
            f"{continuity}\n"
            if continuity else ""
        )
        if not rows:
            todo_state = (
                "No worker subtasks are active for this step. First create 3-6 step-local TodoWrite rows; the final row must be a semantic acceptance check with evidence shape. "
                f"scoped to parent_step_id='{step_id}', with exactly one in_progress item. "
            )
            subtasks_exist_ban = ""
        else:
            state_parts: list[str] = []
            if current:
                state_parts.append(
                    f"Current in_progress subtask: {trim(str(current.get('content', '') or ''), 160)}. "
                )
            elif pending:
                state_parts.append(
                    f"Next pending subtask: {trim(str(pending[0].get('content', '') or ''), 160)}. "
                )
            state_parts.append(
                f"Existing worker subtasks for this step: {len(completed)} completed, {len(pending)} pending. "
            )
            todo_state = "".join(state_parts)
            # Fix 7: allow REFINEMENT, forbid only wholesale recreate. The old
            # absolute ban ("do NOT call TodoWrite … directly execute") pushed
            # multi-agent workers into shallow, bundled execution (e.g. writing
            # 4 subsections in one shot). The worker may now split a coarse
            # subtask into finer child items, add a genuinely missing one, or
            # update status — it just must not restate/duplicate existing rows
            # or drop the final acceptance item. Symmetric across single & multi.
            subtasks_exist_ban = (
                "Subtasks for this step already exist. Do NOT wholesale-recreate, renumber, or restate them. "
                "You MAY refine: split a too-coarse subtask into finer child items, add a genuinely missing "
                "subtask, or update status — reuse existing N.M ids and keep the final acceptance item. "
                "If the current subtask is already concrete, just execute it. "
            )
        if for_manager:
            return (
                f"PLAN/TODO DISCIPLINE: `{PLAN_FILE_RELATIVE_PATH}` is a read-only runtime mirror of the authoritative execution path. "
                "It may be inspected with read_file but must never be edited with write_file/edit_file/bash redirection. "
                "Plan advancement must happen only through route_to_next_agent with advance_plan_step=true after evidence is reviewed. "
                f"Delegate ONLY against the current in-progress plan step (Step {step_idx}: {step_text}). "
                "The delegation must preserve the approved plan charter, prior step outputs, and final deliverable logic. "
                f"{continuity_note}"
                f"{subtasks_exist_ban}"
                f"{todo_state}"
                f"{acceptance_hint}"
                "Treat worker subtasks as the live execution state for the current plan step. "
                "When subtasks exist, tell the owner to finish the current in_progress subtask first and update TodoWrite/TodoWriteRescue after real status changes. "
                "Do not route to finish_current_task while the approved plan still has unfinished steps."
            )
        return (
            f"PLAN/TODO DISCIPLINE: `{PLAN_FILE_RELATIVE_PATH}` is a read-only runtime mirror of the approved plan. "
            "Read it for status; never write/edit it directly. "
            f"Work ONLY on the current in-progress plan step (Step {step_idx}: {step_text}). "
            "Keep this step aligned with the approved plan charter, prior step outputs, and final deliverable logic. "
            f"{continuity_note}"
            f"{subtasks_exist_ban}"
            f"{todo_state}"
            f"{acceptance_hint}"
            "After EACH completed subtask, update TodoWrite or TodoWriteRescue before starting the next one. "
            "Do not call finish_current_task for a subtask or a single plan step; use it only when the overall user task is truly complete."
        )

    def _append_plan_single_todo_reminder(self, plan_step: dict, *, missing_subtasks: bool = False) -> bool:
        if not isinstance(plan_step, dict):
            return False
        step_idx = int(plan_step.get("plan_step_index", 0) or 0) + 1
        now_tick = now_ts()
        if (now_tick - self.last_todo_reminder_ts) < 8:
            return False
        content = self._build_plan_todo_reminder_text(plan_step, missing_subtasks=missing_subtasks)
        if not content:
            return False
        self._append_plan_guidance_bubble(content, summary="todo reminder")
        self.last_todo_reminder_ts = now_tick
        self.todo_reminder_count += 1
        self._emit(
            "status",
            {
                "summary": (
                    "plan+single todo reminder injected "
                    f"(step={step_idx}, missing_subtasks={'yes' if missing_subtasks else 'no'})"
                )
            },
        )
        return True

    def _is_plan_step_acceptance_subtask(self, text: object) -> bool:
        import re

        raw = normalize_work_text(str(text or "")) or str(text or "")
        low = re.sub(r"^\s*\d+\.\d+\s+", "", raw.strip().lower())
        if not low:
            return False
        prefixes = (
            "验收", "驗收", "最终验收", "最終驗收",
            "acceptance", "final acceptance", "final verification",
            "verify acceptance", "semantic acceptance",
            "受入確認", "受け入れ確認", "検収", "最終確認",
        )
        if low.startswith(prefixes):
            return True
        return (
            low.startswith(("final check", "final verify"))
            and ("evidence" in low or "证据" in low or "證據" in low or "証拠" in low)
        )

    def _plan_step_acceptance_terms(self) -> dict[str, str]:
        lang = normalize_ui_language(getattr(self, "ui_language", DEFAULT_UI_LANGUAGE))
        if lang == "en":
            return {
                "prefix": "Acceptance",
                "evidence": "Evidence",
                "suffix": "Evidence: record the actual check result and key tool/file output.",
            }
        if lang == "zh-TW":
            return {
                "prefix": "驗收",
                "evidence": "證據",
                "suffix": "證據：記錄實際檢查結果與關鍵工具/檔案輸出。",
            }
        if lang == "ja":
            return {
                "prefix": "受入確認",
                "evidence": "証拠",
                "suffix": "証拠：実際の確認結果と主要なツール/ファイル出力を記録する。",
            }
        return {
            "prefix": "验收",
            "evidence": "证据",
            "suffix": "证据：记录实际检查结果和关键工具/文件输出。",
        }

    def _normalize_plan_step_acceptance_subtask_text(self, text: object) -> str:
        raw = trim(normalize_work_text(str(text or "")) or str(text or "").strip(), 260)
        if not raw:
            return ""
        terms = self._plan_step_acceptance_terms()
        if not self._is_plan_step_acceptance_subtask(raw):
            sep = ":" if normalize_ui_language(getattr(self, "ui_language", DEFAULT_UI_LANGUAGE)) == "en" else "："
            raw = f"{terms['prefix']}{sep}{raw}"
        evidence_markers = (
            "证据", "證據", "証拠", "根拠", "evidence", "exit code",
            "输出", "輸出", "出力", "output", "日志", "日誌", "ログ", "log",
        )
        if not any(marker.lower() in raw.lower() for marker in evidence_markers):
            raw = trim(f"{raw}；{terms['suffix']}", 300)
        return raw

    def _is_generic_plan_step_acceptance_subtask(self, text: object) -> bool:
        raw = normalize_work_text(str(text or "")) or str(text or "")
        low = raw.lower()
        generic_markers = (
            "根据本步骤目标运行构建/测试/导入检查",
            "根据本步骤目标",
            "对照本步骤目标检查当前产出",
            "依照本步驟目標執行建置/測試/匯入檢查",
            "依照本步驟目標",
            "對照本步驟目標檢查目前產出",
            "このステップの目的に沿ってビルド/テスト/インポート確認",
            "このステップの目的に照らして現在の成果",
            "run the build/test/import check",
            "check whether the current output fully satisfies this step",
            "verify result",
            "check whether output satisfies",
            "current output",
            "this step's output",
            "当前产出是否",
            "本步骤产出",
            "目前產出是否",
            "本步驟產出",
            "record key output",
            "记录关键输出",
            "記錄關鍵輸出",
            "关键工具/文件输出",
            "關鍵工具/檔案輸出",
            "key tool/file output",
        )
        return any(marker.lower() in low for marker in generic_markers)

    def _plan_step_acceptance_subtask_is_specific(
        self,
        text: object,
        plan_step: dict,
        work_subtasks: list[str] | None = None,
    ) -> bool:
        raw = normalize_work_text(str(text or "")) or str(text or "")
        if not raw or not self._is_plan_step_acceptance_subtask(raw):
            return False
        if self._is_generic_plan_step_acceptance_subtask(raw):
            return False
        low = raw.lower()
        evidence_value_markers = (
            "exit_code", "exit code", "rc=", "exit=", "pass", "passed", "ok",
            "size=", "bytes", "kb", "mb", "http 200", "status 200",
            "version=", "semantic_version", "文件大小", "字节", "退出码",
            "通过", "已通过", "成功", "证据", "證據", "証拠",
        )
        if any(marker in low for marker in evidence_value_markers):
            return True
        action_low = re.split(
            r"(?:证据|證據|証拠|根拠|evidence)\s*[:：]",
            raw,
            maxsplit=1,
            flags=re.I,
        )[0].lower()
        concrete_markers = (
            "path", "file", "directory", "folder", "console", "browser", "static", "server",
            "module", "package", "dependency", "schema", "migration", "endpoint", "api",
            "command", "build", "test", "lint", "typecheck", "compile", "runtime", "service",
            "python", "javascript", "typescript", "go", "rust", "java", "kotlin", "swift",
            "c++", "cpp", "c#", "dotnet", "php", "ruby", "html", "css", "sql", "shell",
            "three.js", "vite", "react", "vue", "svelte", "docker", "kubernetes",
            "路径", "文件", "目录", "模块", "包", "控制台", "浏览器", "静态服务", "加载", "入口", "依赖",
            "构建", "测试", "静态检查", "类型检查", "编译", "运行", "服务", "接口", "端点", "数据库", "迁移", "表结构",
            "路徑", "檔案", "目錄", "模組", "套件", "控制台", "瀏覽器", "靜態服務", "載入", "入口", "依賴",
            "建置", "測試", "靜態檢查", "型別檢查", "編譯", "執行", "服務", "介面", "端點", "資料庫", "遷移",
            "パス", "ファイル", "ディレクトリ", "コンソール", "ブラウザ", "読み込み", "依存",
            "ビルド", "テスト", "型チェック", "コンパイル", "実行", "サービス", "エンドポイント", "データベース",
        )
        if any(marker in action_low for marker in concrete_markers):
            return True
        targets = self._plan_step_acceptance_targets(plan_step, work_subtasks)
        for path in targets.get("paths", []) or []:
            if str(path or "").lower() in low:
                return True
        target_aliases = {
            "project_dir": ("project directory", "project folder", "workspace", "项目目录", "工程目录", "專案目錄", "프로ジェクト", "ディレクトリ"),
            "source_code": ("source", "code", "module", "源码", "代码", "模組", "程式碼", "ソース", "コード"),
            "language_code": ("python", "javascript", "typescript", "go", "rust", "java", "kotlin", "swift", "c++", "cpp", "c#", "dotnet", "php", "ruby"),
            "three_dependency": ("three.js", "threejs", "three.min", "three 依赖", "three 依賴", "three 依存"),
            "html_css_js_entry": ("html/css/js", "html", "css", "javascript", "入口文件", "入口檔案", "エントリファイル"),
            "html_entry": ("html", "入口文件", "入口檔案", "エントリファイル"),
            "html_file": ("html",),
            "css_entry": ("css", "入口文件", "入口檔案", "エントリファイル"),
            "css_file": ("css",),
            "js_entry": ("javascript", ".js", "入口文件", "入口檔案", "エントリファイル"),
            "js_file": ("javascript", ".js"),
            "dependency_config": ("dependency", "package", "requirements", "cargo", "go.mod", "pom.xml", "gradle", "package.json", "vite", "npm", "pnpm", "yarn", "依赖", "依賴", "依存"),
            "build_config": ("build", "compile", "makefile", "cmake", "webpack", "vite", "构建", "建置", "ビルド"),
            "frontend_behavior": ("frontend", "webui", "web ui", "界面", "介面", "交互", "互動", "browser", "浏览器", "瀏覽器"),
            "rendering": ("render", "canvas", "fps", "渲染", "描画"),
            "runtime_service": ("run", "runtime", "service", "server", "port", "运行", "服務", "サーバー"),
            "api_behavior": ("api", "endpoint", "route", "request", "response", "接口", "端点", "介面", "エンドポイント"),
            "database_schema": ("database", "schema", "migration", "sql", "sqlite", "postgres", "mysql", "数据库", "資料庫"),
            "data_files": ("csv", "json", "parquet", "dataset", "data", "数据", "資料"),
            "asset_files": ("asset", "image", "svg", "png", "jpg", "font", "资源", "素材", "画像"),
            "config_files": ("config", "settings", ".env", "yaml", "toml", "配置", "設定"),
            "infra_files": ("docker", "kubernetes", "deployment", "ci", "workflow", "部署", "インフラ"),
            "test_output": ("test", "pytest", "ruff", "py_compile", "jest", "vitest", "go test", "cargo test", "测试", "測試", "検証"),
            "lint_typecheck": ("lint", "typecheck", "mypy", "eslint", "tsc", "ruff", "静态检查", "型別檢查"),
            "document_output": ("document", "markdown", ".md", "文档", "文件", "章", "章节", "outline", "chapter", "小说", "文章"),
            "referenced_paths": ("path", "file", "路径", "路徑", "パス", "ファイル"),
        }
        for key in targets.get("keys", []) or []:
            aliases = target_aliases.get(str(key or ""), ())
            if any(alias.lower() in action_low for alias in aliases):
                return True
        return False

    def _plan_step_acceptance_targets(self, plan_step: dict, work_subtasks: list[str] | None = None) -> dict:
        raw_parts = [
            str((plan_step or {}).get("full_content", "") or (plan_step or {}).get("content", "") or "")
        ]
        raw_parts.extend(str(item or "") for item in (work_subtasks or [])[:8])
        text = normalize_embedded_newlines("\n".join(raw_parts))
        low = text.lower()
        document_context = any(
            token in low
            for token in (
                "文档", "文件", "document", "docs/", ".md", "markdown", "说明", "手册",
                "文件", "ドキュメント", "説明", "マニュアル",
            )
        )
        api_runtime_context = any(
            token in low
            for token in (
                "endpoint", "route", "handler", "controller", "middleware", "server", "service", "curl",
                "http request", "api request", "call api", "run server", "serve", "websocket",
                "端点", "路由", "处理器", "控制器", "中间件", "服务", "运行请求", "启动服务", "调用接口",
                "端點", "路由", "處理器", "控制器", "中介軟體", "服務", "執行請求", "啟動服務", "呼叫介面",
                "エンドポイント", "ルート", "ハンドラ", "コントローラ", "ミドルウェア", "サーバー", "サービス",
            )
        )
        paths: list[str] = []
        path_re = re.compile(
            r"(?:[\w.@()+ -]+/)+[\w.@()+ -]+\.[A-Za-z0-9]{1,8}\b"
            r"|[\w.@()+-]+\.(?:html|css|js|mjs|ts|tsx|jsx|json|md|py|txt|yaml|yml|toml|rs|go|java|kt|swift|cpp|c|h)\b"
        )
        for match in path_re.finditer(text):
            value = match.group(0).strip(" \t\r\n.,;:，。；：)）]")
            if " " in value or "\t" in value:
                value = value.replace("\t", " ").split()[-1].strip()
            if value.lower() in {"three.js"}:
                continue
            if value and value not in paths:
                paths.append(value)
            if len(paths) >= 5:
                break

        keys: list[str] = []

        def add(key: str):
            if key not in keys:
                keys.append(key)

        if any(token in low for token in ("项目目录", "工程目录", "专案目录", "專案目錄", "project directory", "project folder", "workspace", "ディレクトリ")):
            add("project_dir")
        source_extensions = (
            ".py", ".go", ".rs", ".java", ".kt", ".kts", ".swift",
            ".cpp", ".cc", ".cxx", ".c", ".h", ".hpp", ".cs", ".php", ".rb", ".lua", ".r", ".scala", ".dart",
            ".sh", ".bash", ".zsh", ".ps1", ".sql",
        )
        if any(ext in low for ext in source_extensions) or any(
            token in low
            for token in (
                "source code", "module", "function", "class", "源码", "源代码", "代码", "模块", "函数", "类",
                "原始碼", "程式碼", "模組", "函式", "ソース", "コード", "モジュール", "関数", "クラス",
            )
        ):
            add("source_code")
        if any(
            token in low
            for token in (
                "python", "typescript", "javascript", "node", "deno", "go ", "golang", "rust", "java", "kotlin",
                "swift", "c++", "cpp", " c ", "c#", "dotnet", ".net", "php", "ruby", "rails", "lua", "scala",
                "dart", "flutter", "shell", "bash", "powershell", "sql",
            )
        ):
            add("language_code")
        if any(token in low for token in ("three.js", "threejs", "three min", "three.min", "three ")):
            add("three_dependency")
        has_html = "html" in low or ".html" in low
        has_css = "css" in low or ".css" in low
        has_js = any(
            token in low
            for token in ("javascript", " js", ".js", "/js", "js/", "js ", "js入口", "js 入口", "脚本", "腳本", "スクリプト")
        )
        has_entry = any(token in low for token in ("入口", "entry", "エントリ"))
        if has_html and has_css and has_js and has_entry:
            add("html_css_js_entry")
        else:
            if has_html:
                add("html_entry" if has_entry else "html_file")
            if has_css:
                add("css_entry" if has_entry else "css_file")
            if has_js:
                add("js_entry" if has_entry else "js_file")
        if any(
            token in low
            for token in (
                "package.json", "requirements.txt", "pyproject.toml", "poetry.lock", "pipfile", "cargo.toml",
                "cargo.lock", "go.mod", "go.sum", "pom.xml", "build.gradle", "gradle", "gemfile",
                "composer.json", "pubspec.yaml", "package-lock.json", "pnpm-lock.yaml", "yarn.lock",
                "vite", "npm", "pnpm", "yarn", "pip", "uv ", "poetry", "cargo", "maven", "依赖", "依賴", "dependency",
            )
        ):
            add("dependency_config")
        if any(
            token in low
            for token in (
                "makefile", "cmakelists.txt", "cmake", "webpack", "vite", "rollup", "esbuild", "tsconfig",
                "build", "compile", "构建", "编译", "建置", "編譯", "ビルド", "コンパイル",
            )
        ):
            add("build_config")
        if any(token in low for token in ("frontend", "webui", "web ui", "界面", "介面", "交互", "互動", "ui", "画面")):
            add("frontend_behavior")
        if any(token in low for token in ("3d", "canvas", "render", "渲染", "描画", "fps", "three.js")):
            add("rendering")
        if any(
            token in low
            for token in (
                "runtime", "server", "port", "daemon", "cli", "command line", "run server", "serve",
                "启动", "运行服务", "启动服务", "端口", "命令行", "啟動", "執行服務", "啟動服務", "服務執行",
                "ポート", "起動", "サーバー", "サービス起動",
            )
        ):
            add("runtime_service")
        if any(
            token in low
            for token in (
                "api", "endpoint", "route", "request", "response", "http", "graphql", "websocket",
                "接口", "端点", "请求", "响应", "路由", "介面", "端點", "請求", "回應", "エンドポイント", "リクエスト",
            )
        ) and (api_runtime_context or not document_context):
            add("api_behavior")
        if any(
            token in low
            for token in (
                "database", "schema", "migration", "sql", "sqlite", "postgres", "postgresql", "mysql", "redis",
                "mongodb", "table", "index", "数据库", "表结构", "迁移", "資料庫", "遷移", "テーブル", "データベース",
            )
        ):
            add("database_schema")
        if any(
            token in low
            for token in (
                "csv", "tsv", "jsonl", "parquet", "dataset", "data file", "data set",
                "数据文件", "数据集", "资料文件", "資料檔案", "資料集", "データファイル", "データセット",
            )
        ):
            add("data_files")
        if any(token in low for token in ("png", "jpg", "jpeg", "svg", "webp", "gif", "font", "asset", "image", "资源", "素材", "画像")):
            add("asset_files")
        if any(token in low for token in (".env", "config", "settings", "yaml", "yml", "toml", "ini", "配置", "設定")):
            add("config_files")
        if any(token in low for token in ("dockerfile", "docker-compose", "kubernetes", "k8s", "ci", "github actions", "workflow", "部署", "インフラ")):
            add("infra_files")
        if any(
            token in low
            for token in (
                "测试", "測試", "test", "pytest", "unittest", "jest", "vitest", "go test", "cargo test",
                "ruff", "py_compile", "验证", "驗證", "検証",
            )
        ):
            add("test_output")
        if any(token in low for token in ("lint", "typecheck", "type check", "mypy", "eslint", "tsc", "clippy", "fmt", "静态检查", "类型检查", "型別檢查")):
            add("lint_typecheck")
        if any(token in low for token in ("文档", "文件", "document", "markdown", ".md", "章", "章节", "outline", "chapter", "小说", "文章")):
            add("document_output")
        if paths:
            add("referenced_paths")
        return {"keys": keys[:8], "paths": paths[:5], "low": low}

