# ============================================================================
# Architecture / 架构 / アーキテクチャ
# Layer 5: RAG parsing, semantic chunking, and retrieval scoring.
# 第五层：RAG 解析、语义分块与检索评分。
# 第5層：RAG 解析、意味チャンク化、検索スコアリング。
# ============================================================================

# Core RAG helpers: normalize document names, extract structure, chunk content,
# and score retrieval candidates before they are surfaced to the model.
def _rag_safe_name(name: str, fallback: str = "document") -> str:
    raw = Path(str(name or fallback)).name
    safe = re.sub(r"[^A-Za-z0-9._-]+", "_", raw).strip("._")
    return safe or fallback


def _rag_detect_language(text: str) -> str:
    sample = str(text or "")
    latin = len(re.findall(r"[A-Za-z]", sample))
    cjk = len(re.findall(r"[\u4e00-\u9fff\u3040-\u30ff]", sample))
    if cjk > latin * 1.2 and cjk >= 8:
        return "zh"
    if latin > cjk * 1.5 and latin >= 12:
        return "en"
    if latin and cjk:
        return "mixed"
    if cjk:
        return "zh"
    if latin:
        return "en"
    return "unknown"


def _rag_cjk_ngrams(seq: str, *, min_n: int = 2, max_n: int = 4, limit: int = 120) -> list[str]:
    text = re.sub(r"\s+", "", str(seq or ""))
    out: list[str] = []
    if len(text) < min_n:
        return out
    for n in range(min_n, max_n + 1):
        if len(out) >= limit:
            break
        for idx in range(0, max(0, len(text) - n + 1)):
            out.append(text[idx : idx + n])
            if len(out) >= limit:
                break
    return out


def _rag_is_noise_token(token: object) -> bool:
    raw = re.sub(r"\s+", " ", str(token or "").strip())
    if not raw:
        return True
    low = raw.lower()
    if re.fullmatch(r"\d+(?:\.\d+)?", low):
        return True
    if re.fullmatch(r"[_./+\-=]+", low):
        return True
    for pattern in RAG_STRUCTURAL_ENTITY_PATTERNS:
        if pattern.fullmatch(raw):
            return True
    has_cjk = bool(re.search(r"[\u4e00-\u9fff\u3040-\u30ff]", raw))
    if has_cjk:
        return raw in RAG_ZH_STOPWORDS or raw in RAG_GENERIC_ENTITY_TERMS_ZH or len(raw) < 2
    if low in RAG_EN_STOPWORDS or low in RAG_GENERIC_ENTITY_TERMS_EN:
        return True
    if len(low) <= 2 and low not in RAG_SHORT_TOKEN_ALLOWLIST:
        return True
    return False


def _rag_entity_allowed(token: object) -> bool:
    raw = re.sub(r"\s+", " ", str(token or "").strip())
    if not raw or _rag_is_noise_token(raw):
        return False
    low = raw.lower()
    for pattern in RAG_STRUCTURAL_ENTITY_PATTERNS:
        if pattern.fullmatch(raw):
            return False
    if low in RAG_GENERIC_ENTITY_TERMS_EN or raw in RAG_GENERIC_ENTITY_TERMS_ZH:
        return False
    if re.fullmatch(r"[a-z][a-z0-9_./+-]{2,40}", low) and low in RAG_EN_STOPWORDS:
        return False
    return True


def _rag_filter_entities(values: list[object], limit: int = 32) -> list[str]:
    out: list[str] = []
    seen: set[str] = set()
    for value in values or []:
        token = re.sub(r"\s+", " ", str(value or "").strip())
        if not token or not _rag_entity_allowed(token):
            continue
        key = token.lower()
        if key in seen:
            continue
        seen.add(key)
        out.append(token)
        if len(out) >= limit:
            break
    return out


def _rag_filename_entity_aliases(filename: object, source_rel_path: object = "", limit: int = 24) -> list[str]:
    base_name = str(filename or "").strip()
    if not base_name and str(source_rel_path or "").strip():
        try:
            base_name = PurePosixPath(str(source_rel_path or "").replace("\\", "/")).name
        except Exception:
            base_name = str(source_rel_path or "").strip().split("/")[-1]
    if not base_name:
        return []
    stem = Path(base_name).stem or Path(base_name).name or base_name
    stem = re.sub(r"\s+", " ", str(stem or "").strip())
    if not stem:
        return []
    raw_parts = [stem]
    camel = re.sub(r"(?<=[a-z0-9])(?=[A-Z])", " ", stem)
    if camel and camel != stem:
        raw_parts.append(camel)
    normalized = re.sub(r"[_./\\-]+", " ", stem).strip()
    if normalized and normalized != stem:
        raw_parts.append(normalized)
    pieces: list[str] = []
    for raw in raw_parts:
        token = re.sub(r"\s+", " ", str(raw or "").strip())
        if token:
            pieces.append(token)
        split_tokens = [
            str(x).strip()
            for x in re.split(r"[^A-Za-z0-9\u4e00-\u9fff\u3040-\u30ff]+", token)
            if str(x).strip()
        ]
        if len(split_tokens) >= 2:
            pieces.append(" ".join(split_tokens))
        pieces.extend(split_tokens)
    return _rag_filter_entities(pieces, limit=limit)


def _rag_apply_filename_entity_policy(
    values: list[object],
    filename: object = "",
    *,
    source_rel_path: object = "",
    allow_filename_entities: bool = False,
    limit: int = 32,
) -> list[str]:
    current = _rag_filter_entities(list(values or []), limit=max(limit * 4, 64))
    aliases = _rag_filename_entity_aliases(filename, source_rel_path=source_rel_path, limit=max(8, min(24, limit)))
    if not aliases:
        return current[:limit]
    alias_keys = {str(x).strip().lower() for x in aliases if str(x).strip()}
    filtered = [token for token in current if str(token).strip().lower() not in alias_keys]
    if allow_filename_entities:
        merged: list[str] = []
        seen: set[str] = set()
        for alias in aliases:
            key = str(alias).strip().lower()
            if not key or key in seen:
                continue
            merged.append(str(alias).strip())
            seen.add(key)
        for token in filtered:
            key = str(token).strip().lower()
            if not key or key in seen:
                continue
            merged.append(str(token).strip())
            seen.add(key)
        return merged[:limit]
    return filtered[:limit]


def _rag_choose_community(category: object, language: object, entities: list[object], raw_community: object = "") -> str:
    cat = str(category or "document").strip() or "document"
    lang = str(language or "unknown").strip() or "unknown"
    raw = str(raw_community or "").strip()
    if ":" in raw:
        parts = raw.split(":", 2)
        if parts[0].strip():
            cat = parts[0].strip()
        if len(parts) >= 3:
            # Already three-level format: validate and return
            s1, s2 = parts[1].strip(), parts[2].strip()
            if _rag_entity_allowed(s1) and _rag_entity_allowed(s2):
                return f"{cat}:{s1}:{s2}"
            if _rag_entity_allowed(s1):
                return f"{cat}:{s1}"
        elif len(parts) >= 2:
            suffix = parts[1].strip()
            if _rag_entity_allowed(suffix):
                # Try to enrich with a second entity from the entities list
                filtered = _rag_filter_entities(list(entities or []), limit=4)
                second = next((e for e in filtered if e.lower() != suffix.lower()), "")
                if second:
                    return f"{cat}:{suffix}:{second}"
                return f"{cat}:{suffix}"
    elif raw and not _rag_is_noise_token(raw):
        filtered = _rag_filter_entities(list(entities or []), limit=4)
        second = next((e for e in filtered if e.lower() != raw.lower()), "")
        if second:
            return f"{cat}:{raw}:{second}"
        return f"{cat}:{raw}"
    # Auto-assign from top entities; use two for research/code categories
    filtered = _rag_filter_entities(list(entities or []), limit=4)
    if filtered:
        first = filtered[0]
        if len(filtered) > 1:
            return f"{cat}:{first}:{filtered[1]}"
        return f"{cat}:{first}"
    return f"{cat}:{lang}"


def _rag_trigram_set(text: str) -> frozenset[str]:
    """Extract character-level trigrams for Jaccard-based content overlap detection."""
    t = " ".join(str(text or "").lower().split())
    if len(t) < 3:
        return frozenset()
    return frozenset(t[i : i + 3] for i in range(len(t) - 2))


def _rag_jaccard_sim(a: frozenset[str], b: frozenset[str]) -> float:
    """Jaccard similarity between two trigram sets. Returns 0.0 if both empty."""
    if not a and not b:
        return 0.0
    union = len(a | b)
    if union == 0:
        return 0.0
    return len(a & b) / union


def _rag_mmr_select(
    rows: list[dict],
    top_k: int,
    *,
    lambda_param: float = 0.6,
    overlap_hard_threshold: float = 0.55,
    overlap_soft_threshold: float = 0.30,
    max_per_doc: int = RAG_RETRIEVAL_MAX_PER_DOC,
) -> list[dict]:
    """Maximum Marginal Relevance selection with per-document capping.

    Selects top_k results that balance relevance (score) and diversity (low overlap
    with already-selected results). Near-duplicate content (Jaccard > overlap_hard_threshold)
    is skipped outright; partial overlaps are penalised.
    """
    if not rows:
        return []
    selected: list[dict] = []
    selected_trigrams: list[frozenset[str]] = []
    doc_counts: dict[str, int] = {}

    for row in rows:
        if len(selected) >= top_k:
            break
        doc_id = str(row.get("doc_id", "") or "")
        if doc_id and doc_counts.get(doc_id, 0) >= max_per_doc:
            continue
        row_tg = _rag_trigram_set(str(row.get("text", "") or ""))
        # Check overlap against already-selected results
        max_overlap = 0.0
        for sel_tg in selected_trigrams:
            sim = _rag_jaccard_sim(row_tg, sel_tg)
            if sim > max_overlap:
                max_overlap = sim
        if max_overlap >= overlap_hard_threshold:
            # Near-duplicate — skip entirely
            continue
        if max_overlap >= overlap_soft_threshold:
            # Partial overlap — penalise by folding in diversity penalty
            diversity = 1.0 - max_overlap
            orig_score = float(row.get("score", 0.0) or 0.0)
            row = dict(row)
            row["score"] = round(orig_score * lambda_param + orig_score * (1.0 - lambda_param) * diversity, 6)
        selected.append(row)
        selected_trigrams.append(row_tg)
        if doc_id:
            doc_counts[doc_id] = doc_counts.get(doc_id, 0) + 1
    return selected


def _rag_tokenize(text: str, max_terms: int = 4000) -> list[str]:
    raw = html.unescape(str(text or ""))
    lowered = raw.lower()
    out: list[str] = []
    # CamelCase decomposition: UserRepository → user, repository (plus userrepository)
    for camel_token in re.findall(r"\b[A-Z][a-zA-Z0-9]{2,40}\b", raw):
        # Split on case transitions: UserRepo → User, Repo; XMLParser → XML, Parser
        split1 = re.sub(r"([a-z])([A-Z])", r"\1 \2", camel_token)
        split2 = re.sub(r"([A-Z]+)([A-Z][a-z])", r"\1 \2", split1)
        for part in split2.split():
            lp = part.lower()
            if len(lp) >= 2 and not _rag_is_noise_token(lp):
                out.append(lp)
        full_lower = camel_token.lower()
        if not _rag_is_noise_token(full_lower):
            out.append(full_lower)
        if len(out) >= max_terms:
            return out
    # snake_case decomposition: get_max_value → get, max, value
    for snake_token in re.findall(r"\b[a-z][a-z0-9]{1,}(?:_[a-z0-9]{1,}){1,}\b", lowered):
        for part in snake_token.split("_"):
            if len(part) >= 2 and not _rag_is_noise_token(part):
                out.append(part)
        if len(out) >= max_terms:
            return out
    for token in re.findall(r"[a-z][a-z0-9_./+-]{1,40}", lowered):
        if _rag_is_noise_token(token):
            continue
        out.append(token)
        if len(out) >= max_terms:
            return out
    for token in re.findall(r"\b\d+(?:\.\d+)?\b", lowered):
        if _rag_is_noise_token(token):
            continue
        out.append(token)
        if len(out) >= max_terms:
            return out
    for seq in re.findall(r"[\u4e00-\u9fff\u3040-\u30ff]{2,}", raw):
        for gram in _rag_cjk_ngrams(seq, limit=80):
            if _rag_is_noise_token(gram):
                continue
            out.append(gram)
            if len(out) >= max_terms:
                return out
    for token in re.findall(r"\b[A-Z]{2,}(?:-[A-Z0-9]{1,8})?\b", raw):
        lowered_token = token.lower()
        if _rag_is_noise_token(lowered_token):
            continue
        out.append(lowered_token)
        if len(out) >= max_terms:
            return out
    return out


def _rag_expand_tokens(tokens: list[str]) -> list[str]:
    seen = {
        str(x).strip().lower()
        for x in tokens
        if str(x).strip() and not _rag_is_noise_token(str(x).strip().lower())
    }
    out = list(seen)
    for group in RAG_TERM_GROUPS:
        gset = {str(x).strip().lower() for x in group if str(x).strip()}
        if seen.intersection(gset):
            for token in gset:
                if token not in seen and not _rag_is_noise_token(token):
                    seen.add(token)
                    out.append(token)
    phrase_tokens = [token for token in seen if " " in token]
    for token in phrase_tokens:
        for part in re.split(r"\s+", token):
            part = part.strip().lower()
            if len(part) >= 3 and part not in seen and not _rag_is_noise_token(part):
                seen.add(part)
                out.append(part)
    return out


def _rag_extract_entities(text: str, limit: int = 32) -> list[str]:
    raw = str(text or "")
    counter: Counter[str] = Counter()
    for m in re.finditer(r"\b(?:[A-Z][a-z]{2,}(?:\s+[A-Z][a-z]{2,}){0,3}|[A-Z]{2,}(?:-[A-Z0-9]{1,8})?)\b", raw):
        token = trim(m.group(0).strip(), 80)
        if _rag_entity_allowed(token):
            counter[token] += 1
    for m in re.finditer(r"[\u4e00-\u9fff]{2,8}", raw):
        token = trim(m.group(0).strip(), 32)
        if _rag_entity_allowed(token):
            counter[token] += 1
    for token, freq in Counter(_rag_tokenize(raw, max_terms=600)).most_common(80):
        if freq < 2:
            continue
        if re.fullmatch(r"[a-z][a-z0-9_./+-]{2,20}", token) and _rag_entity_allowed(token):
            counter[token] += freq
    return _rag_filter_entities([name for name, _ in counter.most_common(limit * 3)], limit=limit)


def _rag_classify_document(filename: str, kind: str, text: str) -> dict:
    name = str(filename or "").lower()
    body = str(text or "").lower()
    labels: list[str] = []
    category = "document"
    if kind in {"image", "audio", "video"}:
        category = "multimodal"
        labels.append(kind)
    elif kind in {"csv", "excel"}:
        category = "dataset"
        labels.extend(["table", "structured"])
    elif kind == "presentation":
        category = "presentation"
        labels.append("slides")
    elif any(x in name for x in (".py", ".js", ".ts", ".java", ".go", ".rs", ".cpp", ".c", ".hpp")):
        category = "code"
        labels.append("source")
    elif any(h in body for h in RAG_RESEARCH_HINTS):
        category = "research"
        labels.extend(["paper", "literature"])
    elif any(h in body for h in ("table", "column", "row", "字段", "列名", "样本", "dataset")):
        category = "dataset"
        labels.append("structured")
    elif any(h in body for h in RAG_CODE_HINTS):
        category = "code"
        labels.append("source")
    if "report" in name or "报告" in body:
        labels.append("report")
    if "citation" in body or "引用" in body or "参考文献" in body:
        labels.append("citation")
    if kind == "pdf":
        labels.append("pdf")
    if kind == "document":
        labels.append("office")
    return {"category": category, "labels": sorted({str(x) for x in labels if str(x).strip()})}


def _rag_embed_text(text: str, session: object, *, model: str = "") -> list[float] | None:
    """Get a dense embedding vector for *text* using the session's ollama connection.

    Returns None on any error so callers can gracefully fall back to TF-IDF-only mode.
    """
    try:
        ollama = getattr(session, "ollama", None)
        if ollama is None:
            return None
        embed_model = str(model or getattr(ollama, "embed_model", "") or "").strip()
        if not embed_model:
            return None
        result = ollama.embed(model=embed_model, input=str(text or "")[:4096])
        if isinstance(result, dict):
            vecs = result.get("embeddings") or result.get("embedding")
            if isinstance(vecs, list) and vecs:
                first = vecs[0] if isinstance(vecs[0], list) else vecs
                if isinstance(first, list) and first:
                    return [float(x) for x in first]
        return None
    except Exception:
        return None


def _rag_embed_batch(texts: list[str], session: object, *, model: str = "") -> list[list[float] | None]:
    """Embed a batch of texts sequentially, returning None for any that fail."""
    results: list[list[float] | None] = []
    for text in texts:
        vec = _rag_embed_text(text, session, model=model)
        results.append(vec)
    return results


def _rag_window_for_query(query: str) -> int:
    """Return focused-excerpt window size based on query specificity.

    Shorter / more targeted queries benefit from a tighter window so the
    model receives only the most relevant snippet; broader queries can use
    the full chunk size.
    """
    q = str(query or "").strip()
    if len(q) < 30:
        return 450   # Very specific: tight window
    if len(q) < 80:
        return 750   # Medium specificity
    return 1200      # Broad query: full chunk


def _rag_focused_excerpt(text: str, query_tokens: list[str], *, window: int = 800, dense_match: bool = False) -> str:
    """Extract a focused excerpt from *text* centred on the highest query-token density region.

    Scans the text in small steps to find where query tokens appear most densely, then
    returns a *window*-character slice around that centre.  Falls back to a leading excerpt
    when no tokens match.  Ellipsis markers are added when text is trimmed.
    """
    text = str(text or "")
    if not text:
        return ""
    if len(text) <= window:
        return text
    tokens = [t.lower() for t in (query_tokens or []) if len(t) > 2]
    if not tokens:
        if dense_match:
            mid = len(text) // 2
            s = max(0, mid - window // 2)
            e = min(len(text), s + window)
            s = max(0, e - window)
            return ("…" if s > 0 else "") + text[s:e] + ("…" if e < len(text) else "")
        return text[:window] + ("…" if len(text) > window else "")
    half = window // 2
    step = max(40, window // 15)
    best_center = half
    best_count = 0
    lo = text.lower()
    for center in range(half, len(text) - half + 1, step):
        segment = lo[max(0, center - half) : center + half]
        count = sum(segment.count(t) for t in tokens)
        if count > best_count:
            best_count = count
            best_center = center
    if best_count == 0 and dense_match:
        best_center = len(text) // 2
    start = max(0, best_center - half)
    end = min(len(text), start + window)
    start = max(0, end - window)
    excerpt = text[start:end]
    prefix = "…" if start > 0 else ""
    suffix = "…" if end < len(text) else ""
    return prefix + excerpt + suffix


def _rag_query_variants(query: str, *, max_variants: int = 4) -> list[str]:
    raw = str(query or "").strip()
    if not raw:
        return []
    variants: list[str] = []

    def _add(value: str) -> None:
        value = trim(" ".join(str(value or "").split()), 360)
        if not value:
            return
        low = value.lower()
        if low not in {v.lower() for v in variants}:
            variants.append(value)

    _add(raw)
    entities = _rag_extract_entities(raw, limit=10)
    if entities:
        _add(" ".join(entities[:8]))
    tokens = _rag_expand_tokens(_rag_tokenize(raw, max_terms=80))
    important = []
    seen: set[str] = set()
    for token in tokens:
        token = str(token).strip()
        low = token.lower()
        if not token or low in seen or _rag_is_noise_token(low):
            continue
        if len(low) < 3 and not re.search(r"[\u4e00-\u9fff]", low):
            continue
        seen.add(low)
        important.append(token)
        if len(important) >= 14:
            break
    if important:
        _add(" ".join(important[:10]))
    path_terms = re.findall(r"\b[\w./-]{2,}\.(?:py|js|ts|tsx|jsx|md|json|yaml|yml|toml|css|html|sql|go|rs|java|cpp|c|h)\b", raw, flags=re.IGNORECASE)
    if path_terms:
        _add(" ".join(path_terms[:8]))
    return variants[: max(1, int(max_variants or 4))]


def _rag_parse_segments(content: str) -> list[tuple[str, int, str, str]]:
    """Split document text into structural segments: (type, depth, heading, body).

    type values:
      "heading"    — Markdown H1-H4 boundary marker (triggers section flush)
      "code_block" — fenced code block or table row group (kept atomic)
      "text"       — ordinary paragraph text
    """
    out: list[tuple[str, int, str, str]] = []
    lines = content.split("\n")
    i = 0
    while i < len(lines):
        line = lines[i]
        stripped = line.strip()
        # Markdown heading (H1-H4)
        hm = re.match(r"^(#{1,4})\s+(.*)", line)
        if hm:
            depth = len(hm.group(1))
            heading = hm.group(2).strip()
            out.append(("heading", depth, heading, ""))
            i += 1
            continue
        # Code fence (``` or ~~~)
        if stripped.startswith("```") or stripped.startswith("~~~"):
            fence = stripped[:3]
            j = i + 1
            while j < len(lines) and not lines[j].strip().startswith(fence):
                j += 1
            code_body = "\n".join(lines[i : j + 1])
            out.append(("code_block", 0, "", code_body))
            i = j + 1
            continue
        # Markdown table (lines starting with |)
        if stripped.startswith("|") and "|" in stripped[1:]:
            j = i
            while j < len(lines) and lines[j].strip().startswith("|"):
                j += 1
            table_body = "\n".join(lines[i:j])
            if table_body.strip():
                out.append(("code_block", 0, "", table_body))
            i = j
            continue
        # Regular text — collect until next structural boundary or two consecutive blank lines
        text_lines: list[str] = []
        consecutive_blank = 0
        while i < len(lines):
            line_text = lines[i]
            stripped_line = line_text.strip()
            if re.match(r"^#{1,4}\s", line_text) or stripped_line.startswith("```") or stripped_line.startswith("~~~"):
                break
            if stripped_line.startswith("|") and "|" in stripped_line[1:]:
                break
            text_lines.append(line_text)
            consecutive_blank = 0 if stripped_line else consecutive_blank + 1
            i += 1
            if consecutive_blank >= 2:
                break
        body = "\n".join(text_lines).strip()
        if body:
            out.append(("text", 0, "", body))
    return out


def _rag_boundary_split(body: str, *, max_chars: int, overlap: int) -> list[str]:
    """Split an oversized block into pieces that end on a natural boundary.

    A plain ``body[i:i+max_chars]`` window cuts mid-sentence or mid-identifier, which
    fragments tokens and hurts both recall (a split identifier matches nothing) and the
    readability of retrieved excerpts. This backs each cut off to the nearest paragraph
    break, sentence end, newline, or whitespace within a look-back window, then carries a
    boundary-aligned overlap tail. Falls back to a hard cut only when no boundary exists
    (e.g. one enormous unbroken token).
    """
    body = str(body or "")
    if len(body) <= max_chars:
        return [body] if body.strip() else []
    step = max(200, max_chars - overlap)
    # Look back at most ~20% of the window for a boundary so we don't shrink chunks too much.
    lookback = max(40, min(max_chars // 5, 400))
    pieces: list[str] = []
    pos = 0
    n = len(body)
    # Boundary patterns in priority order, searched within [cut-lookback, cut].
    boundary_res = [
        re.compile(r"\n\s*\n"),          # paragraph break
        re.compile(r"(?<=[.!?。！？])\s"), # sentence end (Latin + CJK)
        re.compile(r"\n"),               # line break
        re.compile(r"\s"),               # any whitespace
    ]
    while pos < n:
        hard_end = min(pos + max_chars, n)
        if hard_end >= n:
            piece = body[pos:n]
            if piece.strip():
                pieces.append(piece)
            break
        cut = hard_end
        window_start = max(pos + step // 2, hard_end - lookback)
        for rex in boundary_res:
            best = None
            for m in rex.finditer(body, window_start, hard_end):
                best = m
            if best is not None:
                cut = best.end()
                break
        piece = body[pos:cut]
        if piece.strip():
            pieces.append(piece)
        if cut <= pos:  # safety: no progress → hard cut
            cut = hard_end
            pieces.append(body[pos:cut])
        # Overlap tail, aligned to a whitespace boundary so we don't start mid-word.
        next_pos = max(pos + 1, cut - overlap) if overlap else cut
        if overlap and next_pos < cut:
            ws = body.find(" ", next_pos, cut)
            if ws != -1 and ws + 1 < cut:
                next_pos = ws + 1
        pos = next_pos if next_pos > pos else cut
    return pieces


def _rag_chunk_text(text: str, *, max_chars: int = RAG_CHUNK_CHARS, overlap: int = RAG_CHUNK_OVERLAP) -> list[dict]:
    """Semantic-boundary-aware text chunking.

    Respects Markdown structure (H1-H4 headers as hard section boundaries, code fences
    and tables kept atomic).  Each chunk carries parent_heading, is_code_block, and
    section_depth metadata for downstream filtering and context enrichment.
    """
    content = re.sub(r"\r\n?", "\n", str(text or "")).strip()
    if not content:
        return []
    segments = _rag_parse_segments(content)
    chunks: list[dict] = []
    current_text = ""
    current_heading = ""
    current_depth = 0

    def _flush(txt: str, heading: str, depth: int, is_code: bool = False) -> None:
        txt = txt.strip()
        if not txt or len(chunks) >= RAG_MAX_CHUNKS_PER_DOC:
            return
        first_line = next((ln for ln in txt.splitlines() if ln.strip()), txt)
        preview = trim(first_line, 120)
        if heading:
            preview = f"[{heading}] {preview}"
        chunks.append({
            "text": txt,
            "anchor": preview,
            "parent_heading": heading,
            "is_code_block": is_code,
            "section_depth": depth,
        })

    for seg_type, seg_depth, seg_heading, seg_body in segments:
        if len(chunks) >= RAG_MAX_CHUNKS_PER_DOC:
            break
        if seg_type == "heading":
            # Hard section boundary — flush accumulated text
            if current_text:
                _flush(current_text, current_heading, current_depth)
                current_text = ""
            current_heading = seg_heading
            current_depth = seg_depth
        elif seg_type == "code_block":
            # Flush prose buffer, then emit code/table atomically (up to 2500 chars)
            if current_text:
                _flush(current_text, current_heading, current_depth)
                current_text = ""
            max_code = max(max_chars, 2500)
            if len(seg_body) <= max_code:
                _flush(seg_body, current_heading, current_depth, is_code=True)
            else:
                # Very large block — split on natural boundaries, not mid-character.
                for piece in _rag_boundary_split(seg_body, max_chars=max_chars, overlap=overlap):
                    _flush(piece, current_heading, current_depth, is_code=True)
                    if len(chunks) >= RAG_MAX_CHUNKS_PER_DOC:
                        break
        else:
            # Ordinary text paragraph
            if len(current_text) + 2 + len(seg_body) <= max_chars:
                current_text = (current_text + "\n\n" + seg_body).strip() if current_text else seg_body
            else:
                if current_text:
                    _flush(current_text, current_heading, current_depth)
                    tail = current_text[-overlap:].strip() if overlap else ""
                    current_text = (tail + "\n\n" + seg_body).strip() if tail else seg_body
                else:
                    # Single oversized paragraph — split on natural boundaries with overlap
                    pieces = _rag_boundary_split(seg_body, max_chars=max_chars, overlap=overlap)
                    for piece in pieces[:-1]:
                        _flush(piece, current_heading, current_depth)
                        if len(chunks) >= RAG_MAX_CHUNKS_PER_DOC:
                            break
                    if pieces:
                        current_text = pieces[-1]

    if current_text and len(chunks) < RAG_MAX_CHUNKS_PER_DOC:
        _flush(current_text, current_heading, current_depth)
    return chunks[:RAG_MAX_CHUNKS_PER_DOC]




