IDE_JS = """
const E=id=>document.getElementById(id);
const S={config:null,sessions:[],roots:[],activeSession:'',activeRoot:'session',treeCache:new Map(),openFiles:new Map(),activeFile:null,dirty:false};
async function api(path,opts={}){
  const headers=Object.assign({'Content-Type':'application/json'},opts.headers||{});
  const res=await fetch(path,Object.assign({headers},opts));
  const text=await res.text();
  let data={};
  try{data=text?JSON.parse(text):{}}catch{data={error:text||res.statusText}}
  if(!res.ok)throw new Error(data.error||res.statusText);
  return data;
}
function setStatus(text,bad=false){const el=E('status');el.textContent=text||'';el.style.color=bad?'var(--danger)':'var(--muted)'}
function rootQuery(){return 'root_id='+encodeURIComponent(S.activeRoot||'session')}
function pathQuery(path){return '&path='+encodeURIComponent(path||'')}
function activeDir(){if(S.activeFile){const p=S.activeFile.path||'';const i=p.lastIndexOf('/');return i>0?p.slice(0,i):''}return E('cwdInput').value.trim()}
function fileIcon(row){return row.type==='dir'?(row.skipped?'x':'▸'):'·'}
function escapeText(v){return String(v||'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}
async function refreshConfig(){
  S.config=await api('/api/ide/config');
  S.sessions=Array.isArray(S.config.sessions)?S.config.sessions:[];
  S.activeSession=S.activeSession||S.config.active_session_id||'';
  renderSessions();
  renderTools();
  if(!S.activeSession)await createSession();
  await loadRoots();
}
function renderSessions(){
  const sel=E('sessionSelect');sel.innerHTML='';
  for(const row of S.sessions){
    const opt=document.createElement('option');opt.value=row.id;opt.textContent=row.title||row.id;if(row.id===S.activeSession)opt.selected=true;sel.appendChild(opt);
  }
}
async function createSession(){
  const title='IDE Workspace '+new Date().toLocaleTimeString();
  const out=await api('/api/ide/sessions',{method:'POST',body:JSON.stringify({title})});
  S.activeSession=out.id;await refreshConfig();
}
async function loadRoots(){
  if(!S.activeSession)return;
  const out=await api('/api/ide/sessions/'+encodeURIComponent(S.activeSession)+'/workspace/roots');
  S.roots=Array.isArray(out.roots)?out.roots:[];
  renderRoots();
  if(!S.roots.some(r=>r.id===S.activeRoot))S.activeRoot=(S.roots[0]&&S.roots[0].id)||'session';
  E('rootSelect').value=S.activeRoot;
  await loadTree('');
}
function renderRoots(){
  const sel=E('rootSelect');sel.innerHTML='';
  for(const root of S.roots){
    const opt=document.createElement('option');opt.value=root.id;opt.textContent=(root.kind==='mount'?'M ':'S ')+(root.label||root.id);sel.appendChild(opt);
  }
}
function renderTools(){
  const tools=E('toolchains');tools.innerHTML='';
  for(const t of (S.config.toolchains||[])){
    const row=document.createElement('div');row.className='tool-row';
    row.innerHTML='<strong>'+escapeText(t.name)+' '+(t.available?'available':'missing')+'</strong><span>'+escapeText(t.available?Object.keys(t.found||{}).join(', '):t.install_hint)+'</span>';
    tools.appendChild(row);
  }
  const mounts=E('mounts');mounts.innerHTML='';
  for(const m of (S.config.mounts||[])){
    const row=document.createElement('div');row.className='mount-row';
    row.innerHTML='<strong>'+escapeText(m.label||m.id)+'</strong><span>'+escapeText(m.path||'')+'</span><button data-mid="'+escapeText(m.id)+'">Remove</button>';
    row.querySelector('button').onclick=()=>removeMount(m.id).catch(err=>setStatus(err.message,true));
    mounts.appendChild(row);
  }
}
async function loadTree(path){
  if(!S.activeSession)return;
  const out=await api('/api/ide/sessions/'+encodeURIComponent(S.activeSession)+'/workspace/tree?'+rootQuery()+pathQuery(path||''));
  S.treeCache.set((path||''),out.tree.children||[]);
  renderTree();
  setStatus('tree '+(out.scan_ms||0)+'ms');
}
function renderTree(){
  const host=E('tree');host.innerHTML='';
  const draw=(path,depth)=>{
    const rows=S.treeCache.get(path||'')||[];
    for(const row of rows){
      const div=document.createElement('div');div.className='tree-row'+(S.activeFile&&S.activeFile.path===row.path?' is-active':'');
      div.style.paddingLeft=(4+depth*14)+'px';
      div.innerHTML='<button class="tree-twist">'+escapeText(fileIcon(row))+'</button><span class="tree-name">'+escapeText(row.name)+'</span><span class="tree-meta">'+(row.type==='file'?Math.ceil((row.size||0)/1024)+'k':'')+'</span>';
      div.onclick=async(ev)=>{
        ev.stopPropagation();
        if(row.type==='dir'){
          if(row.skipped)return setStatus('directory skipped by performance guard');
          if(S.treeCache.has(row.path))S.treeCache.delete(row.path);else await loadTree(row.path);
          renderTree();
        }else{
          await openFile(row.path);
        }
      };
      host.appendChild(div);
      if(row.type==='dir'&&S.treeCache.has(row.path))draw(row.path,depth+1);
    }
  };
  draw('',0);
}
function renderTabs(){
  const tabs=E('tabs');tabs.innerHTML='';
  for(const [key,file] of S.openFiles){
    const tab=document.createElement('div');tab.className='tab'+(S.activeFile&&key===S.activeFile.key?' is-active':'');
    tab.innerHTML='<span>'+escapeText(file.name||file.path)+'</span><button>x</button>';
    tab.onclick=()=>activateFile(key);
    tab.querySelector('button').onclick=(ev)=>{ev.stopPropagation();closeFile(key)};
    tabs.appendChild(tab);
  }
}
function activateFile(key){
  const file=S.openFiles.get(key);if(!file)return;
  S.activeFile=file;S.dirty=false;E('editor').value=file.content||'';E('editor').classList.add('is-visible');E('emptyState').classList.add('is-hidden');E('cwdInput').value=file.dir||'';renderTabs();renderTree();
}
function closeFile(key){
  S.openFiles.delete(key);
  if(S.activeFile&&S.activeFile.key===key){S.activeFile=null;E('editor').value='';E('editor').classList.remove('is-visible');E('emptyState').classList.remove('is-hidden')}
  renderTabs();
}
async function openFile(path){
  const key=S.activeRoot+'::'+path;
  if(S.openFiles.has(key))return activateFile(key);
  const out=await api('/api/ide/sessions/'+encodeURIComponent(S.activeSession)+'/workspace/file?'+rootQuery()+pathQuery(path));
  if(out.encoding==='base64')throw new Error('binary file cannot be edited here');
  const i=path.lastIndexOf('/');
  const file={key,path,name:path.split('/').pop(),dir:i>0?path.slice(0,i):'',content:out.content||'',root_id:S.activeRoot};
  S.openFiles.set(key,file);activateFile(key);setStatus('opened '+path);
}
async function saveActive(){
  if(!S.activeFile)return;
  const content=E('editor').value;
  await api('/api/ide/sessions/'+encodeURIComponent(S.activeSession)+'/workspace/file',{method:'PUT',body:JSON.stringify({root_id:S.activeRoot,path:S.activeFile.path,content})});
  S.activeFile.content=content;S.dirty=false;setStatus('saved '+S.activeFile.path);await loadTree(activeDir());
}
async function newFile(){
  const rel=prompt('File path',activeDir()?activeDir()+'/untitled.txt':'untitled.txt');if(!rel)return;
  await api('/api/ide/sessions/'+encodeURIComponent(S.activeSession)+'/workspace/file',{method:'PUT',body:JSON.stringify({root_id:S.activeRoot,path:rel,content:''})});
  await loadTree(activeDir());await openFile(rel);
}
async function newFolder(){
  const rel=prompt('Folder path',activeDir()?activeDir()+'/new-folder':'new-folder');if(!rel)return;
  await api('/api/ide/sessions/'+encodeURIComponent(S.activeSession)+'/workspace/mkdir',{method:'POST',body:JSON.stringify({root_id:S.activeRoot,path:rel})});
  await loadTree(activeDir());
}
function readFileAsB64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result||'').split(',',2)[1]||'');r.onerror=()=>reject(r.error||new Error('read failed'));r.readAsDataURL(file)})}
async function uploadFiles(files){
  const list=Array.from(files||[]);if(!list.length)return;
  const items=[];let n=0;
  for(const f of list){items.push({path:f.webkitRelativePath||f.name,content_b64:await readFileAsB64(f)});n++;setStatus('uploading '+n+'/'+list.length)}
  await api('/api/ide/sessions/'+encodeURIComponent(S.activeSession)+'/workspace/upload',{method:'POST',body:JSON.stringify({root_id:S.activeRoot,dest:activeDir(),items})});
  await loadTree(activeDir());setStatus('uploaded '+list.length+' file(s)');
}
async function runCommand(){
  const command=E('commandInput').value.trim();if(!command)return;
  E('terminalOutput').textContent+='\\n$ '+command+'\\n';
  const out=await api('/api/ide/sessions/'+encodeURIComponent(S.activeSession)+'/terminal/run',{method:'POST',body:JSON.stringify({root_id:S.activeRoot,cwd:E('cwdInput').value.trim(),command})});
  E('terminalOutput').textContent+=(out.stdout||'')+(out.stderr?'\\n'+out.stderr:'')+'\\n[exit '+out.returncode+']\\n';
  E('terminalOutput').scrollTop=E('terminalOutput').scrollHeight;
}
async function sendAgent(){
  const message=E('agentPrompt').value.trim();if(!message)return;
  const out=await api('/api/ide/sessions/'+encodeURIComponent(S.activeSession)+'/agent-task',{method:'POST',body:JSON.stringify({root_id:S.activeRoot,active_path:S.activeFile?S.activeFile.path:'',message})});
  E('agentStatus').textContent=out.queued?'queued':'started';
}
async function addMount(){
  const path=E('mountPathInput').value.trim();if(!path)return;
  await api('/api/ide/mounts',{method:'POST',body:JSON.stringify({path})});
  await refreshConfig();await loadRoots();setStatus('mount authorized');
}
async function removeMount(id){
  await api('/api/ide/mounts',{method:'DELETE',body:JSON.stringify({mount_id:id})});
  await refreshConfig();await loadRoots();
}
function bind(){
  document.querySelectorAll('.activity-button').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.activity-button').forEach(x=>x.classList.remove('is-active'));btn.classList.add('is-active');document.querySelectorAll('.panel-view').forEach(x=>x.classList.toggle('is-active',x.dataset.panel===btn.dataset.view))});
  E('createSessionBtn').onclick=()=>createSession().catch(err=>setStatus(err.message,true));
  E('sessionSelect').onchange=async()=>{S.activeSession=E('sessionSelect').value;S.treeCache.clear();S.openFiles.clear();S.activeFile=null;renderTabs();await loadRoots()};
  E('rootSelect').onchange=async()=>{S.activeRoot=E('rootSelect').value;S.treeCache.clear();await loadTree('')};
  E('refreshTreeBtn').onclick=()=>{S.treeCache.clear();loadTree('').catch(err=>setStatus(err.message,true))};
  E('newFileBtn').onclick=()=>newFile().catch(err=>setStatus(err.message,true));
  E('newFolderBtn').onclick=()=>newFolder().catch(err=>setStatus(err.message,true));
  E('uploadFilesBtn').onclick=()=>E('fileInput').click();
  E('uploadFolderBtn').onclick=()=>E('folderInput').click();
  E('fileInput').onchange=()=>uploadFiles(E('fileInput').files).catch(err=>setStatus(err.message,true));
  E('folderInput').onchange=()=>uploadFiles(E('folderInput').files).catch(err=>setStatus(err.message,true));
  E('runCommandBtn').onclick=()=>runCommand().catch(err=>setStatus(err.message,true));
  E('sendAgentBtn').onclick=()=>sendAgent().catch(err=>setStatus(err.message,true));
  E('mountBtn').onclick=()=>addMount().catch(err=>setStatus(err.message,true));
  E('refreshToolsBtn').onclick=()=>refreshConfig().catch(err=>setStatus(err.message,true));
  E('editor').addEventListener('input',()=>{S.dirty=true;if(S.activeFile){S.activeFile.content=E('editor').value}});
  window.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='s'){ev.preventDefault();saveActive().catch(err=>setStatus(err.message,true))}});
}
window.addEventListener('DOMContentLoaded',async()=>{bind();try{await refreshConfig();setStatus('ready')}catch(err){setStatus(err.message,true)}});
"""

# ============================================================================
# Architecture / 架构 / アーキテクチャ
# Layer 7: Application orchestration, runtime services, and UI integration.
# 第七层：应用编排、运行时服务与界面集成。
# 第7層：アプリケーション編成、ランタイムサービス、UI 統合。
# ============================================================================

# Runtime composition root: wires models, skills, session managers, storage,
# background services, and the browser-facing admin/chat surfaces together.
class AppContext:
    def _llm_config_revision(self, config: dict | None) -> str:
        try:
            raw = json_dumps(config or {}, sort_keys=True, default=str)
        except Exception:
            raw = json_dumps(config or {})
        return hashlib.sha256(raw.encode("utf-8", errors="ignore")).hexdigest()[:16]

    def _discover_external_code_source_roots(self) -> list[str]:
        home = Path.home()
        candidate_seeds = [
            self.workspace / "code_corpora",
            self.workspace.parent / "code_corpora",
            self.workspace.parent.parent / "code_corpora",
            self.workspace.parent / "Skills_Master" / "code_corpora",
            self.workspace.parent.parent / "Skills_Master" / "code_corpora",
            REPO_ROOT / "code_corpora",
            home / "Downloads" / "Skills_Master" / "code_corpora",
            home / "Downloads" / "code_corpora",
        ]
        seen: set[str] = set()
        roots: list[str] = []

        def _append(path: Path):
            try:
                resolved = path.resolve()
            except Exception:
                return
            raw = str(resolved)
            if raw in seen or not resolved.exists() or not resolved.is_dir():
                return
            seen.add(raw)
            roots.append(raw)

        for seed in candidate_seeds:
            try:
                base = seed.resolve()
            except Exception:
                continue
            if not base.exists() or not base.is_dir():
                continue
            if (base / "repos").exists() and (base / "repos").is_dir():
                _append(base / "repos")
                continue
            try:
                children = sorted((child for child in base.iterdir() if child.is_dir()), key=lambda p: p.name.lower())
            except Exception:
                children = []
            for child in children:
                if (child / "repos").exists() and (child / "repos").is_dir():
                    _append(child / "repos")
        return roots

    def _sync_global_ollama_defaults(self, active_profile: dict | None = None):
        if not (isinstance(active_profile, dict) and str(active_profile.get("provider", "")).lower() == "ollama"):
            return
        picked = dict(active_profile)
        model = str(picked.get("model", self.model) or self.model).strip()
        base = extract_base_url(str(picked.get("base_url", self.base_url) or self.base_url)).strip()
        if model:
            self.model = model
        if base:
            self.base_url = base

    def __init__(
        self,
        workspace: Path,
        base_url: str,
        model: str,
        skills_root: Path,
        thinking: bool = False,
        default_language: str = DEFAULT_UI_LANGUAGE,
        ui_style: str = DEFAULT_UI_STYLE,
        context_token_limit: int = DEFAULT_CONTEXT_TOKEN_LIMIT,
        context_limit_locked: bool = False,
        max_rounds: int = MAX_AGENT_ROUNDS,
        max_run_seconds: int = MAX_RUN_SECONDS,
        shell_command_timeout_seconds: int = DEFAULT_SHELL_COMMAND_TIMEOUT_SECONDS,
        auto_task_level_ceiling: int = DEFAULT_AUTO_TASK_LEVEL_CEILING,
        auto_model_switch: bool = False,
        arbiter_enabled: bool = True,
        arbiter_model: str = "",
        arbiter_timeout_seconds: float = ARBITER_DEFAULT_TIMEOUT_SECONDS,
        arbiter_max_tokens: int = ARBITER_DEFAULT_MAX_TOKENS,
        arbiter_temperature: float = ARBITER_DEFAULT_TEMPERATURE,
        execution_mode: str = EXECUTION_MODE_SYNC,
        max_output_tokens: int = AGENT_MAX_OUTPUT_TOKENS,
        max_user: int = 0,
        max_user_sessions: int = 0,
        daily_session_limit_per_ip: int = 0,
        daily_session_reset_hour: int = 8,
        js_lib_download_enabled: bool = True,
        rag_include_filename_entities: bool = RAG_INCLUDE_FILENAME_ENTITIES_DEFAULT,
        web_search_enabled: bool = DEFAULT_WEB_SEARCH_ENABLED,
        web_search_setting_locked: bool = False,
        user_memory_mode: str = DEFAULT_USER_MEMORY_MODE,
        user_memory_setting_locked: bool = False,
    ):
        self.workspace = Path(workspace).resolve()
        self.workspace_migration = _migrate_legacy_runtime_roots(self.workspace)
        self.base_url = base_url
        self.model = model
        self.thinking = False
        self.js_lib_root = offline_js_lib_root(self.workspace)
        self.offline_js_summary: dict = {}
        try:
            self.offline_js_summary = load_offline_js_lib_index(self.js_lib_root)
        except Exception:
            self.offline_js_summary = {}
        self.default_language = normalize_ui_language(default_language)
        self.ui_style = normalize_ui_style(ui_style)
        self.context_token_limit = max(
            MIN_CONTEXT_TOKEN_LIMIT,
            min(TOKEN_THRESHOLD, int(context_token_limit or TOKEN_THRESHOLD)),
        )
        self.context_limit_locked = bool(context_limit_locked)
        self.max_rounds = max(
            MIN_AGENT_ROUNDS,
            min(MAX_AGENT_ROUNDS_CAP, int(max_rounds or MAX_AGENT_ROUNDS)),
        )
        self.max_run_seconds = normalize_timeout_seconds(
            max_run_seconds if max_run_seconds is not None else MAX_RUN_SECONDS,
            minimum=MIN_RUN_TIMEOUT_SECONDS,
            maximum=MAX_RUN_TIMEOUT_SECONDS,
            fallback=MAX_RUN_SECONDS,
        )
        self.shell_command_timeout_seconds = normalize_timeout_seconds(
            shell_command_timeout_seconds if shell_command_timeout_seconds is not None else DEFAULT_SHELL_COMMAND_TIMEOUT_SECONDS,
            minimum=MIN_SHELL_COMMAND_TIMEOUT_SECONDS,
            maximum=MAX_SHELL_COMMAND_TIMEOUT_SECONDS,
            fallback=DEFAULT_SHELL_COMMAND_TIMEOUT_SECONDS,
        )
        self.auto_task_level_ceiling = normalize_auto_task_level_ceiling(auto_task_level_ceiling)
        self.auto_model_switch = bool(auto_model_switch)
        self.arbiter_enabled = bool(arbiter_enabled)
        self.arbiter_model = str(arbiter_model or "").strip()
        self.arbiter_timeout_seconds = max(0.2, min(15.0, float(arbiter_timeout_seconds or ARBITER_DEFAULT_TIMEOUT_SECONDS)))
        self.arbiter_max_tokens = max(24, min(256, int(arbiter_max_tokens or ARBITER_DEFAULT_MAX_TOKENS)))
        self.arbiter_temperature = max(0.0, min(1.0, float(arbiter_temperature if arbiter_temperature is not None else ARBITER_DEFAULT_TEMPERATURE)))
        self.execution_mode = normalize_execution_mode(execution_mode, default=EXECUTION_MODE_SYNC)
        self.max_output_tokens = max(256, int(max_output_tokens or AGENT_MAX_OUTPUT_TOKENS))
        self.web_search_enabled = bool(web_search_enabled)
        self.web_search_setting_locked = bool(web_search_setting_locked)
        self.user_memory_mode = normalize_user_memory_mode(user_memory_mode)
        self.user_memory_setting_locked = bool(user_memory_setting_locked)
        self.read_context_policy = DEFAULT_READ_CONTEXT_POLICY
        self.tool_memory_policy = DEFAULT_TOOL_MEMORY_POLICY
        self.skills_root = skills_root
        ensure_runtime_skills(self.skills_root)
        self.skills_store = SkillStore(self.skills_root)
        self.skills_store_refresh_ts = 0.0
        self.default_llm_config = parse_json_object(try_read_text(self.workspace / "LLM.config.json") or "{}", {})
        self.global_llm_config_revision = self._llm_config_revision(self.default_llm_config)
        self.global_llm_config_source = ""
        self.force_global_llm_config_for_users = False
        self.global_profiles_payload = parse_llm_config_profiles(
            self.default_llm_config, self.base_url, self.model
        )
        self.global_profiles = {
            str(p.get("id")): dict(p) for p in self.global_profiles_payload.get("profiles", [])
        }
        self.global_active_profile_id = str(
            self.global_profiles_payload.get("default_profile_id")
            or (next(iter(self.global_profiles.keys())) if self.global_profiles else "ollama")
        )
        active = self.global_profiles.get(self.global_active_profile_id, {})
        self._sync_global_ollama_defaults(active if isinstance(active, dict) else {})
        self.thinking = False
        self.codes_root = (self.workspace / "Codes").resolve()
        self.codes_root.mkdir(parents=True, exist_ok=True)
        self.crypto = CryptoBox(self.codes_root)
        self._session_mgrs: dict[str, SessionManager] = {}
        self._lock = threading.Lock()
        self.max_user = max(0, int(max_user or 0))
        self.max_user_sessions = max(0, int(max_user_sessions or 0))
        self.daily_session_limit_per_ip = max(0, int(daily_session_limit_per_ip or 0))
        self.daily_session_reset_hour = max(0, min(23, int(daily_session_reset_hour or 8)))
        self.js_lib_download_enabled = bool(js_lib_download_enabled)
        self._task_queue: deque[dict] = deque()
        self._task_queue_seq = 0
        self.tool_specs = filter_tool_specs_for_runtime(
            TOOLS,
            web_search_enabled=bool(getattr(self, "web_search_enabled", DEFAULT_WEB_SEARCH_ENABLED)),
        )
        self.web_ui_config_path = str(resolve_optional_file_path("", self.workspace))
        self.web_ui_dir = resolve_web_ui_dir_path(DEFAULT_WEB_UI_DIR, self.workspace)
        self.web_ui_external_requested = False
        self.web_ui_external_enabled = False
        self.web_ui_validation: dict = {"ok": False, "reason": "external_web_ui_disabled"}
        self.web_ui_assets_override: dict[str, str] = {}
        self._builtin_web_ui_assets_cache: dict[str, str] | None = None
        self.show_upload_list = False
        self.ide_mounts_cache: dict[str, list[dict]] = {}
        self.ide_port = IDE_DEFAULT_PORT
        self.ide_enabled = False
        self.rag_include_filename_entities = bool(rag_include_filename_entities)
        self.rag_parser = RAGContentParser(include_filename_entities=self.rag_include_filename_entities)
        self.rag_root = self.workspace / RAG_LIBRARY_DIRNAME
        self.rag_store = RAGLibraryStore(
            self.rag_root,
            include_filename_entities=self.rag_include_filename_entities,
        )
        self.rag_wiki = WikiStore(self.rag_root, kind="knowledge")
        self.rag_service = RAGIngestionService(
            self.rag_store,
            self.rag_parser,
            session_resolver=self._resolve_session_for_user,
            wiki_store=self.rag_wiki,
        )
        self.code_parser = CodeContentParser()
        self.code_root = self.workspace / CODE_LIBRARY_DIRNAME
        self.code_store = CodeLibraryStore(self.code_root)
        self.code_wiki = WikiStore(self.code_root, kind="code")
        self.workflow_memory = WorkflowMemoryStore(self.code_root)
        self.code_service = CodeIngestionService(
            self.code_store,
            self.code_parser,
            session_resolver=self._resolve_session_for_user,
            wiki_store=self.code_wiki,
        )
        self.code_source_roots = self._discover_external_code_source_roots()
        # Global MCP manager (one per app, mounted on agent port + 4). Loaded from the
        # trusted on-disk config; sessions reference this shared instance so health
        # and the available tool set are consistent everywhere and hot-swap is seen
        # at call time. Connection + health monitor start in main() after mount.
        self._mcp_config_path = self.workspace / "LLM.config.json"
        try:
            _mcp_records = mcp_extract_server_configs(self.default_llm_config)
        except Exception:
            _mcp_records = {}
        self.mcp = MCPManager(_mcp_records, logger=self._mcp_app_log, config_path=self._mcp_config_path)
        self.mcp.note_config_loaded()
        self._session_watchdog_stop = threading.Event()
        self._session_watchdog_thread = threading.Thread(
            target=self._session_watchdog_loop,
            name="session-watchdog",
            daemon=True,
        )
        self._session_watchdog_thread.start()

    def _session_watchdog_loop(self):
        while not self._session_watchdog_stop.is_set():
            try:
                self._session_watchdog_scan()
            except Exception:
                pass
            self._session_watchdog_stop.wait(float(SESSION_WATCHDOG_INTERVAL_SECONDS))

    def _session_watchdog_scan(self):
        now_value = now_ts()
        with self._lock:
            managers = list(self._session_mgrs.values())
        recovered_rows: list[tuple[str, str]] = []
        for mgr in managers:
            try:
                with mgr.lock:
                    sessions = list(mgr.sessions.values())
            except Exception:
                continue
            for sess in sessions:
                try:
                    if sess.recover_if_stale(now_value, SESSION_HEARTBEAT_STALE_SECONDS):
                        recovered_rows.append((str(getattr(mgr, "user_id", "") or ""), str(getattr(sess, "id", "") or "")))
                        try:
                            sess._emit(
                                "status",
                                {
                                    "summary": (
                                        str(getattr(sess, "run_recovered_reason", "") or "")
                                        or "session recovered by watchdog"
                                    )
                                },
                            )
                        except Exception:
                            pass
                except Exception:
                    continue
        if recovered_rows and self.scheduler_limits_enabled():
            for uid, sid in recovered_rows[:16]:
                try:
                    self._on_session_run_finished(uid, sid)
                except Exception:
                    continue

    def _builtin_web_ui_assets(self) -> dict[str, str]:
        cached = getattr(self, "_builtin_web_ui_assets_cache", None)
        if isinstance(cached, dict) and cached:
            return cached
        assets = {
            "index.html": INDEX_HTML,
            "style.css": APP_CSS,
            "app.js": APP_JS,
            "app.ts": APP_TS,
            "skills.html": SKILLS_INDEX_HTML,
            "skills.js": SKILLS_APP_JS,
            "skills-extra.css": SKILLS_EXTRA_CSS,
        }
        self._builtin_web_ui_assets_cache = assets
        return assets

    def _resolve_external_web_ui_file(self, root: Path, name: str) -> Path | None:
        candidates = [root / name, root / "frontend" / name]
        for fp in candidates:
            try:
                if fp.exists() and fp.is_file():
                    return fp
            except Exception:
                continue
        return None

    def validate_external_web_ui(self, ui_dir: Path) -> dict:
        root = resolve_web_ui_dir_path(str(ui_dir), self.workspace)
        out: dict = {
            "ok": False,
            "dir": str(root),
            "required_files": list(WEB_UI_REQUIRED_FILES),
            "optional_files": list(WEB_UI_OPTIONAL_FILES),
            "resolved_files": {},
            "missing_files": [],
            "errors": [],
            "checked_at": now_ts(),
        }
        if not root.exists():
            out["errors"].append("directory_not_found")
            return out
        if not root.is_dir():
            out["errors"].append("not_a_directory")
            return out
        for name in WEB_UI_REQUIRED_FILES:
            fp = self._resolve_external_web_ui_file(root, name)
            if not fp:
                out["missing_files"].append(name)
                continue
            txt = try_read_text(fp, max_bytes=4_000_000)
            if txt is None:
                out["errors"].append(f"unreadable:{name}")
                continue
            if not str(txt).strip():
                out["errors"].append(f"empty:{name}")
                continue
            out["resolved_files"][name] = str(fp)
        for name in WEB_UI_OPTIONAL_FILES:
            fp = self._resolve_external_web_ui_file(root, name)
            if fp:
                out["resolved_files"][name] = str(fp)
        out["ok"] = not out["missing_files"] and not out["errors"]
        return out

    def _load_external_web_ui_assets(self, resolved_files: dict) -> tuple[dict[str, str], list[str]]:
        assets: dict[str, str] = {}
        errs: list[str] = []
        for name, fp_raw in resolved_files.items():
            fp = Path(str(fp_raw))
            txt = try_read_text(fp, max_bytes=4_000_000)
            if txt is None:
                errs.append(f"read_failed:{name}")
                continue
            assets[name] = txt
        return assets, errs

    def export_builtin_web_ui(self, ui_dir: Path, overwrite: bool = False) -> dict:
        root = resolve_web_ui_dir_path(str(ui_dir), self.workspace)
        root.mkdir(parents=True, exist_ok=True)
        assets = self._builtin_web_ui_assets()
        written: list[str] = []
        skipped: list[str] = []
        errors: list[str] = []
        for name, content in assets.items():
            fp = root / name
            try:
                if fp.exists() and not overwrite:
                    skipped.append(str(fp))
                    continue
                fp.parent.mkdir(parents=True, exist_ok=True)
                fp.write_text(content, encoding="utf-8")
                written.append(str(fp))
            except Exception as exc:
                errors.append(f"{name}:{exc}")
        return {
            "ok": not errors,
            "dir": str(root),
            "written": written,
            "skipped": skipped,
            "errors": errors,
        }

    def web_ui_status(self) -> dict:
        mode = "external" if self.web_ui_external_enabled else "builtin"
        return {
            "mode": mode,
            "external_requested": bool(self.web_ui_external_requested),
            "external_enabled": bool(self.web_ui_external_enabled),
            "config_path": str(self.web_ui_config_path or ""),
            "dir": str(self.web_ui_dir),
            "show_upload_list": bool(getattr(self, "show_upload_list", False)),
            "ui_style": normalize_ui_style(getattr(self, "ui_style", DEFAULT_UI_STYLE)),
            "js_lib_download_enabled": bool(getattr(self, "js_lib_download_enabled", True)),
            "shell_command_timeout_seconds": int(getattr(self, "shell_command_timeout_seconds", DEFAULT_SHELL_COMMAND_TIMEOUT_SECONDS) or DEFAULT_SHELL_COMMAND_TIMEOUT_SECONDS),
            "daily_session_limit_per_ip": int(getattr(self, "daily_session_limit_per_ip", 0) or 0),
            "daily_session_reset_hour": int(getattr(self, "daily_session_reset_hour", 8) or 8),
            "validation": dict(self.web_ui_validation or {}),
        }

    def configure_web_ui(
        self,
        *,
        config_path: str = "",
        ui_dir: Path | str | None = None,
        enable_external: bool = False,
        export_builtin: bool = False,
        export_overwrite: bool = False,
        show_upload_list: bool | None = None,
    ) -> dict:
        self.web_ui_config_path = str(config_path or self.web_ui_config_path or "")
        self.web_ui_dir = resolve_web_ui_dir_path(str(ui_dir or DEFAULT_WEB_UI_DIR), self.workspace)
        if show_upload_list is not None:
            self.show_upload_list = bool(show_upload_list)
        export_result: dict = {}
        if export_builtin:
            export_result = self.export_builtin_web_ui(self.web_ui_dir, overwrite=bool(export_overwrite))
        self.web_ui_external_requested = bool(enable_external)
        self.web_ui_external_enabled = False
        self.web_ui_assets_override = {}
        self.web_ui_validation = self.validate_external_web_ui(self.web_ui_dir)
        if self.web_ui_external_requested and bool(self.web_ui_validation.get("ok", False)):
            assets, errs = self._load_external_web_ui_assets(
                self.web_ui_validation.get("resolved_files", {}) if isinstance(self.web_ui_validation, dict) else {}
            )
            if not errs:
                self.web_ui_assets_override = assets
                self.web_ui_external_enabled = True
            else:
                self.web_ui_validation = dict(self.web_ui_validation)
                self.web_ui_validation["ok"] = False
                self.web_ui_validation["errors"] = list(self.web_ui_validation.get("errors", [])) + errs
        elif self.web_ui_external_requested:
            self.web_ui_validation = dict(self.web_ui_validation)
            self.web_ui_validation.setdefault("errors", [])
            if "validation_failed" not in self.web_ui_validation["errors"]:
                self.web_ui_validation["errors"].append("validation_failed")
        else:
            self.web_ui_validation = dict(self.web_ui_validation)
            self.web_ui_validation["ok"] = False
            self.web_ui_validation["reason"] = "external_web_ui_disabled"
        out = self.web_ui_status()
        out["export"] = export_result
        return out

    def refresh_web_ui_validation(self, reload_external: bool = False) -> dict:
        validation = self.validate_external_web_ui(self.web_ui_dir)
        self.web_ui_validation = validation
        if reload_external and self.web_ui_external_requested:
            self.web_ui_external_enabled = False
            self.web_ui_assets_override = {}
            if bool(validation.get("ok", False)):
                assets, errs = self._load_external_web_ui_assets(validation.get("resolved_files", {}))
                if not errs:
                    self.web_ui_assets_override = assets
                    self.web_ui_external_enabled = True
                else:
                    self.web_ui_validation = dict(validation)
                    self.web_ui_validation["ok"] = False
                    self.web_ui_validation["errors"] = list(self.web_ui_validation.get("errors", [])) + errs
        return self.web_ui_status()

    def _web_ui_asset(self, name: str) -> str:
        if self.web_ui_external_enabled:
            v = str(self.web_ui_assets_override.get(name, "") or "")
            if v:
                return v
        return str(self._builtin_web_ui_assets().get(name, "") or "")

